def _parse_release_package_version(
    value: object, *, historical: bool = False
) -> tuple[tuple[int, int, int, int, int], str]:
    """Parse canonical governed versions without permissive normalization."""
    if not isinstance(value, str):
        raise ReleaseControlError("release package version is not a string")
    match = re.fullmatch(
        r"(0\.[3-9]|1\.0)\.(0|[1-9][0-9]*)(?:\.post(0|[1-9][0-9]*))?",
        value,
        flags=re.ASCII,
    )
    if match is None or (match[3] is not None and not historical):
        raise ReleaseControlError("release package version is not canonical governed syntax")
    major, minor = (int(part) for part in match[1].split("."))
    post = match[3]
    return (major, minor, int(match[2]), int(post is not None), int(post or "0")), value


def _release_version_pair(
    version: object, tag: object, *, historical: bool = False
) -> tuple[int, int, int, int, int]:
    identity, canonical = _parse_release_package_version(version, historical=historical)
    if not isinstance(tag, str) or tag != "v" + canonical:
        raise ReleaseControlError("release tag and canonical package version differ")
    return identity


def _release_closed_mapping(value: object, keys: set[str], label: str) -> dict[str, Any]:
    if not isinstance(value, dict) or set(value) != keys:
        raise ReleaseControlError(label + " shape is not closed")
    return value


def _release_relative_suffix(value: object, label: str) -> Path:
    if (
        not isinstance(value, str)
        or not value
        or "\\" in value
        or any(ord(character) < 32 for character in value)
        or any(component in {"", ".", ".."} for component in value.split("/"))
    ):
        raise ReleaseControlError(label + " is not a safe relative suffix")
    path = Path(value)
    if path.is_absolute() or path.as_posix() != value:
        raise ReleaseControlError(label + " is not a safe relative suffix")
    return path


def _release_captured_raw_file(
    value: object,
    *,
    containing_path: Path,
    containing_kind: str,
    field: Sequence[str | int],
    captured: _ReleaseCapturedFiles,
    expected_kind: str,
    label: str,
) -> tuple[Path, bytes]:
    """Resolve a typed field from the exact captured declaring record bytes."""
    container = _release_capture_absolute(containing_path)
    try:
        container_name = container.relative_to(captured.root).as_posix()
    except ValueError as exc:
        raise ReleaseControlError(label + " declaring record escapes captured root") from exc
    declaring: Any = _source_json(captured.read(container_name, kind=containing_kind), label)
    try:
        for part in field:
            if isinstance(declaring, dict) and isinstance(part, str):
                declaring = declaring[part]
            elif isinstance(declaring, list) and type(part) is int and 0 <= part < len(declaring):
                declaring = declaring[part]
            else:
                raise ReleaseControlError(label + " field is not in the declaring record")
    except KeyError as exc:
        raise ReleaseControlError(label + " field is missing from the declaring record") from exc
    if canonical_json(declaring) != canonical_json(value):
        raise ReleaseControlError(label + " reference is not the captured declaring field")
    row = _release_closed_mapping(declaring, {"bytes", "path", "sha256"}, label)
    suffix = _release_relative_suffix(row["path"], label + " path")
    if type(row["bytes"]) is not int or row["bytes"] < 0:
        raise ReleaseControlError(label + " size is not a nonnegative integer")
    digest = _require_digest(row["sha256"], label + " raw digest")
    path = container.parent / suffix
    try:
        name = path.relative_to(captured.root).as_posix()
    except ValueError as exc:
        raise ReleaseControlError(label + " escapes its captured root") from exc
    raw = captured.read(name, kind=expected_kind)
    if len(raw) != row["bytes"] or sha256_bytes(raw) != digest:
        raise ReleaseControlError(label + " raw bytes differ from their bound reference")
    return path, raw


def _release_capture_absolute(path: Path) -> Path:
    value = str(path)
    if value.startswith("//") or any(ord(character) < 32 for character in value):
        raise ReleaseControlError("captured release path is not a safe absolute path")
    return _canonical_absolute_path(value, "captured release path")


def _release_held_path(
    path: Path,
    *,
    directory: bool = False,
    expected_directories: tuple[tuple[str, int, int, int], ...] | None = None,
    expected_prefix: tuple[tuple[str, int, int, int], ...] = (),
    expected_identity: tuple[int, ...] | None = None,
) -> tuple[bytes, tuple[int, ...], tuple[tuple[str, int, int, int], ...]]:
    """Check expected ancestor objects before reading through their held descriptors."""
    path = _release_capture_absolute(path)
    descriptors: list[int] = []
    links: list[tuple[int, str, int]] = []
    identities: list[tuple[str, int, int, int]] = []

    def file_identity(info: os.stat_result) -> tuple[int, ...]:
        return (
            info.st_dev,
            info.st_ino,
            info.st_mode,
            info.st_nlink,
            info.st_size,
            info.st_mtime_ns,
            info.st_ctime_ns,
        )

    def check_directory(name: Path, descriptor: int) -> None:
        current = os.fstat(descriptor)
        row = (str(name), current.st_dev, current.st_ino, current.st_mode)
        known = [prior for prior in expected_prefix if prior[0] == str(name)]
        if known and known != [row]:
            raise ReleaseControlError("captured release ancestor changed before member access")
        index = len(identities)
        if expected_directories is not None and (
            index >= len(expected_directories) or row != expected_directories[index]
        ):
            raise ReleaseControlError("captured release root or ancestor was substituted")
        identities.append(row)

    try:
        parent = os.open(path.anchor, os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW)
        descriptors.append(parent)
        visible = Path(path.anchor)
        check_directory(visible, parent)
        for name in path.parts[1:] if directory else path.parts[1:-1]:
            child = os.open(name, os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW, dir_fd=parent)
            descriptors.append(child)
            links.append((parent, name, child))
            visible = visible / name
            check_directory(visible, child)
            parent = child
        if expected_directories is not None and len(identities) != len(expected_directories):
            raise ReleaseControlError("captured release ancestor inventory changed")
        if directory:
            raw = b""
            before = os.fstat(parent)
            if expected_identity is not None and file_identity(before) != expected_identity:
                raise ReleaseControlError("captured release object changed before byte access")
        else:
            descriptor = os.open(
                path.name, os.O_RDONLY | os.O_NONBLOCK | os.O_NOFOLLOW, dir_fd=parent
            )
            descriptors.append(descriptor)
            before = os.fstat(descriptor)
            if not stat.S_ISREG(before.st_mode) or before.st_nlink != 1:
                raise ReleaseControlError(
                    "captured release input is not a single-link regular file"
                )
            if expected_identity is not None and file_identity(before) != expected_identity:
                raise ReleaseControlError("captured release object changed before byte access")
            chunks: list[bytes] = []
            while block := os.read(descriptor, 1024 * 1024):
                chunks.append(block)
            raw = b"".join(chunks)
            after = os.fstat(descriptor)
            current = os.stat(path.name, dir_fd=parent, follow_symlinks=False)
            if (
                len({file_identity(before), file_identity(after), file_identity(current)}) != 1
                or len(raw) != before.st_size
            ):
                raise ReleaseControlError("captured release input changed while reading")
        for parent_fd, name, child_fd in reversed(links):
            held = os.fstat(child_fd)
            visible_info = os.stat(name, dir_fd=parent_fd, follow_symlinks=False)
            if (held.st_dev, held.st_ino, held.st_mode) != (
                visible_info.st_dev,
                visible_info.st_ino,
                visible_info.st_mode,
            ):
                raise ReleaseControlError("captured release ancestor changed while reading")
        return raw, file_identity(before), tuple(identities)
    except OSError as exc:
        raise ReleaseControlError("captured release input cannot be read safely") from exc
    finally:
        close_errors: list[OSError] = []
        for descriptor in reversed(descriptors):
            try:
                os.close(descriptor)
            except OSError as exc:
                close_errors.append(exc)
        if close_errors:
            raise ReleaseControlError(
                "captured release descriptor cleanup failed for "
                + str(len(close_errors))
                + " objects"
            ) from close_errors[0]


@dataclass(frozen=True)
class _ReleaseCapturedFiles:
    """Explicit raw inventory; typed resolver supplies its closed owner table."""

    root: Path
    root_directories: tuple[tuple[str, int, int, int], ...]
    rows: tuple[tuple[str, str, bytes, tuple[int, ...], tuple[tuple[str, int, int, int], ...]], ...]

    @classmethod
    def capture(
        cls,
        root: Path,
        declared: Sequence[tuple[str, str]],
        *,
        forbidden: Sequence[str],
        allowed_kinds: frozenset[str],
        expected_root_directories: tuple[tuple[str, int, int, int], ...] | None = None,
        expected_known_directories: tuple[tuple[str, int, int, int], ...] = (),
        expected_file_identities: Mapping[str, tuple[int, ...]] | None = None,
    ) -> _ReleaseCapturedFiles:
        root = _release_capture_absolute(root)
        if (
            not isinstance(allowed_kinds, frozenset)
            or not allowed_kinds
            or any(
                not isinstance(kind, str)
                or re.fullmatch(r"[a-z][a-z0-9]*(?:[-_.][a-z0-9]+)*", kind) is None
                for kind in allowed_kinds
            )
        ):
            raise ReleaseControlError("captured input resolver has no closed typed owner table")
        _, _, root_directories = _release_held_path(
            root,
            directory=True,
            expected_directories=expected_root_directories,
            expected_prefix=expected_known_directories,
        )
        excluded = tuple(
            _release_relative_suffix(p, "excluded release namespace") for p in forbidden
        )
        selected: dict[str, str] = {}
        for name, kind in declared:
            suffix = _release_relative_suffix(name, "declared release input")
            if kind not in allowed_kinds:
                raise ReleaseControlError("declared release input has an unknown typed owner")
            if any(suffix.is_relative_to(p) or p.is_relative_to(suffix) for p in excluded):
                raise ReleaseControlError(
                    "captured release input overlaps an output or active journal"
                )
            if name in selected and selected[name] != kind:
                raise ReleaseControlError("captured release input has conflicting typed owners")
            selected[name] = kind
        if expected_file_identities is not None and set(expected_file_identities) != set(selected):
            raise ReleaseControlError("captured release file identity inventory differs")
        paths = tuple(Path(name) for name in selected)
        if any(
            a.is_relative_to(b) or b.is_relative_to(a)
            for i, a in enumerate(paths)
            for b in paths[i + 1 :]
        ):
            raise ReleaseControlError("captured release input files overlap")
        rows = []
        physical: set[tuple[int, int]] = set()
        directories: dict[str, tuple[str, int, int, int]] = {}
        for ancestor in (*expected_known_directories, *root_directories):
            if ancestor[0] in directories and directories[ancestor[0]] != ancestor:
                raise ReleaseControlError("captured release supplied ancestor pins conflict")
            directories[ancestor[0]] = ancestor
        for name, kind in sorted(selected.items()):
            raw, observed, ancestors = _release_held_path(
                root / name,
                expected_prefix=tuple(directories.values()),
                expected_identity=None
                if expected_file_identities is None
                else expected_file_identities[name],
            )
            if ancestors[: len(root_directories)] != root_directories:
                raise ReleaseControlError("captured release root changed before file capture")
            if observed[:2] in physical:
                raise ReleaseControlError("captured release inputs alias the same physical file")
            for ancestor in ancestors:
                if ancestor[0] in directories and directories[ancestor[0]] != ancestor:
                    raise ReleaseControlError("captured release ancestor changed during inventory")
                directories[ancestor[0]] = ancestor
            physical.add((observed[0], observed[1]))
            rows.append((name, kind, raw, observed, ancestors))
        captured = cls(root, root_directories, tuple(rows))
        captured.revalidate()
        return captured

    def read(self, name: str, *, kind: str) -> bytes:
        _release_relative_suffix(name, "captured release input read")
        matches = [row for row in self.rows if row[0] == name]
        if len(matches) != 1 or matches[0][1] != kind:
            raise ReleaseControlError("release input read is outside its exact typed inventory")
        _, _, original, identity, ancestors = matches[0]
        try:
            raw, current, _ = _release_held_path(
                self.root / name, expected_directories=ancestors, expected_identity=identity
            )
        except ReleaseControlError as exc:
            raise ReleaseControlError("release input changed after capture") from exc
        if raw != original or identity != current:
            raise ReleaseControlError("release input changed after capture")
        return raw

    def revalidate(self) -> None:
        _release_held_path(self.root, directory=True, expected_directories=self.root_directories)
        for name, kind, _, _, _ in self.rows:
            self.read(name, kind=kind)


_RELEASE_PHASES = ("qualification", "publication_reconciliation", "postpublication")
_RELEASE_EXECUTION_REGISTRIES = {
    "environments": "docs/status/supported-environments.json",
    "scenarios": "docs/status/release-scenarios.json",
    "obligations": "docs/status/release-test-obligations.json",
}


def _release_json_pointer_tokens(pointer: object, label: str) -> list[str]:
    """Validate pointer syntax independently of whether the original document is available."""
    if not isinstance(pointer, str) or (pointer and not pointer.startswith("/")):
        raise ReleaseControlError(label + " has an invalid JSON pointer")
    tokens = []
    for encoded in pointer.split("/")[1:] if pointer else ():
        if re.search(r"~(?![01])", encoded):
            raise ReleaseControlError(label + " has an invalid pointer escape")
        tokens.append(encoded.replace("~1", "/").replace("~0", "~"))
    return tokens


def _release_json_pointer(value: object, pointer: object, label: str) -> Any:
    """Resolve one canonical RFC 6901 pointer without coercion or guessed fields."""
    current = value
    for token in _release_json_pointer_tokens(pointer, label):
        if isinstance(current, dict):
            if token not in current:
                raise ReleaseControlError(label + " points to a missing member")
            current = current[token]
        elif isinstance(current, list):
            if re.fullmatch(r"0|[1-9][0-9]*", token, flags=re.ASCII) is None:
                raise ReleaseControlError(label + " has a noncanonical array index")
            index = int(token)
            if index >= len(current):
                raise ReleaseControlError(label + " points outside an array")
            current = current[index]
        else:
            raise ReleaseControlError(label + " crosses a scalar")
    return current


def _release_unique_json_rows(rows: Sequence[Any]) -> list[Any]:
    """Canonical set of already validated declarations, without Python bool aliases."""
    values = {canonical_json(row): row for row in rows}
    return [json.loads(key) for key in sorted(values)]


def _release_id_rows(value: object, key: str, label: str) -> dict[str, dict[str, Any]]:
    if not isinstance(value, list):
        raise ReleaseControlError(label + " is not an array")
    result: dict[str, dict[str, Any]] = {}
    for row in value:
        if not isinstance(row, dict):
            raise ReleaseControlError(label + " contains a non-object declaration")
        identity = row.get(key)
        if (
            not isinstance(identity, str)
            or re.fullmatch(r"[A-Za-z0-9][A-Za-z0-9._-]{0,255}", identity, flags=re.ASCII) is None
        ):
            raise ReleaseControlError(label + " contains an invalid stable identity")
        if identity in result:
            raise ReleaseControlError(label + " contains a duplicate identity: " + identity)
        result[identity] = row
    return result


def _release_id_list(value: object, label: str, *, nonempty: bool = False) -> list[str]:
    if not isinstance(value, list) or (nonempty and not value):
        raise ReleaseControlError(label + " is not the required identity array")
    result: list[str] = []
    for item in value:
        if (
            not isinstance(item, str)
            or re.fullmatch(r"[A-Za-z0-9][A-Za-z0-9._-]{0,255}", item, flags=re.ASCII) is None
            or item in result
        ):
            raise ReleaseControlError(label + " has an invalid or duplicate identity")
        result.append(item)
    return result


def _release_catalog_declarations(
    registries: Mapping[str, bytes],
) -> tuple[dict[str, Any], dict[str, list[dict[str, Any]]]]:
    """Retain every original row and pointer; authority is checked by the gate caller."""
    if set(registries) != set(_RELEASE_EXECUTION_REGISTRIES.values()):
        raise ReleaseControlError("catalog requires the exact three raw registry owners")
    parsed = {path: _source_json(raw, "execution registry") for path, raw in registries.items()}
    declarations: dict[str, list[dict[str, Any]]] = {
        name: [] for name in ("environments", "scenarios", "obligations", "criteria", "executors")
    }
    for array, path in _RELEASE_EXECUTION_REGISTRIES.items():
        source = parsed[path]
        owned = [(array, array, "id"), ("executors", "executors", "id")]
        if array == "obligations":
            owned.append(("criterion_requirements", "criteria", "criterion_id"))
        for original_array, destination, key in owned:
            _release_id_rows(source.get(original_array), key, original_array)
            for index, row in enumerate(source[original_array]):
                declarations[destination].append(
                    {
                        "source": {
                            "raw_registry_path": path,
                            "raw_registry_digest": sha256_bytes(registries[path]),
                            "json_pointer": "/" + original_array + "/" + str(index),
                        },
                        "value": json.loads(canonical_json(row)),
                    }
                )
    _release_id_rows([row["value"] for row in declarations["executors"]], "id", "global executors")
    for kind, rows in declarations.items():
        key = "criterion_id" if kind == "criteria" else "id"
        rows.sort(
            key=lambda row: (
                row["value"][key],
                row["source"]["raw_registry_path"],
                row["source"]["json_pointer"],
            )
        )
    return parsed, declarations


def _release_scenario_structure(
    registry: Mapping[str, Any],
    *,
    root: str,
    milestone: str,
    phase: str,
    source_refs: Mapping[str, Mapping[str, Any]],
) -> dict[str, Any]:
    """Expand the original finite DAG, retaining every contextual constraint use."""
    if milestone not in MILESTONES or phase not in _RELEASE_PHASES:
        raise ReleaseControlError("scenario expansion has an unknown slot or phase")
    scenarios = _release_id_rows(registry.get("scenarios"), "id", "scenarios")
    if set(source_refs) != set(scenarios):
        raise ReleaseControlError("scenario source pointer inventory is incomplete or extra")
    slots = registry.get("release_slots")
    if (
        not isinstance(slots, list)
        or len(slots) != 7
        or [row.get("milestone") for row in slots if isinstance(row, dict)] != list(MILESTONES)
    ):
        raise ReleaseControlError(
            "scenario release slots differ from the exact ordered seven slots"
        )
    for slot in slots:
        for named_phase in _RELEASE_PHASES:
            _release_id_list(
                slot.get(named_phase + "_scenario_ids"),
                "original phase roots",
                nonempty=named_phase == "qualification",
            )
        attempts = slot.get("qualification_attempts_required")
        if type(attempts) is not int or attempts < 1:
            raise ReleaseControlError("scenario slot has no positive attempt requirement")

    active: set[tuple[str, str]] = set()
    completed: dict[tuple[str, str], tuple[dict[str, Any], tuple[str, ...]]] = {}
    order: list[tuple[str, str]] = []

    def expand(identity: str, selection: str) -> tuple[str, ...]:
        state = (identity, selection)
        if state in active:
            raise ReleaseControlError("cyclic contextual scenario expansion")
        if state in completed:
            return completed[state][1]
        if identity not in scenarios:
            raise ReleaseControlError("scenario expansion names a missing declaration: " + identity)
        row = scenarios[identity]
        if row.get("phase") != phase:
            raise ReleaseControlError("scenario expansion crosses an original phase boundary")
        first = row.get("first_required_release")
        if first not in MILESTONES or MILESTONES.index(first) > MILESTONES.index(selection):
            raise ReleaseControlError(
                "selected scenario is outside its original milestone applicability"
            )
        expansion = row.get("expansion")
        if not isinstance(expansion, dict):
            raise ReleaseControlError("scenario expansion has no closed rule")
        active.add(state)
        order.append(state)
        kind = expansion.get("kind")
        children: list[tuple[str, str]] = []
        if kind == "leaf":
            _release_closed_mapping(expansion, {"kind", "implementation"}, "leaf expansion")
            rule = "LEAF"
        elif kind == "group":
            _release_closed_mapping(expansion, {"kind", "scenario_ids"}, "group expansion")
            rule = "GROUP"
            children = [
                (child, selection)
                for child in _release_id_list(
                    expansion["scenario_ids"], "group children", nonempty=True
                )
            ]
        elif kind == "cumulative":
            _release_closed_mapping(expansion, {"kind", "rule"}, "cumulative expansion")
            rule = expansion["rule"]
            if rule not in {"ALL_PRIOR_REQUIRED", "COMPLETE_CURRENT_CUMULATIVE"}:
                raise ReleaseControlError("unknown cumulative scenario rule")
            stop = MILESTONES.index(selection) + int(rule == "COMPLETE_CURRENT_CUMULATIVE")
            for slot in slots[:stop]:
                for child in slot[phase + "_scenario_ids"]:
                    child_state = (child, slot["milestone"])
                    # A complete-current selector is the root of its own selection,
                    # never its own executable child. All other cycles still fail.
                    if child_state != state:
                        children.append(child_state)
            children = list(dict.fromkeys(children))
            if not children:
                raise ReleaseControlError(
                    "cumulative scenario has no justified earlier/current roots"
                )
        else:
            raise ReleaseControlError("unsupported scenario expansion rule")
        if rule != "LEAF":
            if (
                row.get("kind") not in {"release_requirement", "inheritance_selector"}
                or row.get("expected_subject")
                != {"scope": "production_operation", "verdict": "PASS", "fault_id": None}
                or row.get("retry_policy") != "no_automatic_retry"
                or row.get("qualification_unit_terminal_on_verified_expectation") != "PASS"
            ):
                raise ReleaseControlError(
                    "non-leaf scenario has an unsupported subject or retry contract"
                )
        leaves = (
            tuple(
                sorted(
                    {leaf for child, child_slot in children for leaf in expand(child, child_slot)}
                )
            )
            if children
            else (identity,)
        )
        step = {
            "scenario_id": identity,
            "selection_milestone": selection,
            "rule": rule,
            "direct_children": [
                {"scenario_id": child, "selection_milestone": child_slot}
                for child, child_slot in children
            ],
            "source_declaration": dict(source_refs[identity]),
        }
        completed[state] = (step, leaves)
        active.remove(state)
        return leaves

    leaves = expand(root, milestone)
    uses: list[list[tuple[str, str]]] = []

    def paths(state: tuple[str, str], ancestry: list[tuple[str, str]]) -> None:
        path = [*ancestry, state]
        uses.append(path)
        for child in completed[state][0]["direct_children"]:
            paths((child["scenario_id"], child["selection_milestone"]), path)

    paths((root, milestone), [])
    return {
        "root_scenario_id": root,
        "steps": [completed[state][0] for state in order],
        "leaf_scenario_ids": list(leaves),
        "constraint_uses": uses,
    }


def _release_catalog_graph(
    parsed: Mapping[str, Any],
    declarations: Mapping[str, list[dict[str, Any]]],
) -> dict[str, Any]:
    """Recompute static recipes; neither a declaration nor this graph proves execution."""
    scenario_registry = parsed[_RELEASE_EXECUTION_REGISTRIES["scenarios"]]
    sources: dict[str, dict[str, Any]] = {}
    values: dict[str, dict[str, dict[str, Any]]] = {}
    for kind in ("environments", "scenarios", "obligations", "criteria", "executors"):
        key = "criterion_id" if kind == "criteria" else "id"
        values[kind] = _release_id_rows([row["value"] for row in declarations[kind]], key, kind)
        for row in declarations[kind]:
            source_key = kind + ":" + row["value"][key]
            sources[source_key] = row["source"]
    scenarios, environments, obligations, executors = (
        values["scenarios"],
        values["environments"],
        values["obligations"],
        values["executors"],
    )
    scenario_sources = {identity: sources["scenarios:" + identity] for identity in scenarios}
    unknown: list[dict[str, Any]] = []

    def unresolved(
        kind: str, identity: str, pointer: str, reason: str, dependency: str | None = None
    ) -> dict[str, Any]:
        item = {
            "source_declaration": sources[kind + ":" + identity],
            "stable_id": identity,
            "field_pointer": pointer,
            "unresolved_dependency_id": dependency,
            "reason": reason,
        }
        unknown.append(item)
        return item

    def declared_unknown(node: Any, kind: str, identity: str, pointer: str) -> None:
        if isinstance(node, dict):
            if node.get("state") == "UNRESOLVED":
                reason = node.get("reason")
                if not isinstance(reason, str) or not reason.strip():
                    raise ReleaseControlError("unresolved declaration has no original reason")
                unresolved(kind, identity, pointer, reason)
            for key, child in sorted(node.items()):
                declared_unknown(
                    child, kind, identity, pointer + "/" + key.replace("~", "~0").replace("/", "~1")
                )
        elif isinstance(node, list):
            for index, child in enumerate(node):
                declared_unknown(child, kind, identity, pointer + "/" + str(index))

    for kind, rows in values.items():
        for identity, row in rows.items():
            declared_unknown(row, kind, identity, sources[kind + ":" + identity]["json_pointer"])
    for identity, scenario in scenarios.items():
        for field in ("environment_pairs", "covers_stages"):
            value = scenario.get(field)
            if not isinstance(value, list):
                raise ReleaseControlError("scenario has no explicit " + field + " declaration")
            if field == "covers_stages":
                stages = _release_id_list(value, "scenario covered stages")
                if any(stage not in STAGES for stage in stages):
                    raise ReleaseControlError("scenario declares an unknown release stage")
            if not value:
                expansion = scenario["expansion"]
                if scenario["required_obligations"].get("state") != "UNRESOLVED" or (
                    expansion["kind"] == "leaf"
                    and expansion["implementation"].get("state") == "CONFIGURED"
                ):
                    raise ReleaseControlError("configured scenario has an empty " + field)
                unresolved(
                    "scenarios",
                    identity,
                    scenario_sources[identity]["json_pointer"] + "/" + field,
                    "Original scenario has an explicitly unresolved " + field + " mapping",
                )
    declared_unresolved = list(unknown)
    all_units: dict[str, dict[str, Any]] = {}
    blocked_units: set[str] = set()
    slot_results = []

    def applicable(first: object, milestone: str) -> bool:
        if first == "post-v1.0":
            return False
        if first not in MILESTONES:
            raise ReleaseControlError("obligation has an unknown first-required milestone")
        return MILESTONES.index(str(first)) <= MILESTONES.index(milestone)

    def pairs(row: Mapping[str, Any]) -> list[tuple[str, str]]:
        raw = row.get("environment_pairs")
        if not isinstance(raw, list):
            raise ReleaseControlError("scenario has no explicit environment/profile pairs")
        result = []
        for pair in raw:
            p = _release_closed_mapping(pair, {"environment_id", "profile_id"}, "environment pair")
            environment = environments.get(p["environment_id"])
            if environment is None or environment.get("profile_id") != p["profile_id"]:
                raise ReleaseControlError(
                    "scenario pair differs from its original environment owner"
                )
            selected = (p["environment_id"], p["profile_id"])
            if selected in result:
                raise ReleaseControlError("scenario has a duplicate explicit environment pair")
            result.append(selected)
        return result

    for slot_index, slot in enumerate(scenario_registry["release_slots"]):
        milestone = slot["milestone"]
        result = {
            "milestone": milestone,
            "qualification_attempts_required": slot["qualification_attempts_required"],
            "source": {
                "raw_registry_path": _RELEASE_EXECUTION_REGISTRIES["scenarios"],
                "raw_registry_digest": next(iter(scenario_sources.values()))["raw_registry_digest"],
                "json_pointer": "/release_slots/" + str(slot_index),
            },
            "original_scenario_ids": {},
            "expansions": {},
        }
        for phase in _RELEASE_PHASES:
            structures: dict[str, dict[str, Any]] = {}
            processed: dict[str, set[str]] = {}
            processing: set[str] = set()
            root_unknown: dict[str, list[dict[str, Any]]] = {}

            def structure(identity: str) -> dict[str, Any]:
                if identity not in structures:
                    structures[identity] = _release_scenario_structure(
                        scenario_registry,
                        root=identity,
                        milestone=milestone,
                        phase=phase,
                        source_refs=scenario_sources,
                    )
                return structures[identity]

            def issue(
                identity: str, field: str, reason: str, dependency: str | None = None
            ) -> dict[str, Any]:
                return unresolved(
                    "scenarios",
                    identity,
                    scenario_sources[identity]["json_pointer"] + "/" + field,
                    reason,
                    dependency,
                )

            def required(row: dict[str, Any], affected: list[dict[str, Any]]) -> set[str]:
                mapping = row.get("required_obligations")
                if not isinstance(mapping, dict):
                    raise ReleaseControlError("scenario has no original obligation mapping")
                if mapping.get("state") == "UNRESOLVED":
                    affected.extend(
                        item
                        for item in declared_unresolved
                        if item["source_declaration"] == scenario_sources[row["id"]]
                        and "/required_obligations" in item["field_pointer"]
                    )
                    return set()
                _release_closed_mapping(mapping, {"state", "obligation_ids"}, "scenario coverage")
                if mapping["state"] != "MAPPED":
                    raise ReleaseControlError("unsupported scenario obligation mapping")
                return _release_catalog_resolve_obligations(
                    obligations, mapping["obligation_ids"], milestone
                )

            def leaf_units(identity: str, affected: list[dict[str, Any]]) -> set[str]:
                leaf = scenarios[identity]
                mapping = leaf["expansion"]["implementation"]
                if mapping.get("state") == "UNRESOLVED":
                    affected.extend(
                        item
                        for item in declared_unresolved
                        if item["source_declaration"] == scenario_sources[identity]
                    )
                    return set()
                _release_closed_mapping(mapping, {"state", "executor_ids"}, "leaf implementation")
                if mapping["state"] != "CONFIGURED":
                    raise ReleaseControlError("unsupported leaf implementation mapping")
                selected = set()
                matched_executors: set[str] = set()
                declared_executors = _release_id_list(
                    mapping["executor_ids"], "leaf executors", nonempty=True
                )
                for environment_id, profile_id in pairs(leaf):
                    environment = environments[environment_id]
                    if environment["first_required_release"] is None or not applicable(
                        environment["first_required_release"], milestone
                    ):
                        raise ReleaseControlError(
                            "selected leaf borrows an inapplicable environment"
                        )
                    execution = environment["execution"]
                    if execution.get("state") == "UNRESOLVED":
                        affected.append(
                            issue(
                                identity,
                                "environment_pairs",
                                "Required environment execution remains unresolved",
                                environment_id,
                            )
                        )
                        continue
                    if execution.get("state") != "CONFIGURED":
                        raise ReleaseControlError("unsupported environment execution mapping")
                    matches = 0
                    for executor_id in declared_executors:
                        if executor_id not in executors:
                            raise ReleaseControlError("leaf names an undeclared executor")
                        if executor_id not in execution["executor_ids"]:
                            continue
                        matched_executors.add(executor_id)
                        executor = executors[executor_id]
                        if executor["phase"] != phase:
                            raise ReleaseControlError("leaf executor crosses a phase boundary")
                        binding = executor["binding"]
                        if binding.get("state") == "UNRESOLVED":
                            affected.append(
                                issue(
                                    identity,
                                    "expansion/implementation",
                                    "Required executor binding remains unresolved",
                                    executor_id,
                                )
                            )
                            continue
                        if binding.get("state") != "CONFIGURED":
                            raise ReleaseControlError("unsupported executor binding")
                        recipe = binding["recipe"]
                        if (
                            phase == "qualification"
                            and recipe["effect_class"] == "existing_release_mutation"
                        ):
                            raise ReleaseControlError(
                                "qualification cannot run a release mutation recipe"
                            )
                        identity_tuple = {
                            "slot_milestone": milestone,
                            "scenario_id": identity,
                            "executor_id": executor_id,
                            "environment_id": environment_id,
                            "profile_id": profile_id,
                        }
                        unit_id = "release-unit-sha256-" + sha256_json(identity_tuple)
                        unit = {
                            "unit_id": unit_id,
                            **identity_tuple,
                            "first_required_release": leaf["first_required_release"],
                            "phase": phase,
                            "obligation_ids": [],
                            "coverage_reasons": [],
                            "prerequisite_unit_ids": [],
                            "expected_subject": leaf["expected_subject"],
                            "qualification_unit_terminal_on_verified_expectation": leaf[
                                "qualification_unit_terminal_on_verified_expectation"
                            ],
                            "recipe": recipe,
                            "retry_policy": leaf["retry_policy"],
                            "source_declarations": [scenario_sources[identity]],
                        }
                        prior = all_units.get(unit_id)
                        if prior is not None:
                            ignored = {
                                "obligation_ids",
                                "coverage_reasons",
                                "prerequisite_unit_ids",
                                "source_declarations",
                            }
                            if canonical_json(
                                {k: v for k, v in prior.items() if k not in ignored}
                            ) != canonical_json(
                                {k: v for k, v in unit.items() if k not in ignored}
                            ):
                                raise ReleaseControlError(
                                    "repeated execution tuple has conflicting recipe semantics"
                                )
                        else:
                            all_units[unit_id] = json.loads(canonical_json(unit))
                        selected.add(unit_id)
                        matches += 1
                    if not matches:
                        affected.append(
                            issue(
                                identity,
                                "environment_pairs",
                                "No configured executor witnesses the exact approved pair",
                                environment_id,
                            )
                        )
                for executor_id in sorted(set(declared_executors) - matched_executors):
                    if executor_id not in executors:
                        raise ReleaseControlError("leaf names an undeclared executor")
                    affected.append(
                        issue(
                            identity,
                            "expansion/implementation",
                            "Declared executor has no approved environment/profile mapping",
                            executor_id,
                        )
                    )
                return selected

            def witness(unit_id: str, obligation_id: str) -> bool:
                unit, obligation = all_units[unit_id], obligations[obligation_id]
                mapping = obligation["implementation"]
                if mapping.get("state") == "UNRESOLVED":
                    return False
                if mapping.get("state") != "CONFIGURED":
                    raise ReleaseControlError("unsupported obligation implementation mapping")
                for criterion_id in _release_id_list(
                    obligation["criterion_ids"], "obligation criteria", nonempty=True
                ):
                    if criterion_id not in values["criteria"]:
                        raise ReleaseControlError("obligation names an unknown criterion")
                    criterion_mapping = values["criteria"][criterion_id]["mapping"]
                    if criterion_mapping.get("state") == "UNRESOLVED":
                        return False
                    _release_closed_mapping(
                        criterion_mapping, {"state", "obligation_ids"}, "criterion mapping"
                    )
                    if criterion_mapping[
                        "state"
                    ] != "MAPPED" or obligation_id not in _release_catalog_resolve_obligations(
                        obligations, criterion_mapping["obligation_ids"], milestone
                    ):
                        raise ReleaseControlError(
                            "obligation/criterion coverage is not reciprocal through current lifecycle"
                        )
                if unit["executor_id"] not in mapping["executor_ids"]:
                    return False
                if (
                    unit["environment_id"] not in obligation["environment_ids"]
                    or unit["profile_id"] not in obligation["profile_ids"]
                ):
                    return False
                named_scenarios = _release_id_list(
                    obligation["scenario_ids"], "obligation scenarios", nonempty=True
                )
                if any(scenario not in scenarios for scenario in named_scenarios):
                    raise ReleaseControlError("obligation names an unknown scenario")
                return any(
                    unit["scenario_id"] in structure(scenario)["leaf_scenario_ids"]
                    for scenario in named_scenarios
                    if scenarios[scenario]["phase"] == phase
                    and applicable(scenarios[scenario]["first_required_release"], milestone)
                )

            def process(identity: str) -> set[str]:
                if identity in processing:
                    raise ReleaseControlError("cyclic scenario prerequisite closure")
                if identity in processed:
                    return processed[identity]
                processing.add(identity)
                expanded = structure(identity)
                affected: list[dict[str, Any]] = []
                leaves = {
                    leaf: leaf_units(leaf, affected) for leaf in expanded["leaf_scenario_ids"]
                }
                descendant_units = set().union(*leaves.values())
                for path in expanded["constraint_uses"]:
                    selected_id, _ = path[-1]
                    row = scenarios[selected_id]
                    descendant_leaves = set()
                    prefix = tuple(path)
                    for use in expanded["constraint_uses"]:
                        if (
                            tuple(use[: len(path)]) == prefix
                            and scenarios[use[-1][0]]["expansion"]["kind"] == "leaf"
                        ):
                            descendant_leaves.add(use[-1][0])
                    units = set().union(*(leaves[leaf] for leaf in descendant_leaves))
                    demanded = required(row, affected)
                    if not row["environment_pairs"] or not row["covers_stages"]:
                        blocked_units.update(units)
                        affected.extend(
                            item
                            for item in declared_unresolved
                            if item["source_declaration"] == scenario_sources[selected_id]
                        )
                    source_chain = [scenario_sources[entry[0]] for entry in path]
                    for unit_id in units:
                        unit = all_units[unit_id]
                        unit["source_declarations"] = _release_unique_json_rows(
                            unit["source_declarations"] + source_chain
                        )
                    for environment_id, profile_id in pairs(row):
                        if not any(
                            (all_units[u]["environment_id"], all_units[u]["profile_id"])
                            == (environment_id, profile_id)
                            for u in units
                        ):
                            affected.append(
                                issue(
                                    selected_id,
                                    "environment_pairs",
                                    "Aggregate has no descendant unit for its exact required pair",
                                    environment_id,
                                )
                            )
                    stages = {
                        stage
                        for leaf in descendant_leaves
                        for stage in scenarios[leaf]["covers_stages"]
                    }
                    if not set(row["covers_stages"]) <= stages:
                        affected.append(
                            issue(
                                selected_id,
                                "covers_stages",
                                "Descendant leaf stages do not cover the aggregate stage requirement",
                            )
                        )
                    for obligation_id in sorted(demanded):
                        obligation = obligations[obligation_id]
                        if obligation["implementation"].get("state") == "UNRESOLVED":
                            blocked_units.update(units)
                            affected.extend(
                                item
                                for item in declared_unresolved
                                if item["source_declaration"]
                                == sources["obligations:" + obligation_id]
                            )
                        witnesses = {
                            unit_id for unit_id in units if witness(unit_id, obligation_id)
                        }
                        demanded_pairs = {
                            (e, p)
                            for e, p in pairs(row)
                            if e in obligation["environment_ids"] and p in obligation["profile_ids"]
                        }
                        observed_pairs = {
                            (all_units[u]["environment_id"], all_units[u]["profile_id"])
                            for u in witnesses
                        }
                        if (
                            not witnesses
                            or not demanded_pairs
                            or not demanded_pairs <= observed_pairs
                        ):
                            affected.append(
                                issue(
                                    selected_id,
                                    "required_obligations",
                                    "Required obligation has no complete legitimate descendant witness set",
                                    obligation_id,
                                )
                            )
                        for unit_id in witnesses:
                            unit = all_units[unit_id]
                            unit["obligation_ids"] = sorted(
                                set(unit["obligation_ids"]) | {obligation_id}
                            )
                            refs = [
                                *source_chain,
                                sources["obligations:" + obligation_id],
                                scenario_sources[unit["scenario_id"]],
                                sources["executors:" + unit["executor_id"]],
                            ]
                            criteria = _release_id_list(
                                obligation["criterion_ids"], "obligation criteria", nonempty=True
                            )
                            families = _release_id_list(
                                obligation["family_ids"], "obligation families", nonempty=True
                            )
                            for criterion in criteria:
                                if criterion not in values["criteria"]:
                                    raise ReleaseControlError(
                                        "obligation names an unknown criterion"
                                    )
                                refs.append(sources["criteria:" + criterion])
                            reasons = {r["obligation_id"]: r for r in unit["coverage_reasons"]}
                            prior_refs = reasons.get(obligation_id, {}).get(
                                "source_declarations", []
                            )
                            reasons[obligation_id] = {
                                "obligation_id": obligation_id,
                                "criterion_ids": sorted(criteria),
                                "family_ids": sorted(families),
                                "source_declarations": _release_unique_json_rows(prior_refs + refs),
                            }
                            unit["coverage_reasons"] = [reasons[k] for k in sorted(reasons)]
                    if row["expansion"]["kind"] == "leaf":
                        prerequisites = set()
                        for ancestor, _ in path:
                            prerequisites.update(
                                _release_id_list(
                                    scenarios[ancestor]["prerequisite_scenario_ids"],
                                    "scenario prerequisites",
                                )
                            )
                        dependencies: set[str] = set()
                        for prerequisite in sorted(prerequisites):
                            dependencies.update(process(prerequisite))
                            affected.extend(root_unknown[prerequisite])
                            if root_unknown[prerequisite] or not processed[prerequisite]:
                                blocked_units.update(leaves[selected_id])
                                affected.append(
                                    issue(
                                        selected_id,
                                        "prerequisite_scenario_ids",
                                        "Required prerequisite has no complete configured unit set",
                                        prerequisite,
                                    )
                                )
                        for unit_id in leaves[selected_id]:
                            if unit_id in dependencies:
                                raise ReleaseControlError(
                                    "aggregate prerequisite creates a self edge"
                                )
                            unit = all_units[unit_id]
                            unit["prerequisite_unit_ids"] = sorted(
                                set(unit["prerequisite_unit_ids"]) | dependencies
                            )
                processing.remove(identity)
                processed[identity] = descendant_units
                root_unknown[identity] = _release_unique_json_rows(affected)
                return descendant_units

            roots = slot[phase + "_scenario_ids"]
            traces = []
            for root in roots:
                units = process(root)
                expanded = structure(root)
                traces.append(
                    {k: expanded[k] for k in ("root_scenario_id", "steps", "leaf_scenario_ids")}
                    | {
                        "execution_unit_ids": sorted(units),
                        "unresolved_declarations": root_unknown[root],
                    }
                )
            result["original_scenario_ids"][phase] = list(roots)
            result["expansions"][phase] = traces
        slot_results.append(result)

    # Aggregate prerequisite unions can introduce a cycle even when each source
    # expansion and each individual prerequisite use was acyclic.
    complete: set[str] = set()
    active_units: set[str] = set()

    def visit(unit_id: str) -> None:
        if unit_id not in all_units or unit_id in active_units:
            raise ReleaseControlError("unknown or cyclic configured unit prerequisite")
        if unit_id in complete:
            return
        active_units.add(unit_id)
        unit = all_units[unit_id]
        for dependency in unit["prerequisite_unit_ids"]:
            if (
                all_units[dependency]["slot_milestone"] != unit["slot_milestone"]
                or all_units[dependency]["phase"] != unit["phase"]
            ):
                raise ReleaseControlError("configured prerequisite crosses slot or phase")
            visit(dependency)
        active_units.remove(unit_id)
        complete.add(unit_id)

    late_unknown: list[tuple[str, str, dict[str, Any]]] = []
    for unit_id in sorted(all_units):
        visit(unit_id)
        if not all_units[unit_id]["obligation_ids"]:
            blocked_units.add(unit_id)
            unit = all_units[unit_id]
            reason = unresolved(
                "scenarios",
                unit["scenario_id"],
                scenario_sources[unit["scenario_id"]]["json_pointer"] + "/required_obligations",
                "Configured tuple has no complete legitimate obligation owner",
            )
            late_unknown.append((unit["slot_milestone"], unit["phase"], reason))
    changed = True
    while changed:
        changed = False
        for unit_id, unit in all_units.items():
            if unit_id not in blocked_units and blocked_units.intersection(
                unit["prerequisite_unit_ids"]
            ):
                blocked_units.add(unit_id)
                changed = True
                reason = unresolved(
                    "scenarios",
                    unit["scenario_id"],
                    scenario_sources[unit["scenario_id"]]["json_pointer"]
                    + "/prerequisite_scenario_ids",
                    "A required transitive prerequisite cannot be materialized",
                )
                late_unknown.append((unit["slot_milestone"], unit["phase"], reason))
    removed_units = {unit_id: all_units.pop(unit_id) for unit_id in blocked_units}
    for slot_result in slot_results:
        for trace_phase, traces in slot_result["expansions"].items():
            for trace in traces:
                root_id = trace["root_scenario_id"]
                removal_causes = [
                    unresolved(
                        "scenarios",
                        root_id,
                        scenario_sources[root_id]["json_pointer"] + "/expansion",
                        "Required descendant unit cannot be materialized after complete prerequisite union",
                        removed_units[identity]["scenario_id"],
                    )
                    for identity in trace["execution_unit_ids"]
                    if identity in removed_units
                ]
                trace["unresolved_declarations"] = _release_unique_json_rows(
                    trace["unresolved_declarations"] + removal_causes
                )
                trace["execution_unit_ids"] = [
                    identity for identity in trace["execution_unit_ids"] if identity in all_units
                ]
                reached_sources = [step["source_declaration"] for step in trace["steps"]]
                trace["unresolved_declarations"] = _release_unique_json_rows(
                    trace["unresolved_declarations"]
                    + [
                        row
                        for selected_slot, selected_phase, row in late_unknown
                        if selected_slot == slot_result["milestone"]
                        and selected_phase == trace_phase
                        and row["source_declaration"] in reached_sources
                    ]
                )
    graph = {
        "release_slots": slot_results,
        "execution_units": [all_units[k] for k in sorted(all_units)],
        "unresolved_declarations": _release_unique_json_rows(unknown),
    }
    _release_catalog_complete_slot_coverage(graph, declarations)
    return graph


def _release_scenario_catalog_data(
    registries: Mapping[str, bytes],
    *,
    expected_registry_digests: Mapping[str, str],
    run_id: str,
    producer_intent_digest: str,
) -> dict[str, Any]:
    """Build the complete acyclic catalog from three separately bound raw owners.

    Unresolved work stays explicit. This projection proves neither native source
    authority nor execution and cannot replace the gate's complete input proof,
    applicable-coverage admission or its original two-output producer journal.
    """
    owners = set(_RELEASE_EXECUTION_REGISTRIES.values())
    if set(registries) != owners or set(expected_registry_digests) != owners:
        raise ReleaseControlError("scenario catalog has an incomplete original registry set")
    for name in sorted(owners):
        if sha256_bytes(registries[name]) != _require_digest(
            expected_registry_digests[name], "original scenario catalog registry"
        ):
            raise ReleaseControlError("scenario catalog original registry bytes changed: " + name)
    if (
        not isinstance(run_id, str)
        or re.fullmatch(r"[A-Za-z0-9][A-Za-z0-9._:/-]{0,159}", run_id, re.ASCII) is None
    ):
        raise ReleaseControlError("scenario catalog run identity is invalid")
    parsed, declarations = _release_catalog_declarations(registries)
    data: dict[str, Any] = {
        "declarations": declarations,
        "environment_registry_digest": expected_registry_digests[
            _RELEASE_EXECUTION_REGISTRIES["environments"]
        ],
        "expansion_contract": "metriplane.scenario-expansion.v1",
        "invocation_root_locator": "invocations",
        "obligation_registry_digest": expected_registry_digests[
            _RELEASE_EXECUTION_REGISTRIES["obligations"]
        ],
        "producer_intent_digest": _require_digest(
            producer_intent_digest, "catalog producer intent"
        ),
        "run_id": run_id,
        "scenario_registry_digest": expected_registry_digests[
            _RELEASE_EXECUTION_REGISTRIES["scenarios"]
        ],
        **_release_catalog_graph(parsed, declarations),
    }
    data["catalog_digest"] = sha256_json(data)
    return data


def _release_scenario_catalog_replay(
    record: Mapping[str, Any],
    registries: Mapping[str, bytes],
    *,
    expected_registry_digests: Mapping[str, str],
    run_id: str,
    producer_intent_digest: str,
    synthetic: bool,
) -> dict[str, Any]:
    """Recompute all catalog fields; the gate pair separately proves its journal."""
    validate_record(record, "release-scenario-catalog")
    if record["status"] != "PASS" or record["synthetic"] is not synthetic:
        raise ReleaseControlError("scenario catalog has a different result or authority mode")
    actual = _release_scenario_catalog_data(
        registries,
        expected_registry_digests=expected_registry_digests,
        run_id=run_id,
        producer_intent_digest=producer_intent_digest,
    )
    if canonical_json(record["data"]) != canonical_json(actual):
        raise ReleaseControlError("scenario catalog differs from complete original declarations")
    return actual


def _release_catalog_complete_slot_coverage(
    graph: dict[str, Any],
    declarations: Mapping[str, list[dict[str, Any]]],
) -> None:
    """Account for every applicable original criterion, family and explicit cell."""
    obligations = {r["value"]["id"]: r for r in declarations["obligations"]}
    scenarios = {r["value"]["id"]: r for r in declarations["scenarios"]}
    for slot in graph["release_slots"]:
        milestone = slot["milestone"]
        units = [unit for unit in graph["execution_units"] if unit["slot_milestone"] == milestone]
        required_obligations: set[str] = set()

        def is_current(first: object) -> bool:
            if first == "post-v1.0":
                return False
            if first not in MILESTONES:
                raise ReleaseControlError(
                    "catalog criterion has an unknown first-required milestone"
                )
            return MILESTONES.index(str(first)) <= MILESTONES.index(milestone)

        def missing(
            declaration: dict[str, Any],
            field: str,
            reason: str,
            dependency: str | None,
            phases: set[str],
        ) -> None:
            value = declaration["value"]
            row = {
                "source_declaration": declaration["source"],
                "stable_id": value.get("id", value.get("criterion_id")),
                "field_pointer": declaration["source"]["json_pointer"] + "/" + field,
                "unresolved_dependency_id": dependency,
                "reason": reason,
            }
            graph["unresolved_declarations"] = _release_unique_json_rows(
                graph["unresolved_declarations"] + [row]
            )
            for phase in sorted(phases):
                for trace in slot["expansions"][phase]:
                    trace["unresolved_declarations"] = _release_unique_json_rows(
                        trace["unresolved_declarations"] + [row]
                    )

        for environment in declarations["environments"]:
            row = environment["value"]
            if row.get("declaration") != "REQUIRED":
                continue
            if not is_current(row.get("first_required_release")):
                continue
            # The governed floor is selected before null/missing profile facts;
            # an unbound current macOS minor cannot disappear from qualification.
            if row.get("profile_id") is None or row["execution"].get("state") == "UNRESOLVED":
                for components in (
                    ("profile_id",),
                    ("platform", "os_release"),
                    ("platform", "architecture"),
                    ("runtime", "implementation"),
                    ("runtime", "lock_source"),
                    ("runtime", "dependency_extras"),
                    ("runtime", "toolchain_sources"),
                    ("runtime", "dependency_groups"),
                ):
                    value: Any = row
                    for component in components:
                        value = value.get(component) if isinstance(value, dict) else None
                    if value is None or (
                        components[-1] in {"toolchain_sources", "dependency_groups"} and value == []
                    ):
                        missing(
                            environment,
                            "/".join(components),
                            "Current required environment lacks an original configuration fact",
                            row["id"],
                            {"qualification"},
                        )
                missing(
                    environment,
                    "execution",
                    "Current required environment remains explicitly unresolved",
                    row["id"],
                    {"qualification"},
                )
            elif not any(
                unit["phase"] == "qualification"
                and unit["environment_id"] == row["id"]
                and unit["profile_id"] == row["profile_id"]
                for unit in units
            ):
                missing(
                    environment,
                    "execution",
                    "Current required environment has no configured qualification unit",
                    row["id"],
                    {"qualification"},
                )

        for criterion in declarations["criteria"]:
            row = criterion["value"]
            if not is_current(row["first_required_release"]):
                continue
            families = set(
                _release_id_list(row["required_family_ids"], "criterion families", nonempty=True)
            )
            mapping = row["mapping"]
            if mapping.get("state") == "UNRESOLVED":
                missing(
                    criterion,
                    "mapping",
                    "Applicable criterion coverage is explicitly unresolved",
                    None,
                    {"qualification"},
                )
                continue
            _release_closed_mapping(mapping, {"state", "obligation_ids"}, "criterion mapping")
            if mapping["state"] != "MAPPED":
                raise ReleaseControlError("unsupported criterion coverage mapping")
            selected: set[str] = set()
            for identity in _release_id_list(
                mapping["obligation_ids"], "criterion obligations", nonempty=True
            ):
                selected.update(
                    _release_catalog_resolve_obligations(
                        {key: declaration["value"] for key, declaration in obligations.items()},
                        [identity],
                        milestone,
                    )
                )
            required_obligations.update(selected)
            covered: set[str] = set()
            for identity in selected:
                obligation = obligations[identity]["value"]
                if obligation["implementation"].get("state") == "UNRESOLVED":
                    continue
                if row["criterion_id"] not in obligation["criterion_ids"]:
                    raise ReleaseControlError("criterion/obligation coverage is not reciprocal")
                if any(identity in unit["obligation_ids"] for unit in units):
                    covered.update(obligation["family_ids"])
            if not families <= covered:
                missing(
                    criterion,
                    "required_family_ids",
                    "Applicable criterion lacks configured witnesses for every required family",
                    None,
                    {"qualification"},
                )

        for identity, declaration in obligations.items():
            row = declaration["value"]
            if row["lifecycle"] != "active" or not is_current(row["first_required_release"]):
                continue
            required_obligations.add(identity)
        for identity in sorted(required_obligations):
            declaration = obligations[identity]
            row = declaration["value"]
            dimensions = (
                "criterion_ids",
                "family_ids",
                "environment_ids",
                "profile_ids",
                "scenario_ids",
            )
            absent = [field for field in dimensions if row[field] == []]
            if absent:
                if row["implementation"].get("state") != "UNRESOLVED":
                    raise ReleaseControlError(
                        "configured obligation contains an empty required mapping"
                    )
                # Applicability was established above using the independently
                # checked owner/BOM milestone before any of these empty mappings.
                for field in absent:
                    missing(
                        declaration,
                        field,
                        "Applicable obligation has an explicitly unresolved " + field + " mapping",
                        identity,
                        set(_RELEASE_PHASES),
                    )
                continue
            scenario_ids = _release_id_list(
                row["scenario_ids"], "baseline obligation scenarios", nonempty=True
            )
            if any(name not in scenarios for name in scenario_ids):
                raise ReleaseControlError("baseline obligation names an undeclared scenario")
            phases = {scenarios[name]["value"]["phase"] for name in scenario_ids}
            witnesses = [unit for unit in units if identity in unit["obligation_ids"]]
            expected_environments = set(
                _release_id_list(row["environment_ids"], "obligation environments", nonempty=True)
            )
            expected_profiles = set(
                _release_id_list(row["profile_ids"], "obligation profiles", nonempty=True)
            )
            if (
                not witnesses
                or not expected_environments <= {u["environment_id"] for u in witnesses}
                or not expected_profiles <= {u["profile_id"] for u in witnesses}
            ):
                missing(
                    declaration,
                    "implementation",
                    "Applicable obligation lacks its complete environment/profile projection coverage",
                    identity,
                    phases,
                )


def _release_catalog_resolve_obligations(
    obligations: Mapping[str, Mapping[str, Any]],
    identities: object,
    milestone: str,
) -> set[str]:
    """Resolve one current static mapping; original supersession authority is separate."""
    if milestone not in MILESTONES:
        raise ReleaseControlError("obligation mapping has an unknown selected milestone")
    active: set[str] = set()

    def resolve(identity: str) -> set[str]:
        if identity not in obligations or identity in active:
            raise ReleaseControlError("unknown or cyclic obligation supersession")
        row = obligations[identity]
        first = row["first_required_release"]
        if first == "post-v1.0":
            return set()
        if first not in MILESTONES:
            raise ReleaseControlError("obligation has an unknown first-required milestone")
        if MILESTONES.index(first) > MILESTONES.index(milestone):
            return set()
        active.add(identity)
        if row["lifecycle"] == "active":
            if row["superseded_by"] or row["supersession_authority"]:
                raise ReleaseControlError("active obligation carries an unexplained supersession")
            result = {identity}
        elif row["lifecycle"] == "retired_with_reviewed_supersession":
            if not row["supersession_authority"]:
                raise ReleaseControlError("retired obligation lacks reviewed supersession")
            result = set()
            for successor in _release_id_list(row["superseded_by"], "supersession", nonempty=True):
                result.update(resolve(successor))
            if not result:
                raise ReleaseControlError(
                    "applicable retired obligation has no current replacement"
                )
        else:
            raise ReleaseControlError("unsupported obligation lifecycle")
        active.remove(identity)
        return result

    selected: set[str] = set()
    for identity in _release_id_list(identities, "required obligations", nonempty=True):
        selected.update(resolve(identity))
    return selected


def _release_original_packet(raw: bytes, *, expected_digest: str) -> dict[str, Any]:
    """Replay bytes against the caller's separately authenticated packet binding."""
    if sha256_bytes(raw) != _require_digest(expected_digest, "expected original packet"):
        raise ReleaseControlError("original planning packet differs from expected authority")
    return _source_json(raw, "original planning packet")


def _release_readiness_catalog_projection(
    registry: Mapping[str, Any], *, original_packet: bytes, expected_packet_digest: str
) -> dict[str, Any]:
    """Keep original planning membership separate from current provider observations."""
    packet = _release_original_packet(original_packet, expected_digest=expected_packet_digest)
    tasks = _release_id_rows(packet.get("task_registry"), "task", "original task catalog")
    releases = _release_id_rows(packet.get("releases"), "version", "original release slots")
    if len(tasks) != 93 or list(releases) != list(MILESTONES):
        raise ReleaseControlError("original planning membership is not complete")
    identifiers = [row.get("linear_issue") for row in tasks.values()]
    _release_id_list(identifiers, "original catalog issue identities", nonempty=True)
    fields = (
        "version",
        "linear_milestone_id",
        "release_decision_task",
        "linear_release_decision_issue",
        "required_development_tasks",
        "required_scenario_ids",
        "qualification_scenario_ids",
        "publication_reconciliation_scenario_ids",
        "postpublication_scenario_ids",
        "qualification_attempts_required",
    )
    projected_slots = []
    for milestone, row in releases.items():
        if any(field not in row for field in fields):
            raise ReleaseControlError("original release slot projection is incomplete")
        slot = {field: row[field] for field in fields}
        decision = tasks.get(slot["release_decision_task"])
        if (
            decision is None
            or decision.get("role") != "release_decision"
            or decision.get("linear_issue") != slot["linear_release_decision_issue"]
            or decision.get("first_required_release") != milestone
        ):
            raise ReleaseControlError("original release slot decision differs from its task")
        required = _release_id_list(
            slot["required_development_tasks"], "original development membership", nonempty=True
        )
        if any(identity not in tasks for identity in required):
            raise ReleaseControlError("original slot names an unknown development task")
        roots = []
        for phase in _RELEASE_PHASES:
            roots.extend(
                _release_id_list(
                    slot[phase + "_scenario_ids"],
                    "original phase membership",
                    nonempty=phase == "qualification",
                )
            )
        if canonical_json(roots) != canonical_json(slot["required_scenario_ids"]):
            raise ReleaseControlError("original complete scenario and phase memberships differ")
        attempts = slot["qualification_attempts_required"]
        if type(attempts) is not int or attempts != (3 if milestone in {"v0.9", "v1.0"} else 1):
            raise ReleaseControlError("original qualification repetition requirement differs")
        projected_slots.append(slot)
    projected_tasks = list(tasks.values())
    if canonical_json(registry.get("task_catalog")) != canonical_json(
        projected_tasks
    ) or canonical_json(registry.get("release_gate_slots")) != canonical_json(projected_slots):
        raise ReleaseControlError("readiness registry changed the original complete catalog")
    binding = _release_closed_mapping(
        registry.get("catalog_binding"),
        {"source", "task_registry_sha256", "release_slots_sha256", "snapshot_role"},
        "readiness planning binding",
    )
    reference = _release_closed_mapping(
        binding["source"], {"path", "bytes", "sha256"}, "readiness original packet reference"
    )
    _release_relative_suffix(reference["path"], "readiness original packet path")
    if (
        type(reference["bytes"]) is not int
        or reference["bytes"] != len(original_packet)
        or reference["sha256"] != expected_packet_digest
        or binding["snapshot_role"] != "UNCHANGED_PLANNING_AUTHORITY_NOT_CURRENT_PROVIDER_FACTS"
        or binding["task_registry_sha256"] != sha256_json(projected_tasks)
        or binding["release_slots_sha256"] != sha256_json(projected_slots)
    ):
        raise ReleaseControlError("readiness planning binding differs from original bytes")
    return {"task_catalog": projected_tasks, "release_gate_slots": projected_slots}


def _release_obligation_criterion_projection(
    registry: Mapping[str, Any], *, original_packet: bytes, expected_packet_digest: str
) -> dict[str, dict[str, Any]]:
    """Recompute every exact predicate and family set, including future requirements."""
    packet = _release_original_packet(original_packet, expected_digest=expected_packet_digest)
    tasks = _release_id_rows(packet.get("tasks"), "task_id", "original work orders")
    actual = _release_id_rows(
        registry.get("criterion_requirements"), "criterion_id", "criterion requirements"
    )
    families = packet.get("test_family_definitions")
    if len(tasks) != 93 or not isinstance(families, dict) or len(families) != 19:
        raise ReleaseControlError("original complete task/family authority is incomplete")
    expected = {}
    for task_id, task in tasks.items():
        first = task.get("first_required_release")
        if first not in (*MILESTONES, "post-v1.0"):
            raise ReleaseControlError("original work order has an unknown release boundary")
        predicates = _release_id_rows(
            task.get("task_specific_acceptance_predicates"), "criterion_id", "original predicates"
        )
        if not predicates:
            raise ReleaseControlError("original work order has no acceptance predicates")
        for criterion_id, predicate in predicates.items():
            if criterion_id in expected or not criterion_id.startswith(task_id + ".A"):
                raise ReleaseControlError("original criterion identity has conflicting ownership")
            text = predicate.get("predicate")
            if not isinstance(text, str) or not text.strip():
                raise ReleaseControlError("original acceptance predicate is empty")
            required = _release_id_list(
                predicate.get("required_test_family_ids"),
                "original required families",
                nonempty=True,
            )
            if any(family not in families for family in required):
                raise ReleaseControlError("original criterion names an unknown test family")
            expected[criterion_id] = {
                "task_id": task_id,
                "criterion_id": criterion_id,
                "predicate": text,
                "predicate_digest": sha256_json(text),
                "first_required_release": first,
                "required_family_ids": required,
            }
    if len(expected) != 280 or set(actual) != set(expected):
        raise ReleaseControlError("criterion registry omits or adds original acceptance work")
    for criterion_id, projection in expected.items():
        row = actual[criterion_id]
        if canonical_json({k: row.get(k) for k in projection}) != canonical_json(projection):
            raise ReleaseControlError("criterion registry changed an original predicate/family")
    return expected


def _release_configuration_source(
    value: object,
    *,
    containing_path: Path,
    containing_kind: str,
    field: Sequence[str | int],
    captured: _ReleaseCapturedFiles,
    expected_sources: Mapping[str, Mapping[str, Any]],
) -> bytes:
    """Replay a raw configuration field against independent source expectations.

    The native caller owns expected_sources through its approved source/context
    proof. Neither this reference nor this byte check establishes that authority.
    """
    if containing_kind != "environment-registry":
        raise ReleaseControlError(
            "configuration field requires its exact environment registry owner"
        )
    if len(field) < 3 or field[0] != "environments" or type(field[1]) is not int:
        raise ReleaseControlError("configuration reference has no environment field owner")
    role = tuple(field[2:])
    if len(role) == 2 and role[0] == "authority" and type(role[1]) is int:
        allowed = {".github/workflows/ci.yml"}
    elif len(role) == 3 and role[:2] == ("runtime", "toolchain_sources") and type(role[2]) is int:
        allowed = {".github/workflows/ci.yml", "pyproject.toml"}
    elif role == ("runtime", "lock_source"):
        allowed = {"uv.lock"}
    elif (
        len(role) == 3
        and role[:2] == ("execution", "configuration_sources")
        and type(role[2]) is int
    ):
        allowed = {".github/workflows/ci.yml", "pyproject.toml", "uv.lock"}
    else:
        raise ReleaseControlError("configuration reference has an unknown field role")
    row = _release_closed_mapping(
        value,
        {"binding", "repository", "path", "git_blob", "git_mode", "source_bytes"},
        "configuration source",
    )
    if (
        row["binding"] != "candidate_source_blob"
        or not isinstance(row["path"], str)
        or row["path"] not in allowed
    ):
        raise ReleaseControlError("configuration source kind/path differs from its field owner")
    expected = expected_sources.get(row["path"])
    expected_keys = {"repository", "path", "git_blob", "git_mode", "bytes", "sha256"}
    if expected is None or set(expected) != expected_keys:
        raise ReleaseControlError("configuration source has no independent expected identity")
    _release_relative_suffix(expected["path"], "expected configuration path")
    if (
        expected["path"] != row["path"]
        or expected["repository"] != "Miko997/metriplane"
        or expected["git_mode"] not in {"100644", "100755"}
        or not isinstance(expected["git_blob"], str)
        or re.fullmatch(r"[0-9a-f]{40}", expected["git_blob"], flags=re.ASCII) is None
        or type(expected["bytes"]) is not int
        or expected["bytes"] < 0
    ):
        raise ReleaseControlError("configuration expected source identity is invalid")
    _require_digest(expected["sha256"], "expected configuration raw digest")
    identity_fields = ("repository", "path", "git_blob", "git_mode")
    if canonical_json({key: row[key] for key in identity_fields}) != canonical_json(
        {key: expected[key] for key in identity_fields}
    ):
        raise ReleaseControlError("configuration source differs from independent expected identity")
    # Check the whole reference in its original field, not only the nested R pointer.
    container = _release_capture_absolute(containing_path)
    try:
        name = container.relative_to(captured.root).as_posix()
    except ValueError as exc:
        raise ReleaseControlError("configuration declaring record escapes captured root") from exc
    document = _source_json(captured.read(name, kind=containing_kind), "configuration registry")
    pointer = "/" + "/".join(str(part).replace("~", "~0").replace("/", "~1") for part in field)
    if canonical_json(
        _release_json_pointer(document, pointer, "configuration field")
    ) != canonical_json(row):
        raise ReleaseControlError("configuration source is not its captured original field")
    _, raw = _release_captured_raw_file(
        row["source_bytes"],
        containing_path=container,
        containing_kind=containing_kind,
        field=(*field, "source_bytes"),
        captured=captured,
        expected_kind="configuration-source",
        label="configuration source bytes",
    )
    git_blob = hashlib.sha1(
        b"blob " + str(len(raw)).encode("ascii") + b"\0" + raw, usedforsecurity=False
    ).hexdigest()
    if (
        len(raw) != expected["bytes"]
        or sha256_bytes(raw) != expected["sha256"]
        or git_blob != expected["git_blob"]
    ):
        raise ReleaseControlError(
            "configuration raw bytes differ from independent expected identity"
        )
    return raw


def _release_workflow_declaration(raw: bytes) -> dict[str, Any]:
    """Read the finite YAML declaration without constructors, duplicate keys or aliases."""
    import yaml

    try:
        node = yaml.compose(raw, Loader=yaml.BaseLoader)
        seen: set[int] = set()

        def value(current: yaml.Node, depth: int = 0) -> Any:
            if depth > 64 or id(current) in seen:
                raise ReleaseControlError(
                    "configuration YAML aliases or excessive depth are forbidden"
                )
            seen.add(id(current))
            if isinstance(current, yaml.ScalarNode) and current.tag == "tag:yaml.org,2002:str":
                return current.value
            if isinstance(current, yaml.SequenceNode) and current.tag == "tag:yaml.org,2002:seq":
                return [value(child, depth + 1) for child in current.value]
            if isinstance(current, yaml.MappingNode) and current.tag == "tag:yaml.org,2002:map":
                result: dict[str, Any] = {}
                for key, child in current.value:
                    name = value(key, depth + 1)
                    if not isinstance(name, str) or name in result or name == "<<":
                        raise ReleaseControlError(
                            "configuration YAML has duplicate or non-string keys"
                        )
                    result[name] = value(child, depth + 1)
                return result
            raise ReleaseControlError("configuration YAML contains an unsupported node or tag")

        parsed = value(node) if node is not None else None
    except (yaml.YAMLError, UnicodeError, ValueError, RecursionError) as exc:
        raise ReleaseControlError("configuration workflow cannot be parsed") from exc
    if not isinstance(parsed, dict):
        raise ReleaseControlError("configuration workflow must be a mapping")
    return parsed


def _release_current_environment_floor(configuration: Mapping[str, bytes]) -> list[dict[str, Any]]:
    """Project only existing governed jobs; floating runner labels are not image proof."""
    if set(configuration) != {".github/workflows/ci.yml", "pyproject.toml", "uv.lock"}:
        raise ReleaseControlError(
            "current environment floor has an incomplete configuration closure"
        )
    _validate_source_build_metadata(configuration["pyproject.toml"], configuration["uv.lock"])
    workflow = _release_workflow_declaration(configuration[".github/workflows/ci.yml"])
    try:
        project = tomllib.loads(configuration["pyproject.toml"].decode())
        lock = tomllib.loads(configuration["uv.lock"].decode())
        if (
            project["project"]["requires-python"].replace(" ", "") != ">=3.12,<3.14"
            or lock["requires-python"].replace(" ", "") != ">=3.12,<3.14"
        ):
            raise ReleaseControlError("current environment floor differs from Python source policy")
        jobs = workflow["jobs"]
        result = []
        for job_id, family, minors, label in (
            ("test", "linux", ["3.12"], "ubuntu-latest"),
            ("linux-python313", "linux", ["3.13"], "ubuntu-latest"),
            ("macos-regressions", "macos", ["3.12", "3.13"], "macos-latest"),
        ):
            job = jobs[job_id]
            if job["runs-on"] != label:
                raise ReleaseControlError("current environment runner differs from governed job")
            version = "${{ matrix.python-version }}" if family == "macos" else minors[0]
            setup = [
                step
                for step in job["steps"]
                if re.fullmatch(r"actions/setup-python@[0-9a-f]{40}", step.get("uses", ""))
            ]
            if len(setup) != 1 or setup[0]["with"]["python-version"] != version:
                raise ReleaseControlError("current environment Python differs from governed job")
            if family == "macos" and job["strategy"]["matrix"] != {
                "python-version": minors,
                "shard-index": ["0", "1", "2", "3"],
            }:
                raise ReleaseControlError(
                    "current macOS matrix differs from the complete eight-shard floor"
                )
            commands = [" ".join(step["run"].split()) for step in job["steps"] if "run" in step]
            suffix = "" if job_id == "test" else " --python " + version
            if "uv sync --locked --group dev" + suffix not in commands:
                raise ReleaseControlError(
                    "current environment locked installation differs from governed job"
                )
            index, count = ("${{ matrix.shard-index }}", "4") if family == "macos" else ("0", "1")
            command = (
                "uv run --frozen"
                + suffix
                + " python tools/check_required_terminal.py shard-run"
                + " --platform "
                + family
                + " --python-version "
                + version
                + " --shard-index "
                + index
                + " --shard-count "
                + count
                + ' --report-dir "$RUNNER_TEMP/ci-suite"'
            )
            if command not in commands:
                raise ReleaseControlError(
                    "current environment complete-suite command differs from governed job"
                )
            for minor in minors:
                result.append(
                    {
                        "id": "current-ci-" + family + "-py" + minor.replace(".", ""),
                        "job_id": job_id,
                        "os_family": family,
                        "runner_kind": "github-hosted",
                        "runner_labels": [label],
                        "python_minor": minor,
                        "implementation": "CPython",
                        "dependency_groups": ["dev"],
                        "dependency_extras": [],
                    }
                )
        return result
    except (KeyError, TypeError, AttributeError, UnicodeError, tomllib.TOMLDecodeError) as exc:
        raise ReleaseControlError("current environment configuration is incomplete") from exc


def _release_environment_floor_projection(
    registry: Mapping[str, Any],
    *,
    containing_path: Path,
    captured: _ReleaseCapturedFiles,
    expected_sources: Mapping[str, Mapping[str, Any]],
) -> list[dict[str, Any]]:
    """Replay each configuration role and retain every governed current CI cell."""
    container = _release_capture_absolute(containing_path)
    try:
        name = container.relative_to(captured.root).as_posix()
    except ValueError as exc:
        raise ReleaseControlError("environment registry escapes captured root") from exc
    original = _source_json(
        captured.read(name, kind="environment-registry"), "environment registry"
    )
    if canonical_json(registry) != canonical_json(original):
        raise ReleaseControlError(
            "environment projection differs from its captured original registry"
        )
    registry = original
    configuration: dict[str, bytes] = {}
    rows = _release_id_rows(registry["environments"], "id", "environment floor")
    positions = {row["id"]: index for index, row in enumerate(registry["environments"])}
    raw_rows = set()
    for identity, row in rows.items():
        index = positions[identity]
        fields: list[tuple[tuple[str | int, ...], Any]] = [
            (("authority", position), source) for position, source in enumerate(row["authority"])
        ]
        runtime = row["runtime"]
        fields.extend(
            (("runtime", "toolchain_sources", position), source)
            for position, source in enumerate(runtime["toolchain_sources"])
        )
        fields.append((("runtime", "lock_source"), runtime["lock_source"]))
        if row["execution"]["state"] == "CONFIGURED":
            fields.extend(
                (("execution", "configuration_sources", position), source)
                for position, source in enumerate(row["execution"]["configuration_sources"])
            )
        for field, source in fields:
            if not isinstance(source, dict) or "binding" not in source:
                continue  # Original JSON C links have their separate authority owner.
            raw = _release_configuration_source(
                source,
                containing_path=containing_path,
                containing_kind="environment-registry",
                field=("environments", index, *field),
                captured=captured,
                expected_sources=expected_sources,
            )
            if field[0] == "authority":
                raw_rows.add(identity)
            if source["path"] in configuration and configuration[source["path"]] != raw:
                raise ReleaseControlError("environment configuration references conflict")
            configuration[source["path"]] = raw
    floor = _release_current_environment_floor(configuration)
    if raw_rows != {row["id"] for row in floor}:
        raise ReleaseControlError(
            "environment registry omits or relabels a governed CI requirement"
        )
    result = []
    for required in floor:
        row = rows[required["id"]]
        if row["declaration"] != "REQUIRED" or row["first_required_release"] != "v0.4":
            raise ReleaseControlError("current required environment was demoted or deferred")
        for section, names in (
            ("platform", ("os_family", "runner_kind", "runner_labels")),
            (
                "runtime",
                ("python_minor", "implementation", "dependency_groups", "dependency_extras"),
            ),
        ):
            if canonical_json({key: row[section][key] for key in names}) != canonical_json(
                {key: required[key] for key in names}
            ):
                raise ReleaseControlError(
                    "environment declaration differs from its original configuration"
                )
        if (
            len(row["authority"]) != 1
            or [source.get("path") for source in row["runtime"]["toolchain_sources"]]
            != ["pyproject.toml", ".github/workflows/ci.yml"]
            or not isinstance(row["runtime"]["lock_source"], dict)
            or row["runtime"]["lock_source"].get("path") != "uv.lock"
        ):
            raise ReleaseControlError(
                "environment floor lacks its complete field-owned source bindings"
            )
        result.append(
            {
                **required,
                "source_declaration": {
                    "raw_registry_path": _RELEASE_EXECUTION_REGISTRIES["environments"],
                    "json_pointer": "/environments/" + str(positions[row["id"]]),
                    "canonical_subject_digest": sha256_json(row),
                },
            }
        )
    captured.revalidate()
    return result


def _release_linear_wire_identity(value: object) -> dict[str, Any]:
    if not isinstance(value, dict) or not {"id", "uuid", "projectId", "teamId"} <= value.keys():
        raise ReleaseControlError("Linear wire identity omits an explicit provider field")
    return _release_linear_identity(
        {
            "provider": "linear",
            "issue_identifier": value["id"],
            "issue_id": value["uuid"],
            "project_id": value["projectId"],
            "team_id": value["teamId"],
        }
    )


def _release_linear_wire_fields(value: object) -> dict[str, Any]:
    """Missing nullable fields stay blocked until their transport semantics are proven."""
    if not isinstance(value, dict) or not set(_RELEASE_LINEAR_INDEX_FIELDS) <= value.keys():
        raise ReleaseControlError("Linear wire omits required or explicit nullable fields")
    _release_linear_wire_identity(value)
    for key in ("title", "status", "statusType"):
        _require_nonempty_string(value[key], "Linear wire " + key)
    if not isinstance(value["description"], str):
        raise ReleaseControlError("Linear wire description is not complete text")
    for key in ("assigneeId", "parentId"):
        if value[key] is not None:
            _release_linear_uuid(value[key], "Linear wire " + key)
    for key in ("createdAt", "updatedAt", "archivedAt", "completedAt", "startedAt", "canceledAt"):
        if key in {"createdAt", "updatedAt"} or value[key] is not None:
            _parse_utc_timestamp(value[key], "Linear wire " + key)
    milestone = value["projectMilestone"]
    if milestone is not None:
        if not isinstance(milestone, dict) or not {"id", "name"} <= milestone.keys():
            raise ReleaseControlError("Linear wire milestone identity is incomplete")
        _release_linear_uuid(milestone["id"], "Linear wire milestone")
        _require_nonempty_string(milestone["name"], "Linear wire milestone name")
        if value["projectId"] is None:
            raise ReleaseControlError("Linear milestone has no owning project")
    return {key: value[key] for key in _RELEASE_LINEAR_INDEX_FIELDS}


def _release_linear_round_projection(
    payloads: Mapping[str, Mapping[str, Any]],
    *,
    round_number: int,
    root_project_ids: frozenset[str],
    root_issue_ids: frozenset[str],
) -> dict[str, Any]:
    """Replay one whole wire graph. Call only after original-byte observation validation."""
    if (
        type(round_number) is not int
        or round_number not in {1, 2}
        or not root_project_ids
        or not root_issue_ids
    ):
        raise ReleaseControlError("Linear replay lacks independently bound round roots")
    for key in root_project_ids | root_issue_ids:
        _release_linear_uuid(key, "Linear round root")
    pages: dict[str, dict[str | None, Mapping[str, Any]]] = {}
    details: dict[str, Mapping[str, Any]] = {}
    statuses: dict[str, Mapping[str, Any]] = {}
    milestones: dict[str, Mapping[str, Any]] = {}
    for member in payloads.values():
        observation = member["observation"]
        if observation["round"] != round_number:
            continue
        arguments, tool = observation["arguments"], observation["tool"]
        if tool == "mcp__codex_apps__linear_list_issues":
            project, request_cursor = arguments["project"], arguments.get("cursor")
            destination = pages.setdefault(project, {})
            if request_cursor in destination:
                raise ReleaseControlError("Linear round repeats a project cursor")
            destination[request_cursor] = member
        else:
            if tool == "mcp__codex_apps__linear_get_issue":
                target, target_map = arguments["id"], details
            elif tool == "mcp__codex_apps__linear_list_issue_statuses":
                target, target_map = arguments["team"], statuses
            elif tool == "mcp__codex_apps__linear_list_milestones":
                target, target_map = arguments["project"], milestones
            else:
                raise ReleaseControlError("Linear round contains an unowned observation")
            if target in target_map:
                raise ReleaseControlError("Linear round repeats a detail or dictionary read")
            target_map[target] = member
    if set(pages) != root_project_ids:
        raise ReleaseControlError("Linear round omits or adds a governed project scan")
    identities: dict[str, dict[str, Any]] = {}
    identifiers: dict[str, str] = {}
    by_id: dict[str, Mapping[str, Any]] = {}
    for identifier, member in details.items():
        identity = _release_linear_wire_identity(member["payload"])
        issue_id = identity["issue_id"]
        if identity["issue_identifier"] != identifier or issue_id in identities:
            raise ReleaseControlError("Linear detail aliases its requested identifier or UUID")
        identities[issue_id], identifiers[identifier], by_id[issue_id] = identity, issue_id, member
    if not root_issue_ids <= identities.keys():
        raise ReleaseControlError("Linear round lacks a directly requested catalogue/context root")
    scans, index_rows, index_ids = [], {}, {}
    for project in sorted(pages):
        remaining = dict(pages[project])
        cursor: str | None = None
        seen_cursors: set[str] = set()
        page_ids, issue_ids = [], []
        previous_end: datetime | None = None
        while True:
            if cursor not in remaining:
                raise ReleaseControlError("Linear project scan lacks its initial or next page")
            member = remaining.pop(cursor)
            observation, body = member["observation"], member["payload"]
            if (
                not isinstance(body, dict)
                or "hasNextPage" not in body
                or type(body["hasNextPage"]) is not bool
            ):
                raise ReleaseControlError("Linear project response has no exact pagination verdict")
            expected_keys = {"issues", "hasNextPage"} | (
                {"cursor"} if body["hasNextPage"] else set()
            )
            _release_closed_mapping(body, expected_keys, "Linear project page")
            rows = body["issues"]
            if not isinstance(rows, list) or len(rows) > 250 or (body["hasNextPage"] and not rows):
                raise ReleaseControlError("Linear project page is malformed or truncated")
            page_start = _parse_utc_timestamp(observation["started_at"], "Linear page start")
            if previous_end is not None and previous_end > page_start:
                raise ReleaseControlError("Linear next page starts before its cursor was observed")
            previous_end = _parse_utc_timestamp(
                observation["completed_at"], "Linear page completion"
            )
            page_ids.append(observation["id"])
            for value in rows:
                fields = _release_linear_wire_fields(value)
                issue_id = fields["uuid"]
                if (
                    fields["projectId"] != project
                    or issue_id in index_rows
                    or issue_id not in identities
                    or canonical_json(_release_linear_wire_identity(fields))
                    != canonical_json(identities[issue_id])
                ):
                    raise ReleaseControlError(
                        "Linear project index repeats, omits or misassigns a detail identity"
                    )
                index_rows[issue_id] = fields
                index_ids[issue_id] = [observation["id"]]
                issue_ids.append(issue_id)
            if not body["hasNextPage"]:
                if remaining:
                    raise ReleaseControlError("Linear project scan has orphaned extra pages")
                break
            cursor = _require_nonempty_string(body["cursor"], "Linear next cursor")
            if cursor in seen_cursors:
                raise ReleaseControlError("Linear project cursor loops")
            seen_cursors.add(cursor)
        scans.append(
            {
                "project_id": project,
                "round": round_number,
                "page_observation_ids": page_ids,
                "issue_ids": sorted(issue_ids),
                "terminal_has_next_page": False,
            }
        )

    for issue_id, identity in identities.items():
        if identity["project_id"] in root_project_ids and issue_id not in index_rows:
            raise ReleaseControlError(
                "Linear original detail identity is absent from its governed full project index"
            )

    def endpoints(issue_id: str) -> dict[str, Any]:
        wire = by_id[issue_id]["payload"]
        if not isinstance(wire, dict) or "relations" not in wire or "parentId" not in wire:
            raise ReleaseControlError("Linear detail lacks complete original relation fields")
        relations = _release_closed_mapping(
            wire["relations"],
            {"blocks", "blockedBy", "relatedTo", "duplicateOf"},
            "Linear wire relations",
        )

        def edge(value: object) -> dict[str, str]:
            if (
                not isinstance(value, dict)
                or not isinstance(value.get("id"), str)
                or value["id"] not in identifiers
            ):
                raise ReleaseControlError(
                    "Linear relation lacks an original endpoint identity readback"
                )
            return {"issue_id": identifiers[value["id"]], "issue_identifier": value["id"]}

        result: dict[str, Any] = {}
        for native, normalized in [
            ("blocks", "blocks"),
            ("blockedBy", "blocked_by"),
            ("relatedTo", "related_to"),
        ]:
            if not isinstance(relations[native], list):
                raise ReleaseControlError("Linear wire relation list is incomplete")
            result[normalized] = sorted(
                [edge(value) for value in relations[native]],
                key=lambda row: (row["issue_identifier"], row["issue_id"]),
            )
        result["duplicate_of"] = (
            None if relations["duplicateOf"] is None else edge(relations["duplicateOf"])
        )
        parent = wire["parentId"]
        if parent is not None:
            _release_linear_uuid(parent, "Linear parent")
            if parent not in identities:
                raise ReleaseControlError("Linear parent lacks original identity readback")
        result["parent"] = (
            None
            if parent is None
            else {key: identities[parent][key] for key in ("issue_id", "issue_identifier")}
        )
        return result

    subjects = set(root_issue_ids) | set(index_rows)
    pending = list(subjects)
    edges: dict[str, dict[str, Any]] = {}
    while pending:
        issue_id = pending.pop()
        edges[issue_id] = endpoints(issue_id)
        for value in edges[issue_id]["blocked_by"]:
            if value["issue_id"] not in subjects:
                subjects.add(value["issue_id"])
                pending.append(value["issue_id"])

    def edge_ids(value: Mapping[str, Any]) -> set[str]:
        return {
            row["issue_id"]
            for key, rows in value.items()
            for row in (
                ([] if rows is None else [rows]) if key in {"parent", "duplicate_of"} else rows
            )
        }

    boundary = set().union(*(edge_ids(value) for value in edges.values())) - subjects
    selected = subjects | boundary
    for issue_id in boundary:
        edges[issue_id] = endpoints(issue_id)
    identity_only = set().union(*(edge_ids(value) for value in edges.values())) - selected
    if set(identities) != selected | identity_only:
        raise ReleaseControlError("Linear capture contains unowned extra detail observations")
    # Identity-only lookups resolve outer references of boundary records. Their relations do
    # not recursively import unrelated projects, and they cannot become release prerequisites.
    needed_teams = {identities[key]["team_id"] for key in selected}
    needed_projects = root_project_ids | {
        identities[key]["project_id"]
        for key in selected
        if identities[key]["project_id"] is not None
    }
    if set(statuses) != needed_teams or set(milestones) != needed_projects:
        raise ReleaseControlError("Linear round dictionaries do not cover its exact teams/projects")
    team_rows, state_maps = [], {}
    for team in sorted(statuses):
        member = statuses[team]
        states = _release_id_rows(member["payload"], "id", "Linear original states")
        values = [_release_linear_state(states[key]) for key in sorted(states)]
        if not values or len({(row["name"], row["type"]) for row in values}) != len(values):
            raise ReleaseControlError("Linear team dictionary is empty or ambiguously names states")
        state_maps[team] = {(row["name"], row["type"]): row for row in values}
        team_rows.append(
            {"team_id": team, "observation_id": member["observation"]["id"], "states": values}
        )
    milestone_rows, milestone_maps = [], {}
    for project in sorted(milestones):
        member = milestones[project]
        body = _release_closed_mapping(
            member["payload"], {"milestones"}, "Linear original milestone dictionary"
        )
        members = _release_id_rows(body["milestones"], "id", "Linear original milestones")
        values = []
        for key in sorted(members):
            _release_linear_uuid(key, "Linear dictionary milestone")
            name = _require_nonempty_string(
                members[key].get("name"), "Linear dictionary milestone name"
            )
            values.append({"id": key, "name": name, "project_id": project})
        milestone_maps[project] = {row["id"]: row for row in values}
        milestone_rows.append(
            {
                "project_id": project,
                "observation_id": member["observation"]["id"],
                "milestones": values,
            }
        )
    normalized = []
    for issue_id in sorted(selected, key=lambda key: (identities[key]["issue_identifier"], key)):
        member = by_id[issue_id]
        fields = _release_linear_wire_fields(member["payload"])
        identity = identities[issue_id]
        if identity["project_id"] in root_project_ids and issue_id not in index_rows:
            raise ReleaseControlError(
                "Linear detail assigned to a root project is absent from its full index"
            )
        if issue_id in index_rows and canonical_json(fields) != canonical_json(
            index_rows[issue_id]
        ):
            raise ReleaseControlError("Linear index/detail fields drift within a capture round")
        state = state_maps[identity["team_id"]].get((fields["status"], fields["statusType"]))
        if state is None:
            raise ReleaseControlError("Linear detail state is absent from its own team dictionary")
        milestone = fields["projectMilestone"]
        if milestone is not None:
            expected = milestone_maps[identity["project_id"]].get(milestone["id"])
            if expected is None or milestone["name"] != expected["name"]:
                raise ReleaseControlError(
                    "Linear detail milestone differs from its project dictionary"
                )
            milestone = expected
        row = {
            "identity": identity,
            "title": fields["title"],
            "description": fields["description"],
            "state": state,
            "project_milestone": milestone,
            "assignee_ids": [] if fields["assigneeId"] is None else [fields["assigneeId"]],
            "detail_observation_id": member["observation"]["id"],
            "index_observation_ids": index_ids.get(issue_id, []),
            **edges[issue_id],
        }
        for native, target in [
            ("createdAt", "created_at"),
            ("updatedAt", "updated_at"),
            ("archivedAt", "archived_at"),
            ("completedAt", "completed_at"),
            ("startedAt", "started_at"),
            ("canceledAt", "canceled_at"),
        ]:
            row[target] = fields[native]
        normalized.append(row)
    _release_linear_issue_rows(normalized, root_issue_ids=frozenset(subjects))
    semantic = {
        "project_scans": [
            {"project_id": row["project_id"], "issue_ids": row["issue_ids"]} for row in scans
        ],
        "issues": [
            {
                key: value
                for key, value in row.items()
                if key not in {"detail_observation_id", "index_observation_ids"}
            }
            for row in normalized
        ],
        "team_statuses": [
            {key: value for key, value in row.items() if key != "observation_id"}
            for row in team_rows
        ],
        "project_milestones": [
            {key: value for key, value in row.items() if key != "observation_id"}
            for row in milestone_rows
        ],
        "blocking_closure_issue_ids": sorted(subjects),
        "relation_endpoint_issue_ids": sorted(boundary),
        "boundary_identity_readbacks": [identities[key] for key in sorted(identity_only)],
    }
    return {
        "project_scans": scans,
        "issues": normalized,
        "team_statuses": team_rows,
        "project_milestones": milestone_rows,
        "blocking_closure_issue_ids": sorted(subjects),
        "relation_endpoint_issue_ids": sorted(boundary),
        "semantic": semantic,
        "projection_digest": sha256_json(semantic),
    }


