def _release_original_arguments(tool: str, argv: object) -> dict[str, Any]:
    """Parse original argv using exact existing forms without process exit or IO."""
    if tool not in TOOL_CONTRACTS or not isinstance(argv, list) or not argv:
        raise ReleaseControlError("original invocation has no known command contract")
    if (
        any(
            not isinstance(value, str) or not value or any(ord(c) < 32 for c in value)
            for value in argv
        )
        or Path(argv[0]).name != tool
    ):
        raise ReleaseControlError("original invocation command identity is invalid")
    contract = TOOL_CONTRACTS[tool]
    result: dict[str, Any] = {}
    index = 1
    while index < len(argv):
        flag, separator, inline = argv[index].partition("=")
        if not flag.startswith("--") or flag[2:] not in contract.flags:
            raise ReleaseControlError("original invocation has an unknown command flag")
        name = flag[2:]
        if name in result and name not in contract.repeatable:
            raise ReleaseControlError("original invocation has a duplicate command flag")
        if name in contract.boolean:
            if separator:
                raise ReleaseControlError("original boolean invocation flag has a value")
            value: Any = True
        else:
            if separator:
                value = inline
            else:
                index += 1
                if index >= len(argv) or argv[index].startswith("--"):
                    raise ReleaseControlError("original invocation flag has no value")
                value = argv[index]
            if not value.strip():
                raise ReleaseControlError("original invocation flag has an empty value")
            if name in contract.integer:
                try:
                    value = int(value)
                except ValueError as exc:
                    raise ReleaseControlError(
                        "original invocation integer differs from worker grammar"
                    ) from exc
                if value == 0:
                    raise ReleaseControlError(
                        "original invocation zero is absent under its worker contract"
                    )
            if name in contract.choices and value not in contract.choices[name]:
                raise ReleaseControlError(
                    "original invocation value is outside its command contract"
                )
        if name in contract.repeatable:
            result.setdefault(name, []).append(value)
        else:
            result[name] = value
        index += 1
    present = frozenset(result)
    matches = [
        form
        for form in contract.forms
        if form.required <= present
        and present <= form.required | contract.optional
        and all(result[key] in values for key, values in form.equals)
    ]
    if len(matches) != 1:
        raise ReleaseControlError(
            "original invocation does not select exactly one complete command form"
        )
    return result


def _release_historical_path(value: object, cwd: Path) -> Path:
    """Resolve a lexical historical path; never inspect or open its original location."""
    if not isinstance(value, str) or any(ord(c) < 32 for c in value):
        raise ReleaseControlError("historical command path is invalid")
    if value.startswith("/"):
        return _canonical_absolute_path(value, "historical command path")
    return cwd / _release_relative_suffix(value, "historical command path")


def _release_original_invocation_binding(
    context: ReleaseInvocation,
    *,
    expected_tool: str,
    captured: _ReleaseCapturedFiles,
    output_plan: Sequence[Mapping[str, str]],
) -> tuple[Path, dict[str, Any]]:
    """Bind original complete input/output maps to one independently located current root."""
    companions = {row[2] for row in _RELEASE_GATE_PREREQUISITES.values() if row[2] is not None}
    if (
        expected_tool not in set(_RELEASE_GATE_PREREQUISITES) | companions
        or context.intent["tool"] != expected_tool
    ):
        raise ReleaseControlError("original prerequisite tool differs from its native owner")
    _release_captured_original_context(context, captured=captured)
    intent = context.intent
    arguments = _release_original_arguments(expected_tool, intent["argv"])
    cwd = _canonical_absolute_path(
        intent["environment"]["working_directory"], "original working directory"
    )
    original_directory = _release_historical_path(arguments["invocation-dir"], cwd)
    if original_directory.parts[-3:] != (
        "invocations",
        _invocation_stage(expected_tool),
        f"{intent['sequence']:03d}",
    ):
        raise ReleaseControlError("original invocation argv has a different stage/sequence")
    original_root = original_directory.parents[2]
    if (
        context.directory
        != context.root
        / "invocations"
        / _invocation_stage(expected_tool)
        / f"{intent['sequence']:03d}"
    ):
        raise ReleaseControlError("current invocation root differs from its independent placement")
    try:
        context.root.relative_to(captured.root)
    except ValueError as exc:
        raise ReleaseControlError("current prerequisite root escapes captured closure") from exc
    plan = sorted(output_plan, key=lambda row: row["path"])
    if canonical_json(intent["planned_outputs"]) != canonical_json(plan):
        raise ReleaseControlError(
            "original prerequisite output plan differs from native expectation"
        )
    contract = TOOL_CONTRACTS[expected_tool]
    if contract.output_flag is not None:
        kind = _RELEASE_GATE_PREREQUISITES[expected_tool][0]
        primary = [row for row in plan if row["schema_id"] == "metriplane." + kind + ".v1"]
        if len(primary) != 1:
            raise ReleaseControlError("original prerequisite needs one exact primary output")
        suffix = _release_relative_suffix(primary[0]["path"], "prerequisite output path")
        if _release_historical_path(arguments[contract.output_flag], cwd) != original_root / suffix:
            raise ReleaseControlError("original prerequisite output argument differs from its plan")
    elif plan:
        raise ReleaseControlError("original companion validator cannot have canonical outputs")
    seen = set()
    for row in intent["inputs"]:
        original = _canonical_absolute_path(row["path"], "original prerequisite input")
        try:
            suffix = original.relative_to(original_root)
        except ValueError as exc:
            raise ReleaseControlError(
                "original prerequisite input escapes its original root"
            ) from exc
        _release_relative_suffix(suffix.as_posix(), "original prerequisite input")
        current = context.root / suffix
        key = current.relative_to(captured.root).as_posix()
        if key in seen:
            raise ReleaseControlError("original prerequisite has duplicate input placement")
        seen.add(key)
        raw = captured.read(key, kind="prerequisite-original")
        if sha256_bytes(raw) != row["sha256"]:
            raise ReleaseControlError("original prerequisite input changed during relocation")
    captured.revalidate()
    return original_root, arguments


def _release_captured_journal_terminal(
    context: ReleaseInvocation,
    *,
    captured: _ReleaseCapturedFiles,
    require_pass: bool,
    gate_pair_owner: bool = False,
) -> dict[str, Any]:
    record = _release_captured_journal_terminal_content(
        context, captured=captured, require_pass=require_pass, gate_pair_owner=gate_pair_owner
    )
    if gate_pair_owner:
        _release_gate_terminal_commit_replay(context, record, captured=captured)
    return record


def _release_captured_original_context(
    context: ReleaseInvocation, *, captured: _ReleaseCapturedFiles
) -> None:
    """The fixed prerequisite owner set remains separate from current gate outputs."""
    allowed = set(_RELEASE_GATE_PREREQUISITES) | {
        row[2] for row in _RELEASE_GATE_PREREQUISITES.values() if row[2] is not None
    }
    if context.intent.get("tool") not in allowed:
        raise ReleaseControlError("captured prerequisite has no native command owner")
    _release_captured_command_context(
        context, captured=captured, expected_tool=context.intent["tool"]
    )


def _release_captured_command_context(
    context: ReleaseInvocation,
    *,
    captured: _ReleaseCapturedFiles,
    expected_tool: str,
) -> None:
    """Check original held intent identity for one separately selected command.

    This byte predicate neither registers a prerequisite owner nor admits a
    derived record. In particular, passing a Python context cannot replace its
    original retained intent or turn a pending invocation into a completed one.
    """
    if expected_tool not in TOOL_CONTRACTS:
        raise ReleaseControlError("captured command has no declared tool contract")
    try:
        name = (context.directory / "intent.json").relative_to(captured.root).as_posix()
    except ValueError as exc:
        raise ReleaseControlError("original command context escapes capture") from exc
    raw = captured.read(name, kind="prerequisite-original")
    intent = _source_json(raw, "original command intent")
    if intent.get("tool") != expected_tool:
        raise ReleaseControlError("captured command differs from its selected owner")
    actual = _validate_intent_bytes(context.directory, raw)
    if actual.root != context.root or canonical_json(actual.intent) != canonical_json(
        context.intent
    ):
        raise ReleaseControlError("command context differs from its captured original intent")


def _release_prerequisite_origin_rows(
    bundle: Mapping[str, Any],
    *,
    bundle_path: Path,
    captured: _ReleaseCapturedFiles,
    expected_context_digest: str,
    before: str,
) -> list[dict[str, Any]]:
    """Bind the thirteen explicit native origins; no row gains semantic authority here."""
    container = _release_capture_absolute(bundle_path)
    try:
        name = container.relative_to(captured.root).as_posix()
    except ValueError as exc:
        raise ReleaseControlError("prerequisite bundle escapes captured closure") from exc
    original = _source_json(captured.read(name, kind="prerequisite-proofs"), "prerequisite bundle")
    if canonical_json(bundle) != canonical_json(original):
        raise ReleaseControlError("prerequisite bundle differs from its captured original")
    data = _release_closed_mapping(
        original,
        {"schema_version", "release_context_digest", "proofs", "captured_original_files"},
        "prerequisite proof bundle",
    )
    _require_digest(expected_context_digest, "independent prerequisite context")
    if (
        data["schema_version"] != "metriplane.release-prerequisite-proofs.v1"
        or data["release_context_digest"] != expected_context_digest
    ):
        raise ReleaseControlError("prerequisite proof bundle has a different context")
    deadline = _parse_utc_timestamp(before, "gate input capture boundary")
    if (
        not isinstance(data["proofs"], list)
        or not data["proofs"]
        or not isinstance(data["captured_original_files"], list)
        or not data["captured_original_files"]
    ):
        raise ReleaseControlError("prerequisite bundle has no complete original proof inventory")

    def resolve(value: object, field: Sequence[str | int]) -> tuple[Path, bytes]:
        return _release_captured_raw_file(
            value,
            containing_path=container,
            containing_kind="prerequisite-proofs",
            field=field,
            captured=captured,
            expected_kind="prerequisite-original",
            label="original prerequisite member",
        )

    files = set()
    for index, reference in enumerate(data["captured_original_files"]):
        path, _ = resolve(reference, ("captured_original_files", index))
        if path in files:
            raise ReleaseControlError("prerequisite original inventory duplicates a file")
        files.add(path)
    if files != {
        captured.root / row[0] for row in captured.rows if row[1] == "prerequisite-original"
    }:
        raise ReleaseControlError(
            "prerequisite original files differ from the captured typed inventory"
        )
    results = []
    checked_roots: set[Path] = set()
    seen_records: set[Path] = set()
    for index, value in enumerate(data["proofs"]):
        row = _release_closed_mapping(
            value,
            {
                "producer",
                "stage",
                "record_type",
                "record_kind",
                "record",
                "record_digest",
                "original_run_root",
                "producer_intent",
                "producer_terminal",
                "companion_validations",
            },
            "prerequisite origin",
        )
        producer = row["producer"]
        if not isinstance(producer, str) or producer not in _RELEASE_GATE_PREREQUISITES:
            raise ReleaseControlError("prerequisite origin has an unknown native producer")
        record_type, record_kind, companion = _RELEASE_GATE_PREREQUISITES[producer]
        if (row["stage"], row["record_type"], row["record_kind"]) != (
            _invocation_stage(producer),
            record_type,
            record_kind,
        ):
            raise ReleaseControlError("prerequisite origin differs from its closed native type")
        root = container.parent / _release_relative_suffix(
            row["original_run_root"], "original prerequisite run root"
        )
        if root not in checked_roots:
            _release_replay_original_namespace(captured, root)
            checked_roots.add(root)
        record_path, record_raw = resolve(row["record"], ("proofs", index, "record"))
        if record_path in seen_records:
            raise ReleaseControlError("prerequisite bundle duplicates an original record")
        seen_records.add(record_path)
        record = _source_json(record_raw, "original prerequisite record")
        validate_record(record, record_type)
        if (
            record["status"] != "PASS"
            or record["signatures"] != []
            or record["data"].get("kind") != record_kind
            or sha256_json(record) != row["record_digest"]
        ):
            raise ReleaseControlError("original prerequisite record type/result/digest differs")
        intent_path, intent_raw = resolve(
            row["producer_intent"], ("proofs", index, "producer_intent")
        )
        terminal_path, _ = resolve(row["producer_terminal"], ("proofs", index, "producer_terminal"))
        expected_directory = (
            root / "invocations" / _invocation_stage(producer) / f"{record['sequence']:03d}"
        )
        if (
            intent_path != expected_directory / "intent.json"
            or terminal_path != expected_directory / "invocation.json"
        ):
            raise ReleaseControlError(
                "prerequisite original journal has a different run/stage/sequence"
            )
        if _source_json(intent_raw, "original prerequisite intent").get("tool") != producer:
            raise ReleaseControlError("prerequisite intent has a different native owner")
        context = _validate_intent_bytes(expected_directory, intent_raw)
        if (
            context.root != root
            or record["invocation_id"] != context.intent["invocation_id"]
            or record["data"].get("producer_intent_digest") != sha256_json(context.intent)
            or record["data"].get("invocation_root_locator") != "invocations"
        ):
            raise ReleaseControlError(
                "original prerequisite record does not bind its exact producer"
            )
        try:
            record_suffix = record_path.relative_to(root).as_posix()
        except ValueError as exc:
            raise ReleaseControlError("prerequisite output escapes its original run") from exc
        primary = {"path": record_suffix, "schema_id": "metriplane." + record_type + ".v1"}
        if primary not in context.intent["planned_outputs"]:
            raise ReleaseControlError(
                "original prerequisite output is absent from its producer plan"
            )
        historical_root, arguments = _release_original_invocation_binding(
            context,
            expected_tool=producer,
            captured=captured,
            output_plan=context.intent["planned_outputs"],
        )
        lineage = _release_replay_original_lineage(context, captured=captured)
        terminal = lineage[0]["terminal"]
        completed = _parse_utc_timestamp(
            terminal["data"]["completed_at"], "prerequisite completion"
        )
        if completed > deadline or record["synthetic"] != terminal["synthetic"]:
            raise ReleaseControlError(
                "prerequisite completed after capture or changed authority mode"
            )
        companions = row["companion_validations"]
        if not isinstance(companions, list) or len(companions) != (0 if companion is None else 1):
            raise ReleaseControlError("prerequisite lacks its exact required companion")
        companion_results = []
        for ci, supplied in enumerate(companions):
            witness = _release_closed_mapping(
                supplied, {"tool", "stage", "intent", "terminal"}, "prerequisite companion"
            )
            if (
                companion is None
                or witness["tool"] != companion
                or witness["stage"] != _invocation_stage(companion)
            ):
                raise ReleaseControlError("prerequisite has a different companion owner")
            ci_path, ci_raw = resolve(
                witness["intent"], ("proofs", index, "companion_validations", ci, "intent")
            )
            ct_path, _ = resolve(
                witness["terminal"], ("proofs", index, "companion_validations", ci, "terminal")
            )
            ci_value = _source_json(ci_raw, "original companion intent")
            if ci_value.get("tool") != companion:
                raise ReleaseControlError("original companion intent differs from its native owner")
            validation = _validate_intent_bytes(ci_path.parent, ci_raw)
            if validation.root != root or ct_path != validation.directory / "invocation.json":
                raise ReleaseControlError(
                    "companion journal has a different independently located root"
                )
            companion_original_root, ca = _release_original_invocation_binding(
                validation, expected_tool=companion, captured=captured, output_plan=[]
            )
            companion_lineage = _release_replay_original_lineage(validation, captured=captured)
            completion = companion_lineage[0]["terminal"]
            if (
                not (
                    completed
                    <= _parse_utc_timestamp(validation.intent["started_at"], "companion start")
                    <= _parse_utc_timestamp(
                        completion["data"]["completed_at"], "companion completion"
                    )
                    <= deadline
                )
                or completion["synthetic"] != record["synthetic"]
            ):
                raise ReleaseControlError("original companion chronology or authority mode differs")
            consumed_flag = (
                "receipts"
                if companion == "validate_release_retention.py"
                else "through-receipt"
                if producer == "update_release_attempt_index.py"
                else "record"
            )
            if consumed_flag not in ca:
                raise ReleaseControlError(
                    "original companion selected the wrong native record form"
                )
            original_record = companion_original_root / record_suffix
            companion_cwd = _canonical_absolute_path(
                validation.intent["environment"]["working_directory"],
                "original companion working directory",
            )
            if _release_historical_path(ca[consumed_flag], companion_cwd) != original_record:
                raise ReleaseControlError("original companion consumed a different record path")
            consumed_input = {
                "path": str(original_record),
                "schema_id": "metriplane." + record_type + ".v1",
                "sha256": sha256_bytes(record_raw),
            }
            if consumed_input not in validation.intent["inputs"]:
                raise ReleaseControlError(
                    "original companion did not capture the exact original record"
                )
            _release_original_companion_bindings(context, validation, captured=captured)
            # Native per-tool replay also binds backend controls, complete
            # transitive input semantics and independently expected authority.
            companion_results.append(
                {
                    "tool": companion,
                    "arguments": ca,
                    "intent": validation.intent,
                    "terminal": completion,
                    "lineage": companion_lineage,
                }
            )
        results.append(
            {
                "producer": producer,
                "record_path": record_path.relative_to(captured.root).as_posix(),
                "record": record,
                "run_root": root.relative_to(captured.root).as_posix(),
                "historical_root": str(historical_root),
                "arguments": arguments,
                "intent": context.intent,
                "terminal": terminal,
                "lineage": lineage,
                "companions": companion_results,
            }
        )
    for root in sorted(checked_roots):
        _release_assert_original_journal_inventory(captured, root)
    captured.revalidate()
    return results


def _release_original_consumed_file(
    intent: Mapping[str, Any],
    *,
    current_root: Path,
    captured: _ReleaseCapturedFiles,
    expected_tool: str,
    flag: str,
    expected_schema_id: str,
) -> tuple[Path, bytes]:
    """Bind a native input flag to its original exact path/type/hash at the current root.

    Original intent/journal verification is owned by prerequisite replay. This helper
    supplies semantic consumers with one explicit file; it never searches or opens the
    historical location and grants no provider authority.
    """
    root = _release_capture_absolute(current_root)
    if not root.is_relative_to(captured.root) or intent.get("tool") != expected_tool:
        raise ReleaseControlError("native original input differs from its current root or owner")
    if type(intent.get("sequence")) is not int or intent["sequence"] < 1:
        raise ReleaseControlError("native original input has an invalid sequence")
    _release_captured_original_context(
        ReleaseInvocation(
            root / "invocations" / _invocation_stage(expected_tool) / f"{intent['sequence']:03d}",
            root,
            intent,
        ),
        captured=captured,
    )
    _require_nonempty_string(expected_schema_id, "native original input type")
    arguments = _release_original_arguments(expected_tool, intent.get("argv"))
    if flag not in arguments:
        raise ReleaseControlError("native original input lacks required --" + flag)
    argument = arguments[flag]
    if flag in TOOL_CONTRACTS[expected_tool].repeatable:
        if not isinstance(argument, list) or len(argument) != 1:
            raise ReleaseControlError("native original input requires exactly one --" + flag)
        argument = argument[0]
    cwd = _canonical_absolute_path(
        intent["environment"]["working_directory"], "native original working directory"
    )
    directory = _release_historical_path(arguments["invocation-dir"], cwd)
    if directory.parts[-3:] != (
        "invocations",
        _invocation_stage(expected_tool),
        f"{intent['sequence']:03d}",
    ):
        raise ReleaseControlError("native input invocation differs from its original stage")
    historical_root = directory.parents[2]
    historical_path = _release_historical_path(argument, cwd)
    if not historical_path.is_relative_to(historical_root):
        raise ReleaseControlError("native original input escapes its original run root")
    suffix = _release_relative_suffix(
        historical_path.relative_to(historical_root).as_posix(), "native original input"
    )
    path = root / suffix
    selected = [row for row in intent["inputs"] if row["path"] == str(historical_path)]
    if len(selected) != 1 or selected[0]["schema_id"] != expected_schema_id:
        raise ReleaseControlError("native input flag is absent or has a different original type")
    raw = captured.read(path.relative_to(captured.root).as_posix(), kind="prerequisite-original")
    if selected[0]["sha256"] != sha256_bytes(raw):
        raise ReleaseControlError("native input flag differs from original captured type or bytes")
    return path, raw


def _release_original_companion_bindings(
    producer: ReleaseInvocation,
    companion: ReleaseInvocation,
    *,
    captured: _ReleaseCapturedFiles,
) -> None:
    """Bind the six existing companion contracts to their original producer controls.

    This is additional original-journal input correspondence. Native phase schemas,
    live provider readbacks, backend identity and independent authority remain required.
    """
    _release_captured_original_context(producer, captured=captured)
    _release_captured_original_context(companion, captured=captured)
    tool = producer.intent["tool"]
    expected = _RELEASE_GATE_PREREQUISITES.get(tool)
    if (
        expected is None
        or expected[2] is None
        or companion.intent["tool"] != expected[2]
        or companion.root != producer.root
    ):
        raise ReleaseControlError("original companion controls have a different native owner")
    pa = _release_original_arguments(tool, producer.intent["argv"])
    ca = _release_original_arguments(companion.intent["tool"], companion.intent["argv"])

    def path(
        context: ReleaseInvocation, arguments: Mapping[str, Any], flag: str, value: object
    ) -> Path:
        cwd = _canonical_absolute_path(
            context.intent["environment"]["working_directory"],
            "original companion working directory",
        )
        historical_directory = _release_historical_path(arguments["invocation-dir"], cwd)
        if historical_directory.parts[-3:] != (
            "invocations",
            _invocation_stage(context.intent["tool"]),
            f"{context.intent['sequence']:03d}",
        ):
            raise ReleaseControlError("original companion control journal suffix differs")
        historical_root = historical_directory.parents[2]
        selected = _release_historical_path(value, cwd)
        if not selected.is_relative_to(historical_root):
            raise ReleaseControlError(
                "original companion control escapes its original run: " + flag
            )
        suffix = selected.relative_to(historical_root)
        if suffix != Path():
            _release_relative_suffix(suffix.as_posix(), "original companion control")
        return context.root / suffix

    def file_rows(
        context: ReleaseInvocation, arguments: Mapping[str, Any], flag: str
    ) -> list[dict[str, str]]:
        values = (
            arguments[flag]
            if flag in TOOL_CONTRACTS[context.intent["tool"]].repeatable
            else [arguments[flag]]
        )
        result = []
        for value in values:
            current = path(context, arguments, flag, value)
            cwd = _canonical_absolute_path(
                context.intent["environment"]["working_directory"],
                "original control working directory",
            )
            original = _release_historical_path(value, cwd)
            inputs = [row for row in context.intent["inputs"] if row["path"] == str(original)]
            if len(inputs) != 1:
                raise ReleaseControlError("original companion control was not captured: " + flag)
            raw = captured.read(
                current.relative_to(captured.root).as_posix(), kind="prerequisite-original"
            )
            if sha256_bytes(raw) != inputs[0]["sha256"]:
                raise ReleaseControlError("original companion control bytes changed: " + flag)
            result.append({**inputs[0], "path": str(current)})
        if len({row["path"] for row in result}) != len(result):
            raise ReleaseControlError("original companion repeats a shared input: " + flag)
        return sorted(result, key=lambda row: row["path"])

    def shared_file(flag: str, *, same_location: bool = True) -> None:
        if flag not in pa or flag not in ca:
            raise ReleaseControlError("original producer/companion lack a shared --" + flag)
        left, right = file_rows(producer, pa, flag), file_rows(companion, ca, flag)
        if not same_location:
            left = [{k: v for k, v in row.items() if k != "path"} for row in left]
            right = [{k: v for k, v in row.items() if k != "path"} for row in right]
        if left != right:
            raise ReleaseControlError(
                "original companion consumed a different shared input: " + flag
            )

    if tool == "capture_linear_release_snapshot.py":
        if set(ca) != {"record", "registry", "invocation-dir"}:
            raise ReleaseControlError("initial Linear companion used a later fresh-decision form")
        shared_file("registry")
    elif tool == "record_release_role_assignments.py":
        for flag in ("milestone", "run-id"):
            if pa[flag] != ca[flag]:
                raise ReleaseControlError("original role companion scope differs: " + flag)
        trust = {
            "provider-attestation-keyring",
            "provider-attestation-keyring-digest",
            "authority-policy-digest",
        }
        for arguments in (pa, ca):
            if set(arguments) & trust not in (set(), trust):
                raise ReleaseControlError("original role companion trust controls are incomplete")
        if set(pa) & trust != set(ca) & trust or (
            producer.intent["environment"]["fixture_mode"] == "0" and not trust <= set(pa)
        ):
            raise ReleaseControlError(
                "original role companion does not preserve the original trust controls"
            )
        if trust <= set(pa):
            for flag in trust - {"provider-attestation-keyring"}:
                if _require_digest(pa[flag], "original role trust control") != ca[flag]:
                    raise ReleaseControlError("original role companion uses another trust identity")
            shared_file("provider-attestation-keyring", same_location=False)
    elif tool == "resolve_release_target.py":
        shared_file("targets")
    elif tool == "retain_release_evidence.py":
        supplied = {"input", "manifest"}
        if set(pa) & supplied != set(ca) & supplied:
            raise ReleaseControlError(
                "original retention companion selected a different input form"
            )
        for flag in sorted(supplied & set(pa)):
            shared_file(flag)
        for flag in ("invocation-root", "through-stage"):
            if (flag in pa) != (flag in ca):
                raise ReleaseControlError(
                    "original retention companion journal boundary is missing"
                )
            if flag in pa:
                left = path(producer, pa, flag, pa[flag]) if flag == "invocation-root" else pa[flag]
                right = (
                    path(companion, ca, flag, ca[flag]) if flag == "invocation-root" else ca[flag]
                )
                if left != right:
                    raise ReleaseControlError(
                        "original retention companion journal boundary differs"
                    )
    elif tool in {"update_release_attempt_index.py", "export_release_attempt_index.py"}:
        if pa["index-backend"] != ca["index-backend"]:
            raise ReleaseControlError("original index companion selects another backend")
        if "genesis" in pa:
            shared_file("genesis")
        else:
            # The update producer consumes entry receipts, not genesis directly.
            # Receipt/genesis semantics belong to the native index replay.
            file_rows(companion, ca, "genesis")
    elif tool == "build_release_evidence_manifest.py":
        required = "require-lkg-disposition-and-applicable-invalidation-receipt"
        if required in pa and required not in ca:
            raise ReleaseControlError("original manifest companion omits required LKG disposition")
    else:
        raise ReleaseControlError("original companion input contract has no closed owner")
    captured.revalidate()


def _release_assert_original_journal_inventory(
    captured: _ReleaseCapturedFiles, run_root: Path
) -> None:
    """Reject unlisted journal members before reading their bytes, through held directories."""
    root = _release_capture_absolute(run_root)
    try:
        root.relative_to(captured.root)
    except ValueError as exc:
        raise ReleaseControlError("original journal namespace escapes capture") from exc
    journal = root / "invocations"
    known_files: set[Path] = set()
    expected_directories: dict[str, tuple[str, int, int, int]] = {
        row[0]: row for row in captured.root_directories
    }
    for name, kind, _, _, ancestors in captured.rows:
        path = captured.root / name
        if path.is_relative_to(journal):
            if len(path.relative_to(journal).parts) < 3:
                raise ReleaseControlError(
                    "original journal namespace is not a stage/sequence directory"
                )
            if kind != "prerequisite-original":
                raise ReleaseControlError(
                    "original journal member has a conflicting captured owner"
                )
            known_files.add(path)
        for row in ancestors:
            if row[0] in expected_directories and expected_directories[row[0]] != row:
                raise ReleaseControlError("original journal ancestor identity conflicts")
            expected_directories[row[0]] = row
    if not known_files:
        raise ReleaseControlError("original journal namespace has no captured members")
    children: dict[Path, set[str]] = {}
    for path in known_files:
        current = path
        while current != journal:
            children.setdefault(current.parent, set()).add(current.name)
            current = current.parent
    stages = {_invocation_stage(tool) for tool in _RELEASE_GATE_PREREQUISITES}
    stages.update(
        _invocation_stage(row[2])
        for row in _RELEASE_GATE_PREREQUISITES.values()
        if row[2] is not None
    )
    if not children[journal] <= stages:
        raise ReleaseControlError("captured original namespace has an unrelated journal stage")
    for stage in children[journal]:
        sequences = children.get(journal / stage, set())
        if any(
            re.fullmatch(r"[0-9]{3,}", name, flags=re.ASCII) is None for name in sequences
        ) or sorted(sequences, key=int) != [f"{i:03d}" for i in range(1, len(sequences) + 1)]:
            raise ReleaseControlError("captured original journal sequences are not contiguous")
    descriptors: list[int] = []
    links: list[tuple[int, str, int]] = []

    def check(path: Path, descriptor: int) -> None:
        observed = os.fstat(descriptor)
        expected = expected_directories.get(str(path))
        if (
            expected is None
            or (str(path), observed.st_dev, observed.st_ino, observed.st_mode) != expected
        ):
            raise ReleaseControlError("original journal directory changed from captured ancestry")

    try:
        descriptor = os.open(journal.anchor, os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW)
        descriptors.append(descriptor)
        visible = Path(journal.anchor)
        check(visible, descriptor)
        for component in journal.parts[1:]:
            child = os.open(
                component, os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW, dir_fd=descriptor
            )
            descriptors.append(child)
            links.append((descriptor, component, child))
            descriptor = child
            visible /= component
            check(visible, descriptor)

        def visit(path: Path, parent_fd: int) -> None:
            names = set(os.listdir(parent_fd))
            expected = children.get(path, set())
            # A producer may create its two empty scratch directories. They hold
            # no original bytes and cannot introduce another stage or sequence.
            empty_scratch = names - expected if path.parent.parent == journal else set()
            if not empty_scratch <= {"staged", "workspace"} or names - empty_scratch != expected:
                raise ReleaseControlError("original journal has an unlisted or missing member")
            for name in sorted(names):
                child_path = path / name
                info = os.stat(name, dir_fd=parent_fd, follow_symlinks=False)
                if child_path in known_files:
                    if not stat.S_ISREG(info.st_mode) or info.st_nlink != 1:
                        raise ReleaseControlError(
                            "original journal member is not a safe regular file"
                        )
                    continue
                if not stat.S_ISDIR(info.st_mode):
                    raise ReleaseControlError("original journal has an unlisted or unsafe object")
                child_fd = os.open(
                    name, os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW, dir_fd=parent_fd
                )
                descriptors.append(child_fd)
                links.append((parent_fd, name, child_fd))
                if name in empty_scratch:
                    if os.listdir(child_fd):
                        raise ReleaseControlError(
                            "original empty scratch directory has unlisted files"
                        )
                else:
                    check(child_path, child_fd)
                    visit(child_path, child_fd)
            if set(os.listdir(parent_fd)) != names:
                raise ReleaseControlError("original journal namespace changed during inspection")

        visit(journal, descriptor)
        for parent_fd, name, child_fd in reversed(links):
            held = os.fstat(child_fd)
            current_info = os.stat(name, dir_fd=parent_fd, follow_symlinks=False)
            if (held.st_dev, held.st_ino, held.st_mode) != (
                current_info.st_dev,
                current_info.st_ino,
                current_info.st_mode,
            ):
                raise ReleaseControlError(
                    "original journal ancestor changed during namespace inspection"
                )
    except OSError as exc:
        raise ReleaseControlError("original journal namespace cannot be inspected safely") from exc
    finally:
        failures = []
        for descriptor in reversed(descriptors):
            try:
                os.close(descriptor)
            except OSError as exc:
                failures.append(exc)
        if failures:
            raise ReleaseControlError(
                "original journal namespace descriptor cleanup failed"
            ) from failures[0]
    captured.revalidate()


def _release_captured_partial_inventory(
    context: ReleaseInvocation, *, captured: _ReleaseCapturedFiles
) -> None:
    """Replay readable bytes and unsafe partial metadata through a pinned journal."""
    _release_captured_original_context(context, captured=captured)
    name = (context.directory / "partial-files.json").relative_to(captured.root).as_posix()
    raw = captured.read(name, kind="prerequisite-original")
    value = _release_closed_mapping(
        _source_json(raw, "original partial inventory"),
        {"schema_version", "roots", "files", "unreadable"},
        "original partial inventory",
    )
    if value["schema_version"] != "metriplane.release-partial-files.v1" or raw != canonical_json(
        value
    ):
        raise ReleaseControlError("original partial inventory is noncanonical")
    intent_name = (context.directory / "intent.json").relative_to(captured.root).as_posix()
    intent_rows = [row for row in captured.rows if row[0] == intent_name]
    if len(intent_rows) != 1:
        raise ReleaseControlError("original partial inventory lacks its held journal")
    directory_fd = _release_gate_open_pinned_directory(context.directory, intent_rows[0][4])
    try:
        projected = _release_gate_partial_projection_at(context, directory_fd)
    finally:
        os.close(directory_fd)
    if canonical_json(value) != canonical_json(projected):
        raise ReleaseControlError(
            "original partial inventory differs from its complete retained payload"
        )
    for file_row in value["files"]:
        member = _release_closed_mapping(
            file_row, {"path", "sha256", "size"}, "original partial readable file"
        )
        member_raw = captured.read(member["path"], kind="prerequisite-original")
        if len(member_raw) != member["size"] or sha256_bytes(member_raw) != member["sha256"]:
            raise ReleaseControlError("original partial readable bytes differ")
    captured.revalidate()


def _release_replay_original_lineage(
    context: ReleaseInvocation, *, captured: _ReleaseCapturedFiles, require_pass: bool = True
) -> list[dict[str, Any]]:
    """Replay a strictly decreasing original retry chain, retaining failures unchanged."""
    result: list[dict[str, Any]] = []
    current = context
    terminal_required = True
    latest_start: datetime | None = None
    mode = context.intent["environment"]["fixture_mode"]
    while True:
        _release_captured_original_context(current, captured=captured)
        _release_original_invocation_binding(
            current,
            expected_tool=context.intent["tool"],
            captured=captured,
            output_plan=current.intent["planned_outputs"],
        )
        start = _parse_utc_timestamp(current.intent["started_at"], "original lineage start")
        if current.intent["environment"]["fixture_mode"] != mode or (
            latest_start is not None and start > latest_start
        ):
            raise ReleaseControlError("original invocation lineage changes mode or chronology")
        terminal = None
        if terminal_required:
            terminal = _release_captured_journal_terminal(
                current, captured=captured, require_pass=require_pass and not result
            )
            if (
                latest_start is not None
                and _parse_utc_timestamp(
                    terminal["data"]["completed_at"], "original lineage completion"
                )
                > latest_start
            ):
                raise ReleaseControlError(
                    "original predecessor completed after its successor started"
                )
            if terminal["status"] != "PASS":
                _release_captured_partial_inventory(current, captured=captured)
        else:
            name = (current.directory / "invocation.json").relative_to(captured.root).as_posix()
            if any(row[0] == name for row in captured.rows):
                raise ReleaseControlError("original interrupted predecessor acquired a terminal")
            partial_name = (
                (current.directory / "partial-files.json").relative_to(captured.root).as_posix()
            )
            if any(row[0] == partial_name for row in captured.rows):
                _release_captured_partial_inventory(current, captured=captured)
        _release_captured_journal_members(current, captured=captured, terminal=terminal)
        result.append(
            {
                "intent": current.intent,
                "terminal": terminal,
                "disposition": "TERMINAL"
                if terminal is not None
                else "INTERRUPTED_MISSING_TERMINAL",
            }
        )
        predecessor = current.intent["predecessor"]
        if predecessor is None:
            break
        terminal_required = predecessor["terminal_digest"] is not None
        latest_start = start
        directory = current.directory.parent / f"{predecessor['sequence']:03d}"
        name = (directory / "intent.json").relative_to(captured.root).as_posix()
        raw = captured.read(name, kind="prerequisite-original")
        original = _source_json(raw, "original predecessor intent")
        if (
            original.get("tool") != context.intent["tool"]
            or sha256_bytes(raw) != predecessor["intent_digest"]
        ):
            raise ReleaseControlError("original lineage predecessor identity differs")
        previous = _validate_intent_bytes(directory, raw)
        if (
            type(previous.intent["sequence"]) is not int
            or previous.intent["sequence"] != current.intent["sequence"] - 1
        ):
            raise ReleaseControlError("original lineage does not decrease by one exact sequence")
        if terminal_required:
            terminal_raw = captured.read(
                (directory / "invocation.json").relative_to(captured.root).as_posix(),
                kind="prerequisite-original",
            )
            if sha256_bytes(terminal_raw) != predecessor["terminal_digest"]:
                raise ReleaseControlError("original lineage predecessor terminal identity differs")
        current = previous
    captured.revalidate()
    return result


def _release_replay_original_namespace(captured: _ReleaseCapturedFiles, run_root: Path) -> None:
    """Replay every captured stage through its latest terminal, including failed history."""
    _release_assert_original_journal_inventory(captured, run_root)

    latest: dict[str, ReleaseInvocation] = {}
    for name, kind, _, _, _ in captured.rows:
        path = captured.root / name
        if not path.is_relative_to(run_root):
            continue
        parts = path.relative_to(run_root).parts
        if len(parts) != 4 or parts[0] != "invocations" or parts[3] != "intent.json":
            continue
        if kind != "prerequisite-original":
            raise ReleaseControlError("original intent has a conflicting capture owner")
        raw = captured.read(name, kind=kind)
        value = _source_json(raw, "original namespace intent")
        allowed = set(_RELEASE_GATE_PREREQUISITES) | {
            row[2] for row in _RELEASE_GATE_PREREQUISITES.values() if row[2] is not None
        }
        if value.get("tool") not in allowed:
            raise ReleaseControlError("original namespace has no native command owner")
        context = _validate_intent_bytes(path.parent, raw)
        if context.root != run_root:
            raise ReleaseControlError("original namespace intent has a different root")
        if (
            parts[1] not in latest
            or context.intent["sequence"] > latest[parts[1]].intent["sequence"]
        ):
            latest[parts[1]] = context
    # Every top-level stage requires its own captured intent; arbitrary payload
    # files named intent.json beneath scratch directories cannot create a stage.
    stages = {
        (captured.root / row[0]).relative_to(run_root).parts[1]
        for row in captured.rows
        if (captured.root / row[0]).is_relative_to(run_root / "invocations")
    }
    if set(latest) != stages:
        raise ReleaseControlError("original namespace contains a stage without an intent")
    for stage in sorted(latest):
        _release_replay_original_lineage(latest[stage], captured=captured, require_pass=False)
    _release_assert_original_journal_inventory(captured, run_root)


def _release_captured_journal_members(
    context: ReleaseInvocation,
    *,
    captured: _ReleaseCapturedFiles,
    terminal: Mapping[str, Any] | None,
) -> None:
    """Capture membership does not authorize extra common-journal or scratch payloads."""
    members = {
        (captured.root / row[0]).relative_to(context.directory).as_posix(): row[0]
        for row in captured.rows
        if (captured.root / row[0]).is_relative_to(context.directory)
    }
    allowed = {
        "intent.json",
        "invocation.json",
        "stdout",
        "stderr",
        "partial-files.json",
        "worker.pid",
        "worker-result.json",
        "staged",
        "workspace",
    }
    if (
        terminal is not None
        and terminal["status"] == "PASS"
        and context.intent["tool"]
        in {
            "prepare_release_gate_input.py",
            "validate_release_evidence_stores.py",
            "capture_release_target_observations.py",
            "record_release_role_assignments.py",
            "retain_release_evidence.py",
            "export_release_attempt_index.py",
            "export_release_burn_lineage.py",
            "update_release_attempt_index.py",
        }
    ):
        allowed.add("terminal-commit.json")
    if any(Path(name).parts[0] not in allowed for name in members):
        raise ReleaseControlError("original journal contains an unowned captured member")
    for name in members:
        if len(Path(name).parts) > 1 and Path(name).parts[0] not in {"staged", "workspace"}:
            raise ReleaseControlError("original journal common member is not a file")
    for scratch in ("staged", "workspace"):
        if os.path.lexists(context.directory / scratch):
            _release_held_path(context.directory / scratch, directory=True)

    def read(name: str) -> bytes:
        if name not in members:
            raise ReleaseControlError("original journal lacks required worker evidence")
        return captured.read(members[name], kind="prerequisite-original")

    if "worker.pid" in members:
        pid = _release_closed_mapping(
            _source_json(read("worker.pid"), "original worker"), {"pid"}, "original worker"
        )
        if type(pid["pid"]) is not int or pid["pid"] <= 0:
            raise ReleaseControlError("original worker PID is invalid")
    worker = None
    if "worker-result.json" in members:
        worker = _release_closed_mapping(
            _source_json(read("worker-result.json"), "original worker result"),
            {"schema_version", "exit_code", "outputs", "producer_intent_digest"},
            "original worker result",
        )
        if (
            "worker.pid" not in members
            or worker["schema_version"] != "metriplane.release-worker-result.v1"
            or type(worker["exit_code"]) is not int
            or worker["exit_code"] < 0
            or worker["producer_intent_digest"] != sha256_json(context.intent)
            or not isinstance(worker["outputs"], list)
        ):
            raise ReleaseControlError("original worker result does not bind its exact intent")
        worker_outputs = []
        for value in worker["outputs"]:
            output = _release_closed_mapping(
                value, {"path", "schema_id", "sha256"}, "original worker output"
            )
            _release_relative_suffix(output["path"], "original worker output path")
            _require_nonempty_string(output["schema_id"], "original worker output type")
            _require_digest(output["sha256"], "original worker output bytes")
            worker_outputs.append({"path": output["path"], "schema_id": output["schema_id"]})
        if worker["exit_code"] != 0 and worker["outputs"] != []:
            raise ReleaseControlError("failed original worker has canonical output claims")
        if worker["exit_code"] == 0 and canonical_json(worker_outputs) != canonical_json(
            context.intent["planned_outputs"]
        ):
            raise ReleaseControlError("original successful worker does not fill its exact plan")
        if (
            terminal is not None
            and terminal["status"] not in {"BLOCKED", "CANCELLED"}
            and worker["exit_code"] != terminal["data"]["exit_code"]
        ):
            raise ReleaseControlError("original worker and terminal outcomes differ")
    if terminal is not None and terminal["status"] == "FAIL" and worker is None:
        raise ReleaseControlError("original failed worker lacks its common verdict")
    if terminal is not None and terminal["status"] == "PASS":
        staged = {name for name in members if name.startswith("staged/")}
        workspace = {name for name in members if name.startswith("workspace/")}
        if workspace:
            raise ReleaseControlError("passing prerequisite workspace lacks native owner replay")
        outputs = terminal["data"]["outputs"]
        if worker is None or not os.path.lexists(context.directory / "staged"):
            raise ReleaseControlError("passing original journal lacks its complete worker evidence")
        if context.intent["tool"] in {
            "validate_release_evidence_stores.py",
            "capture_release_target_observations.py",
            "record_release_role_assignments.py",
            "retain_release_evidence.py",
            "export_release_attempt_index.py",
            "export_release_burn_lineage.py",
            "update_release_attempt_index.py",
        }:
            witness = _release_closed_mapping(
                _source_json(read("terminal-commit.json"), "prerequisite terminal witness"),
                {"schema_version", "intent_sha256", "terminal_sha256"},
                "prerequisite terminal witness",
            )
            if witness != {
                "schema_version": "metriplane.gate-terminal-commit.v1",
                "intent_sha256": sha256_json(context.intent),
                "terminal_sha256": sha256_json(terminal),
            }:
                raise ReleaseControlError(
                    "passing native prerequisite lacks its durable terminal witness"
                )
        if canonical_json(worker["outputs"]) != canonical_json(outputs):
            raise ReleaseControlError("original worker output plan differs from its PASS terminal")
        if staged != {"staged/" + row["path"] for row in outputs}:
            raise ReleaseControlError(
                "passing prerequisite staged members differ from its exact plan"
            )
        if staged:
            for row in outputs:
                if sha256_bytes(read("staged/" + row["path"])) != row["sha256"]:
                    raise ReleaseControlError(
                        "original staged bytes differ from the installed output"
                    )
    captured.revalidate()


def _release_linear_identity(value: object, *, require_project: bool = False) -> dict[str, Any]:
    identity = _release_closed_mapping(
        value,
        {"provider", "issue_id", "issue_identifier", "project_id", "team_id"},
        "Linear issue identity",
    )
    if (
        identity["provider"] != "linear"
        or not isinstance(identity["issue_identifier"], str)
        or re.fullmatch(r"[A-Z][A-Z0-9]*-[1-9][0-9]*", identity["issue_identifier"], re.ASCII)
        is None
    ):
        raise ReleaseControlError("Linear issue provider/identifier is invalid")
    for key in ("issue_id", "project_id", "team_id"):
        if key == "project_id" and identity[key] is None and not require_project:
            continue
        _release_linear_uuid(identity[key], "Linear issue " + key)
    return identity


def _release_linear_issue_rows(
    values: object, *, root_issue_ids: frozenset[str] | None = None
) -> dict[str, dict[str, Any]]:
    """Check complete normalized identities and reciprocal edges; raw replay is separate."""
    if not isinstance(values, list) or not values:
        raise ReleaseControlError("Linear snapshot has no complete issue rows")
    issues: dict[str, dict[str, Any]] = {}
    identifiers: set[str] = set()
    for value in values:
        row = _release_closed_mapping(
            value,
            {
                "identity",
                "title",
                "description",
                "project_milestone",
                "parent",
                "state",
                "assignee_ids",
                "created_at",
                "updated_at",
                "archived_at",
                "completed_at",
                "started_at",
                "canceled_at",
                "blocks",
                "blocked_by",
                "related_to",
                "duplicate_of",
                "detail_observation_id",
                "index_observation_ids",
            },
            "complete Linear issue",
        )
        identity = _release_linear_identity(row["identity"])
        issue_id, identifier = identity["issue_id"], identity["issue_identifier"]
        if issue_id in issues or identifier in identifiers:
            raise ReleaseControlError("Linear snapshot duplicates a UUID or identifier")
        issues[issue_id] = row
        identifiers.add(identifier)
        _require_nonempty_string(row["title"], "Linear issue title")
        if not isinstance(row["description"], str):
            raise ReleaseControlError("Linear issue description is not complete text")
        _require_nonempty_string(row["detail_observation_id"], "Linear detail observation")
        for key in ("assignee_ids", "index_observation_ids"):
            members = _release_id_list(row[key], "Linear " + key, nonempty=False)
            if members != sorted(members):
                raise ReleaseControlError("Linear issue identity inventory is not canonical")
            if key == "assignee_ids":
                for member in members:
                    _release_linear_uuid(member, "Linear assignee")
        for key in (
            "created_at",
            "updated_at",
            "archived_at",
            "completed_at",
            "started_at",
            "canceled_at",
        ):
            if key in {"created_at", "updated_at"} or row[key] is not None:
                _parse_utc_timestamp(row[key], "Linear " + key)
        if _parse_utc_timestamp(row["updated_at"], "Linear update") < _parse_utc_timestamp(
            row["created_at"], "Linear creation"
        ):
            raise ReleaseControlError("Linear issue update precedes creation")
        _release_linear_state(row["state"])
        if row["project_milestone"] is not None:
            milestone = _release_closed_mapping(
                row["project_milestone"], {"id", "name", "project_id"}, "Linear milestone"
            )
            if milestone["project_id"] != identity["project_id"]:
                raise ReleaseControlError("Linear milestone belongs to another project")
            for key in milestone:
                _require_nonempty_string(milestone[key], "Linear milestone " + key)
            _release_linear_uuid(milestone["id"], "Linear milestone ID")
            _release_linear_uuid(milestone["project_id"], "Linear milestone project")
    if list(issues) != sorted(
        issues, key=lambda issue_id: (issues[issue_id]["identity"]["issue_identifier"], issue_id)
    ):
        raise ReleaseControlError("Linear issue rows are not canonically ordered")

    subjects = set(issues) if root_issue_ids is None else set(root_issue_ids)
    pending = list(subjects)
    while pending:
        issue_id = pending.pop()
        if issue_id not in issues:
            raise ReleaseControlError("Linear capture lacks an original root or blocking subject")
        dependencies = issues[issue_id]["blocked_by"]
        if not isinstance(dependencies, list):
            raise ReleaseControlError("Linear blocking inventory is incomplete")
        for value in dependencies:
            edge = _release_closed_mapping(
                value, {"issue_id", "issue_identifier"}, "Linear dependency"
            )
            endpoint = edge["issue_id"]
            if not isinstance(endpoint, str) or endpoint not in issues:
                raise ReleaseControlError("Linear capture omits a blocking dependency")
            if endpoint not in subjects:
                subjects.add(endpoint)
                pending.append(endpoint)

    reference_identifiers = {
        key: row["identity"]["issue_identifier"] for key, row in issues.items()
    }
    reference_ids = {identifier: key for key, identifier in reference_identifiers.items()}

    def relations(row: Mapping[str, Any], key: str) -> list[str]:
        values = row[key]
        if key in {"parent", "duplicate_of"}:
            values = [] if values is None else [values]
        if not isinstance(values, list):
            raise ReleaseControlError("Linear relation inventory is incomplete")
        found = []
        ordering = []
        for value in values:
            edge = _release_closed_mapping(
                value, {"issue_id", "issue_identifier"}, "Linear relation endpoint"
            )
            endpoint = edge["issue_id"]
            _release_linear_uuid(endpoint, "Linear relation endpoint")
            if (
                not isinstance(endpoint, str)
                or endpoint == row["identity"]["issue_id"]
                or endpoint in found
                or not isinstance(edge["issue_identifier"], str)
                or re.fullmatch(r"[A-Z][A-Z0-9]*-[1-9][0-9]*", edge["issue_identifier"], re.ASCII)
                is None
                or (
                    endpoint in issues
                    and edge["issue_identifier"] != issues[endpoint]["identity"]["issue_identifier"]
                )
                or (row["identity"]["issue_id"] in subjects and endpoint not in issues)
            ):
                raise ReleaseControlError(
                    "Linear relation endpoint is missing, aliased or repeated"
                )
            found.append(endpoint)
            identifier = edge["issue_identifier"]
            if (
                reference_identifiers.get(endpoint, identifier) != identifier
                or reference_ids.get(identifier, endpoint) != endpoint
            ):
                raise ReleaseControlError(
                    "Linear boundary reference aliases a known UUID or identifier"
                )
            reference_identifiers[endpoint] = identifier
            reference_ids[identifier] = endpoint
            ordering.append((edge["issue_identifier"], endpoint))
        if ordering != sorted(ordering):
            raise ReleaseControlError("Linear relations are not canonically ordered")
        return found

    edges = {
        issue_id: {
            key: relations(row, key)
            for key in ["blocks", "blocked_by", "related_to", "parent", "duplicate_of"]
        }
        for issue_id, row in issues.items()
    }
    for issue_id, families in edges.items():
        if issue_id not in subjects:
            continue
        for forward, reverse in [("blocks", "blocked_by"), ("blocked_by", "blocks")]:
            for endpoint in families[forward]:
                if issue_id not in edges[endpoint][reverse]:
                    raise ReleaseControlError("Linear blocking relation is not reciprocal")
    return issues


def _release_linear_catalog_dependencies(
    registry: Mapping[str, Any],
    *,
    issues: object,
    original_packet: bytes,
    expected_packet_digest: str,
    original_work_orders: bytes,
    expected_work_orders_digest: str,
) -> dict[str, list[str]]:
    """Project the 93 original declarations, independently of observed blocking edges.

    Both packet identities are independently held by the caller. Current normalized
    descriptions must preserve the work-order marker. Noncatalog/context amendments
    need their separate authority; this projection neither supplies nor authorizes them.
    """
    catalog = _release_readiness_catalog_projection(
        registry, original_packet=original_packet, expected_packet_digest=expected_packet_digest
    )["task_catalog"]
    packet = _release_original_packet(
        original_work_orders, expected_digest=expected_work_orders_digest
    )
    orders = _release_id_rows(packet.get("tasks"), "task_id", "original dependency work orders")
    catalog_by_task = {row["task"]: row for row in catalog}
    if len(orders) != 93 or set(orders) != set(catalog_by_task):
        raise ReleaseControlError(
            "dependency work orders differ from the complete original catalog"
        )
    if not isinstance(issues, list):
        raise ReleaseControlError("dependency descriptions lack complete normalized issue rows")
    descriptions: dict[str, str] = {}
    issue_ids: set[str] = set()
    for issue in issues:
        if not isinstance(issue, dict):
            raise ReleaseControlError("dependency description issue is malformed")
        identity = _release_linear_identity(issue.get("identity"))
        identifier, issue_id = identity["issue_identifier"], identity["issue_id"]
        if identifier in descriptions or issue_id in issue_ids:
            raise ReleaseControlError("dependency description identity is duplicated or aliased")
        description = issue.get("description")
        if not isinstance(description, str):
            raise ReleaseControlError("dependency description is absent")
        descriptions[identifier] = description
        issue_ids.add(issue_id)
    marker = "METRIPLANE_MP2_DEPENDENCIES_V1"
    pattern = (
        r"^<!-- " + marker + r"\nTask: (MP2-[0-9]{3})\n"
        r"Authoritative blocked by: \[((?:MP2-[0-9]{3})(?:, MP2-[0-9]{3})*)?\]\n-->$"
    )
    result = {}
    for task_id, original in orders.items():
        row = catalog_by_task[task_id]
        if re.fullmatch(r"MP2-[0-9]{3}", task_id, flags=re.ASCII) is None or any(
            field not in original
            or field not in row
            or canonical_json(original[field]) != canonical_json(row[field])
            for field in ("linear_issue", "role", "first_required_release", "linear_milestone_id")
        ):
            raise ReleaseControlError(
                "dependency work-order identity differs from original catalog"
            )
        dependencies = _release_id_list(
            original.get("authoritative_blocked_by"),
            "original authoritative dependency set",
            nonempty=False,
        )
        if task_id in dependencies or not set(dependencies) <= set(orders):
            raise ReleaseControlError("original dependency names self or an unknown catalog task")
        identifier = row["linear_issue"]
        description = descriptions.get(identifier)
        if description is None or description.count(marker) != 1:
            raise ReleaseControlError("catalog issue lacks one unambiguous dependency marker")
        # The retained description bridge permits only Markdown hard-break
        # trailing-space removal here. Preserve the original observation bytes.
        marker_view = re.sub(r" {2,}$", "", description, flags=re.MULTILINE)
        matches = re.findall(pattern, marker_view, flags=re.MULTILINE | re.ASCII)
        if len(matches) != 1 or matches[0][0] != task_id:
            raise ReleaseControlError(
                "catalog dependency marker is malformed or names another task"
            )
        declared = _release_id_list(
            matches[0][1].split(", ") if matches[0][1] else [],
            "marker authoritative dependency set",
            nonempty=False,
        )
        if set(declared) != set(dependencies):
            raise ReleaseControlError("catalog dependency marker changed the original declaration")
        result[identifier] = sorted(catalog_by_task[name]["linear_issue"] for name in dependencies)
    return dict(sorted(result.items()))


def _release_linear_bom_projection(
    registry: Mapping[str, Any],
    *,
    context_id: str,
    issues: object,
    original_packet: bytes,
    expected_packet_digest: str,
    declared_dependencies: Mapping[str, Sequence[str]],
) -> dict[str, Any]:
    """Recompute cumulative membership without granting provider or declaration authority."""
    projection = _release_readiness_catalog_projection(
        registry, original_packet=original_packet, expected_packet_digest=expected_packet_digest
    )
    policies = _release_id_rows(registry.get("release_contexts"), "context_id", "release contexts")
    if context_id not in policies:
        raise ReleaseControlError("Linear snapshot selects an unknown context")
    policy = policies[context_id]
    milestone = policy.get("framework_milestone")
    if milestone not in MILESTONES or policy.get("preserve_original_cumulative_bom") is not True:
        raise ReleaseControlError("Linear context does not preserve its cumulative obligations")
    bindings = _release_id_rows(
        registry.get("provider_issue_bindings"), "issue_identifier", "provider issue bindings"
    )
    catalog = {row["linear_issue"]: row for row in projection["task_catalog"]}
    decision = _release_linear_identity(policy.get("decision"), require_project=True)
    direct = policy.get("direct_gate_issues")
    if not isinstance(direct, list) or not direct:
        raise ReleaseControlError("Linear context has no direct gate identities")
    # An assignment binding is not a dependency role. Only catalogue/context subjects
    # and their actual blocking closure enter this BOM replay; full index coverage is
    # independently replayed by the raw snapshot consumer.
    root_ids = frozenset(
        {
            _release_linear_identity(bindings[key].get("identity"))["issue_id"]
            for key in catalog
            if key in bindings
        }
        | {decision["issue_id"]}
        | {_release_linear_identity(row, require_project=True)["issue_id"] for row in direct}
    )
    actual = _release_linear_issue_rows(issues, root_issue_ids=root_ids)
    bound_ids: dict[str, str] = {}
    unresolved = []
    for identifier, binding in bindings.items():
        identity = _release_linear_identity(binding.get("identity"))
        issue_id = identity["issue_id"]
        if identity["issue_identifier"] != identifier or issue_id in bound_ids.values():
            raise ReleaseControlError("Linear provider policy duplicates or aliases an issue")
        if issue_id not in actual or canonical_json(actual[issue_id]["identity"]) != canonical_json(
            identity
        ):
            raise ReleaseControlError("Linear snapshot omits or changes a bound issue identity")
        if canonical_json(actual[issue_id]["project_milestone"]) != canonical_json(
            binding.get("expected_milestone")
        ):
            raise ReleaseControlError("Linear issue differs from its own governed milestone")
        task = catalog.get(identifier)
        if binding.get("catalog_task_id") != (None if task is None else task["task"]):
            raise ReleaseControlError("Linear policy invented or changed a catalog identity")
        if binding.get("binding_status") not in {"RESOLVED", "UNRESOLVED"}:
            raise ReleaseControlError("Linear provider binding has an unknown status")
        if binding["binding_status"] == "UNRESOLVED":
            unresolved.append(identifier)
        bound_ids[identifier] = issue_id
    if not set(catalog) <= set(bound_ids):
        raise ReleaseControlError("Linear policy omits an original catalog issue")
    direct_ids = []
    for identity in [decision, *direct]:
        _release_linear_identity(identity, require_project=True)
        identifier, issue_id = identity["issue_identifier"], identity["issue_id"]
        if bound_ids.get(identifier) != issue_id or canonical_json(
            actual[issue_id]["identity"]
        ) != canonical_json(identity):
            raise ReleaseControlError("Linear context identity differs from its per-entity policy")
        if identity is not decision:
            if issue_id in direct_ids or issue_id == decision["issue_id"]:
                raise ReleaseControlError(
                    "Linear direct gates duplicate the current decision or a gate"
                )
            direct_ids.append(issue_id)
    provider_milestone = _release_closed_mapping(
        policy.get("provider_milestone"), {"id", "name", "project_id"}, "selected context milestone"
    )
    _release_linear_uuid(provider_milestone["id"], "selected context milestone ID")
    _release_linear_uuid(provider_milestone["project_id"], "selected context milestone project")
    _require_nonempty_string(provider_milestone["name"], "selected context milestone name")
    if provider_milestone["project_id"] != decision["project_id"] or canonical_json(
        provider_milestone
    ) != canonical_json(actual[decision["issue_id"]]["project_milestone"]):
        raise ReleaseControlError("selected context milestone differs from its current decision")
    if policy.get("roadmap_catalog_task_id") != (
        catalog[decision["issue_identifier"]]["task"]
        if decision["issue_identifier"] in catalog
        else None
    ):
        raise ReleaseControlError("Linear current decision has a fabricated roadmap identity")
    selected = MILESTONES.index(milestone)
    reasons: dict[str, set[str]] = {}

    def include(issue_id: str, reason: str) -> None:
        reasons.setdefault(issue_id, set()).add(reason)

    for identifier, task in catalog.items():
        first = task.get("first_required_release")
        if first not in (*MILESTONES, "post-v1.0") or type(task.get("blocks_release")) is not bool:
            raise ReleaseControlError("Linear catalog has an unknown cumulative requirement")
        if (
            task["role"] == "implementation"
            and task["blocks_release"]
            and first in MILESTONES
            and MILESTONES.index(first) <= selected
        ):
            include(bound_ids[identifier], "cumulative_catalog")
    for slot in projection["release_gate_slots"][: selected + 1]:
        for task_id in slot["required_development_tasks"]:
            row = next(task for task in catalog.values() if task["task"] == task_id)
            include(bound_ids[row["linear_issue"]], "cumulative_catalog")
        prior_id = bound_ids[slot["linear_release_decision_issue"]]
        if prior_id != decision["issue_id"]:
            include(prior_id, "prior_roadmap_decision")
    include(decision["issue_id"], "current_decision")
    for issue_id in direct_ids:
        include(issue_id, "context_direct_gate")
    visiting: set[str] = set()
    complete: set[str] = set()

    def visit(issue_id: str) -> None:
        if issue_id in visiting:
            raise ReleaseControlError("Linear required blocking graph contains a cycle")
        if issue_id in complete:
            return
        visiting.add(issue_id)
        identifier = actual[issue_id]["identity"]["issue_identifier"]
        expected = declared_dependencies.get(identifier)
        if not isinstance(expected, (list, tuple)):
            raise ReleaseControlError(
                "Linear required issue has no complete dependency declaration"
            )
        names = _release_id_list(list(expected), "declared Linear dependencies", nonempty=False)
        if set(names) != {row["issue_identifier"] for row in actual[issue_id]["blocked_by"]}:
            raise ReleaseControlError(
                "Linear required dependencies differ from their exact declarations"
            )
        for edge in actual[issue_id]["blocked_by"]:
            dependency = edge["issue_id"]
            if bound_ids.get(edge["issue_identifier"]) != dependency:
                raise ReleaseControlError(
                    "Linear required dependency has no governed identity binding"
                )
            include(dependency, "blocking_dependency")
            visit(dependency)
        visiting.remove(issue_id)
        complete.add(issue_id)

    for issue_id in list(reasons):
        visit(issue_id)
    bom: list[dict[str, Any]] = []
    for issue_id in sorted(
        reasons, key=lambda item: (actual[item]["identity"]["issue_identifier"], item)
    ):
        row = actual[issue_id]
        task = catalog.get(row["identity"]["issue_identifier"])
        role = (
            "release_decision"
            if issue_id == decision["issue_id"]
            else (
                task["role"]
                if task is not None
                else "context_direct_gate"
                if issue_id in direct_ids
                else "transitive_dependency"
            )
        )
        bom.append(
            {
                "catalog_task_id": None if task is None else task["task"],
                "catalog_first_required_release": None
                if task is None
                else task["first_required_release"],
                "role": role,
                "inclusion_reasons": sorted(reasons[issue_id]),
                "issue": row,
            }
        )
    return {
        "catalog_issue_ids": sorted(bound_ids[identifier] for identifier in catalog),
        "decision_issue_id": decision["issue_id"],
        "direct_gate_issue_ids": sorted(direct_ids),
        "required_bom": bom,
        "required_bom_ids": [row["issue"]["identity"]["issue_identifier"] for row in bom],
        "required_bom_snapshot_digest": sha256_json(bom),
        "catalog_projection_digest": sha256_json(projection),
        "unresolved_bindings": sorted(unresolved),
    }


def _release_task_state_policy_projection(raw: bytes, *, expected_digest: str) -> dict[str, Any]:
    """Check the exact raw policy and its existing transition/time constraints."""
    if sha256_bytes(raw) != _require_digest(expected_digest, "raw task-state policy"):
        raise ReleaseControlError(
            "raw task-state policy differs from its independent source identity"
        )
    policy = _release_closed_mapping(
        _source_json(raw, "raw task-state policy"),
        {
            "allowed_transitions",
            "authority_status",
            "cross_system_atomicity",
            "freshness_windows_seconds",
            "no_other_authorized_transition",
            "owner",
            "provider",
            "schema_version",
            "server_clock_skew_budget_seconds",
            "workflow_states",
        },
        "raw task-state policy",
    )
    required_transitions = [
        {
            "authorized_role": "release_operator",
            "from": "open_running",
            "provider_event_required": True,
            "required_after": "latest_lkg_pointer_envelope_and_index_read_validated",
            "to": "open_finalizing",
        },
        {
            "authorized_role": "release_operator",
            "from": "open_finalizing",
            "provider_event_required": True,
            "required_after": "applicable_durable_close_root_validated",
            "to": "closed",
        },
    ]
    if (
        policy["schema_version"] != "metriplane.release-task-state-policy.v1"
        or policy["owner"] != "MP2-007"
        or policy["authority_status"] != "POLICY_ONLY_NO_LIVE_PROVIDER_RECEIPT"
        or policy["cross_system_atomicity"] != "not_claimed"
        or policy["no_other_authorized_transition"] is not True
        or canonical_json(policy["allowed_transitions"]) != canonical_json(required_transitions)
        or canonical_json(policy["freshness_windows_seconds"])
        != canonical_json({"prepromotion": 300, "terminal_commit": 120})
        or canonical_json(policy["server_clock_skew_budget_seconds"])
        != canonical_json({"capture": 30, "terminal_commit": 30})
    ):
        raise ReleaseControlError(
            "raw task-state policy weakens or changes its governed constraints"
        )
    provider = _release_closed_mapping(policy["provider"], {"id", "team_id"}, "task-state provider")
    if provider["id"] != "linear":
        raise ReleaseControlError("task-state policy uses a different provider")
    _release_linear_uuid(provider["team_id"], "task-state team")
    states = _release_closed_mapping(
        policy["workflow_states"],
        {"open_running", "open_finalizing", "closed"},
        "task-state workflow",
    )
    ids = []
    for key, expected_type in [
        ("open_running", "started"),
        ("open_finalizing", "started"),
        ("closed", "completed"),
    ]:
        state = _release_linear_state(states[key])
        if state["type"] != expected_type or state["id"] in ids:
            raise ReleaseControlError("task-state workflow has an aliased or wrong lifecycle state")
        ids.append(state["id"])
    return policy


def _release_original_role_byte_replay(
    protected_path: Path,
    *,
    context_path: Path,
    captured: _ReleaseCapturedFiles,
    expected_context_digest: str,
    expected_run_id: str,
    expected_milestone: str,
    expected_assignment_policy_digest: str,
    expected_authority_policy_digest: str,
    expected_keyring_digest: str,
    use_interval: tuple[str, str],
    live: bool,
    attestation_verifier: ProviderAttestationVerifier | None = None,
) -> dict[str, Any]:
    """Replay original signed role bytes; native policy/provenance delegation is still required.

    This projection grants no roles. In particular a signature by the embedded operator does
    not establish that operator's independent authority to make the assignment.
    """
    path = _release_capture_absolute(protected_path)
    context_file = _release_capture_absolute(context_path)
    if not path.is_relative_to(captured.root) or not context_file.is_relative_to(captured.root):
        raise ReleaseControlError("original role input/context escapes captured root")
    record = _source_json(
        captured.read(path.relative_to(captured.root).as_posix(), kind="prerequisite-original"),
        "original protected role input",
    )
    validate_record(record, "release-protected-input")
    if record["status"] != "PASS" or record["synthetic"] is live:
        raise ReleaseControlError("original protected role input mode or verdict differs")
    data = _release_closed_mapping(
        record["data"],
        {
            "input_kind",
            "assignment_kind",
            "decision",
            "authorized_role",
            "conflicts",
            "signer_identity",
            "signing_method",
            "issued_at",
            "expires_at",
            "authority_policy_digest",
            "provider_attestation_keyring_digest",
            "assignments",
            "assignment_payload_digest",
            "release_context",
            "assignment_policy_registry",
            "role_provenance_files",
            "subject_digests",
        },
        "original protected role input data",
    )
    for key, value in {
        "input_kind": "role_assignment",
        "assignment_kind": "protected_release_roles",
        "decision": "ASSIGNED",
        "authorized_role": "release_operator",
        "conflicts": [],
        "signing_method": "provider-attestation-v1",
        "authority_policy_digest": _require_digest(
            expected_authority_policy_digest, "expected role authority"
        ),
        "provider_attestation_keyring_digest": _require_digest(
            expected_keyring_digest, "expected role keyring"
        ),
    }.items():
        if canonical_json(data[key]) != canonical_json(value):
            raise ReleaseControlError("original protected role binding differs: " + key)
    started = _parse_utc_timestamp(use_interval[0], "original role action start")
    finished = _parse_utc_timestamp(use_interval[1], "original role action end")
    issued = _parse_utc_timestamp(data["issued_at"], "original role authorization start")
    expires = _parse_utc_timestamp(data["expires_at"], "original role authorization end")
    if not issued <= started <= finished < expires:
        raise ReleaseControlError("original role action is outside its authorization interval")
    refs = {}
    for field, kind in [
        ("release_context", "prerequisite-original"),
        ("assignment_policy_registry", "prerequisite-original"),
    ]:
        refs[field] = _release_captured_raw_file(
            data[field],
            containing_path=path,
            containing_kind="prerequisite-original",
            field=("data", field),
            captured=captured,
            expected_kind=kind,
            label="original role " + field,
        )
    if refs["release_context"][0] != context_file:
        raise ReleaseControlError("original protected role input selects another context path")
    context = _source_json(refs["release_context"][1], "original role context")
    validate_record(context, "release-context")
    if (
        context["status"] != "PASS"
        or context["synthetic"] is not record["synthetic"]
        or sha256_json(context)
        != _require_digest(expected_context_digest, "expected complete role context")
        or context["data"].get("framework_milestone") != expected_milestone
    ):
        raise ReleaseControlError(
            "original role context mode, complete digest or milestone differs"
        )
    policy_raw = refs["assignment_policy_registry"][1]
    if sha256_bytes(policy_raw) != _require_digest(
        expected_assignment_policy_digest, "expected original role assignment policy"
    ):
        raise ReleaseControlError(
            "original role assignment policy bytes differ from expected authority"
        )
    assignments = data["assignments"]
    if not isinstance(assignments, dict):
        raise ReleaseControlError("original role assignment payload is not an object")
    actors = _release_role_assignment_payload(
        assignments,
        live=live,
        expected_milestone=expected_milestone,
        expected_run_id=expected_run_id,
        expected_authority_policy_digest=expected_authority_policy_digest,
        check_conflicts=True,
        attestation_verifier=attestation_verifier,
        expected_context_digest=expected_context_digest,
        use_interval=use_interval,
    )
    if assignments["provider_attestation_keyring_digest"] != expected_keyring_digest:
        raise ReleaseControlError(
            "original assignment payload keyring differs from protected input"
        )
    subjects = [
        {"subject": "assignment_payload", "sha256": sha256_json(assignments)},
        {"subject": "release_context", "sha256": sha256_json(context)},
        {"subject": "assignment_policy_registry", "sha256": sha256_bytes(policy_raw)},
    ]
    if data["assignment_payload_digest"] != subjects[0]["sha256"] or canonical_json(
        data["subject_digests"]
    ) != canonical_json(subjects):
        raise ReleaseControlError(
            "original role ordered subjects differ from their complete C/R owners"
        )
    provenance = _release_closed_mapping(
        data["role_provenance_files"],
        {
            "operator",
            "non_author_reviewer",
            "infrastructure_owner",
            "publisher",
            "independent_assurance",
        },
        "original role provenance files",
    )
    assurance_required = expected_milestone in {"v0.9", "v1.0"}
    if (
        assignments["independent_assurance"]["applicability"]
        != ("required" if assurance_required else "not_applicable")
        or (provenance["independent_assurance"] is None) is assurance_required
    ):
        raise ReleaseControlError(
            "original role assurance applicability differs from its milestone"
        )
    original_provenance = {}
    for role in provenance:
        if role == "independent_assurance" and not assurance_required:
            continue
        original_path, original_raw = _release_captured_raw_file(
            provenance[role],
            containing_path=path,
            containing_kind="prerequisite-original",
            field=("data", "role_provenance_files", role),
            captured=captured,
            expected_kind="prerequisite-original",
            label="original " + role + " provenance",
        )
        binding = (
            assignments[role]["binding"] if role == "independent_assurance" else assignments[role]
        )
        if binding["provenance_digest"] != sha256_bytes(original_raw):
            raise ReleaseControlError("original role provenance R differs from assignment binding")
        original_provenance[role] = {
            "path": original_path,
            "bytes": original_raw,
            "binding": binding,
        }
    signer = _require_nonempty_string(data["signer_identity"], "original role signer")
    operator = actors["authorized_executor_id"]
    if signer != operator[1]:
        raise ReleaseControlError("original role signer differs from its declared executor")
    signers = _validated_record_signers(
        record, live=live, attestation_verifier=attestation_verifier
    )
    signing_identity = operator if live else ("test-fixture", operator[1])
    if signing_identity not in signers:
        raise ReleaseControlError(
            "original protected envelope lacks the declared executor signature"
        )
    captured.revalidate()
    return {
        "record": record,
        "assignments": assignments,
        "actors": actors,
        "assignment_policy_bytes": policy_raw,
        "original_provenance": original_provenance,
    }


def _release_recorded_role_byte_replay(
    record_path: Path,
    *,
    protected_path: Path,
    context_path: Path,
    captured: _ReleaseCapturedFiles,
    expected_context_digest: str,
    expected_run_id: str,
    expected_milestone: str,
    expected_assignment_policy_digest: str,
    expected_authority_policy_digest: str,
    expected_keyring_digest: str,
    expected_producer_intent_digest: str,
    expected_invocation_id: str,
    expected_sequence: int,
    use_interval: tuple[str, str],
    live: bool,
    attestation_verifier: ProviderAttestationVerifier | None = None,
) -> dict[str, Any]:
    """Bind the unsigned recorder projection to untouched authenticated original bytes.

    The enclosing native owner must independently replay the original producer/companion
    journals, their exact input mapping and role delegation before admitting this result.
    Neither empty signatures nor these supplied expected identities confer that authority.
    """
    original = _release_original_role_byte_replay(
        protected_path,
        context_path=context_path,
        captured=captured,
        expected_context_digest=expected_context_digest,
        expected_run_id=expected_run_id,
        expected_milestone=expected_milestone,
        expected_assignment_policy_digest=expected_assignment_policy_digest,
        expected_authority_policy_digest=expected_authority_policy_digest,
        expected_keyring_digest=expected_keyring_digest,
        use_interval=use_interval,
        live=live,
        attestation_verifier=attestation_verifier,
    )
    path = _release_capture_absolute(record_path)
    if not path.is_relative_to(captured.root) or path == protected_path:
        raise ReleaseControlError("recorded roles have no distinct captured output path")
    record = _source_json(
        captured.read(path.relative_to(captured.root).as_posix(), kind="prerequisite-original"),
        "original role recorder output",
    )
    validate_record(record, "release-role-assignments")
    if (
        record["status"] != "PASS"
        or record["synthetic"] is not original["record"]["synthetic"]
        or record["signatures"] != []
        or record["invocation_id"] != _require_invocation(expected_invocation_id)
        or type(expected_sequence) is not int
        or expected_sequence < 1
        or record["sequence"] != expected_sequence
    ):
        raise ReleaseControlError("recorded role envelope differs from its unsigned native output")
    assignments = original["assignments"]
    data = _release_closed_mapping(
        record["data"],
        set(assignments)
        | {
            "kind",
            "original_protected_input",
            "original_protected_input_digest",
            "producer_intent_digest",
            "invocation_root_locator",
        },
        "recorded role projection",
    )
    reference_path, _ = _release_captured_raw_file(
        data["original_protected_input"],
        containing_path=path,
        containing_kind="prerequisite-original",
        field=("data", "original_protected_input"),
        captured=captured,
        expected_kind="prerequisite-original",
        label="recorded role original protected input",
    )
    if reference_path != protected_path:
        raise ReleaseControlError("recorded roles select a different original protected input path")
    expected = {
        **assignments,
        "kind": "recorded_assignments",
        "original_protected_input": data["original_protected_input"],
        "original_protected_input_digest": sha256_json(original["record"]),
        "producer_intent_digest": _require_digest(
            expected_producer_intent_digest, "original role producer intent"
        ),
        "invocation_root_locator": "invocations",
    }
    if canonical_json(data) != canonical_json(expected):
        raise ReleaseControlError("recorded roles differ from their complete original assignment")
    captured.revalidate()
    return {**original, "recorded_assignments": record}


def _release_linear_uuid(value: object, label: str) -> str:
    if (
        not isinstance(value, str)
        or re.fullmatch(
            r"[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}", value, re.ASCII
        )
        is None
    ):
        raise ReleaseControlError(label + " is not a canonical provider UUID")
    return value


def _release_linear_state(value: object) -> dict[str, Any]:
    state = _release_closed_mapping(value, {"id", "name", "type"}, "Linear workflow state")
    _release_linear_uuid(state["id"], "Linear state ID")
    _require_nonempty_string(state["name"], "Linear state name")
    _require_nonempty_string(state["type"], "Linear state category")
    return state


def _release_linear_lifecycle(
    projection: Mapping[str, Any],
    *,
    issues: Mapping[str, Mapping[str, Any]],
    team_statuses: object,
    task_state_policy_raw: bytes,
    expected_task_state_policy_digest: str,
) -> None:
    """Classify from each exact team dictionary, never from a sticky completion timestamp."""
    policy = _release_task_state_policy_projection(
        task_state_policy_raw, expected_digest=expected_task_state_policy_digest
    )
    dictionaries = _release_id_rows(team_statuses, "team_id", "Linear team status dictionaries")
    if set(dictionaries) != {row["identity"]["team_id"] for row in issues.values()}:
        raise ReleaseControlError(
            "Linear team status dictionaries do not cover the exact issue teams"
        )
    states: dict[str, dict[str, dict[str, Any]]] = {}
    for team, value in dictionaries.items():
        _release_linear_uuid(team, "Linear status dictionary team")
        row = _release_closed_mapping(
            value, {"team_id", "observation_id", "states"}, "Linear team dictionary"
        )
        _require_nonempty_string(row["observation_id"], "Linear status observation")
        members = _release_id_rows(row["states"], "id", "Linear states")
        if not members or list(members) != sorted(members):
            raise ReleaseControlError("Linear team states are not a complete canonical dictionary")
        states[team] = {key: _release_linear_state(value) for key, value in members.items()}
    for issue_row in issues.values():
        state = _release_linear_state(issue_row["state"])
        if canonical_json(
            states[issue_row["identity"]["team_id"]].get(state["id"])
        ) != canonical_json(state):
            raise ReleaseControlError("Linear issue state differs from its own team dictionary")
    current_id = projection["decision_issue_id"]
    if current_id not in issues:
        raise ReleaseControlError("Linear current decision is missing")
    current = issues[current_id]
    if current["identity"]["team_id"] != policy["provider"]["team_id"] or canonical_json(
        current["state"]
    ) != canonical_json(policy["workflow_states"]["open_running"]):
        raise ReleaseControlError("Linear current decision is not its governed open-running state")
    bom = projection["required_bom"]
    if (
        not isinstance(bom, list)
        or not bom
        or projection["required_bom_snapshot_digest"] != sha256_json(bom)
    ):
        raise ReleaseControlError("Linear lifecycle received an incomplete full BOM")
    seen = set()
    for required in bom:
        row = required["issue"]
        issue_id = row["identity"]["issue_id"]
        if issue_id in seen or canonical_json(issues.get(issue_id)) != canonical_json(row):
            raise ReleaseControlError("Linear lifecycle BOM differs from its full frozen issue")
        seen.add(issue_id)
        if row["archived_at"] is not None:
            raise ReleaseControlError("Linear required issue is archived")
        if issue_id == current_id:
            continue
        if row["state"]["type"] != "completed":
            raise ReleaseControlError("Linear required issue is not genuinely completed")
        if row["identity"]["team_id"] == policy["provider"]["team_id"] and canonical_json(
            row["state"]
        ) != canonical_json(policy["workflow_states"]["closed"]):
            raise ReleaseControlError("Linear required issue is not the governed closed state")
    if current_id not in seen:
        raise ReleaseControlError("Linear required BOM omits the current decision")


_RELEASE_LINEAR_INDEX_FIELDS: Final[tuple[str, ...]] = (
    "id",
    "uuid",
    "title",
    "description",
    "projectMilestone",
    "status",
    "statusType",
    "assigneeId",
    "projectId",
    "parentId",
    "teamId",
    "createdAt",
    "updatedAt",
    "archivedAt",
    "completedAt",
    "startedAt",
    "canceledAt",
)


def _release_linear_observation_payloads(
    snapshot_path: Path, *, captured: _ReleaseCapturedFiles
) -> dict[str, dict[str, Any]]:
    """Replay exact original tool response bytes; capture/provider authority is still separate."""
    path = _release_capture_absolute(snapshot_path)
    if not path.is_relative_to(captured.root):
        raise ReleaseControlError("Linear original snapshot escapes captured inputs")
    raw = captured.read(path.relative_to(captured.root).as_posix(), kind="prerequisite-original")
    try:
        record = _source_json(raw, "original Linear snapshot")
    except RecursionError as exc:
        raise ReleaseControlError("original Linear snapshot exceeds parser nesting") from exc
    validate_record(record, "linear-release-snapshot")
    if record["status"] != "PASS" or record["signatures"] != []:
        raise ReleaseControlError(
            "original Linear capture is not an unsigned native derived result"
        )
    data = _release_closed_mapping(
        record["data"],
        {
            "snapshot_contract",
            "tool",
            "readiness_registry_digest",
            "task_state_policy_digest",
            "catalog_projection_digest",
            "context_policy_id",
            "framework_milestone",
            "task_id",
            "decision_issue_id",
            "state",
            "capture_started_at",
            "capture_completed_at",
            "raw_observations",
            "project_scans",
            "team_statuses",
            "project_milestones",
            "issues",
            "catalog_issue_ids",
            "direct_gate_issue_ids",
            "required_bom_ids",
            "required_bom",
            "required_bom_snapshot_digest",
            "coverage",
            "stabilization",
            "snapshot_digest",
            "producer_intent_digest",
            "invocation_root_locator",
        },
        "original full Linear snapshot data",
    )
    if (
        data["snapshot_contract"] != "full-project-plus-cross-project-dependency-closure.v1"
        or data["tool"] != "capture_linear_release_snapshot.py"
        or data["invocation_root_locator"] != "invocations"
    ):
        raise ReleaseControlError("original Linear snapshot has a different capture owner/contract")
    _require_digest(data["producer_intent_digest"], "Linear original producer intent")
    if data["snapshot_digest"] != sha256_json(
        {key: value for key, value in data.items() if key != "snapshot_digest"}
    ):
        raise ReleaseControlError("original Linear snapshot semantic digest differs")

    def read_response(index: int, reference: object) -> tuple[Path, bytes]:
        return _release_captured_raw_file(
            reference,
            containing_path=path,
            containing_kind="prerequisite-original",
            field=("data", "raw_observations", index, "response"),
            captured=captured,
            expected_kind="prerequisite-original",
            label="original Linear tool response",
        )

    return _release_linear_observation_content(
        data, read_response=read_response, revalidate=captured.revalidate
    )


def _release_linear_snapshot_replay(
    snapshot_path: Path,
    *,
    captured: _ReleaseCapturedFiles,
    readiness_registry_raw: bytes,
    expected_readiness_digest: str,
    original_packet: bytes,
    expected_packet_digest: str,
    original_work_orders: bytes,
    expected_work_orders_digest: str,
    task_state_policy_raw: bytes,
    expected_task_state_policy_digest: str,
    context_id: str,
    declared_dependencies: Mapping[str, Sequence[str]],
    observed_at: str,
    consumer_stage: str,
) -> dict[str, Any]:
    """Compose raw, graph, BOM and lifecycle replay; this does not grant provider authority."""
    if sha256_bytes(readiness_registry_raw) != _require_digest(
        expected_readiness_digest, "independently expected readiness registry"
    ):
        raise ReleaseControlError("Linear raw readiness policy differs from independent identity")
    registry = _source_json(readiness_registry_raw, "original raw readiness policy")
    policy = _release_task_state_policy_projection(
        task_state_policy_raw, expected_digest=expected_task_state_policy_digest
    )
    if consumer_stage not in {"prepromotion", "terminal_commit"}:
        raise ReleaseControlError("Linear replay has an ungoverned freshness consumer")
    now = _parse_utc_timestamp(observed_at, "Linear consumer clock")
    path = _release_capture_absolute(snapshot_path)
    payloads = _release_linear_observation_payloads(path, captured=captured)
    record = _source_json(
        captured.read(path.relative_to(captured.root).as_posix(), kind="prerequisite-original"),
        "original Linear snapshot",
    )
    data = record["data"]
    if (
        data["readiness_registry_digest"] != expected_readiness_digest
        or data["task_state_policy_digest"] != expected_task_state_policy_digest
        or data["context_policy_id"] != context_id
    ):
        raise ReleaseControlError("Linear snapshot differs from independent raw policies/context")
    end = _parse_utc_timestamp(data["capture_completed_at"], "Linear capture completion")
    age = (now - end).total_seconds()
    if (
        age < -policy["server_clock_skew_budget_seconds"]["capture"]
        or age > policy["freshness_windows_seconds"][consumer_stage]
    ):
        raise ReleaseControlError(
            "Linear original capture is stale or beyond the future clock budget"
        )
    for member in payloads.values():
        observation = member["observation"]
        if observation["round"] == 2:
            original_end = _parse_utc_timestamp(
                observation["completed_at"], "Linear original observation completion"
            )
            if (now - original_end).total_seconds() > policy["freshness_windows_seconds"][
                consumer_stage
            ]:
                raise ReleaseControlError(
                    "Linear original second-round observation is stale; wrapper time cannot refresh it"
                )
    content = _release_linear_snapshot_projection(
        registry,
        payloads=payloads,
        original_packet=original_packet,
        expected_packet_digest=expected_packet_digest,
        original_work_orders=original_work_orders,
        expected_work_orders_digest=expected_work_orders_digest,
        task_state_policy_raw=task_state_policy_raw,
        expected_task_state_policy_digest=expected_task_state_policy_digest,
        context_id=context_id,
        declared_dependencies=declared_dependencies,
    )
    expected, projection = content["expected"], content["projection"]
    for key, value in expected.items():
        if canonical_json(data[key]) != canonical_json(value):
            raise ReleaseControlError("Linear claimed snapshot differs from raw replay: " + key)
    _release_linear_provider_clock(payloads, policy)
    captured.revalidate()
    return {"record": record, "projection": projection}


def _release_git_oid(value: object, label: str) -> str:
    if not isinstance(value, str) or re.fullmatch(r"[0-9a-f]{40}", value, re.ASCII) is None:
        raise ReleaseControlError(label + " is not a canonical Git object identity")
    return value


def _release_target_policy_projection(value: object, *, milestone: str) -> dict[str, Any]:
    policy = _release_closed_mapping(
        value,
        {
            "resolution_mode",
            "conflict_disposition",
            "initial_normalized_package_version",
            "initial_release_tag",
        },
        "release context target policy",
    )
    version = _release_version_pair(
        policy["initial_normalized_package_version"], policy["initial_release_tag"]
    )
    pairs = {
        "owner_approved_exact_target": "BLOCKED_REQUIRES_NEW_OWNER_RELEASE_IDENTITY",
        "next_unused_same_milestone_patch": "DURABLE_BURN_THEN_SAME_MILESTONE_PATCH",
    }
    if (
        milestone not in MILESTONES
        or f"v{version[0]}.{version[1]}" != milestone
        or not isinstance(policy["resolution_mode"], str)
        or pairs.get(policy["resolution_mode"]) != policy["conflict_disposition"]
    ):
        raise ReleaseControlError("release target policy changes milestone or conflict authority")
    return policy


def _release_target_registry_projection(
    raw: bytes, *, expected_digest: str, milestone: str
) -> list[str]:
    """Replay the original seven-slot target policy without reading a checkout."""
    if sha256_bytes(raw) != _require_digest(expected_digest, "original target registry"):
        raise ReleaseControlError(
            "target registry differs from independently expected original bytes"
        )
    registry = _release_closed_mapping(
        _source_json(raw, "original target registry"),
        {"milestones", "owner", "schema_version"},
        "original target registry",
    )
    if (
        registry["owner"] != "MP2-007"
        or registry["schema_version"] != "metriplane.release-targets.v1"
    ):
        raise ReleaseControlError("original target registry has another owner or schema")
    rows = _release_id_rows(registry["milestones"], "id", "original target milestones")
    if list(rows) != list(MILESTONES) or milestone not in rows:
        raise ReleaseControlError("original target registry omits or changes roadmap slots")
    for index, (name, value) in enumerate(rows.items()):
        row = _release_closed_mapping(
            value,
            {"id", "predecessor", "required_targets", "version_line"},
            "original target milestone",
        )
        if (
            row["required_targets"] != ["github-release", "pypi", "testpypi"]
            or row["version_line"] != name + ".x"
            or row["predecessor"] != ("v0.3.0" if index == 0 else MILESTONES[index - 1])
        ):
            raise ReleaseControlError(
                "original target policy changes required targets or roadmap lineage"
            )
    return list(rows[milestone]["required_targets"])


def _release_target_conflict_projection(
    observed_targets: object,
    retained_burns: object,
    *,
    milestone: str,
    expected_versions: Sequence[str],
    target_registry_raw: bytes,
    expected_target_registry_digest: str,
    expected_operation_order: Sequence[str],
) -> dict[str, Any]:
    """Preserve every conflict and derive new pairs against original complete history.

    The caller must separately prove the native observations, complete indexed
    lineage, original receipt order and requested versions. This pure projection grants no native
    authority, target-selection permission, durable receipt or release admission.
    """
    if milestone not in MILESTONES:
        raise ReleaseControlError("target conflict projection has an unknown milestone")
    versions = _release_id_list(
        list(expected_versions), "original requested target versions", nonempty=True
    )
    for version in versions:
        parsed = _release_version_pair(version, "v" + version)
        if f"v{parsed[0]}.{parsed[1]}" != milestone:
            raise ReleaseControlError("requested target version is outside its milestone")
    targets = set(
        _release_target_registry_projection(
            target_registry_raw,
            expected_digest=expected_target_registry_digest,
            milestone=milestone,
        )
    )
    operation_order = _release_id_list(
        list(expected_operation_order), "original indexed burn operation order", nonempty=False
    )
    for receipt in operation_order:
        _require_digest(receipt, "original indexed burn receipt")
    if not isinstance(observed_targets, list) or not isinstance(retained_burns, list):
        raise ReleaseControlError("target conflicts lack complete observation/history arrays")
    history: set[tuple[str, str]] = set()
    history_order = []
    operations: dict[str, tuple[int, str, str]] = {}
    for value in retained_burns:
        row = _release_closed_mapping(
            value,
            {
                "burn_manifest_digest",
                "index_receipt_digest",
                "observation_digest",
                "package_version",
                "release_tag",
                "sequence",
                "target_id",
            },
            "original retained burn row",
        )
        version = row["package_version"]
        parsed = _release_version_pair(version, row["release_tag"], historical=True)
        if (
            not isinstance(row["target_id"], str)
            or row["target_id"] not in targets
            or f"v{parsed[0]}.{parsed[1]}" != milestone
            or type(row["sequence"]) is not int
            or row["sequence"] < 1
        ):
            raise ReleaseControlError("retained burn target/milestone/operation is invalid")
        for field in ("burn_manifest_digest", "index_receipt_digest", "observation_digest"):
            _require_digest(row[field], "original retained burn " + field)
        receipt = row["index_receipt_digest"]
        operation = (row["sequence"], row["burn_manifest_digest"], row["observation_digest"])
        if receipt in operations and operations[receipt] != operation:
            raise ReleaseControlError("retained burn operation has conflicting original receipts")
        operations[receipt] = operation
        key = (row["target_id"], version)
        if key in history:
            raise ReleaseControlError("retained burn history repeats a target/version pair")
        history.add(key)
        history_order.append((receipt, *key))
    if set(operations) != set(operation_order):
        raise ReleaseControlError(
            "retained burn history differs from original indexed receipt order"
        )
    positions = {receipt: index for index, receipt in enumerate(operation_order)}
    if history_order != sorted(history_order, key=lambda row: (positions[row[0]], *row[1:])):
        raise ReleaseControlError("retained burn history is not in original operation order")
    seen = set()
    affected = []
    for value in observed_targets:
        row = _release_closed_mapping(
            value,
            {"artifacts", "raw_result_digest", "state", "target_id", "version"},
            "original observed target",
        )
        if not isinstance(row["target_id"], str) or not isinstance(row["version"], str):
            raise ReleaseControlError("observed target pair is malformed")
        key = (row["target_id"], row["version"])
        if key in seen or key[0] not in targets or key[1] not in versions:
            raise ReleaseControlError("observed target duplicates or changes a requested pair")
        seen.add(key)
        _require_digest(row["raw_result_digest"], "observed target raw response")
        if not isinstance(row["state"], str) or row["state"] not in {
            "unused",
            "occupied",
            "partial",
        }:
            raise ReleaseControlError("unknown target state cannot prove conflict absence")
        artifacts = row["artifacts"]
        if not isinstance(artifacts, list) or (row["state"] == "unused" and artifacts):
            raise ReleaseControlError("unused target has artifacts or lacks its exact inventory")
        names = set()
        for artifact in artifacts:
            item = _release_closed_mapping(
                artifact,
                {"expected_digest", "name", "observed_digest", "original_read_back", "size"},
                "prebuild target artifact",
            )
            name = _require_nonempty_string(item["name"], "observed artifact name")
            if (
                name in names
                or item["expected_digest"] is not None
                or type(item["size"]) is not int
                or item["size"] < 0
            ):
                raise ReleaseControlError(
                    "prebuild artifact duplicates or fabricates expected authority"
                )
            names.add(name)
            digest = _require_digest(item["observed_digest"], "observed artifact raw bytes")
            raw = _release_closed_mapping(
                item["original_read_back"],
                {"path", "bytes", "sha256"},
                "observed artifact readback",
            )
            _release_relative_suffix(raw["path"], "observed artifact readback path")
            if (
                type(raw["bytes"]) is not int
                or raw["bytes"] != item["size"]
                or raw["sha256"] != digest
            ):
                raise ReleaseControlError("observed artifact readback byte identity differs")
        if row["state"] in {"occupied", "partial"}:
            affected.append(
                {"target_id": key[0], "version": key[1], "target_state_digest": sha256_json(row)}
            )
    if seen != {(target, version) for target in targets for version in versions}:
        raise ReleaseControlError("target observations omit a requested provider/version pair")
    affected.sort(key=lambda row: (row["target_id"], row["version"]))
    newly_affected = [row for row in affected if (row["target_id"], row["version"]) not in history]
    return {
        "affected_targets": affected,
        "newly_affected_targets": newly_affected,
        "disposition": "new_burn" if newly_affected else "no_new_burn",
        "indexing_required": bool(newly_affected),
    }


def _release_target_selection_projection(
    observed_targets: object,
    retained_burns: object,
    *,
    target_policy: object,
    milestone: str,
    expected_versions: Sequence[str],
    target_registry_raw: bytes,
    expected_target_registry_digest: str,
    expected_operation_order: Sequence[str],
) -> dict[str, Any]:
    """Select from a complete original search; an exact conflict remains unusable.

    Native transport, original index/receipt replay and independently approved
    context policy must precede this projection. Its control facts do not grant
    release admission, and recording a burn cannot erase a historical conflict.
    """
    policy = _release_target_policy_projection(target_policy, milestone=milestone)
    conflicts = _release_target_conflict_projection(
        observed_targets,
        retained_burns,
        milestone=milestone,
        expected_versions=expected_versions,
        target_registry_raw=target_registry_raw,
        expected_target_registry_digest=expected_target_registry_digest,
        expected_operation_order=expected_operation_order,
    )
    initial = policy["initial_normalized_package_version"]
    versions = list(expected_versions)
    if not versions or versions[0] != initial:
        raise ReleaseControlError("target search does not start at the approved initial identity")
    occupied = {row["version"] for row in conflicts["affected_targets"]}
    assert isinstance(retained_burns, list)  # The complete conflict projection checked this.
    forbidden = occupied | {row["package_version"] for row in retained_burns}
    if policy["resolution_mode"] == "owner_approved_exact_target":
        if versions != [initial]:
            raise ReleaseControlError("exact-target policy cannot search a replacement identity")
        selected = initial
    else:
        initial_identity = _release_version_pair(initial, "v" + initial)
        for offset, version in enumerate(versions):
            parsed = _release_version_pair(version, "v" + version)
            if parsed[2] != initial_identity[2] + offset:
                raise ReleaseControlError("target search omits or reorders a same-milestone patch")
        selected = next((version for version in versions if version not in forbidden), None)
        if selected is None:
            raise ReleaseControlError("target search has no completely observed unused identity")
        if selected != versions[-1]:
            raise ReleaseControlError("target search continues after its first unused identity")
    return {
        **conflicts,
        "initial_package_version": "v" + initial,
        "initial_release_tag": policy["initial_release_tag"],
        "selected_package_version": "v" + selected,
        "selected_release_tag": "v" + selected,
        "resolution_rule": policy["resolution_mode"],
        "burn_target_ids": sorted({row["target_id"] for row in conflicts["affected_targets"]}),
        "prior_burn_digests": sorted({row["burn_manifest_digest"] for row in retained_burns}),
        "target_usable": selected not in forbidden,
    }


def _release_target_control_data(
    record_type: str,
    *,
    context: Mapping[str, Any],
    observations: Mapping[str, Any],
    lineage: Mapping[str, Any],
    expected_context_digest: str,
    expected_observations_digest: str,
    expected_lineage_digest: str,
    target_registry_raw: bytes,
    expected_target_registry_digest: str,
    expected_versions: Sequence[str],
    expected_operation_order: Sequence[str],
    producer_intent_digest: str,
) -> tuple[dict[str, Any], bool]:
    """Build one original control payload; the second result is target usability.

    This is shared semantic construction, not a native proof or unsigned-record
    admission. Callers must first replay the complete original context, provider
    observations and indexed lineage, and later bind their own complete journal.
    An exact-target diagnostic can be recorded while target usability is false;
    every gate/source consumer must reject that target even after a durable burn.
    """
    if record_type not in {"release-target-resolution", "release-target-burn"}:
        raise ReleaseControlError("target control has an unknown producer record type")
    for record, kind, expected, self_field in (
        (context, "release-context", expected_context_digest, "context_digest"),
        (
            observations,
            "release-target-observations",
            expected_observations_digest,
            "observation_digest",
        ),
        (lineage, "release-burn-lineage", expected_lineage_digest, "lineage_digest"),
    ):
        validate_record(record, kind)
        if (
            sha256_json(record) != _require_digest(expected, "original " + kind)
            or record["status"] != "PASS"
            or record["synthetic"] != context["synthetic"]
        ):
            raise ReleaseControlError("target control changes original input identity or mode")
        data = record["data"]
        if data.get(self_field) != sha256_json(
            {key: value for key, value in data.items() if key != self_field}
        ):
            raise ReleaseControlError("target control original semantic digest differs")
    milestone = context["data"].get("framework_milestone")
    if not isinstance(milestone, str) or lineage["data"].get("milestone") != milestone:
        raise ReleaseControlError("target control original context and lineage milestone differ")
    original_context = _release_closed_mapping(
        observations["data"].get("original_release_context"),
        {"record_type", "record_digest", "original_file"},
        "target observations original context",
    )
    if (
        original_context["record_type"] != "release-context"
        or original_context["record_digest"] != expected_context_digest
        or observations["data"].get("registry_digest") != expected_target_registry_digest
        or observations["data"].get("capture_phase") != "prebuild"
        or lineage["data"].get("read_back_complete") is not True
        or lineage["data"].get("index_backend_id") != "attempt-index"
    ):
        raise ReleaseControlError("target control original policy, capture or history differs")
    selection = _release_target_selection_projection(
        observations["data"].get("targets"),
        lineage["data"].get("burns"),
        target_policy=context["data"].get("target_policy"),
        milestone=milestone,
        expected_versions=expected_versions,
        target_registry_raw=target_registry_raw,
        expected_target_registry_digest=expected_target_registry_digest,
        expected_operation_order=expected_operation_order,
    )
    payload: dict[str, Any] = {
        "burn_lineage_digest": expected_lineage_digest,
        "invocation_root_locator": "invocations",
        "milestone": milestone,
        "producer_intent_digest": _require_digest(producer_intent_digest, "target producer intent"),
    }
    if record_type == "release-target-resolution":
        payload.update(
            {
                field: selection[field]
                for field in (
                    "burn_target_ids",
                    "initial_package_version",
                    "initial_release_tag",
                    "prior_burn_digests",
                    "resolution_rule",
                    "selected_package_version",
                    "selected_release_tag",
                )
            }
        )
        payload.update(
            observations_digest=expected_observations_digest,
            release_context_digest=expected_context_digest,
            requires_new_burn=selection["indexing_required"],
        )
        payload["resolution_digest"] = sha256_json(payload)
    else:
        payload.update(
            affected_targets=selection["affected_targets"],
            disposition=selection["disposition"],
            indexing_required=selection["indexing_required"],
            observation_digest=expected_observations_digest,
            resolved_package_version=selection["selected_package_version"],
            resolved_release_tag=selection["selected_release_tag"],
            reason=(
                f"{len(selection['affected_targets'])} observed conflicting target/version pairs; "
                f"{len(selection['newly_affected_targets'])} require a new durable burn. "
                "Previously indexed pairs remain forbidden."
            ),
        )
        payload["burn_id"] = sha256_json(payload) if selection["indexing_required"] else None
    return payload, bool(selection["target_usable"])


def _release_target_original_file(
    root: Path, reference: object, *, label: str
) -> tuple[Path, bytes]:
    row = _release_closed_mapping(reference, {"path", "bytes", "sha256"}, label + " original file")
    suffix = _release_relative_suffix(row["path"], label + " original path")
    path = root / suffix
    raw = _safe_release_bytes(path)
    if (
        type(row["bytes"]) is not int
        or row["bytes"] < 0
        or len(raw) != row["bytes"]
        or sha256_bytes(raw) != _require_digest(row["sha256"], label + " original digest")
    ):
        raise ReleaseControlError(label + " original byte identity differs")
    return path, raw


def _release_target_command_originals(
    observations_path: Path, lineage_path: Path
) -> tuple[dict[str, Any], dict[str, Any], dict[str, Any], bytes, list[str], list[str]]:
    observations_path = observations_path.absolute()
    lineage_path = lineage_path.absolute()
    root = observations_path.parent
    if lineage_path.parent != root:
        raise ReleaseControlError("target control inputs do not share one retained run root")
    observations = read_json(observations_path)
    lineage = read_json(lineage_path)
    validate_record(observations, "release-target-observations")
    validate_record(lineage, "release-burn-lineage")
    validate_release_producer_journal(
        observations,
        observations_path,
        producer="capture_release_target_observations.py",
    )
    validate_release_producer_journal(
        lineage, lineage_path, producer="export_release_burn_lineage.py"
    )
    observation_data = observations["data"]
    context_link = _release_closed_mapping(
        observation_data.get("original_release_context"),
        {"record_type", "record_digest", "original_file"},
        "target observation context link",
    )
    if context_link["record_type"] != "release-context":
        raise ReleaseControlError("target observation context link has another type")
    _, context_raw = _release_target_original_file(
        root, context_link["original_file"], label="release context"
    )
    context = _source_json(context_raw, "target control original context")
    validate_record(context, "release-context")
    if sha256_json(context) != context_link["record_digest"]:
        raise ReleaseControlError("target observation changes original context C")
    _, registry_raw = _release_target_original_file(
        root, observation_data.get("original_registry"), label="target registry"
    )
    versions = sorted(
        {
            _require_nonempty_string(row.get("version"), "observed target version")
            for row in observation_data.get("targets", [])
            if isinstance(row, dict)
        },
        key=lambda version: _release_version_pair(version, "v" + version),
    )
    operation_order: list[str] = []
    for row in lineage["data"].get("burns", []):
        if not isinstance(row, dict):
            raise ReleaseControlError("burn lineage row is not an object")
        receipt = _require_digest(row.get("index_receipt_digest"), "burn lineage index receipt")
        if receipt not in operation_order:
            operation_order.append(receipt)
    return observations, lineage, context, registry_raw, versions, operation_order


def _release_target_command_input_paths(
    tool: str, argv: Sequence[str], root: Path
) -> list[tuple[Path, str]]:
    arguments = _release_original_arguments(tool, [tool, *argv])
    observations_flag = (
        "live-target-observations" if tool == "resolve_release_target.py" else "target-observations"
    )
    lineage_flag = (
        "retained-burn-lineage" if tool == "resolve_release_target.py" else "burn-lineage"
    )
    observations_path = _release_historical_path(arguments[observations_flag], Path.cwd())
    lineage_path = _release_historical_path(arguments[lineage_flag], Path.cwd())
    if observations_path.parent != root or lineage_path.parent != root:
        raise ReleaseControlError("target control inputs must be directly retained in its run root")
    observations = read_json(observations_path)
    validate_record(observations, "release-target-observations")
    data = observations["data"]
    context_link = _release_closed_mapping(
        data.get("original_release_context"),
        {"record_type", "record_digest", "original_file"},
        "target command context link",
    )
    context_path, _ = _release_target_original_file(
        root, context_link["original_file"], label="release context"
    )
    registry_path, _ = _release_target_original_file(
        root, data.get("original_registry"), label="target registry"
    )
    result = [
        (observations_path, "metriplane.release-target-observations.v1"),
        (lineage_path, "metriplane.release-burn-lineage.v1"),
        (context_path, "metriplane.release-context.v1"),
        (registry_path, "metriplane.release-targets.v1"),
    ]
    if tool == "resolve_release_target.py":
        supplied_registry = _release_historical_path(arguments["targets"], Path.cwd())
        if supplied_registry != registry_path:
            raise ReleaseControlError("target resolution selects another target registry")
    else:
        target_path = _release_historical_path(arguments["target-resolution"], Path.cwd())
        if target_path.parent != root:
            raise ReleaseControlError(
                "target burn resolution must be directly retained in its run root"
            )
        result.append((target_path, "metriplane.release-target-resolution.v1"))
    if len({path for path, _ in result}) != len(result):
        raise ReleaseControlError("target control input paths alias")
    return result


def _release_predecessor_command_input_paths(
    tool: str, argv: Sequence[str], root: Path
) -> list[tuple[Path, str]]:
    """Close predecessor commands over every selected original byte before reservation."""
    if tool not in {"resolve_release_predecessor.py", "validate_release_predecessor.py"}:
        raise ReleaseControlError("predecessor input collector has another tool")
    arguments = _release_original_arguments(tool, [tool, *argv])
    cwd = _release_capture_absolute(Path.cwd())

    def command_path(flag: str) -> Path:
        path = _release_historical_path(arguments[flag], cwd)
        if not path.is_relative_to(root) or path == root:
            raise ReleaseControlError("predecessor command input escapes its run root: " + flag)
        _release_relative_suffix(path.relative_to(root).as_posix(), "predecessor command input")
        return path

    if tool == "validate_release_predecessor.py":
        record_path = command_path("record")
        record = read_json(record_path)
        validate_record(record, "release-predecessor")
        producer_directory = (
            root / "invocations/resolve-release-predecessor" / f"{record['sequence']:03d}"
        )
        producer = _validate_intent(producer_directory)
        if producer.intent["invocation_id"] != record["invocation_id"]:
            raise ReleaseControlError("predecessor validator selected another producer intent")
        producer_cwd = _canonical_absolute_path(
            producer.intent["environment"]["working_directory"],
            "predecessor producer working directory",
        )
        producer_args = _release_original_arguments(
            "resolve_release_predecessor.py", producer.intent["argv"]
        )
        original_directory = _release_historical_path(producer_args["invocation-dir"], producer_cwd)
        original_root = original_directory.parents[2]
        relocated: list[tuple[Path, str]] = [(record_path, "metriplane.release-predecessor.v1")]
        for row in producer.intent["inputs"]:
            original = _canonical_absolute_path(row["path"], "predecessor producer input")
            try:
                suffix = original.relative_to(original_root)
            except ValueError as exc:
                raise ReleaseControlError(
                    "predecessor producer input escapes its run root"
                ) from exc
            relocated.append(
                (
                    root
                    / _release_relative_suffix(
                        suffix.as_posix(), "predecessor relocated producer input"
                    ),
                    row["schema_id"],
                )
            )
        selected_paths = {path for path, _ in relocated}
        if any(
            command_path(flag) not in selected_paths
            for flag in ("release-context", "predecessor-policy")
        ):
            raise ReleaseControlError(
                "predecessor validator selects inputs outside the original producer closure"
            )
        return relocated

    fixed = (
        ("release-context", "metriplane.release-context.v1"),
        ("predecessor-policy", "application/octet-stream"),
        ("prerequisite-proofs", "metriplane.release-predecessor-proof-index.v1"),
        ("chain-genesis", "application/octet-stream"),
        ("attempt-index-genesis", "application/octet-stream"),
        ("stores", "metriplane.release-evidence-store-registry.v1"),
        ("v0.4-genesis", "application/octet-stream"),
    )
    inputs = [(command_path(flag), schema) for flag, schema in fixed]
    policy = _source_json(
        _safe_release_bytes(command_path("predecessor-policy")),
        "predecessor command policy",
    )
    decision = policy.get("expected_predecessor_decision")
    if isinstance(decision, dict):
        authority = decision.get("authority")
        if not isinstance(authority, dict):
            raise ReleaseControlError("predecessor historical decision authority is malformed")
        registry_ref = _release_closed_mapping(
            authority.get("raw_registry"),
            {"path", "bytes", "sha256"},
            "predecessor historical decision registry",
        )
        inputs.append(
            (
                root
                / _release_relative_suffix(
                    registry_ref["path"], "predecessor historical decision registry path"
                ),
                "application/octet-stream",
            )
        )
    for name, schema in (
        ("gate-input.json", "metriplane.release-gate-input.v1"),
        ("target-resolution.json", "metriplane.release-target-resolution.v1"),
    ):
        path = root / name
        if not path.is_file() or path.is_symlink():
            raise ReleaseControlError("predecessor command lacks its bound " + name)
        inputs.append((path, schema))

    proof_path = command_path("prerequisite-proofs")
    proof = _release_closed_mapping(
        read_json(proof_path),
        {"schema_version", "records", "raw_proofs", "git_objects", "artifacts"},
        "predecessor command proof index",
    )
    if proof["schema_version"] != "metriplane.release-predecessor-proof-index.v1":
        raise ReleaseControlError("predecessor command proof index type differs")
    for group in ("records", "raw_proofs", "git_objects", "artifacts"):
        rows = proof[group]
        if not isinstance(rows, list):
            raise ReleaseControlError("predecessor command proof group is not a list")
        for row in rows:
            if not isinstance(row, dict) or not isinstance(row.get("original_file"), dict):
                raise ReleaseControlError("predecessor command proof row lacks original bytes")
            reference = row["original_file"]
            suffix = _release_relative_suffix(
                reference.get("path"), "predecessor command proof original path"
            )
            schema = (
                "metriplane." + str(row.get("record_type")) + ".v1"
                if group == "records"
                else "application/octet-stream"
            )
            inputs.append((root / suffix, schema))
    selected: dict[Path, str] = {}
    for path, schema in inputs:
        if path in selected and selected[path] != schema:
            raise ReleaseControlError("predecessor command aliases differently typed inputs")
        selected[path] = schema
    return sorted(selected.items(), key=lambda row: str(row[0]))


def _release_predecessor_proof_originals(
    root: Path, proof_path: Path
) -> tuple[dict[str, Any], dict[tuple[str, str], tuple[Path, dict[str, Any]]]]:
    """Read and authenticate every indexed predecessor original from one retained root."""
    root = _release_capture_absolute(root)
    proof_path = _release_capture_absolute(proof_path)
    if not proof_path.is_relative_to(root):
        raise ReleaseControlError("predecessor proof index escapes its retained root")
    proof = _release_closed_mapping(
        read_json(proof_path),
        {"schema_version", "records", "raw_proofs", "git_objects", "artifacts"},
        "predecessor proof index",
    )
    if proof["schema_version"] != "metriplane.release-predecessor-proof-index.v1":
        raise ReleaseControlError("predecessor proof index type differs")
    originals: dict[tuple[str, str], tuple[Path, dict[str, Any]]] = {}
    paths: set[Path] = set()
    for group in ("records", "raw_proofs", "git_objects", "artifacts"):
        rows = proof[group]
        if not isinstance(rows, list):
            raise ReleaseControlError("predecessor proof group is not a list")
        for value in rows:
            if not isinstance(value, dict):
                raise ReleaseControlError("predecessor proof row is not an object")
            reference = _release_closed_mapping(
                value.get("original_file"),
                {"path", "bytes", "sha256"},
                "predecessor indexed original",
            )
            path = root / _release_relative_suffix(
                reference["path"], "predecessor indexed original path"
            )
            if path in paths:
                raise ReleaseControlError("predecessor proof index aliases original paths")
            paths.add(path)
            raw = _safe_release_bytes(path)
            if (
                type(reference["bytes"]) is not int
                or reference["bytes"] < 0
                or len(raw) != reference["bytes"]
                or sha256_bytes(raw)
                != _require_digest(reference["sha256"], "predecessor indexed original R")
            ):
                raise ReleaseControlError("predecessor indexed original bytes differ")
            if group == "records":
                record_type = _require_nonempty_string(
                    value.get("record_type"), "predecessor indexed record type"
                )
                record = _source_json(raw, "predecessor indexed record")
                validate_record(record, record_type)
                digest = _require_digest(value.get("record_digest"), "predecessor indexed record C")
                if raw != canonical_json(record) or sha256_json(record) != digest:
                    raise ReleaseControlError(
                        "predecessor indexed record differs from its canonical identity"
                    )
                key = (record_type, digest)
                if key in originals:
                    raise ReleaseControlError("predecessor proof index repeats a record identity")
                originals[key] = (path, record)
            elif group == "git_objects":
                object_type = value.get("object_type")
                if object_type not in {"blob", "commit", "tag", "tree"}:
                    raise ReleaseControlError("predecessor indexed Git object type differs")
                oid = _release_git_oid(value.get("git_object_id"), "predecessor indexed Git object")
                actual = hashlib.sha1(
                    f"{object_type} {len(raw)}\0".encode("ascii") + raw,
                    usedforsecurity=False,
                ).hexdigest()
                if actual != oid:
                    raise ReleaseControlError("predecessor indexed Git object bytes differ")
            elif group == "artifacts":
                if value.get("artifact_kind") not in {"wheel", "sdist"}:
                    raise ReleaseControlError("predecessor indexed artifact type differs")
                _require_nonempty_string(
                    value.get("filename"), "predecessor indexed artifact filename"
                )
    return proof, originals


def _release_predecessor_original_record(
    originals: Mapping[tuple[str, str], tuple[Path, dict[str, Any]]],
    record_type: str,
    digest: object,
    label: str,
) -> dict[str, Any]:
    """Resolve one authenticated full-record C without scanning or filename inference."""
    identity = _require_digest(digest, label + " C")
    resolved = originals.get((record_type, identity))
    if resolved is None:
        raise ReleaseControlError(label + " is absent from the authenticated proof closure")
    record = resolved[1]
    if record["record_type"] != record_type or sha256_json(record) != identity:
        raise ReleaseControlError(label + " differs from its authenticated record identity")
    return record


def _release_predecessor_unique_record(
    originals: Mapping[tuple[str, str], tuple[Path, dict[str, Any]]],
    record_type: str,
    predicate: Callable[[dict[str, Any]], bool],
    label: str,
) -> tuple[str, dict[str, Any]]:
    """Select one semantic root only after every candidate has an authenticated C."""
    matches = [
        (digest, record)
        for (kind, digest), (_path, record) in originals.items()
        if kind == record_type and predicate(record)
    ]
    if len(matches) != 1:
        raise ReleaseControlError(label + " is absent, duplicated or ambiguous")
    return matches[0]


def _release_predecessor_manifest_contains(
    manifest: Mapping[str, Any], required_record_digests: set[str]
) -> None:
    """Require exact canonical record bytes as distinct entries in a retained envelope."""
    entries = _release_evidence_manifest_content(manifest["data"])
    observed = [entry["sha256"] for entry in entries]
    for digest in required_record_digests:
        _require_digest(digest, "predecessor manifest required original")
        if observed.count(digest) != 1:
            raise ReleaseControlError(
                "predecessor manifest does not contain one exact required original"
            )


def _release_predecessor_subject_originals(
    root: Path, proof: Mapping[str, Any], subject: Mapping[str, Any]
) -> None:
    """Bind policy-selected Git/artifact identities to the authenticated original bytes."""
    required_git = {
        "commit": subject.get("source_commit"),
        "tree": subject.get("source_tree"),
        "tag": subject.get("tag_object"),
    }
    observed_git: dict[str, str] = {}
    for value in proof["git_objects"]:
        row = _release_closed_mapping(
            value,
            {"kind", "object_type", "git_object_id", "original_file"},
            "predecessor selected Git original",
        )
        object_type = row["object_type"]
        if object_type in observed_git:
            raise ReleaseControlError("predecessor proof repeats a selected Git object type")
        observed_git[object_type] = row["git_object_id"]
    if observed_git != required_git:
        raise ReleaseControlError("predecessor Git originals differ from the policy subject")

    expected_artifacts = _release_original_artifact_descriptors(
        subject.get("artifacts"), package_version=subject["normalized_package_version"]
    )
    observed_artifacts: dict[str, dict[str, Any]] = {}
    for value in proof["artifacts"]:
        row = _release_closed_mapping(
            value,
            {"kind", "artifact_kind", "filename", "original_file"},
            "predecessor selected artifact original",
        )
        kind = row["artifact_kind"]
        ref = _release_closed_mapping(
            row["original_file"], {"path", "bytes", "sha256"}, "predecessor artifact bytes"
        )
        path = root / _release_relative_suffix(ref["path"], "predecessor artifact path")
        raw = _safe_release_bytes(path)
        if kind in observed_artifacts or (
            row["filename"] != expected_artifacts.get(kind, {}).get("filename")
            or len(raw) != expected_artifacts.get(kind, {}).get("bytes")
            or sha256_bytes(raw) != expected_artifacts.get(kind, {}).get("sha256")
            or ref["bytes"] != len(raw)
            or ref["sha256"] != sha256_bytes(raw)
            or canonical_json(ref) != canonical_json(expected_artifacts[kind]["readback"])
        ):
            raise ReleaseControlError("predecessor artifact original differs from policy subject")
        observed_artifacts[kind] = row
    if set(observed_artifacts) != {"wheel", "sdist"}:
        raise ReleaseControlError("predecessor proof lacks the exact two distributions")


def _release_predecessor_original_ref(root: Path, path: Path) -> dict[str, Any]:
    path = _release_capture_absolute(path)
    if not path.is_relative_to(root) or path == root:
        raise ReleaseControlError("predecessor original reference escapes its retained root")
    raw = _safe_release_bytes(path)
    return {
        "path": _release_relative_suffix(
            path.relative_to(root).as_posix(), "predecessor original reference"
        ).as_posix(),
        "bytes": len(raw),
        "sha256": sha256_bytes(raw),
    }


def _release_predecessor_selection_observations(
    root: Path, proof: Mapping[str, Any], *, observed_at: str
) -> dict[str, Any]:
    """Select each current readback once by its existing proof-index purpose."""
    fields = (
        "provider_state",
        "provider_event_history",
        "success_chain_readback",
        "lkg_state_and_history_readback",
        "attempt_index_readback",
    )
    selected: dict[str, dict[str, Any]] = {}
    for value in proof["raw_proofs"]:
        row = _release_closed_mapping(
            value, {"kind", "purpose", "original_file"}, "predecessor selection proof"
        )
        purpose = row["purpose"]
        if purpose not in fields:
            continue
        if purpose in selected:
            raise ReleaseControlError("predecessor selection readback purpose is duplicated")
        ref = _release_closed_mapping(
            row["original_file"], {"path", "bytes", "sha256"}, "predecessor selection bytes"
        )
        path = root / _release_relative_suffix(ref["path"], "predecessor selection path")
        raw = _safe_release_bytes(path)
        if ref["bytes"] != len(raw) or ref["sha256"] != sha256_bytes(raw):
            raise ReleaseControlError("predecessor selection readback bytes differ")
        selected[purpose] = dict(ref)
    if set(selected) != set(fields):
        raise ReleaseControlError("predecessor proof lacks one exact current selection readback")
    _parse_utc_timestamp(observed_at, "predecessor selection observation time")
    return {"observed_at": observed_at, **selected}


def _release_predecessor_candidate_identity_payload(
    candidate: Mapping[str, Any], *, subject: Mapping[str, Any]
) -> None:
    """Validate an original candidate identity, including governed historical post releases."""
    if set(candidate) != _CANDIDATE_FIELDS:
        raise ReleaseControlError("historical predecessor candidate shape is not closed")
    for field in _CANDIDATE_FIELDS - {
        "build_invocation_id",
        "control_journal_locator",
        "final_directory",
        "evaluation_adoption_digest",
        "evaluation_adoption_mode",
        "milestone",
        "package_version",
        "release_tag",
    }:
        _require_digest(candidate[field], "historical predecessor candidate " + field)
    milestone = subject.get("framework_milestone")
    release_tag = subject.get("release_tag")
    normalized = subject.get("normalized_package_version")
    if (
        candidate["candidate_digest"] != _candidate_payload_digest(candidate)
        or candidate["milestone"] != milestone
        or candidate["package_version"] != release_tag
        or candidate["release_tag"] != release_tag
        or candidate["evaluation_adoption_mode"] != "none"
        or candidate["evaluation_adoption_digest"] is not None
        or not isinstance(release_tag, str)
        or not release_tag.startswith("v")
    ):
        raise ReleaseControlError("historical predecessor candidate identity differs")
    parsed = _release_version_pair(normalized, release_tag, historical=True)
    if milestone != f"v{parsed[0]}.{parsed[1]}":
        raise ReleaseControlError("historical predecessor candidate milestone differs")
    _require_invocation(candidate["build_invocation_id"])
    final = _canonical_absolute_path(
        candidate["final_directory"], "historical predecessor candidate directory"
    )
    locator = _canonical_absolute_path(
        candidate["control_journal_locator"], "historical predecessor control locator"
    )
    if (
        final.name != candidate["candidate_digest"]
        or final.parent.name != release_tag
        or locator.parts[-4:] != ("invocations", "candidate-finalization", "001", "invocation.json")
        or locator.parents[4] != final.parent.parent / ".control"
        or re.fullmatch(r"[A-Za-z0-9][A-Za-z0-9._-]{0,159}", locator.parents[3].name) is None
    ):
        raise ReleaseControlError("historical predecessor candidate paths differ")


def _release_predecessor_static_authorities(
    *,
    chain_genesis_raw: bytes,
    attempt_genesis_raw: bytes,
    release_genesis_raw: bytes,
    stores_raw: bytes,
    chain_backend: str,
    attempt_index_backend: str,
    lkg_backend: str,
) -> str:
    """Replay the closed static roots captured by the predecessor command."""
    release_genesis = _release_closed_mapping(
        _source_json(release_genesis_raw, "predecessor release genesis"),
        {
            "annotated_tag_object",
            "authority",
            "commit",
            "schema_version",
            "synthetic",
            "tree",
            "version",
        },
        "predecessor release genesis",
    )
    if (
        release_genesis["schema_version"] != "metriplane.release-genesis.v1"
        or release_genesis["authority"] != "historical-observation"
        or release_genesis["synthetic"] is not False
        or release_genesis["version"] != "v0.3.0"
    ):
        raise ReleaseControlError("predecessor release genesis identity differs")
    for field in ("annotated_tag_object", "commit", "tree"):
        _release_git_oid(release_genesis[field], "predecessor release genesis " + field)

    chain_genesis = _release_closed_mapping(
        _source_json(chain_genesis_raw, "predecessor chain genesis"),
        {"predecessor", "release", "release_genesis_digest", "schema_version", "sequence"},
        "predecessor chain genesis",
    )
    if (
        chain_genesis["schema_version"] != "metriplane.release-evidence-chain-genesis.v1"
        or chain_genesis["predecessor"] is not None
        or chain_genesis["release"] != "v0.3.0"
        or chain_genesis["sequence"] != 0
        or chain_genesis["release_genesis_digest"] != sha256_json(release_genesis)
    ):
        raise ReleaseControlError("predecessor chain genesis differs from release genesis")

    attempt_genesis = _release_closed_mapping(
        _source_json(attempt_genesis_raw, "predecessor attempt-index genesis"),
        {"cas_required", "entries", "epoch", "no_overwrite", "schema_version"},
        "predecessor attempt-index genesis",
    )
    if (
        attempt_genesis["schema_version"] != "metriplane.release-attempt-index-genesis.v1"
        or attempt_genesis["cas_required"] is not True
        or attempt_genesis["no_overwrite"] is not True
        or attempt_genesis["epoch"] != 0
        or attempt_genesis["entries"] != []
    ):
        raise ReleaseControlError("predecessor attempt-index genesis is not the empty CAS root")

    registry = _release_closed_mapping(
        _source_json(stores_raw, "predecessor store registry"),
        {
            "attempt_index",
            "backends",
            "live_status",
            "owner",
            "schema_version",
            "secrets_embedded",
            "stores",
        },
        "predecessor store registry",
    )
    if (
        registry["schema_version"] != "metriplane.release-evidence-stores.v1"
        or registry["owner"] != "MP2-007"
        or registry["secrets_embedded"] is not False
    ):
        raise ReleaseControlError("predecessor store registry owner or type differs")
    backends = registry["backends"]
    if not isinstance(backends, list) or any(not isinstance(row, dict) for row in backends):
        raise ReleaseControlError("predecessor backend registry is malformed")
    backend_ids = [row.get("backend_id") for row in backends]
    if backend_ids != [
        "payload-store-a",
        "payload-store-b",
        "attempt-index",
        "success-chain",
        "last-known-good",
        "main-health-state",
        "main-health-summary",
    ] or [attempt_index_backend, chain_backend, lkg_backend] != [
        "attempt-index",
        "success-chain",
        "last-known-good",
    ]:
        raise ReleaseControlError("predecessor command changes the governed backend identities")
    stores = registry["stores"]
    if not isinstance(stores, list) or len(stores) != 2:
        raise ReleaseControlError("predecessor store registry lacks its exact pair")
    declarations = [
        _release_closed_mapping(
            row,
            {"backend_id", "id", "independence_group", "live_binding"},
            "predecessor store declaration",
        )
        for row in stores
    ]
    if (
        [row["backend_id"] for row in declarations] != ["payload-store-a", "payload-store-b"]
        or [row["id"] for row in declarations] != ["payload-store-a", "payload-store-b"]
        or len({row["independence_group"] for row in declarations}) != 2
    ):
        raise ReleaseControlError("predecessor store declarations are aliased or reordered")
    return sha256_bytes(attempt_genesis_raw)


def _release_predecessor_decision_authority(
    root: Path, decision: Mapping[str, Any], *, subject: Mapping[str, Any]
) -> dict[str, str]:
    """Resolve the policy-selected historical issue from its original registry bytes."""
    binding = _release_closed_mapping(
        decision, {"identity", "authority"}, "historical predecessor decision binding"
    )
    identity = _release_linear_identity(binding["identity"], require_project=True)
    authority = _release_closed_mapping(
        binding["authority"],
        {"raw_registry", "json_pointer", "canonical_row_digest"},
        "historical predecessor decision authority",
    )
    ref = _release_closed_mapping(
        authority["raw_registry"],
        {"path", "bytes", "sha256"},
        "historical predecessor decision registry",
    )
    path = root / _release_relative_suffix(
        ref["path"], "historical predecessor decision registry path"
    )
    raw = _safe_release_bytes(path)
    if len(raw) != ref["bytes"] or sha256_bytes(raw) != ref["sha256"]:
        raise ReleaseControlError("historical predecessor decision registry bytes differ")
    registry = _source_json(raw, "historical predecessor decision registry")
    row = _release_closed_mapping(
        _release_json_pointer(
            registry,
            authority["json_pointer"],
            "historical predecessor decision registry pointer",
        ),
        {"identity", "framework_milestone", "release_tag"},
        "historical predecessor decision row",
    )
    if (
        sha256_json(row) != authority["canonical_row_digest"]
        or canonical_json(_release_linear_identity(row["identity"], require_project=True))
        != canonical_json(identity)
        or row["framework_milestone"] != subject["framework_milestone"]
        or row["release_tag"] != subject["release_tag"]
    ):
        raise ReleaseControlError("historical predecessor decision row changes its selection")
    return identity


def _release_predecessor_raw_proof(
    root: Path, proof: Mapping[str, Any], *, purpose: str
) -> tuple[dict[str, Any], bytes]:
    matches = [
        row
        for row in proof["raw_proofs"]
        if isinstance(row, dict) and row.get("purpose") == purpose
    ]
    if len(matches) != 1:
        raise ReleaseControlError("predecessor raw proof is absent or ambiguous: " + purpose)
    row = _release_closed_mapping(
        matches[0], {"kind", "purpose", "original_file"}, "predecessor raw proof"
    )
    ref = _release_closed_mapping(
        row["original_file"], {"path", "bytes", "sha256"}, "predecessor raw proof bytes"
    )
    raw = _safe_release_bytes(
        root / _release_relative_suffix(ref["path"], "predecessor raw proof path")
    )
    if len(raw) != ref["bytes"] or sha256_bytes(raw) != ref["sha256"]:
        raise ReleaseControlError("predecessor raw proof bytes differ: " + purpose)
    return dict(ref), raw


def _release_predecessor_closed_decision(
    root: Path,
    proof: Mapping[str, Any],
    originals: Mapping[tuple[str, str], tuple[Path, dict[str, Any]]],
    *,
    closed_digest: str,
    candidate_full_digest: str,
    close_root_digest: str,
    decision_identity: Mapping[str, str],
) -> None:
    """Replay the synthetic Closed envelope and its exact original provider/policy bytes."""
    record = _release_predecessor_original_record(
        originals, "release-protected-input", closed_digest, "selected signed Closed decision"
    )
    data = _release_closed_mapping(
        record["data"],
        {
            "input_kind",
            "transition_kind",
            "decision",
            "authorized_role",
            "conflicts",
            "signer_identity",
            "signing_method",
            "authority_policy_digest",
            "provider_attestation_keyring_digest",
            "issued_at",
            "expires_at",
            "provider_event",
            "original_provider_close_event",
            "task_state_policy_registry",
            "subject_digests",
        },
        "selected signed Closed decision data",
    )
    if {
        "input_kind": data["input_kind"],
        "transition_kind": data["transition_kind"],
        "decision": data["decision"],
        "authorized_role": data["authorized_role"],
        "conflicts": data["conflicts"],
        "signing_method": data["signing_method"],
    } != {
        "input_kind": "task_state_transition",
        "transition_kind": "release_decision_closed",
        "decision": "CLOSED",
        "authorized_role": "release_operator",
        "conflicts": [],
        "signing_method": "provider-attestation-v1",
    }:
        raise ReleaseControlError("selected Closed decision weakens its transition authority")
    for field in ("authority_policy_digest", "provider_attestation_keyring_digest"):
        _require_digest(data[field], "selected Closed " + field)
    issued = _parse_utc_timestamp(data["issued_at"], "selected Closed issue time")
    expires = _parse_utc_timestamp(data["expires_at"], "selected Closed expiry time")
    if expires <= issued:
        raise ReleaseControlError("selected Closed authorization interval is invalid")
    event = _release_closed_mapping(
        data["provider_event"],
        {
            "provider",
            "api_version",
            "team_id",
            "project_id",
            "issue_id",
            "issue_identifier",
            "event_id",
            "actor_id",
            "before_state_id",
            "after_state_id",
            "before_state_key",
            "after_state_key",
            "server_timestamp",
        },
        "selected Closed provider event",
    )
    event_identity = {key: event[key] for key in decision_identity}
    event_time = _parse_utc_timestamp(event["server_timestamp"], "selected Closed provider event")
    if (
        canonical_json(event_identity) != canonical_json(decision_identity)
        or event["provider"] != "linear"
        or event["before_state_key"] != "open_finalizing"
        or event["after_state_key"] != "closed"
        or not issued <= event_time < expires
        or data["signer_identity"] != event["actor_id"]
    ):
        raise ReleaseControlError("selected Closed provider event changes its issue or transition")
    for field in ("before_state_id", "after_state_id"):
        _release_linear_uuid(event[field], "selected Closed " + field)
    for field in ("api_version", "event_id", "actor_id", "signer_identity"):
        _require_nonempty_string(
            event[field] if field in event else data[field], "selected Closed " + field
        )

    event_ref, event_raw = _release_predecessor_raw_proof(
        root, proof, purpose="original_provider_close_event"
    )
    policy_ref, policy_raw = _release_predecessor_raw_proof(
        root, proof, purpose="task_state_policy_registry"
    )
    if (
        canonical_json(data["original_provider_close_event"]) != canonical_json(event_ref)
        or canonical_json(data["task_state_policy_registry"]) != canonical_json(policy_ref)
        or canonical_json(_source_json(event_raw, "selected original provider close event"))
        != canonical_json(event)
    ):
        raise ReleaseControlError("selected Closed original provider or policy bytes differ")
    _release_task_state_policy_projection(policy_raw, expected_digest=sha256_bytes(policy_raw))

    subjects = data["subject_digests"]
    expected_names = [
        "predecessor_candidate_identity",
        "decision_identity",
        "role_assignments",
        "task_state_policy_registry",
        "durable_close_root",
        "original_provider_close_event",
    ]
    if (
        not isinstance(subjects, list)
        or len(subjects) != len(expected_names)
        or any(
            not isinstance(row, dict) or set(row) != {"subject", "sha256"} or row["subject"] != name
            for row, name in zip(subjects, expected_names, strict=True)
        )
    ):
        raise ReleaseControlError("selected Closed decision lacks its ordered subjects")
    values = {row["subject"]: row["sha256"] for row in subjects}
    if (
        values["predecessor_candidate_identity"] != candidate_full_digest
        or values["decision_identity"] != sha256_json(decision_identity)
        or values["durable_close_root"] != close_root_digest
        or values["task_state_policy_registry"] != sha256_bytes(policy_raw)
        or values["original_provider_close_event"] != sha256_bytes(event_raw)
    ):
        raise ReleaseControlError("selected Closed decision changes an original subject")
    role_record = _release_predecessor_original_record(
        originals,
        "release-role-assignments",
        values["role_assignments"],
        "selected Closed role assignments",
    )
    if role_record["status"] != "PASS":
        raise ReleaseControlError("selected Closed role assignments are not passing")
    signers = _validated_record_signers(record, live=False)
    if signers != {("test-fixture", data["signer_identity"])}:
        raise ReleaseControlError("selected Closed decision has another authenticated signer")


def _release_predecessor_reconciled_graph(
    originals: Mapping[tuple[str, str], tuple[Path, dict[str, Any]]],
    *,
    subject: Mapping[str, Any],
    candidate_milestone: str,
    decision_identity: Mapping[str, str],
) -> dict[str, Any]:
    """Resolve the selected historical success/closure graph by authenticated links.

    This is the relationship layer for RECONCILED_LKG. Native backend, provider,
    signature and two-store authority are replayed by their existing owners; this
    function prevents a caller from substituting an unrelated valid record.
    """
    if candidate_milestone not in MILESTONES[:-1]:
        raise ReleaseControlError("reconciled predecessor candidate milestone is unsupported")
    selected_version = _release_version_pair(
        subject.get("normalized_package_version"), subject.get("release_tag"), historical=True
    )
    predecessor_milestone = subject.get("framework_milestone")
    if (
        predecessor_milestone not in MILESTONES[:-2]
        or predecessor_milestone != f"v{selected_version[0]}.{selected_version[1]}"
    ):
        raise ReleaseControlError("reconciled predecessor subject has another milestone")

    candidate_full_digest, candidate_record = _release_predecessor_unique_record(
        originals,
        "release-candidate-identity",
        lambda record: (
            record.get("status") == "PASS"
            and record.get("data", {}).get("milestone") == predecessor_milestone
            and record.get("data", {}).get("package_version")
            in {subject.get("normalized_package_version"), subject.get("release_tag")}
            and record.get("data", {}).get("release_tag") == subject.get("release_tag")
        ),
        "policy-selected predecessor candidate",
    )
    candidate = candidate_record["data"]
    _release_predecessor_candidate_identity_payload(candidate, subject=subject)
    source_record = _release_predecessor_original_record(
        originals,
        "release-source-freeze",
        candidate["source_freeze_digest"],
        "policy-selected predecessor source freeze",
    )
    source = source_record["data"]
    if (
        source_record["status"] != "PASS"
        or source.get("dirty") is not False
        or source.get("milestone") != predecessor_milestone
        or source.get("source_sha") != subject.get("source_commit")
        or source.get("source_tree") != subject.get("source_tree")
    ):
        raise ReleaseControlError("policy-selected predecessor source identity differs")
    artifact_record = _release_predecessor_original_record(
        originals,
        "release-artifact-manifest",
        candidate["artifact_manifest_digest"],
        "policy-selected predecessor artifact manifest",
    )
    artifacts = _validate_artifact_manifest_payload(
        artifact_record["data"], expected_milestone=predecessor_milestone
    )
    expected_artifacts = _release_original_artifact_descriptors(
        subject.get("artifacts"), package_version=subject["normalized_package_version"]
    )
    actual_artifacts = {
        "wheel" if row["path"].endswith(".whl") else "sdist": {
            "filename": row["path"],
            "bytes": row["size"],
            "sha256": row["sha256"],
        }
        for row in artifacts
        if row["path"].endswith((".whl", ".tar.gz"))
    }
    if set(actual_artifacts) != {"wheel", "sdist"} or any(
        actual_artifacts[kind]
        != {
            "filename": expected_artifacts[kind]["filename"],
            "bytes": expected_artifacts[kind]["bytes"],
            "sha256": expected_artifacts[kind]["sha256"],
        }
        for kind in ("wheel", "sdist")
    ):
        raise ReleaseControlError("policy-selected predecessor artifact bytes differ")

    lkg_digest, lkg_record = _release_predecessor_unique_record(
        originals,
        "release-last-known-good",
        lambda record: (
            record.get("status") == "PASS"
            and record.get("data", {}).get("state") == "LKG"
            and record.get("data", {}).get("invalidation_decision_digest") is None
            and record.get("data", {}).get("milestone") == predecessor_milestone
            and record.get("data", {}).get("candidate_digest") == candidate["candidate_digest"]
        ),
        "active policy-selected last-known-good transition",
    )
    lkg = _release_closed_mapping(
        lkg_record["data"],
        {
            "backend_id",
            "candidate_digest",
            "chain_head",
            "committed_token",
            "expected_generation",
            "invalidation_decision_digest",
            "milestone",
            "new_generation",
            "operation_id",
            "previous_release_digest",
            "read_back_digest",
            "reconciliation_digest",
            "state",
        },
        "selected last-known-good transition",
    )
    if (
        lkg["backend_id"] != "last-known-good"
        or type(lkg["expected_generation"]) is not int
        or type(lkg["new_generation"]) is not int
        or lkg["new_generation"] != lkg["expected_generation"] + 1
    ):
        raise ReleaseControlError("selected last-known-good transition is not a CAS successor")
    for field in ("chain_head", "read_back_digest", "reconciliation_digest"):
        _require_digest(lkg[field], "selected last-known-good " + field)

    reconciliation_digest = _require_digest(lkg["reconciliation_digest"], "selected reconciliation")
    reconciliation_record = _release_predecessor_original_record(
        originals,
        "release-publication-reconciliation",
        reconciliation_digest,
        "selected publication reconciliation",
    )
    reconciliation = reconciliation_record["data"]
    if (
        reconciliation_record["status"] != "PASS"
        or reconciliation.get("result") != "RECONCILED"
        or reconciliation.get("burn_required") is not False
        or reconciliation.get("partial_targets") != []
        or reconciliation.get("milestone") != predecessor_milestone
        or reconciliation.get("candidate_digest") != candidate["candidate_digest"]
    ):
        raise ReleaseControlError("selected publication reconciliation is not exact and clean")
    qualification_digest = _require_digest(
        reconciliation.get("qualification_digest"), "selected qualification"
    )
    qualification_record = _release_predecessor_original_record(
        originals,
        "release-qualification",
        qualification_digest,
        "selected release qualification",
    )
    if (
        qualification_record["status"] != "PASS"
        or qualification_record["data"].get("candidate_digest") != candidate["candidate_digest"]
        or qualification_record["data"].get("milestone") != predecessor_milestone
    ):
        raise ReleaseControlError("selected qualification belongs to another candidate")

    chain_receipt_digest, chain_record = _release_predecessor_unique_record(
        originals,
        "release-evidence-chain",
        lambda record: (
            record.get("status") == "PASS"
            and record.get("data", {}).get("committed_head") == lkg["chain_head"]
            and record.get("data", {}).get("read_back_digest") == lkg["chain_head"]
            and record.get("data", {}).get("candidate_digest") == candidate["candidate_digest"]
            and record.get("data", {}).get("reconciliation_digest") == reconciliation_digest
        ),
        "selected success-chain transition",
    )
    chain = _release_closed_mapping(
        chain_record["data"],
        {
            "backend_id",
            "candidate_digest",
            "committed_head",
            "disposition",
            "evidence_manifest_digest",
            "expected_head",
            "final_receipts_digest",
            "generation",
            "milestone",
            "operation_id",
            "previous_head",
            "read_back_digest",
            "reconciliation_digest",
        },
        "selected success-chain transition",
    )
    if (
        chain["backend_id"] != "success-chain"
        or chain["disposition"] not in {"committed", "idempotent"}
        or type(chain["generation"]) is not int
        or chain["generation"] < 1
        or chain["milestone"] != predecessor_milestone
        or chain["previous_head"] != chain["expected_head"]
    ):
        raise ReleaseControlError("selected success-chain transition is not an exact CAS append")
    ancestry_head = chain["previous_head"]
    ancestry_generation = chain["generation"] - 1
    seen_chain_heads = {chain["committed_head"]}
    while ancestry_generation:

        def matches_prior_chain(record: Mapping[str, Any]) -> bool:
            data = record.get("data", {})
            return (
                record.get("status") == "PASS"
                and isinstance(data, dict)
                and data.get("backend_id") == "success-chain"
                and data.get("committed_head") == ancestry_head
                and data.get("read_back_digest") == ancestry_head
                and data.get("generation") == ancestry_generation
            )

        _prior_digest, prior_record = _release_predecessor_unique_record(
            originals,
            "release-evidence-chain",
            matches_prior_chain,
            "selected prior success-chain transition",
        )
        prior = prior_record["data"]
        if (
            prior.get("committed_head") in seen_chain_heads
            or prior.get("previous_head") != prior.get("expected_head")
            or prior.get("disposition") not in {"committed", "idempotent"}
        ):
            raise ReleaseControlError("selected success-chain ancestry has a cycle or fork")
        seen_chain_heads.add(prior["committed_head"])
        ancestry_head = prior.get("previous_head")
        ancestry_generation -= 1
    if ancestry_head is not None:
        raise ReleaseControlError("selected success-chain ancestry does not reach genesis")
    evidence_manifest_digest = _require_digest(
        chain["evidence_manifest_digest"], "selected final evidence manifest"
    )
    evidence_manifest_record = _release_predecessor_original_record(
        originals,
        "release-evidence-manifest",
        evidence_manifest_digest,
        "selected final evidence manifest",
    )
    evidence_manifest = evidence_manifest_record["data"]
    if (
        evidence_manifest_record["status"] != "PASS"
        or evidence_manifest.get("phase") != "qualified-publication"
        or evidence_manifest.get("candidate_digest") != candidate["candidate_digest"]
        or reconciliation.get("evidence_manifest_digest") != evidence_manifest_digest
    ):
        raise ReleaseControlError(
            "selected final evidence manifest is not the reconciled candidate"
        )
    _require_nonempty_string(chain["operation_id"], "selected success-chain operation")
    final_retention_digest = _require_digest(
        chain.get("final_receipts_digest"), "selected final retention"
    )
    final_retention = _release_predecessor_original_record(
        originals,
        "release-retention-receipts",
        final_retention_digest,
        "selected final retention",
    )
    if (
        final_retention["status"] != "PASS"
        or final_retention["data"].get("phase") != "final"
        or final_retention["data"].get("input_digest") != evidence_manifest_digest
    ):
        raise ReleaseControlError("selected final retention does not retain the final manifest")

    prior_lkg_digest = lkg["previous_release_digest"]
    prior_lkg_generation = lkg["expected_generation"]
    seen_lkg_digests = {lkg_digest}
    while prior_lkg_generation:
        prior_lkg_record = _release_predecessor_original_record(
            originals,
            "release-last-known-good",
            prior_lkg_digest,
            "selected prior last-known-good transition",
        )
        prior_lkg = prior_lkg_record["data"]
        if (
            prior_lkg_record["status"] != "PASS"
            or prior_lkg.get("backend_id") != "last-known-good"
            or prior_lkg.get("state") != "LKG"
            or prior_lkg.get("new_generation") != prior_lkg_generation
            or prior_lkg.get("expected_generation") != prior_lkg_generation - 1
            or prior_lkg_digest in seen_lkg_digests
        ):
            raise ReleaseControlError("selected last-known-good ancestry has a gap or cycle")
        seen_lkg_digests.add(prior_lkg_digest)
        prior_lkg_digest = prior_lkg.get("previous_release_digest")
        prior_lkg_generation -= 1
    if prior_lkg_digest is not None:
        raise ReleaseControlError("selected last-known-good ancestry does not reach genesis")

    pointer_transition_retention_digest, pointer_transition_retention = (
        _release_predecessor_unique_record(
            originals,
            "release-retention-receipts",
            lambda record: (
                record.get("status") == "PASS"
                and record.get("data", {}).get("phase") == "pointer-transition"
                and record.get("data", {}).get("input_digest") == lkg_digest
            ),
            "selected LKG transition retention",
        )
    )
    pointer_envelope_digest, pointer_envelope = _release_predecessor_unique_record(
        originals,
        "release-evidence-manifest",
        lambda record: (
            record.get("status") == "PASS"
            and record.get("data", {}).get("phase") == "pointer-transition"
            and record.get("data", {}).get("candidate_digest") == candidate["candidate_digest"]
        ),
        "selected pointer envelope",
    )
    _release_predecessor_manifest_contains(
        pointer_envelope, {lkg_digest, pointer_transition_retention_digest}
    )
    pointer_retention_digest, pointer_retention = _release_predecessor_unique_record(
        originals,
        "release-retention-receipts",
        lambda record: (
            record.get("status") == "PASS"
            and record.get("data", {}).get("phase") == "pointer-transition-envelope"
            and record.get("data", {}).get("input_digest") == pointer_envelope_digest
        ),
        "selected pointer envelope retention",
    )
    pointer_index_receipt_digest, pointer_index = _release_predecessor_unique_record(
        originals,
        "release-attempt-index",
        lambda record: (
            record.get("status") == "PASS"
            and record.get("data", {}).get("kind") == "update_receipt"
            and record.get("data", {}).get("scope_kind") == "release_candidate"
            and record.get("data", {}).get("stage") == "pointer-transition"
            and record.get("data", {}).get("entry_manifest_digest") == pointer_envelope_digest
            and record.get("data", {}).get("entry_receipts_digest") == pointer_retention_digest
        ),
        "selected pointer attempt-index receipt",
    )
    pointer_entry = _release_index_receipt_content(pointer_index["data"])
    if pointer_entry["scope"].get("candidate_id") != candidate["candidate_digest"]:
        raise ReleaseControlError("pointer attempt-index receipt names another candidate")

    close_root_digest, close_root = _release_predecessor_unique_record(
        originals,
        "release-attempt-index",
        lambda record: (
            record.get("status") == "PASS"
            and record.get("data", {}).get("kind") == "update_receipt"
            and record.get("data", {}).get("scope_kind") == "release_candidate"
            and record.get("data", {}).get("stage") == "release-task-finalizing"
        ),
        "selected durable close root",
    )
    close_entry = _release_index_receipt_content(close_root["data"])
    if close_entry["scope"].get("candidate_id") != candidate["candidate_digest"]:
        raise ReleaseControlError("durable close root names another candidate")
    close_manifest_digest = close_entry["entry_manifest_digest"]
    close_manifest = _release_predecessor_original_record(
        originals,
        "release-evidence-manifest",
        close_manifest_digest,
        "selected close-ready manifest",
    )
    close_retention_digest = _require_digest(
        close_entry["entry_receipts_digest"], "selected close-ready retention"
    )
    close_retention = _release_predecessor_original_record(
        originals,
        "release-retention-receipts",
        close_retention_digest,
        "selected close-ready retention",
    )
    if (
        close_retention["status"] != "PASS"
        or close_retention["data"].get("phase") != "release-task-finalizing"
        or close_retention["data"].get("input_digest") != close_manifest_digest
    ):
        raise ReleaseControlError("durable close root does not retain its exact manifest")
    close_ready_observation_digest, close_ready_observation = _release_predecessor_unique_record(
        originals,
        "release-task-state-observation",
        lambda record: (
            record.get("status") == "PASS"
            and record.get("data", {}).get("candidate_digest") == candidate["candidate_digest"]
            and record.get("data", {}).get("latest_pointer_index_digest")
            == pointer_index_receipt_digest
            and record.get("data", {}).get("phase") == "close-ready"
        ),
        "selected close-ready task-state observation",
    )
    _release_predecessor_manifest_contains(
        close_manifest, {pointer_index_receipt_digest, close_ready_observation_digest}
    )

    closed_decision_digest, closed = _release_predecessor_unique_record(
        originals,
        "release-protected-input",
        lambda record: (
            record.get("status") == "PASS"
            and record.get("data", {}).get("input_kind") == "task_state_transition"
            and record.get("data", {}).get("transition_kind") == "release_decision_closed"
            and record.get("data", {}).get("decision") == "CLOSED"
        ),
        "selected signed Closed decision",
    )
    subjects = closed["data"].get("subject_digests")
    subject_names = [
        "predecessor_candidate_identity",
        "decision_identity",
        "role_assignments",
        "task_state_policy_registry",
        "durable_close_root",
        "original_provider_close_event",
    ]
    if (
        not isinstance(subjects, list)
        or len(subjects) != len(subject_names)
        or any(
            not isinstance(row, dict) or set(row) != {"subject", "sha256"} or row["subject"] != name
            for row, name in zip(subjects, subject_names, strict=True)
        )
    ):
        raise ReleaseControlError("selected Closed decision lacks its ordered subjects")
    subject_rows = {row["subject"]: row["sha256"] for row in subjects}
    for name, digest in subject_rows.items():
        _require_digest(digest, "selected Closed " + name)
    if (
        subject_rows.get("predecessor_candidate_identity") != candidate_full_digest
        or subject_rows.get("decision_identity") != sha256_json(decision_identity)
        or subject_rows.get("durable_close_root") != close_root_digest
    ):
        raise ReleaseControlError("selected Closed decision changes its candidate or durable root")

    for (_kind, _digest), (_path, record) in originals.items():
        if (
            record.get("record_type") == "release-evidence-chain"
            and record.get("data", {}).get("previous_head") == chain["committed_head"]
        ):
            raise ReleaseControlError("selected predecessor success chain has a later successor")
        if record.get("record_type") == "release-last-known-good":
            data = record.get("data", {})
            if data.get("previous_release_digest") == lkg_digest:
                raise ReleaseControlError(
                    "selected predecessor last-known-good has a later successor"
                )
            if (
                data.get("state") == "INVALIDATED"
                and data.get("previous_release_digest") == lkg_digest
            ):
                raise ReleaseControlError("selected predecessor has a later signed invalidation")
        if (
            record.get("record_type") == "release-postpublication-conflict"
            and record.get("data", {}).get("candidate_digest") == candidate["candidate_digest"]
        ):
            raise ReleaseControlError("selected predecessor has an unresolved later conflict")

    return {
        "qualification_digest": qualification_digest,
        "reconciliation_digest": reconciliation_digest,
        "final_retention_digest": final_retention_digest,
        "chain_receipt_digest": chain_receipt_digest,
        "chain_head": lkg["chain_head"],
        "lkg_digest": lkg_digest,
        "pointer_transition_retention_digest": pointer_transition_retention_digest,
        "pointer_envelope_digest": pointer_envelope_digest,
        "pointer_retention_digest": pointer_retention_digest,
        "pointer_index_receipt_digest": pointer_index_receipt_digest,
        "closed_decision_digest": closed_decision_digest,
        "close_ready_observation_digest": close_ready_observation_digest,
        "close_root_digest": close_root_digest,
    }


def _release_predecessor_control_operation(
    args: argparse.Namespace, context: ReleaseInvocation
) -> dict[str, Any]:
    """Produce one fixture predecessor from the complete captured original graph."""
    if os.environ.get("METRIPLANE_RELEASE_FIXTURE_MODE") != "1":
        raise ReleaseControlError(
            "live predecessor selection requires bound provider, store and backend authority"
        )
    if args.genesis_only or not args.require_prior_lkg or not args.require_prior_decision_closed:
        raise ReleaseControlError("connected predecessor fixture requires reconciled LKG history")
    root = context.root
    context_path = _release_predecessor_context_path(context, args.release_context)
    policy_path = _release_predecessor_context_path(context, args.predecessor_policy)
    proof_path = _release_predecessor_context_path(context, args.prerequisite_proofs)
    context_record = read_json(context_path)
    validate_record(context_record, "release-context")
    policy_raw = _safe_release_bytes(policy_path)
    proof, originals = _release_predecessor_proof_originals(root, proof_path)
    policy_source = _source_json(policy_raw, "original predecessor policy")
    authority = _release_closed_mapping(
        policy_source.get("selection_authority"),
        {"readiness_registry", "context_row_pointer", "context_policy_digest"},
        "predecessor selection authority",
    )
    readiness_ref = _release_closed_mapping(
        authority["readiness_registry"],
        {"path", "bytes", "sha256"},
        "predecessor readiness registry",
    )
    readiness_path = root / _release_relative_suffix(
        readiness_ref["path"], "predecessor readiness registry path"
    )
    readiness_raw = _safe_release_bytes(readiness_path)
    if (
        len(readiness_raw) != readiness_ref["bytes"]
        or sha256_bytes(readiness_raw) != readiness_ref["sha256"]
    ):
        raise ReleaseControlError("predecessor readiness registry bytes differ")
    linear_digest = _require_digest(
        context_record["data"].get("linear_snapshot_digest"),
        "predecessor current Linear snapshot",
    )
    linear_record = _release_predecessor_original_record(
        originals,
        "linear-release-snapshot",
        linear_digest,
        "predecessor current Linear snapshot",
    )
    expected_context_id = _require_nonempty_string(
        policy_source.get("readiness_context_id"), "predecessor readiness context"
    )
    policy_inputs = {
        "readiness_registry_raw": readiness_raw,
        "expected_readiness_digest": readiness_ref["sha256"],
        "predecessor_policy_raw": policy_raw,
        "expected_predecessor_policy_digest": sha256_bytes(policy_raw),
        "expected_context_id": expected_context_id,
        "linear_snapshot": linear_record,
    }
    current = _release_context_policy_projection(context_record, **policy_inputs)
    policy = _release_predecessor_policy_projection(
        policy_raw,
        expected_digest=sha256_bytes(policy_raw),
        readiness_registry_raw=readiness_raw,
        expected_readiness_digest=readiness_ref["sha256"],
        expected_context_id=expected_context_id,
    )
    subject = policy["expected_predecessor_subject"]
    if (
        policy["lineage_mode"] != "RECONCILED_LKG"
        or args.milestone != current["framework_milestone"]
        or args.expected_predecessor_milestone != subject["framework_milestone"]
        or args.project_id != current["decision"]["project_id"]
    ):
        raise ReleaseControlError("predecessor command changes its current policy selection")
    _release_predecessor_subject_originals(root, proof, subject)
    decision_identity = _release_predecessor_decision_authority(
        root, policy["expected_predecessor_decision"], subject=subject
    )
    linked = _release_predecessor_reconciled_graph(
        originals,
        subject=subject,
        candidate_milestone=args.milestone,
        decision_identity=decision_identity,
    )
    candidate_full_digest, _candidate_record = _release_predecessor_unique_record(
        originals,
        "release-candidate-identity",
        lambda record: (
            record.get("status") == "PASS"
            and record.get("data", {}).get("milestone") == subject["framework_milestone"]
            and record.get("data", {}).get("release_tag") == subject["release_tag"]
        ),
        "policy-selected predecessor candidate",
    )
    _release_predecessor_closed_decision(
        root,
        proof,
        originals,
        closed_digest=linked["closed_decision_digest"],
        candidate_full_digest=candidate_full_digest,
        close_root_digest=linked["close_root_digest"],
        decision_identity=decision_identity,
    )
    chain_record = _release_predecessor_original_record(
        originals,
        "release-evidence-chain",
        linked["chain_receipt_digest"],
        "selected success-chain transition",
    )
    lkg_record = _release_predecessor_original_record(
        originals,
        "release-last-known-good",
        linked["lkg_digest"],
        "selected last-known-good transition",
    )
    pointer_index = _release_predecessor_original_record(
        originals,
        "release-attempt-index",
        linked["pointer_index_receipt_digest"],
        "selected pointer attempt-index receipt",
    )
    attempt_genesis_path = _release_predecessor_context_path(context, args.attempt_index_genesis)
    attempt_genesis_digest = _release_predecessor_static_authorities(
        chain_genesis_raw=_safe_release_bytes(
            _release_predecessor_context_path(context, args.chain_genesis)
        ),
        attempt_genesis_raw=_safe_release_bytes(attempt_genesis_path),
        release_genesis_raw=_safe_release_bytes(
            _release_predecessor_context_path(context, args.v0_4_genesis)
        ),
        stores_raw=_safe_release_bytes(_release_predecessor_context_path(context, args.stores)),
        chain_backend=args.chain_backend,
        attempt_index_backend=args.attempt_index_backend,
        lkg_backend=args.lkg_backend,
    )
    if (
        args.chain_backend != chain_record["data"].get("backend_id")
        or args.lkg_backend != lkg_record["data"].get("backend_id")
        or args.attempt_index_backend != pointer_index["data"].get("backend_id")
        or pointer_index["data"].get("genesis_digest") != attempt_genesis_digest
    ):
        raise ReleaseControlError("predecessor command changes a selected backend or genesis")
    gate = read_json(root / "gate-input.json")
    target = read_json(root / "target-resolution.json")
    validate_record(gate, "release-gate-input")
    validate_record(target, "release-target-resolution")
    if (
        gate["status"] != "PASS"
        or target["status"] != "PASS"
        or gate["synthetic"] is not True
        or target["synthetic"] is not True
    ):
        raise ReleaseControlError("predecessor fixture gate or target is not synthetic PASS")
    references = {
        "release_context": _release_predecessor_original_ref(root, context_path),
        "predecessor_policy": _release_predecessor_original_ref(root, policy_path),
        "proof_index": _release_predecessor_original_ref(root, proof_path),
    }
    data = {
        "lineage_mode": "RECONCILED_LKG",
        "candidate_milestone": args.milestone,
        "predecessor_milestone": subject["framework_milestone"],
        "version": subject["release_tag"],
        "package_version": subject["normalized_package_version"],
        "release_context_digest": sha256_json(context_record),
        "release_context": references["release_context"],
        "predecessor_policy_digest": sha256_bytes(policy_raw),
        "predecessor_policy": references["predecessor_policy"],
        "predecessor_subject": subject,
        "predecessor_subject_digest": sha256_json(subject),
        "proof_index": references["proof_index"],
        "producer_intent_digest": sha256_json(context.intent),
        "invocation_root_locator": "invocations",
        "genesis_authority_digest": None,
        "completion_digest": None,
        "selection_observations": _release_predecessor_selection_observations(
            root, proof, observed_at=context.intent["started_at"]
        ),
        **linked,
    }
    record = make_record(
        "release-predecessor",
        data,
        invocation_id=context.intent["invocation_id"],
        sequence=context.intent["sequence"],
        synthetic=True,
    )
    _release_predecessor_content(
        record,
        gate["data"],
        target=target,
        original_bytes={
            "release_context": _safe_release_bytes(context_path),
            "predecessor_policy": policy_raw,
            "proof_index": _safe_release_bytes(proof_path),
        },
        expected_original_paths={key: value["path"] for key, value in references.items()},
        expected_record_digest=sha256_json(record),
        expected_invocation_id=context.intent["invocation_id"],
        expected_sequence=context.intent["sequence"],
        expected_producer_intent_digest=sha256_json(context.intent),
        context_policy_inputs=policy_inputs,
        synthetic=True,
    )
    return record


def _validate_release_predecessor_operation(
    args: argparse.Namespace, context: ReleaseInvocation
) -> dict[str, Any]:
    if args.validate_genesis_only or not (
        args.read_back_chain
        and args.read_back_lkg
        and args.read_back_pointer_index
        and args.require_embedded_prior_decision_closed_observation
    ):
        raise ReleaseControlError("predecessor validation lacks complete reconciled readback")
    record_path = _release_predecessor_context_path(context, args.record)
    record = read_json(record_path)
    validate_record(record, "release-predecessor")
    validate_release_producer_journal(
        record, record_path, producer="resolve_release_predecessor.py"
    )
    producer = _validate_intent(
        context.root / "invocations/resolve-release-predecessor" / f"{record['sequence']:03d}"
    )
    producer_args = _build_tool_parser(
        "resolve_release_predecessor.py", TOOL_CONTRACTS["resolve_release_predecessor.py"]
    ).parse_args(producer.intent["argv"][1:])
    expected = _release_predecessor_control_operation(producer_args, producer)
    if canonical_json(record) != canonical_json(expected):
        raise ReleaseControlError("predecessor validation differs from its original graph")
    for flag in ("release_context", "predecessor_policy"):
        if _release_predecessor_context_path(context, getattr(args, flag)) != (
            _release_predecessor_context_path(producer, getattr(producer_args, flag))
        ):
            raise ReleaseControlError("predecessor validation selects another current input")
    if args.milestone != record["data"]["candidate_milestone"]:
        raise ReleaseControlError("predecessor validation changes its candidate milestone")
    return record


def _release_predecessor_context_path(context: ReleaseInvocation, value: object) -> Path:
    """Relocate one original predecessor path into the current retained run root."""
    cwd = _canonical_absolute_path(
        context.intent["environment"]["working_directory"],
        "predecessor command working directory",
    )
    arguments = _release_original_arguments(context.intent["tool"], context.intent["argv"])
    original_directory = _release_historical_path(arguments["invocation-dir"], cwd)
    if original_directory.parts[-3:] != (
        "invocations",
        _invocation_stage(context.intent["tool"]),
        f"{context.intent['sequence']:03d}",
    ):
        raise ReleaseControlError(
            "predecessor command invocation path changes its reserved sequence"
        )
    original_root = original_directory.parents[2]
    original = _release_historical_path(value, cwd)
    try:
        suffix = original.relative_to(original_root)
    except ValueError as exc:
        raise ReleaseControlError(
            "predecessor command input escapes its original run root"
        ) from exc
    return context.root / _release_relative_suffix(
        suffix.as_posix(), "predecessor command input path"
    )


def _validate_release_predecessor_bound_invocation(
    context: ReleaseInvocation,
    *,
    outputs: list[dict[str, str]] | None = None,
    output_root: Path | None = None,
) -> None:
    """Replay predecessor reservation from its exact relocated closed input inventory."""
    tool = context.intent["tool"]
    if tool not in {"resolve_release_predecessor.py", "validate_release_predecessor.py"}:
        raise ReleaseControlError("predecessor invocation binding has another tool")
    expected_directory = (
        context.root / "invocations" / _invocation_stage(tool) / f"{context.intent['sequence']:03d}"
    )
    if context.directory != expected_directory:
        raise ReleaseControlError("predecessor invocation differs from its retained root")
    arguments = _release_original_arguments(tool, context.intent["argv"])
    if _release_predecessor_context_path(context, arguments["invocation-dir"]) != context.directory:
        raise ReleaseControlError("predecessor invocation argument differs from its journal")
    current: dict[Path, str] = {}
    for row in context.intent["inputs"]:
        path = _release_predecessor_context_path(context, row["path"])
        schema = _require_nonempty_string(row["schema_id"], "predecessor captured input schema")
        if path in current and current[path] != schema:
            raise ReleaseControlError("predecessor captured inputs alias different types")
        if sha256_bytes(_safe_release_bytes(path)) != _require_digest(
            row["sha256"], "predecessor captured input R"
        ):
            raise ReleaseControlError("predecessor captured input changed after reservation")
        current[path] = schema

    if tool == "resolve_release_predecessor.py":
        proof_path = _release_predecessor_context_path(context, arguments["prerequisite-proofs"])
        proof, _ = _release_predecessor_proof_originals(context.root, proof_path)
        required = {
            _release_predecessor_context_path(context, arguments[flag])
            for flag in (
                "release-context",
                "predecessor-policy",
                "prerequisite-proofs",
                "chain-genesis",
                "attempt-index-genesis",
                "stores",
                "v0.4-genesis",
            )
        } | {context.root / "gate-input.json", context.root / "target-resolution.json"}
        policy = _source_json(
            _safe_release_bytes(
                _release_predecessor_context_path(context, arguments["predecessor-policy"])
            ),
            "predecessor bound policy",
        )
        decision = policy.get("expected_predecessor_decision")
        if isinstance(decision, dict):
            authority = decision.get("authority")
            if not isinstance(authority, dict):
                raise ReleaseControlError("predecessor historical decision authority is malformed")
            ref = _release_closed_mapping(
                authority.get("raw_registry"),
                {"path", "bytes", "sha256"},
                "predecessor historical decision registry",
            )
            required.add(
                context.root
                / _release_relative_suffix(
                    ref["path"], "predecessor historical decision registry path"
                )
            )
        for group in ("records", "raw_proofs", "git_objects", "artifacts"):
            required.update(
                context.root
                / _release_relative_suffix(
                    row["original_file"]["path"], "predecessor required original path"
                )
                for row in proof[group]
            )
        if set(current) != required:
            raise ReleaseControlError("predecessor captured input closure differs from proof graph")
        expected_plan = [
            {"path": Path(arguments["out"]).name, "schema_id": "metriplane.release-predecessor.v1"}
        ]
    else:
        record_path = _release_predecessor_context_path(context, arguments["record"])
        record = read_json(record_path)
        validate_record(record, "release-predecessor")
        validate_release_producer_journal(
            record, record_path, producer="resolve_release_predecessor.py"
        )
        for flag in ("release-context", "predecessor-policy"):
            if _release_predecessor_context_path(context, arguments[flag]) not in current:
                raise ReleaseControlError("predecessor validator changed producer inputs")
        expected_plan = []
    if context.intent["planned_outputs"] != expected_plan:
        raise ReleaseControlError("predecessor invocation output plan differs")
    if outputs is not None:
        root = context.root if output_root is None else output_root
        expected_outputs = [
            {**row, "sha256": sha256_bytes(_safe_release_bytes(root / row["path"]))}
            for row in expected_plan
        ]
        if outputs != expected_outputs:
            raise ReleaseControlError("predecessor output bytes differ from its plan")


def _release_target_validation_input_paths(
    argv: Sequence[str], root: Path
) -> list[tuple[Path, str]]:
    arguments = _release_original_arguments(
        "validate_release_target_resolution.py",
        ["validate_release_target_resolution.py", *argv],
    )
    record_path = _release_historical_path(arguments["record"], Path.cwd())
    if record_path.parent != root:
        raise ReleaseControlError("target resolution validation record escapes its run root")
    record = read_json(record_path)
    validate_record(record, "release-target-resolution")
    validate_release_producer_journal(record, record_path, producer="resolve_release_target.py")
    producer_directory = root / "invocations/resolve-release-target" / f"{record['sequence']:03d}"
    producer = _validate_intent(producer_directory)
    if producer.intent["invocation_id"] != record["invocation_id"]:
        raise ReleaseControlError("target resolution validation selects another producer intent")
    producer_arguments = _release_original_arguments(
        "resolve_release_target.py", producer.intent["argv"]
    )
    targets_path = _release_historical_path(arguments["targets"], Path.cwd())
    producer_cwd = _canonical_absolute_path(
        producer.intent["environment"]["working_directory"],
        "target resolution producer working directory",
    )
    producer_directory = _release_historical_path(
        producer_arguments["invocation-dir"], producer_cwd
    )
    producer_root = producer_directory.parents[2]
    original_targets = _release_historical_path(producer_arguments["targets"], producer_cwd)
    try:
        target_suffix = original_targets.relative_to(producer_root)
    except ValueError as exc:
        raise ReleaseControlError(
            "target resolution producer registry escapes its run root"
        ) from exc
    current_targets = root / _release_relative_suffix(
        target_suffix.as_posix(), "target resolution producer registry"
    )
    if targets_path != current_targets:
        raise ReleaseControlError("target resolution validation selects another target registry")
    inputs = []
    for row in producer.intent["inputs"]:
        original = _canonical_absolute_path(row["path"], "target resolution producer input")
        try:
            suffix = original.relative_to(producer_root)
        except ValueError as exc:
            raise ReleaseControlError(
                "target resolution producer input escapes its run root"
            ) from exc
        inputs.append(
            (
                root
                / _release_relative_suffix(suffix.as_posix(), "target resolution producer input"),
                row["schema_id"],
            )
        )
    if record_path in {path for path, _ in inputs}:
        raise ReleaseControlError("target validation record aliases an original producer input")
    return [(record_path, "metriplane.release-target-resolution.v1"), *inputs]


def _release_target_context_path(context: ReleaseInvocation, value: object) -> Path:
    """Relocate one original command path into the context's retained run root."""
    cwd = _canonical_absolute_path(
        context.intent["environment"]["working_directory"], "target command working directory"
    )
    arguments = _release_original_arguments(context.intent["tool"], context.intent["argv"])
    original_directory = _release_historical_path(arguments["invocation-dir"], cwd)
    if original_directory.parts[-3:] != (
        "invocations",
        _invocation_stage(context.intent["tool"]),
        f"{context.intent['sequence']:03d}",
    ):
        raise ReleaseControlError("target command invocation path changes its reserved sequence")
    original_root = original_directory.parents[2]
    original = _release_historical_path(value, cwd)
    try:
        suffix = original.relative_to(original_root)
    except ValueError as exc:
        raise ReleaseControlError("target command input escapes its original run root") from exc
    _release_relative_suffix(suffix.as_posix(), "target command input path")
    return context.root / suffix


def _validate_release_target_bound_invocation(
    context: ReleaseInvocation,
    *,
    outputs: list[dict[str, str]] | None = None,
    output_root: Path | None = None,
) -> None:
    """Bind target lifecycle commands to their exact reserved input and output bytes."""
    tool = context.intent["tool"]
    if tool not in {
        "resolve_release_target.py",
        "record_release_target_burn.py",
        "validate_release_target_resolution.py",
    }:
        raise ReleaseControlError("target invocation binding has another tool")
    if context.directory != (
        context.root / "invocations" / _invocation_stage(tool) / f"{context.intent['sequence']:03d}"
    ):
        raise ReleaseControlError("target invocation differs from its current retained root")
    arguments = _release_original_arguments(tool, context.intent["argv"])
    if _release_target_context_path(context, arguments["invocation-dir"]) != context.directory:
        raise ReleaseControlError("target invocation argument differs from its retained journal")

    if tool == "validate_release_target_resolution.py":
        record_path = _release_target_context_path(context, arguments["record"])
        record = read_json(record_path)
        validate_record(record, "release-target-resolution")
        validate_release_producer_journal(record, record_path, producer="resolve_release_target.py")
        producer_directory = (
            context.root / "invocations/resolve-release-target" / f"{record['sequence']:03d}"
        )
        producer = _validate_intent(producer_directory)
        if producer.intent["invocation_id"] != record["invocation_id"]:
            raise ReleaseControlError("target validator selected another producer intent")
        producer_arguments = _release_original_arguments(
            "resolve_release_target.py", producer.intent["argv"]
        )
        if _release_target_context_path(context, arguments["targets"]) != (
            _release_target_context_path(producer, producer_arguments["targets"])
        ):
            raise ReleaseControlError("target validator selected another target registry")
        current_inputs = [
            (record_path, "metriplane.release-target-resolution.v1"),
            *[
                (
                    _release_target_context_path(producer, row["path"]),
                    row["schema_id"],
                )
                for row in producer.intent["inputs"]
            ],
        ]
    else:
        observations_flag = (
            "live-target-observations"
            if tool == "resolve_release_target.py"
            else "target-observations"
        )
        lineage_flag = (
            "retained-burn-lineage" if tool == "resolve_release_target.py" else "burn-lineage"
        )
        observations_path = _release_target_context_path(context, arguments[observations_flag])
        lineage_path = _release_target_context_path(context, arguments[lineage_flag])
        if observations_path.parent != context.root or lineage_path.parent != context.root:
            raise ReleaseControlError("target command inputs leave their retained run root")
        observations = read_json(observations_path)
        validate_record(observations, "release-target-observations")
        data = observations["data"]
        context_link = _release_closed_mapping(
            data.get("original_release_context"),
            {"record_type", "record_digest", "original_file"},
            "target command context link",
        )
        context_path, _ = _release_target_original_file(
            context.root, context_link["original_file"], label="release context"
        )
        registry_path, _ = _release_target_original_file(
            context.root, data.get("original_registry"), label="target registry"
        )
        current_inputs = [
            (observations_path, "metriplane.release-target-observations.v1"),
            (lineage_path, "metriplane.release-burn-lineage.v1"),
            (context_path, "metriplane.release-context.v1"),
            (registry_path, "metriplane.release-targets.v1"),
        ]
        if tool == "resolve_release_target.py":
            if _release_target_context_path(context, arguments["targets"]) != registry_path:
                raise ReleaseControlError("target resolution selected another target registry")
        else:
            current_inputs.append(
                (
                    _release_target_context_path(context, arguments["target-resolution"]),
                    "metriplane.release-target-resolution.v1",
                )
            )

    cwd = _canonical_absolute_path(
        context.intent["environment"]["working_directory"], "target command working directory"
    )
    original_directory = _release_historical_path(arguments["invocation-dir"], cwd)
    original_root = original_directory.parents[2]
    expected_inputs = []
    for path, schema_id in current_inputs:
        suffix = path.relative_to(context.root)
        expected_inputs.append(
            {
                "path": str(original_root / suffix),
                "schema_id": schema_id,
                "sha256": sha256_bytes(_safe_release_bytes(path)),
            }
        )
    expected_inputs.sort(key=lambda row: row["path"])
    if context.intent["inputs"] != expected_inputs:
        raise ReleaseControlError("target invocation input identity changed after reservation")

    expected_plan: list[dict[str, str]] = []
    if tool != "validate_release_target_resolution.py":
        record_type = (
            "release-target-resolution"
            if tool == "resolve_release_target.py"
            else "release-target-burn"
        )
        output = _release_target_context_path(context, arguments["out"])
        if output.parent != context.root:
            raise ReleaseControlError("target command output leaves its retained run root")
        expected_plan = [
            {
                "path": output.name,
                "schema_id": f"metriplane.{record_type}.v1",
            }
        ]
    if context.intent["planned_outputs"] != expected_plan:
        raise ReleaseControlError("target invocation output plan differs from its contract")
    if outputs is not None:
        root = context.root if output_root is None else output_root
        expected_outputs = [
            {**row, "sha256": sha256_bytes(_safe_release_bytes(root / row["path"]))}
            for row in expected_plan
        ]
        if outputs != expected_outputs:
            raise ReleaseControlError("target invocation output bytes differ from its plan")


def _release_target_control_operation(
    tool: str, args: argparse.Namespace, context: ReleaseInvocation
) -> dict[str, Any]:
    if os.environ.get("METRIPLANE_RELEASE_FIXTURE_MODE") != "1":
        raise ReleaseControlError(
            "live target control requires bound provider, index and release authority"
        )
    observations_flag = (
        "live_target_observations" if tool == "resolve_release_target.py" else "target_observations"
    )
    lineage_flag = (
        "retained_burn_lineage" if tool == "resolve_release_target.py" else "burn_lineage"
    )
    observations_path = _release_target_context_path(context, getattr(args, observations_flag))
    lineage_path = _release_target_context_path(context, getattr(args, lineage_flag))
    observations, lineage, original_context, registry_raw, versions, operation_order = (
        _release_target_command_originals(observations_path, lineage_path)
    )
    expected_context_digest = sha256_json(original_context)
    expected_registry_digest = sha256_bytes(registry_raw)
    if tool == "resolve_release_target.py":
        expected, _ = _release_target_control_data(
            "release-target-resolution",
            context=original_context,
            observations=observations,
            lineage=lineage,
            expected_context_digest=expected_context_digest,
            expected_observations_digest=sha256_json(observations),
            expected_lineage_digest=sha256_json(lineage),
            target_registry_raw=registry_raw,
            expected_target_registry_digest=expected_registry_digest,
            expected_versions=versions,
            expected_operation_order=operation_order,
            producer_intent_digest=sha256_json(context.intent),
        )
        if any(
            getattr(args, flag) != expected[field]
            for flag, field in (
                ("milestone", "milestone"),
                ("initial_package_version", "initial_package_version"),
                ("initial_release_tag", "initial_release_tag"),
            )
        ):
            raise ReleaseControlError("target resolution command changes approved target policy")
        record_type = "release-target-resolution"
    else:
        target_path = _release_target_context_path(context, args.target_resolution)
        if target_path.parent != observations_path.absolute().parent:
            raise ReleaseControlError("target burn resolution escapes its retained run root")
        target = read_json(target_path)
        validate_record(target, "release-target-resolution")
        validate_release_producer_journal(target, target_path, producer="resolve_release_target.py")
        resolved, _ = _release_target_control_data(
            "release-target-resolution",
            context=original_context,
            observations=observations,
            lineage=lineage,
            expected_context_digest=expected_context_digest,
            expected_observations_digest=sha256_json(observations),
            expected_lineage_digest=sha256_json(lineage),
            target_registry_raw=registry_raw,
            expected_target_registry_digest=expected_registry_digest,
            expected_versions=versions,
            expected_operation_order=operation_order,
            producer_intent_digest=target["data"]["producer_intent_digest"],
        )
        _release_graph_primary_equal(target, resolved)
        expected, _ = _release_target_control_data(
            "release-target-burn",
            context=original_context,
            observations=observations,
            lineage=lineage,
            expected_context_digest=expected_context_digest,
            expected_observations_digest=sha256_json(observations),
            expected_lineage_digest=sha256_json(lineage),
            target_registry_raw=registry_raw,
            expected_target_registry_digest=expected_registry_digest,
            expected_versions=versions,
            expected_operation_order=operation_order,
            producer_intent_digest=sha256_json(context.intent),
        )
        record_type = "release-target-burn"
    return make_record(
        record_type,
        expected,
        invocation_id=context.intent["invocation_id"],
        sequence=context.intent["sequence"],
        synthetic=True,
    )


def _validate_release_target_resolution_operation(
    args: argparse.Namespace, context: ReleaseInvocation
) -> dict[str, Any]:
    if not args.read_back_lineage:
        raise ReleaseControlError("target resolution validation requires complete lineage readback")
    record_path = _release_target_context_path(context, args.record)
    record = read_json(record_path)
    validate_record(record, "release-target-resolution")
    validate_release_producer_journal(record, record_path, producer="resolve_release_target.py")
    producer_directory = (
        context.root / "invocations/resolve-release-target" / f"{record['sequence']:03d}"
    )
    producer = _validate_intent(producer_directory)
    if producer.intent["invocation_id"] != record["invocation_id"]:
        raise ReleaseControlError("target resolution record has another producer intent")
    producer_args = _build_tool_parser(
        "resolve_release_target.py", TOOL_CONTRACTS["resolve_release_target.py"]
    ).parse_args(producer.intent["argv"][1:])
    expected = _release_target_control_operation(
        "resolve_release_target.py", producer_args, producer
    )
    if canonical_json(record) != canonical_json(expected):
        raise ReleaseControlError("target resolution differs from original inputs and lineage")
    original_targets = _release_target_context_path(producer, producer_args.targets)
    if _release_target_context_path(context, args.targets) != original_targets:
        raise ReleaseControlError("target resolution validation uses another target registry")
    return record


def _release_original_artifact_descriptors(
    value: object, *, package_version: str
) -> dict[str, dict[str, Any]]:
    """Validate descriptor identity; native package and actual byte replay remain mandatory."""
    rows = _release_id_rows(value, "kind", "original comparison artifacts")
    if set(rows) != {"wheel", "sdist"}:
        raise ReleaseControlError("original comparison needs exactly one wheel and one sdist")
    names: set[str] = set()
    for kind, value in rows.items():
        row = _release_closed_mapping(
            value,
            {"kind", "filename", "bytes", "sha256", "readback"},
            "original artifact descriptor",
        )
        name = _release_relative_suffix(row["filename"], "original artifact filename")
        if (
            len(name.parts) != 1
            or row["filename"] in names
            or type(row["bytes"]) is not int
            or row["bytes"] < 1
        ):
            raise ReleaseControlError(
                "original artifact has an aliased filename or invalid byte count"
            )
        names.add(row["filename"])
        if (
            kind == "wheel"
            and (
                not row["filename"].startswith("metriplane-" + package_version + "-")
                or not row["filename"].endswith(".whl")
            )
        ) or (kind == "sdist" and row["filename"] != "metriplane-" + package_version + ".tar.gz"):
            raise ReleaseControlError(
                "original artifact filename differs from its package identity"
            )
        _require_digest(row["sha256"], "original artifact bytes")
        readback = _release_closed_mapping(
            row["readback"], {"path", "bytes", "sha256"}, "original artifact readback"
        )
        _release_relative_suffix(readback["path"], "original artifact readback path")
        if (
            type(readback["bytes"]) is not int
            or readback["bytes"] != row["bytes"]
            or readback["sha256"] != row["sha256"]
        ):
            raise ReleaseControlError(
                "original artifact readback descriptor does not bind the payload"
            )
    return rows


def _release_context_policy_projection(
    context: Mapping[str, Any],
    *,
    readiness_registry_raw: bytes,
    expected_readiness_digest: str,
    predecessor_policy_raw: bytes,
    expected_predecessor_policy_digest: str,
    expected_context_id: str,
    linear_snapshot: Mapping[str, Any],
) -> dict[str, Any]:
    """Check the acyclic supplied context policy; no signer, baseline or LKG proof is granted."""
    validate_record(context, "release-context")
    validate_record(linear_snapshot, "linear-release-snapshot")
    if (
        context["status"] != "PASS"
        or linear_snapshot["status"] != "PASS"
        or context["synthetic"] is not linear_snapshot["synthetic"]
    ):
        raise ReleaseControlError(
            "release context and frozen Linear snapshot have different modes/verdicts"
        )
    for raw, digest, label in [
        (readiness_registry_raw, expected_readiness_digest, "readiness"),
        (predecessor_policy_raw, expected_predecessor_policy_digest, "predecessor"),
    ]:
        if sha256_bytes(raw) != _require_digest(
            digest, "independently expected " + label + " policy"
        ):
            raise ReleaseControlError(
                "release context original " + label + " bytes differ from expected policy"
            )
    registry = _source_json(readiness_registry_raw, "original readiness registry")
    contexts = _release_id_rows(
        registry.get("release_contexts"), "context_id", "original release context policies"
    )
    if expected_context_id not in contexts:
        raise ReleaseControlError("release context has no independently selected policy")
    selected = contexts[expected_context_id]
    data = _release_closed_mapping(
        context["data"],
        {
            "comparison_baseline",
            "context_digest",
            "context_id",
            "context_policy_digest",
            "cumulative_bom_snapshot_digest",
            "decision",
            "direct_gate_issues",
            "framework_milestone",
            "linear_snapshot_digest",
            "predecessor_policy_digest",
            "predecessor_requirement",
            "provider_milestone",
            "readiness_registry_digest",
            "roadmap_catalog_task_id",
            "target_policy",
        },
        "complete supplied release context",
    )
    if data["context_digest"] != sha256_json(
        {key: value for key, value in data.items() if key != "context_digest"}
    ):
        raise ReleaseControlError("release context self digest differs")
    for key in (
        "context_id",
        "decision",
        "direct_gate_issues",
        "framework_milestone",
        "predecessor_requirement",
        "provider_milestone",
        "roadmap_catalog_task_id",
        "target_policy",
    ):
        if key not in selected or canonical_json(data[key]) != canonical_json(selected[key]):
            raise ReleaseControlError("release context differs from its original policy: " + key)
    if (
        selected.get("preserve_original_cumulative_bom") is not True
        or data["predecessor_requirement"]
        != "VALIDATE_ORIGINAL_GENESIS_OR_RECONCILED_LKG_GRAPH_UNDER_BOUND_POLICY"
    ):
        raise ReleaseControlError("release context weakens cumulative or predecessor requirements")
    if (
        data["readiness_registry_digest"] != expected_readiness_digest
        or data["predecessor_policy_digest"] != expected_predecessor_policy_digest
        or data["context_policy_digest"] != sha256_json(selected)
        or data["linear_snapshot_digest"] != sha256_json(linear_snapshot)
    ):
        raise ReleaseControlError(
            "release context has a wrong raw policy or complete-record binding"
        )
    decision = _release_linear_identity(data["decision"], require_project=True)
    direct = data["direct_gate_issues"]
    if not isinstance(direct, list) or not direct:
        raise ReleaseControlError("release context lacks its direct gate identities")
    seen = {decision["issue_id"]}
    identifiers = {decision["issue_identifier"]}
    for value in direct:
        identity = _release_linear_identity(value, require_project=True)
        if identity["issue_id"] in seen or identity["issue_identifier"] in identifiers:
            raise ReleaseControlError("release context aliases a direct gate or decision")
        seen.add(identity["issue_id"])
        identifiers.add(identity["issue_identifier"])
    target = _release_target_policy_projection(
        data["target_policy"], milestone=data["framework_milestone"]
    )
    frozen = linear_snapshot["data"]
    if not isinstance(frozen, dict):
        raise ReleaseControlError("release context has no complete frozen Linear payload")
    for key, expected in {
        "context_policy_id": expected_context_id,
        "readiness_registry_digest": expected_readiness_digest,
        "framework_milestone": data["framework_milestone"],
        "decision_issue_id": decision["issue_id"],
        "task_id": decision["issue_identifier"],
        "direct_gate_issue_ids": sorted(seen - {decision["issue_id"]}),
        "required_bom_snapshot_digest": data["cumulative_bom_snapshot_digest"],
    }.items():
        if canonical_json(frozen.get(key)) != canonical_json(expected):
            raise ReleaseControlError(
                "release context differs from complete Linear snapshot: " + key
            )
    _require_digest(data["cumulative_bom_snapshot_digest"], "complete context BOM")
    baseline = _release_closed_mapping(
        data["comparison_baseline"],
        {
            "artifacts",
            "normalized_package_version",
            "release_observation",
            "release_tag",
            "source_commit",
            "source_tree",
            "tag_object",
            "tag_observation",
        },
        "release context comparison baseline",
    )
    baseline_version = _release_version_pair(
        baseline["normalized_package_version"], baseline["release_tag"], historical=True
    )
    initial = _release_version_pair(
        target["initial_normalized_package_version"], target["initial_release_tag"]
    )
    if baseline_version[:2] > initial[:2] or (
        target["resolution_mode"] == "owner_approved_exact_target" and baseline_version >= initial
    ):
        raise ReleaseControlError(
            "release comparison baseline is not older than the requested target"
        )
    baseline_policy = _release_closed_mapping(
        selected.get("comparison_baseline_policy"),
        {
            "normalized_package_version",
            "release_tag",
            "source_commit",
            "source_tree",
            "wheel_sha256",
            "sdist_sha256",
        },
        "original context comparison policy",
    )
    for key in ("normalized_package_version", "release_tag", "source_commit", "source_tree"):
        if baseline[key] != baseline_policy[key]:
            raise ReleaseControlError(
                "release comparison baseline differs from selected policy: " + key
            )
    for key in ("source_commit", "source_tree", "tag_object"):
        _release_git_oid(baseline[key], "original comparison " + key)
    artifacts = _release_original_artifact_descriptors(
        baseline["artifacts"], package_version=baseline["normalized_package_version"]
    )
    for kind, row in artifacts.items():
        if row["sha256"] != _require_digest(
            baseline_policy[kind + "_sha256"], "original comparison package policy"
        ):
            raise ReleaseControlError("release comparison artifact differs from original policy")
    for key in ("tag_observation", "release_observation"):
        ref = _release_closed_mapping(
            baseline[key], {"path", "bytes", "sha256"}, "original comparison observation"
        )
        _release_relative_suffix(ref["path"], "comparison observation path")
        if type(ref["bytes"]) is not int or ref["bytes"] < 1:
            raise ReleaseControlError("original comparison observation has invalid byte count")
        _require_digest(ref["sha256"], "comparison original observation")
    return data


def _release_comparison_baseline_readback(
    context_path: Path,
    *,
    captured: _ReleaseCapturedFiles,
) -> dict[str, Any]:
    """Replay original GitHub tag/release responses and package bytes, without LKG credit."""
    path = _release_capture_absolute(context_path)
    if not path.is_relative_to(captured.root):
        raise ReleaseControlError("comparison context escapes captured inputs")
    record = _source_json(
        captured.read(path.relative_to(captured.root).as_posix(), kind="release-context"),
        "original comparison context",
    )
    validate_record(record, "release-context")
    if record["status"] != "PASS":
        raise ReleaseControlError("comparison context is not passing")
    baseline = _release_closed_mapping(
        record["data"].get("comparison_baseline"),
        {
            "artifacts",
            "normalized_package_version",
            "release_observation",
            "release_tag",
            "source_commit",
            "source_tree",
            "tag_object",
            "tag_observation",
        },
        "complete comparison baseline",
    )
    _release_version_pair(
        baseline["normalized_package_version"], baseline["release_tag"], historical=True
    )
    for key in ("source_commit", "source_tree", "tag_object"):
        _release_git_oid(baseline[key], "comparison " + key)
    artifacts = _release_original_artifact_descriptors(
        baseline["artifacts"], package_version=baseline["normalized_package_version"]
    )

    def read(value: object, field: Sequence[str | int], *, distribution: bool = False) -> bytes:
        return _release_captured_raw_file(
            value,
            containing_path=path,
            containing_kind="release-context",
            field=field,
            captured=captured,
            expected_kind="distribution-original" if distribution else "comparison-original",
            label="original comparison sidecar",
        )[1]

    tag = _release_closed_mapping(
        _source_json(
            read(baseline["tag_observation"], ("data", "comparison_baseline", "tag_observation")),
            "original GitHub tag response",
        ),
        {"data"},
        "GitHub tag response",
    )
    repository = _release_closed_mapping(
        _release_closed_mapping(tag["data"], {"repository"}, "GitHub tag data")["repository"],
        {"nameWithOwner", "ref"},
        "GitHub tag repository",
    )
    ref = _release_closed_mapping(repository["ref"], {"name", "prefix", "target"}, "GitHub tag ref")
    annotated = _release_closed_mapping(
        ref["target"], {"__typename", "oid", "name", "target"}, "GitHub annotated tag"
    )
    commit = _release_closed_mapping(
        annotated["target"], {"__typename", "oid", "tree"}, "GitHub tag commit"
    )
    tree = _release_closed_mapping(commit["tree"], {"oid"}, "GitHub commit tree")
    if (
        repository["nameWithOwner"] != "Miko997/metriplane"
        or ref["name"] != baseline["release_tag"]
        or ref["prefix"] != "refs/tags/"
        or annotated["__typename"] != "Tag"
        or annotated["oid"] != baseline["tag_object"]
        or annotated["name"] != baseline["release_tag"]
        or commit["__typename"] != "Commit"
        or commit["oid"] != baseline["source_commit"]
        or tree["oid"] != baseline["source_tree"]
    ):
        raise ReleaseControlError(
            "original GitHub annotated tag/commit/tree differs from comparison identity"
        )
    published = _source_json(
        read(
            baseline["release_observation"], ("data", "comparison_baseline", "release_observation")
        ),
        "original GitHub release response",
    )
    required = {
        "id",
        "url",
        "html_url",
        "tag_name",
        "draft",
        "prerelease",
        "published_at",
        "assets",
    }
    if (
        not required <= published.keys()
        or type(published["id"]) is not int
        or published["id"] < 1
        or published["draft"] is not False
        or published["prerelease"] is not False
        or published["tag_name"] != baseline["release_tag"]
        or published["url"]
        != "https://api.github.com/repos/Miko997/metriplane/releases/" + str(published["id"])
        or published["html_url"]
        != "https://github.com/Miko997/metriplane/releases/tag/" + baseline["release_tag"]
        or any(key in published for key in ("errors", "error", "message", "truncated"))
    ):
        raise ReleaseControlError(
            "original GitHub comparison release is incomplete, unpublished or differently bound"
        )
    _parse_utc_timestamp(published["published_at"], "original comparison publication")
    if not isinstance(published["assets"], list):
        raise ReleaseControlError("original GitHub release lacks its asset inventory")
    assets: dict[str, Mapping[str, Any]] = {}
    for value in published["assets"]:
        if not isinstance(value, dict) or not isinstance(value.get("name"), str):
            raise ReleaseControlError("original GitHub release asset lacks its name")
        name = value["name"]
        if len(_release_relative_suffix(name, "original asset name").parts) != 1 or name in assets:
            raise ReleaseControlError("original GitHub release repeats or aliases an asset")
        assets[name] = value
    distribution_names = {name for name in assets if name.endswith((".whl", ".tar.gz"))}
    if distribution_names != {row["filename"] for row in artifacts.values()}:
        raise ReleaseControlError(
            "original GitHub release does not have the exact comparison distribution pair"
        )
    for index, row in enumerate(baseline["artifacts"]):
        raw = read(
            row["readback"],
            ("data", "comparison_baseline", "artifacts", index, "readback"),
            distribution=True,
        )
        if len(raw) != row["bytes"] or sha256_bytes(raw) != row["sha256"]:
            raise ReleaseControlError(
                "comparison distribution payload differs from its original identity"
            )
        asset = assets[row["filename"]]
        if (
            asset.get("state") != "uploaded"
            or type(asset.get("size")) is not int
            or asset["size"] != len(raw)
            or asset.get("digest") != "sha256:" + sha256_bytes(raw)
            or asset.get("browser_download_url")
            != "https://github.com/Miko997/metriplane/releases/download/"
            + baseline["release_tag"]
            + "/"
            + row["filename"]
        ):
            raise ReleaseControlError(
                "original GitHub distribution metadata differs from downloaded bytes"
            )
    captured.revalidate()
    return baseline


def _release_predecessor_policy_projection(
    raw: bytes,
    *,
    expected_digest: str,
    readiness_registry_raw: bytes,
    expected_readiness_digest: str,
    expected_context_id: str,
) -> dict[str, Any]:
    """Bind predecessor selection and unweakened proof requirements; never claim history exists."""
    for content, digest, label in [
        (raw, expected_digest, "predecessor"),
        (readiness_registry_raw, expected_readiness_digest, "readiness"),
    ]:
        if sha256_bytes(content) != _require_digest(digest, "expected original " + label):
            raise ReleaseControlError(
                "original " + label + " policy differs from its independent identity"
            )
    registry = _source_json(readiness_registry_raw, "original predecessor readiness policy")
    contexts = _release_id_rows(
        registry.get("release_contexts"), "context_id", "predecessor context policies"
    )
    if expected_context_id not in contexts:
        raise ReleaseControlError("predecessor policy has no independently selected context")
    context = contexts[expected_context_id]
    policy = _release_closed_mapping(
        _source_json(raw, "original predecessor policy"),
        {
            "schema_version",
            "owner",
            "repository",
            "readiness_context_id",
            "framework_milestone",
            "target_policy",
            "lineage_mode",
            "expected_predecessor_subject",
            "selection_authority",
            "proof_requirements",
            "expected_predecessor_decision",
        },
        "original predecessor policy",
    )
    milestone = policy["framework_milestone"]
    if (
        policy["schema_version"] != "metriplane.release-predecessor-policy.v1"
        or policy["owner"] != "MP2-007"
        or policy["repository"] != "Miko997/metriplane"
        or policy["readiness_context_id"] != expected_context_id
        or milestone != context.get("framework_milestone")
    ):
        raise ReleaseControlError("predecessor policy selects another repository/context/milestone")
    target = _release_target_policy_projection(policy["target_policy"], milestone=milestone)
    if canonical_json(target) != canonical_json(context.get("target_policy")):
        raise ReleaseControlError("predecessor policy changes the context target")
    selection = _release_closed_mapping(
        policy["selection_authority"],
        {"readiness_registry", "context_row_pointer", "context_policy_digest"},
        "predecessor selection authority",
    )
    selected_pointer = "/release_contexts/" + str(list(contexts).index(expected_context_id))
    if (
        selection["context_row_pointer"] != selected_pointer
        or selection["context_policy_digest"] != sha256_json(context)
        or canonical_json(
            _release_json_pointer(registry, selected_pointer, "predecessor context pointer")
        )
        != canonical_json(context)
    ):
        raise ReleaseControlError(
            "predecessor selection does not bind the exact complete context policy row"
        )
    selection_raw = _release_closed_mapping(
        selection["readiness_registry"],
        {"path", "bytes", "sha256"},
        "predecessor original readiness reference",
    )
    _release_relative_suffix(selection_raw["path"], "predecessor original readiness path")
    if (
        type(selection_raw["bytes"]) is not int
        or selection_raw["bytes"] != len(readiness_registry_raw)
        or selection_raw["sha256"] != expected_readiness_digest
    ):
        raise ReleaseControlError(
            "predecessor selection reference differs from original readiness bytes"
        )
    subject = _release_closed_mapping(
        policy["expected_predecessor_subject"],
        {
            "framework_milestone",
            "normalized_package_version",
            "release_tag",
            "source_commit",
            "source_tree",
            "tag_object",
            "artifacts",
        },
        "policy-selected predecessor subject",
    )
    version = _release_version_pair(
        subject["normalized_package_version"], subject["release_tag"], historical=True
    )
    for key in ("source_commit", "source_tree", "tag_object"):
        _release_git_oid(subject[key], "selected original predecessor " + key)
    _release_original_artifact_descriptors(
        subject["artifacts"], package_version=subject["normalized_package_version"]
    )
    keys = {
        "original_genesis",
        "qualification",
        "exact_byte_reconciliation",
        "final_two_store_retention",
        "success_chain_ancestry_and_current_head",
        "cas_lkg_transition_and_current_state",
        "pointer_envelope_two_store_retention_and_index",
        "original_signed_closed_decision_and_durable_root",
        "complete_later_invalidation_conflict_recovery_walk",
        "indexed_release_completion",
    }
    requirements = _release_closed_mapping(
        policy["proof_requirements"], keys, "original predecessor proof requirements"
    )
    if policy["lineage_mode"] == "ORIGINAL_BOOTSTRAP":
        slots = _release_id_rows(
            registry.get("release_gate_slots"), "version", "original roadmap predecessor slots"
        )
        slot = slots.get("v0.4", {})
        decision = _release_linear_identity(context.get("decision"), require_project=True)
        bindings = _release_id_rows(
            registry.get("provider_issue_bindings"),
            "issue_identifier",
            "original bootstrap provider bindings",
        )
        slot_identifier = _require_nonempty_string(
            slot.get("linear_release_decision_issue"), "original bootstrap slot issue"
        )
        binding = bindings.get(slot_identifier, {})
        original_identity = _release_linear_identity(binding.get("identity"), require_project=True)
        if (
            milestone != "v0.4"
            or target["initial_normalized_package_version"] != "0.4.0"
            or context.get("roadmap_catalog_task_id") != slot.get("release_decision_task")
            or decision["issue_identifier"] != slot.get("linear_release_decision_issue")
            or canonical_json(decision) != canonical_json(original_identity)
            or binding.get("catalog_task_id") != slot.get("release_decision_task")
            or subject["framework_milestone"] is not None
            or subject["normalized_package_version"] != "0.3.0"
            or policy["expected_predecessor_decision"] is not None
        ):
            raise ReleaseControlError(
                "original bootstrap is restricted to the actual initial framework context; patch releases cannot select it"
            )
        expected = {key: key == "original_genesis" for key in keys}
    elif policy["lineage_mode"] == "RECONCILED_LKG":
        previous = subject["framework_milestone"]
        allowed = {milestone}
        if milestone in MILESTONES and MILESTONES.index(milestone) > 0:
            allowed.add(MILESTONES[MILESTONES.index(milestone) - 1])
        if (
            not isinstance(previous, str)
            or previous not in allowed
            or previous not in MILESTONES
            or previous != f"v{version[0]}.{version[1]}"
        ):
            raise ReleaseControlError(
                "selected predecessor is not the governed same-line or preceding-line release"
            )
        initial = _release_version_pair(
            target["initial_normalized_package_version"], target["initial_release_tag"]
        )
        if target["resolution_mode"] == "owner_approved_exact_target" and version >= initial:
            raise ReleaseControlError(
                "selected predecessor is not older than the exact current target"
            )
        decision_binding = _release_closed_mapping(
            policy["expected_predecessor_decision"],
            {"identity", "authority"},
            "historical predecessor decision binding",
        )
        identity = _release_linear_identity(decision_binding["identity"], require_project=True)
        current_decision = _release_linear_identity(context.get("decision"), require_project=True)
        if any(identity[key] == current_decision[key] for key in ("issue_id", "issue_identifier")):
            raise ReleaseControlError(
                "historical predecessor decision aliases the current decision"
            )
        if not identity["issue_identifier"].startswith("MET-"):
            raise ReleaseControlError(
                "historical predecessor decision does not have its governed provider identifier"
            )
        authority = _release_closed_mapping(
            decision_binding["authority"],
            {"raw_registry", "json_pointer", "canonical_row_digest"},
            "original historical assignment authority",
        )
        if not isinstance(authority["json_pointer"], str) or not authority[
            "json_pointer"
        ].startswith("/"):
            raise ReleaseControlError(
                "historical assignment authority lacks its original row pointer"
            )
        _release_json_pointer_tokens(authority["json_pointer"], "historical assignment authority")
        _require_digest(authority["canonical_row_digest"], "historical assignment row")
        original = _release_closed_mapping(
            authority["raw_registry"], {"path", "bytes", "sha256"}, "original historical registry"
        )
        _release_relative_suffix(original["path"], "original historical registry path")
        if type(original["bytes"]) is not int or original["bytes"] < 1:
            raise ReleaseControlError("original historical registry has no valid byte count")
        _require_digest(original["sha256"], "original historical registry bytes")
        expected = {key: key != "original_genesis" for key in keys}
        expected["indexed_release_completion"] = milestone == "v1.0" or previous in {"v0.9", "v1.0"}
    else:
        raise ReleaseControlError("predecessor lineage selection is unknown")
    if canonical_json(requirements) != canonical_json(expected):
        raise ReleaseControlError(
            "predecessor policy changes or weakens original proof requirements"
        )
    return policy


_RELEASE_GATE_REGISTRY_INPUTS: Final[Mapping[str, str]] = {
    "readiness-registry": "readiness-registry",
    "obligations": "obligation-registry",
    "scenarios": "scenario-registry",
    "environments": "environment-registry",
    "targets": "target-registry",
    "evidence-stores": "evidence-store-registry",
    "task-state-policy": "task-state-policy-registry",
}
_RELEASE_GATE_DIRECT_RECORDS: Final[Mapping[str, str]] = {
    "linear-snapshot": "linear-release-snapshot",
    "role-assignments": "release-role-assignments",
    "target-resolution": "release-target-resolution",
    "target-burn": "release-target-burn",
    "target-burn-index-receipt": "release-attempt-index",
}


def _release_gate_declared_input_capture(
    root: Path,
    argv: list[str],
    *,
    expected_registry_digests: Mapping[str, str],
    original_inventory: Mapping[str, tuple[str, str]] | None = None,
    original_root_directories: tuple[tuple[str, int, int, int], ...] | None = None,
    original_capture: _ReleaseCapturedFiles | None = None,
) -> dict[str, Any]:
    try:
        return _release_gate_declared_input_capture_impl(
            root,
            argv,
            expected_registry_digests=expected_registry_digests,
            original_inventory=original_inventory,
            original_root_directories=original_root_directories,
            original_capture=original_capture,
        )
    except (KeyError, TypeError, AttributeError, IndexError, OSError) as exc:
        raise ReleaseControlError(
            "gate declared input shape or original file is incomplete"
        ) from exc


def _release_gate_declared_input_capture_impl(
    root: Path,
    argv: list[str],
    *,
    expected_registry_digests: Mapping[str, str],
    original_inventory: Mapping[str, tuple[str, str]] | None = None,
    original_root_directories: tuple[tuple[str, int, int, int], ...] | None = None,
    original_capture: _ReleaseCapturedFiles | None = None,
) -> dict[str, Any]:
    """Capture declared bytes before intent, retaining semantic roles separately from transport.

    The original proof inventory is a transport declaration, not proof of native completeness.
    Original journal/native replay must still prove its exact reachable ownership before effects.
    This routine does not reserve an intent, construct outputs or admit any derived authority.
    """
    root = _release_capture_absolute(root)
    if original_capture is not None:
        if not isinstance(original_capture, _ReleaseCapturedFiles) or original_capture.root != root:
            raise ReleaseControlError("original gate capture has a different current root")
        if (
            original_root_directories is not None
            and original_root_directories != original_capture.root_directories
        ):
            raise ReleaseControlError("original gate capture root expectations conflict")
        original_root_directories = original_capture.root_directories
    _, _, root_directories = _release_held_path(
        root, directory=True, expected_directories=original_root_directories
    )
    if original_inventory is not None:
        for name, (kind, digest) in original_inventory.items():
            _release_relative_suffix(name, "original gate inventory")
            _require_nonempty_string(kind, "original gate input type")
            _require_digest(digest, "original gate input bytes")
    arguments = _release_original_arguments("prepare_release_gate_input.py", argv)
    if set(expected_registry_digests) != set(_RELEASE_GATE_REGISTRY_INPUTS):
        raise ReleaseControlError(
            "gate capture lacks seven independently expected registry identities"
        )
    for flag, digest in expected_registry_digests.items():
        _require_digest(digest, "independent gate registry " + flag)
    directory = _release_capture_absolute(Path(arguments["invocation-dir"]))
    suffix = directory.relative_to(root) if directory.is_relative_to(root) else Path()
    if (
        len(suffix.parts) != 3
        or suffix.parts[:2] != ("invocations", "gate-input")
        or re.fullmatch(r"[0-9]{3,}", suffix.name, flags=re.ASCII) is None
        or int(suffix.name) < 1
        or suffix.name != f"{int(suffix.name):03d}"
        or _release_capture_absolute(Path(arguments["out"])) != root / "gate-input.json"
    ):
        raise ReleaseControlError("gate capture invocation/output is not its exact current root")
    excluded = [
        "gate-input.json",
        "scenario-catalog.json",
        "invocations/gate-input",
        "invocations/gate-input-validation",
    ]
    forbidden = tuple(Path(name) for name in excluded)
    raw_files: dict[str, bytes] = {}
    observed_files: dict[str, tuple[int, ...]] = {}
    observed_ancestors: dict[str, tuple[tuple[str, int, int, int], ...]] = {}
    known_directories = {row[0]: row for row in root_directories}
    prior_files = {} if original_capture is None else {row[0]: row for row in original_capture.rows}
    if original_capture is not None:
        for row in original_capture.rows:
            for ancestor in row[4]:
                if ancestor[0] in known_directories and known_directories[ancestor[0]] != ancestor:
                    raise ReleaseControlError(
                        "original gate capture contains conflicting ancestor pins"
                    )
                known_directories[ancestor[0]] = ancestor
    semantics: dict[str, set[str]] = {}
    originals: set[str] = set()

    def read(path: Path, kind: str) -> bytes:
        path = _release_capture_absolute(path)
        if not path.is_relative_to(root):
            raise ReleaseControlError("gate declared input escapes its current root")
        name = path.relative_to(root).as_posix()
        relative = _release_relative_suffix(name, "gate declared input")
        if original_inventory is not None:
            if name not in original_inventory:
                raise ReleaseControlError("gate file is absent from the original input inventory")
            original_kind, _ = original_inventory[name]
            allowed_original = {"metriplane.prerequisite-original.v1"}
            if kind != "prerequisite-original":
                allowed_original.add("metriplane." + kind + ".v1")
            if original_kind not in allowed_original:
                raise ReleaseControlError("gate file has a different original captured type")
        if any(relative.is_relative_to(p) or p.is_relative_to(relative) for p in forbidden):
            raise ReleaseControlError("gate declared input overlaps an output or active journal")
        # A generic original transport reference may share one concrete semantic role only.
        roles = semantics.setdefault(name, set())
        if kind != "prerequisite-original" and roles - {kind, "prerequisite-original"}:
            raise ReleaseControlError("gate input has incompatible semantic declarations")
        roles.add(kind)
        if original_capture is not None and name not in prior_files:
            raise ReleaseControlError("gate input is absent from the held original capture")
        prior = prior_files.get(name)
        if (
            prior is not None
            and prior[1] not in {kind, "prerequisite-original"}
            and kind != "prerequisite-original"
        ):
            raise ReleaseControlError("gate input differs from its held original type")
        raw, identity, ancestors = _release_held_path(
            path,
            expected_prefix=tuple(known_directories.values()),
            expected_directories=prior[4] if prior is not None else observed_ancestors.get(name),
            expected_identity=prior[3] if prior is not None else observed_files.get(name),
        )
        if prior is not None and raw != prior[2]:
            raise ReleaseControlError("gate held original bytes changed")
        if original_inventory is not None and sha256_bytes(raw) != original_inventory[name][1]:
            raise ReleaseControlError("gate file differs from its original bytes before parsing")
        if name in raw_files and (
            raw_files[name] != raw
            or observed_files[name] != identity
            or observed_ancestors[name] != ancestors
        ):
            raise ReleaseControlError("gate input changed while its references were enumerated")
        raw_files[name] = raw
        observed_files[name] = identity
        observed_ancestors[name] = ancestors
        known_directories.update((row[0], row) for row in ancestors)
        return raw

    def reference(container: Path, value: object, kind: str) -> Path:
        row = _release_closed_mapping(
            value, {"path", "bytes", "sha256"}, "gate original raw reference"
        )
        if type(row["bytes"]) is not int or row["bytes"] < 0:
            raise ReleaseControlError("gate raw reference has an invalid byte count")
        path = container.parent / _release_relative_suffix(row["path"], "gate raw reference")
        raw = read(path, kind)
        if len(raw) != row["bytes"] or sha256_bytes(raw) != _require_digest(
            row["sha256"], "gate raw reference"
        ):
            raise ReleaseControlError("gate original raw reference bytes differ")
        return path

    direct = {}
    objects = {}
    flags = {
        **_RELEASE_GATE_REGISTRY_INPUTS,
        **_RELEASE_GATE_DIRECT_RECORDS,
        "release-context": "release-context",
        "predecessor-policy": "predecessor-policy",
        "prerequisite-proofs": "prerequisite-proofs",
        "provider-attestation-keyring": "provider-attestation-keyring",
    }
    for flag, kind in flags.items():
        if flag not in arguments:
            continue
        path = _release_capture_absolute(Path(arguments[flag]))
        if flag == "target-resolution":
            if path != root / "target-resolution.json":
                raise ReleaseControlError("gate target resolution has a different fixed path")
        elif not path.is_relative_to(root / "inputs") or path == root / "inputs":
            raise ReleaseControlError("gate direct input is not below its exact inputs directory")
        raw = read(path, kind)
        direct[flag] = path
        objects[flag] = _source_json(raw, "gate direct " + flag)
        if (
            flag in expected_registry_digests
            and sha256_bytes(raw) != expected_registry_digests[flag]
        ):
            raise ReleaseControlError("gate raw registry differs from independently expected bytes")
        if flag in _RELEASE_GATE_DIRECT_RECORDS or flag == "release-context":
            validate_record(objects[flag], kind)
    trust_flags = {
        "provider-attestation-keyring",
        "provider-attestation-keyring-digest",
        "authority-policy-digest",
    }
    if (set(arguments) & trust_flags) not in (set(), trust_flags):
        raise ReleaseControlError("gate supplied trust controls are incomplete")
    if trust_flags <= set(arguments):
        keyring = objects["provider-attestation-keyring"]
        keyring_digest = _require_digest(
            arguments["provider-attestation-keyring-digest"], "gate expected keyring"
        )
        if sha256_json(keyring) != keyring_digest or release_authority_policy_digest(
            keyring_digest
        ) != _require_digest(arguments["authority-policy-digest"], "gate expected authority"):
            raise ReleaseControlError(
                "gate captured keyring differs from independent trust controls"
            )
    bundle = _release_closed_mapping(
        objects["prerequisite-proofs"],
        {"schema_version", "release_context_digest", "proofs", "captured_original_files"},
        "gate prerequisite transport",
    )
    if bundle["schema_version"] != "metriplane.release-prerequisite-proofs.v1" or bundle[
        "release_context_digest"
    ] != sha256_json(objects["release-context"]):
        raise ReleaseControlError("gate original transport selects another context")
    if (
        not isinstance(bundle["captured_original_files"], list)
        or not bundle["captured_original_files"]
    ):
        raise ReleaseControlError("gate original transport inventory is missing")
    container = direct["prerequisite-proofs"]
    for row in bundle["captured_original_files"]:
        path = reference(container, row, "prerequisite-original")
        name = path.relative_to(root).as_posix()
        if name in originals or path == container:
            raise ReleaseControlError("gate original transport repeats a file or contains itself")
        originals.add(name)
    if not isinstance(bundle["proofs"], list) or not bundle["proofs"]:
        raise ReleaseControlError("gate original proof inventory is missing")
    proof_records = {}
    for row in bundle["proofs"]:
        if (
            not isinstance(row, dict)
            or not isinstance(row.get("producer"), str)
            or row["producer"] not in _RELEASE_GATE_PREREQUISITES
        ):
            raise ReleaseControlError("gate prerequisite has an unknown original owner")
        kind, record_kind, companion = _RELEASE_GATE_PREREQUISITES[row["producer"]]
        if (
            row.get("record_type") != kind
            or row.get("record_kind") != record_kind
            or row.get("stage") != _invocation_stage(row["producer"])
        ):
            raise ReleaseControlError("gate prerequisite changes its closed original type")
        path = reference(container, row.get("record"), kind)
        name = path.relative_to(root).as_posix()
        if name not in originals or name in proof_records:
            raise ReleaseControlError(
                "gate prerequisite record is absent or repeated in original inventory"
            )
        record = _source_json(raw_files[name], "gate original record")
        validate_record(record, kind)
        if (
            sha256_json(record) != row.get("record_digest")
            or record["data"].get("kind") != record_kind
        ):
            raise ReleaseControlError(
                "gate prerequisite record differs from original semantic identity"
            )
        proof_records[name] = record
        for field in ("producer_intent", "producer_terminal"):
            if (
                reference(container, row.get(field), "prerequisite-original")
                .relative_to(root)
                .as_posix()
                not in originals
            ):
                raise ReleaseControlError("gate original producer journal is undeclared")
        companions = row.get("companion_validations")
        if not isinstance(companions, list) or len(companions) != (0 if companion is None else 1):
            raise ReleaseControlError("gate original companion inventory differs")
        for validation in companions:
            if not isinstance(validation, dict) or validation.get("tool") != companion:
                raise ReleaseControlError("gate original companion has a different owner")
            for field in ("intent", "terminal"):
                if (
                    reference(container, validation.get(field), "prerequisite-original")
                    .relative_to(root)
                    .as_posix()
                    not in originals
                ):
                    raise ReleaseControlError("gate original companion journal is undeclared")
    target_control_origin = None
    for flag in _RELEASE_GATE_DIRECT_RECORDS:
        if flag not in direct:
            continue
        if flag == "target-resolution":
            control_name = direct[flag].relative_to(root).as_posix()
            matching = [
                name
                for name, record in proof_records.items()
                if record["record_type"] == "release-target-resolution"
                and raw_files[name] == raw_files[control_name]
                and sha256_json(record) == sha256_json(objects[flag])
            ]
            if len(matching) != 1:
                raise ReleaseControlError(
                    "gate fixed target control lacks exactly one byte-identical original output"
                )
            target_control_origin = matching[0]
        elif direct[flag].relative_to(root).as_posix() not in proof_records:
            raise ReleaseControlError(
                "gate direct CLI record is not its exact original producer path"
            )

    # Each traversal below is owned by a named schema field. Never discover references by
    # searching arbitrary JSON for path-looking objects, walking directories or guessed names.
    readiness = objects["readiness-registry"]
    reference(
        direct["readiness-registry"], readiness["catalog_binding"]["source"], "authority-original"
    )
    reference(
        direct["readiness-registry"],
        readiness["linear_capture_policy"]["provider_transport_binding"],
        "authority-original",
    )
    for field in ("provider_issue_bindings", "release_contexts"):
        for row in readiness[field]:
            reference(
                direct["readiness-registry"], row["assignment_authority"], "authority-original"
            )
    for flag in ("obligations", "scenarios", "environments"):
        for row in objects[flag]["authority_sources"]:
            reference(direct[flag], row["raw_file"], "authority-original")

    def source_reference(container: Path, source: object) -> None:
        if not isinstance(source, dict):
            raise ReleaseControlError("gate configured source declaration is invalid")
        if source.get("binding") == "candidate_source_blob":
            reference(container, source["source_bytes"], "configuration-source")
        elif "source_bytes" in source:
            raise ReleaseControlError("gate source bytes have an unknown binding owner")
        else:
            _release_closed_mapping(
                source,
                {"repository", "commit", "tree", "path", "blob"},
                "original protected Git source declaration",
            )

    def owner_reference(container: Path, owner: object) -> None:
        if not isinstance(owner, dict) or owner.get("kind") not in {
            "pytest_node",
            "python_entry",
            "workflow_job",
            "supplied_attestation",
        }:
            raise ReleaseControlError("gate configured execution owner is unknown")
        source_reference(container, owner["source"])

    for flag in ("obligations", "scenarios", "environments"):
        container = direct[flag]
        for executor in objects[flag]["executors"]:
            binding = executor["binding"]
            if binding["state"] == "UNRESOLVED":
                _release_closed_mapping(
                    binding, {"state", "required_owner_paths", "reason"}, "unresolved gate executor"
                )
                continue
            if binding["state"] != "CONFIGURED":
                raise ReleaseControlError("gate executor binding is unknown")
            _release_closed_mapping(binding, {"state", "recipe"}, "configured gate executor")
            recipe = binding["recipe"]
            owner_reference(container, recipe["owner"])
            if recipe["required_operation_owner"] is not None:
                owner_reference(container, recipe["required_operation_owner"])
            launch = recipe["launch"]
            if launch["kind"] == "workflow_job":
                source_reference(container, launch["workflow_source"])
                owner_reference(container, launch["dispatch_owner"])
            elif launch["kind"] == "supplied_attestation":
                owner_reference(container, launch["validator_owner"])
            elif launch["kind"] != "argv":
                raise ReleaseControlError("gate executor launch is unknown")
            for output in recipe["expected_outputs"]:
                owner_reference(container, output["validator_owner"])
            for sidecar in recipe["input_sidecars"]:
                reference(container, sidecar, "execution-sidecar")
            for resource in recipe["resources"]:
                resource_binding = resource["binding"]
                if resource_binding["state"] == "CONFIGURED":
                    _release_closed_mapping(
                        resource_binding, {"state", "configuration"}, "configured gate resource"
                    )
                    reference(
                        container, resource_binding["configuration"], "resource-configuration"
                    )
                elif resource_binding["state"] == "UNRESOLVED":
                    _release_closed_mapping(
                        resource_binding, {"state", "reason"}, "unresolved gate resource"
                    )
                else:
                    raise ReleaseControlError("gate resource binding is unknown")
    for row in objects["environments"]["environments"]:
        sources = [
            *row["authority"],
            *row["runtime"]["toolchain_sources"],
            row["runtime"]["lock_source"],
        ]
        if row["execution"]["state"] == "CONFIGURED":
            owner_reference(direct["environments"], row["execution"]["owner"])
            sources.extend(row["execution"]["configuration_sources"])
        elif row["execution"]["state"] == "UNRESOLVED":
            _release_closed_mapping(
                row["execution"], {"state", "reason"}, "unresolved environment execution"
            )
        else:
            raise ReleaseControlError("gate environment execution binding is unknown")
        for source in sources:
            if isinstance(source, dict) and source.get("source_bytes") is not None:
                reference(direct["environments"], source["source_bytes"], "configuration-source")
    for backend in objects["evidence-stores"]["backends"]:
        if backend["live_binding"] is None:
            if backend["binding_status"] != "UNRESOLVED":
                raise ReleaseControlError("gate backend binding lacks declared original files")
            continue
        if backend["binding_status"] != "BOUND_CONFIGURED":
            raise ReleaseControlError(
                "gate backend original files lack their configured declaration"
            )
        binding = _release_closed_mapping(
            backend["live_binding"],
            {
                "adapter_id",
                "public_configuration",
                "owner_binding_authority",
                "provider_resource_identity",
                "administration_identity",
                "durability_retention_policy",
                "namespace_policy",
            },
            "gate durable backend live binding",
        )
        for field in (
            "public_configuration",
            "owner_binding_authority",
            "provider_resource_identity",
            "administration_identity",
            "durability_retention_policy",
            "namespace_policy",
        ):
            reference(direct["evidence-stores"], binding[field], "backend-binding-original")
    context = objects["release-context"]["data"]
    baseline = context["comparison_baseline"]
    for field in ("tag_observation", "release_observation"):
        reference(direct["release-context"], baseline[field], "comparison-original")
    for row in baseline["artifacts"]:
        reference(direct["release-context"], row["readback"], "distribution-original")
    predecessor = objects["predecessor-policy"]
    reference(
        direct["predecessor-policy"],
        predecessor["selection_authority"]["readiness_registry"],
        "readiness-registry",
    )
    for row in predecessor["expected_predecessor_subject"]["artifacts"]:
        reference(direct["predecessor-policy"], row["readback"], "distribution-original")
    if predecessor["expected_predecessor_decision"] is not None:
        reference(
            direct["predecessor-policy"],
            predecessor["expected_predecessor_decision"]["authority"]["raw_registry"],
            "authority-original",
        )
    captured = _ReleaseCapturedFiles.capture(
        root,
        [
            (name, "prerequisite-original" if name in originals else next(iter(roles)))
            for name, roles in sorted(semantics.items())
        ],
        forbidden=excluded,
        allowed_kinds=frozenset(
            {"prerequisite-original", *[kind for roles in semantics.values() for kind in roles]}
        ),
        expected_root_directories=root_directories,
        expected_known_directories=tuple(known_directories.values()),
        expected_file_identities=observed_files,
    )
    if original_capture is not None:
        if (
            captured.rows != original_capture.rows
            or captured.root_directories != original_capture.root_directories
        ):
            raise ReleaseControlError(
                "gate reconstructed closure differs from its held original capture"
            )
        captured = original_capture
    if captured.root_directories != root_directories:
        raise ReleaseControlError("gate root changed while its inputs were enumerated")
    for name, kind, raw, identity, ancestors in captured.rows:
        if (
            raw != raw_files[name]
            or identity != observed_files[name]
            or ancestors != observed_ancestors[name]
        ):
            raise ReleaseControlError("gate input changed between enumeration and held capture")
    # Both views retain exactly the same held files and identities. Semantic purpose cannot
    # replace original journal transport ownership or establish native authority.
    semantic_capture = _ReleaseCapturedFiles(
        captured.root,
        captured.root_directories,
        tuple(
            (
                name,
                next(iter(semantics[name] - {"prerequisite-original"}), kind),
                raw,
                identity,
                ancestors,
            )
            for name, kind, raw, identity, ancestors in captured.rows
        ),
    )
    return {
        "arguments": arguments,
        "direct_paths": direct,
        "captured": captured,
        "semantic_captured": semantic_capture,
        "target_control_origin": target_control_origin,
        "semantic_roles": tuple(
            (name, tuple(sorted(roles - {"prerequisite-original"})))
            for name, roles in sorted(semantics.items())
        ),
    }


_RELEASE_GATE_OUTPUT_PLAN = (
    ("gate-input.json", "metriplane.release-gate-input.v1"),
    ("scenario-catalog.json", "metriplane.release-scenario-catalog.v1"),
)


def _release_gate_input_plan_replay(
    context: ReleaseInvocation,
    *,
    expected_registry_digests: Mapping[str, str],
    original_capture: _ReleaseCapturedFiles | None = None,
    original_intent_capture: _ReleaseCapturedFiles | None = None,
) -> dict[str, Any]:
    """Replay one original gate input plan at an independently located current root.

    This binds captured bytes and original argv, not terminal success or native authority.
    Its returned lexical argv is used only to enumerate the relocated input closure;
    the original intent and historical argv remain untouched.
    """
    root = _release_capture_absolute(context.root)
    directory = _release_capture_absolute(context.directory)
    if directory.parent.parent != root / "invocations":
        raise ReleaseControlError("gate input replay has a different current journal root")
    if original_capture is not None and original_capture.root != root:
        raise ReleaseControlError("gate replay has a different held capture root")
    held_intent = original_intent_capture
    if isinstance(context, _ReleaseGateInvocation):
        if held_intent is not None and held_intent is not context.intent_capture:
            raise ReleaseControlError("gate replay replaced its producer-held original intent")
        held_intent = context.intent_capture
    if held_intent is not None and (
        not isinstance(held_intent, _ReleaseCapturedFiles)
        or held_intent.root != root
        or (
            original_capture is not None
            and held_intent.root_directories != original_capture.root_directories
        )
    ):
        raise ReleaseControlError("gate held original intent has different root custody")
    expected_root = (
        original_capture.root_directories
        if original_capture is not None
        else (held_intent.root_directories if held_intent is not None else None)
    )
    _, _, root_ancestors = _release_held_path(
        root, directory=True, expected_directories=expected_root
    )
    intent_path = directory / "intent.json"
    if held_intent is not None:
        name = intent_path.relative_to(root).as_posix()
        if len(held_intent.rows) != 1 or held_intent.rows[0][:2] != (
            name,
            "release-invocation-intent",
        ):
            raise ReleaseControlError("gate held original intent capture differs")
        raw = held_intent.read(name, kind="release-invocation-intent")
        _, _, _, identity, ancestors = held_intent.rows[0]
    else:
        raw, identity, ancestors = _release_held_path(intent_path, expected_prefix=root_ancestors)
    original = _validate_intent_bytes(directory, raw)
    if (
        original.root != root
        or original.intent["tool"] != "prepare_release_gate_input.py"
        or canonical_json(original.intent) != canonical_json(context.intent)
    ):
        raise ReleaseControlError("gate input replay differs from the original captured intent")
    intent = original.intent
    arguments = _release_original_arguments(intent["tool"], intent["argv"])
    cwd = _canonical_absolute_path(
        intent["environment"]["working_directory"], "original gate working directory"
    )
    historical_directory = _release_historical_path(arguments["invocation-dir"], cwd)
    journal_suffix = Path("invocations") / "gate-input" / f"{intent['sequence']:03d}"
    if historical_directory.parts[-3:] != journal_suffix.parts:
        raise ReleaseControlError("original gate argv has a different stage or sequence")
    historical_root = historical_directory.parents[2]
    if directory != root / journal_suffix:
        raise ReleaseControlError("current gate journal differs from its original exact suffix")
    plan = [{"path": name, "schema_id": kind} for name, kind in _RELEASE_GATE_OUTPUT_PLAN]
    if (
        intent["planned_outputs"] != plan
        or _release_historical_path(arguments["out"], cwd) != historical_root / "gate-input.json"
    ):
        raise ReleaseControlError("original gate does not plan its exact two canonical outputs")

    relocated = dict(arguments)
    input_flags = {
        *_RELEASE_GATE_REGISTRY_INPUTS,
        *_RELEASE_GATE_DIRECT_RECORDS,
        "release-context",
        "predecessor-policy",
        "prerequisite-proofs",
        "provider-attestation-keyring",
    }
    for flag in input_flags & set(arguments):
        historical = _release_historical_path(arguments[flag], cwd)
        if not historical.is_relative_to(historical_root):
            raise ReleaseControlError("original gate direct input escapes its original root")
        suffix = historical.relative_to(historical_root)
        _release_relative_suffix(suffix.as_posix(), "original gate direct input")
        if flag == "target-resolution":
            if suffix != Path("target-resolution.json"):
                raise ReleaseControlError("original gate target control has a different path")
        elif suffix.parts[0] != "inputs" or len(suffix.parts) < 2:
            raise ReleaseControlError("original gate direct input is outside its inputs directory")
        relocated[flag] = str(root / suffix)
    relocated["invocation-dir"] = str(directory)
    relocated["out"] = str(root / "gate-input.json")
    argv = [intent["tool"]]
    contract = TOOL_CONTRACTS[intent["tool"]]
    for flag, value in sorted(relocated.items()):
        argv.append("--" + flag)
        if flag not in contract.boolean:
            argv.append(str(value))
    original_inventory: dict[str, tuple[str, str]] = {}
    for row in intent["inputs"]:
        historical = _canonical_absolute_path(row["path"], "original gate captured input")
        if not historical.is_relative_to(historical_root):
            raise ReleaseControlError("original gate inventory escapes its original root")
        input_name = historical.relative_to(historical_root).as_posix()
        _release_relative_suffix(input_name, "original gate captured input")
        if input_name in original_inventory:
            raise ReleaseControlError("original gate inventory repeats a relative input")
        original_inventory[input_name] = (row["schema_id"], row["sha256"])
    captured_plan = _release_gate_declared_input_capture(
        root,
        argv,
        expected_registry_digests=expected_registry_digests,
        original_inventory=original_inventory,
        original_root_directories=root_ancestors,
        original_capture=original_capture,
    )
    captured = captured_plan["captured"]
    expected_inputs = sorted(
        (
            {
                "path": str(historical_root / name),
                "schema_id": "metriplane." + kind + ".v1",
                "sha256": sha256_bytes(value),
            }
            for name, kind, value, _, _ in captured.rows
        ),
        key=lambda row: row["path"],
    )
    if intent["inputs"] != expected_inputs:
        raise ReleaseControlError("gate reconstructed closure differs from its original inventory")
    captured.revalidate()
    after, current, _ = _release_held_path(
        intent_path, expected_directories=ancestors, expected_identity=identity
    )
    if after != raw or current != identity or captured.root_directories != root_ancestors:
        raise ReleaseControlError("gate intent or root changed during input replay")
    return {
        **captured_plan,
        "original_arguments": arguments,
        "historical_root": historical_root,
        "intent": intent,
        "intent_ancestors": ancestors,
        "intent_identity": identity,
    }


def _release_gate_pair_data(
    subjects: Mapping[str, Mapping[str, Any]],
    registries: Mapping[str, bytes],
    *,
    expected_subject_digests: Mapping[str, str],
    expected_registry_digests: Mapping[str, str],
    predecessor_policy_raw: bytes,
    expected_predecessor_policy_digest: str,
    expected_context_id: str,
    expected_predecessor_milestone: str,
    milestone: str,
    run_id: str,
    producer_intent_digest: str,
    invocation_id: str,
    sequence: int,
    synthetic: bool,
    no_new_burn: bool,
    burn_index_original: Mapping[str, Any] | None,
) -> dict[str, Any]:
    """Construct the gate's complete content against its exact acyclic catalog.

    This shared content layer is called only after original native inputs are
    verified. The new-burn form also replays the exact supplied original index
    command and its held subject/manifest/retention bytes. This does not
    authenticate roles/providers/stores, grant coverage or
    declare a target usable. Worker, supervisor and public consumers still need
    the original input proof and exact common two-output journal before use.
    """
    kinds = {
        "release-context": "release-context",
        "linear-snapshot": "linear-release-snapshot",
        "role-assignments": "release-role-assignments",
        "target-resolution": "release-target-resolution",
        "target-burn": "release-target-burn",
        "scenario-catalog": "release-scenario-catalog",
    }
    if type(no_new_burn) is not bool or type(synthetic) is not bool:
        raise ReleaseControlError("gate pair has no explicit burn or authority mode")
    if not no_new_burn:
        kinds["target-burn-index-receipt"] = "release-attempt-index"
    if set(subjects) != set(kinds) or set(expected_subject_digests) != set(kinds):
        raise ReleaseControlError("gate pair original record closure differs from its burn form")
    fields = {
        "readiness-registry": "readiness_registry_digest",
        "obligations": "obligation_registry_digest",
        "scenarios": "scenario_registry_digest",
        "environments": "environment_registry_digest",
        "targets": "target_registry_digest",
        "evidence-stores": "evidence_store_registry_digest",
        "task-state-policy": "task_state_policy_digest",
    }
    if set(registries) != set(fields) or set(expected_registry_digests) != set(fields):
        raise ReleaseControlError("gate pair lacks its seven original raw registries")
    for name in fields:
        if sha256_bytes(registries[name]) != _require_digest(
            expected_registry_digests[name], "gate original " + name
        ):
            raise ReleaseControlError("gate pair changes original registry bytes before parsing")
    if type(sequence) is not int or sequence < 1 or milestone not in MILESTONES:
        raise ReleaseControlError("gate pair producer sequence or milestone is invalid")
    _require_invocation(invocation_id)
    _require_digest(producer_intent_digest, "gate pair original producer")
    for name, kind in kinds.items():
        record = subjects[name]
        validate_record(record, kind)
        if (
            record["status"] != "PASS"
            or record["synthetic"] is not synthetic
            or sha256_json(record)
            != _require_digest(expected_subject_digests[name], "gate original " + name)
        ):
            raise ReleaseControlError("gate pair original record mode, result or full C differs")
    context = subjects["release-context"]
    _release_context_policy_projection(
        context,
        readiness_registry_raw=registries["readiness-registry"],
        expected_readiness_digest=expected_registry_digests["readiness-registry"],
        predecessor_policy_raw=predecessor_policy_raw,
        expected_predecessor_policy_digest=expected_predecessor_policy_digest,
        expected_context_id=expected_context_id,
        linear_snapshot=subjects["linear-snapshot"],
    )
    predecessor = _release_predecessor_policy_projection(
        predecessor_policy_raw,
        expected_digest=expected_predecessor_policy_digest,
        readiness_registry_raw=registries["readiness-registry"],
        expected_readiness_digest=expected_registry_digests["readiness-registry"],
        expected_context_id=expected_context_id,
    )
    predecessor_subject = predecessor["expected_predecessor_subject"]
    if expected_predecessor_milestone != (
        predecessor_subject["framework_milestone"] or predecessor_subject["release_tag"]
    ):
        raise ReleaseControlError("gate pair changes the original predecessor selection")
    # These cross-links supplement each original type-specific native validator.
    roles = subjects["role-assignments"]["data"]
    resolution = subjects["target-resolution"]["data"]
    burn = subjects["target-burn"]["data"]
    context_digest = expected_subject_digests["release-context"]
    if (
        subjects["linear-snapshot"]["data"].get("task_state_policy_digest")
        != expected_registry_digests["task-state-policy"]
        or context["data"]["framework_milestone"] != milestone
        or roles.get("milestone") != milestone
        or roles.get("run_id") != run_id
        or roles.get("release_context_digest") != context_digest
        or roles.get("kind") != "recorded_assignments"
        or resolution.get("milestone") != milestone
        or resolution.get("release_context_digest") != context_digest
        or resolution.get("resolution_rule") != context["data"]["target_policy"]["resolution_mode"]
        or burn.get("milestone") != milestone
        or burn.get("resolved_package_version") != resolution.get("selected_package_version")
        or burn.get("resolved_release_tag") != resolution.get("selected_release_tag")
        or burn.get("observation_digest") != resolution.get("observations_digest")
        or burn.get("burn_lineage_digest") != resolution.get("burn_lineage_digest")
        or resolution.get("requires_new_burn") is not (not no_new_burn)
        or burn.get("indexing_required") is not (not no_new_burn)
        or burn.get("disposition") != ("no_new_burn" if no_new_burn else "new_burn")
    ):
        raise ReleaseControlError("gate pair context, run, target or burn bindings differ")
    if no_new_burn and burn_index_original is not None:
        raise ReleaseControlError("no-new-burn gate has an unexpected index command graph")
    if not no_new_burn:
        original_index = _release_closed_mapping(
            burn_index_original,
            {
                "update",
                "receipt_path",
                "captured",
                "subject_path",
                "expected_scope",
                "expected_operation_id",
                "expected_index_backend",
                "expected_prior_head",
            },
            "gate original burn index command graph",
        )
        binding = _release_index_original_update_binding(
            subjects["target-burn-index-receipt"],
            **original_index,
            subject_record=subjects["target-burn"],
            expected_milestone=milestone,
            expected_release_tag=burn["resolved_release_tag"],
            expected_synthetic=synthetic,
        )
        entry = _release_index_receipt_content(subjects["target-burn-index-receipt"]["data"])
        scope = entry["scope"]
        if canonical_json(binding["entry"]) != canonical_json(entry):
            raise ReleaseControlError("gate burn receipt differs from its original command replay")
        if (
            entry["milestone"] != milestone
            or scope["kind"] != "release_staging"
            or scope["stage"] != "target-burn"
            or scope["run_id"] != run_id
            or scope["release_tag"] != burn.get("resolved_release_tag")
            or scope["candidate_id"] is not None
        ):
            raise ReleaseControlError("gate pair burn receipt changes the original scope")
    catalog = subjects["scenario-catalog"]
    if (
        catalog["invocation_id"] != invocation_id
        or catalog["sequence"] != sequence
        or catalog["signatures"] != []
    ):
        raise ReleaseControlError("gate pair catalog belongs to a different producer envelope")
    _release_scenario_catalog_replay(
        catalog,
        {path: registries[name] for name, path in _RELEASE_EXECUTION_REGISTRIES.items()},
        expected_registry_digests={
            path: expected_registry_digests[name]
            for name, path in _RELEASE_EXECUTION_REGISTRIES.items()
        },
        run_id=run_id,
        producer_intent_digest=producer_intent_digest,
        synthetic=synthetic,
    )
    data = {
        **{field: expected_registry_digests[name] for name, field in fields.items()},
        "release_context_digest": context_digest,
        "linear_snapshot_digest": expected_subject_digests["linear-snapshot"],
        "role_assignments_digest": expected_subject_digests["role-assignments"],
        "target_resolution_digest": expected_subject_digests["target-resolution"],
        "target_burn_digest": expected_subject_digests["target-burn"],
        "target_burn_index_receipt_digest": expected_subject_digests.get(
            "target-burn-index-receipt"
        ),
        "scenario_catalog_digest": expected_subject_digests["scenario-catalog"],
        "predecessor_policy_digest": expected_predecessor_policy_digest,
        "expected_predecessor_milestone": expected_predecessor_milestone,
        "milestone": milestone,
        "run_id": run_id,
        "producer_intent_digest": producer_intent_digest,
        "invocation_root_locator": "invocations",
    }
    data["gate_input_digest"] = sha256_json(data)
    return data


def _release_gate_pair_output_replay(
    context: ReleaseInvocation,
    *,
    captured: _ReleaseCapturedFiles,
    expected_gate_data: Mapping[str, Any],
    expected_catalog_record: Mapping[str, Any],
) -> dict[str, Any]:
    result = _release_gate_pair_output_content(
        context,
        captured=captured,
        expected_gate_data=expected_gate_data,
        expected_catalog_record=expected_catalog_record,
    )
    _release_gate_terminal_commit_replay(context, result["terminal"], captured=captured)
    return result


def _release_source_input_content(
    gate: Mapping[str, Any],
    target: Mapping[str, Any],
    *,
    context: Mapping[str, Any],
    catalog: Mapping[str, Any],
    expected_record_digests: Mapping[str, str],
    run_id: str,
    synthetic: bool,
    context_policy_inputs: Mapping[str, Any],
    target_control_inputs: Mapping[str, Any],
) -> tuple[dict[str, Any], dict[str, Any]]:
    """Replay the current source/candidate input content, without granting authority.

    The native caller must bind these originals and expectations through its held
    input capture, authenticate all original prerequisites, replay the complete
    gate/catalog two-output journal and applicable catalog, and retain that capture
    through return. These checks do not create verified-derived membership or
    replace any existing signer, producer, source or candidate proof requirement.
    No live caller is wired by this pure content helper.
    """
    records = {
        "gate-input": (gate, "release-gate-input"),
        "target-resolution": (target, "release-target-resolution"),
        "release-context": (context, "release-context"),
        "scenario-catalog": (catalog, "release-scenario-catalog"),
    }
    if (
        type(synthetic) is not bool
        or not isinstance(expected_record_digests, Mapping)
        or set(expected_record_digests) != set(records)
    ):
        raise ReleaseControlError("source inputs lack an exact mode or original record set")
    for name, (record, kind) in records.items():
        validate_record(record, kind)
        if (
            record["status"] != "PASS"
            or record["synthetic"] is not synthetic
            or sha256_json(record)
            != _require_digest(expected_record_digests[name], "source original " + name)
        ):
            raise ReleaseControlError("source input changes original identity, status or mode")
    if target["signatures"] != [] or catalog["signatures"] != []:
        raise ReleaseControlError("source derived target or original gate companion has signatures")
    gate_fields = set(_SOURCE_REGISTRY_INPUTS) | {
        "expected_predecessor_milestone",
        "gate_input_digest",
        "invocation_root_locator",
        "linear_snapshot_digest",
        "milestone",
        "predecessor_policy_digest",
        "producer_intent_digest",
        "release_context_digest",
        "role_assignments_digest",
        "run_id",
        "scenario_catalog_digest",
        "target_burn_digest",
        "target_burn_index_receipt_digest",
        "target_resolution_digest",
    }
    target_fields = {
        "burn_lineage_digest",
        "burn_target_ids",
        "initial_package_version",
        "initial_release_tag",
        "invocation_root_locator",
        "milestone",
        "observations_digest",
        "prior_burn_digests",
        "producer_intent_digest",
        "release_context_digest",
        "requires_new_burn",
        "resolution_digest",
        "resolution_rule",
        "selected_package_version",
        "selected_release_tag",
    }
    catalog_fields = {
        "catalog_digest",
        "expansion_contract",
        "producer_intent_digest",
        "invocation_root_locator",
        "run_id",
        "scenario_registry_digest",
        "environment_registry_digest",
        "obligation_registry_digest",
        "declarations",
        "release_slots",
        "execution_units",
        "unresolved_declarations",
    }
    gate_data = _release_data(gate, gate_fields, "source gate input")
    target_data = _release_data(target, target_fields, "source target resolution")
    catalog_data = _release_data(catalog, catalog_fields, "source companion catalog")
    if (
        not isinstance(run_id, str)
        or re.fullmatch(r"[A-Za-z0-9][A-Za-z0-9._:/-]{0,159}", run_id, re.ASCII) is None
        or gate_data["run_id"] != run_id
        or catalog_data["run_id"] != run_id
    ):
        raise ReleaseControlError("source inputs change the independently selected run")
    for data, self_field, label in (
        (gate_data, "gate_input_digest", "gate"),
        (target_data, "resolution_digest", "target"),
        (catalog_data, "catalog_digest", "catalog"),
    ):
        if data["invocation_root_locator"] != "invocations":
            raise ReleaseControlError("source " + label + " changes its journal locator")
        _require_digest(data["producer_intent_digest"], "source " + label + " original intent")
        if data[self_field] != sha256_json({k: v for k, v in data.items() if k != self_field}):
            raise ReleaseControlError("source " + label + " semantic digest differs")
    for key in gate_fields - {
        "milestone",
        "run_id",
        "expected_predecessor_milestone",
        "invocation_root_locator",
        "target_burn_index_receipt_digest",
    }:
        _require_digest(gate_data[key], "source gate " + key)
    receipt = gate_data["target_burn_index_receipt_digest"]
    if receipt is not None:
        _require_digest(receipt, "source gate original burn index receipt")
    _require_nonempty_string(
        gate_data["expected_predecessor_milestone"],
        "source original predecessor selector",
    )
    if (
        gate_data["milestone"] not in MILESTONES
        or target_data["milestone"] != gate_data["milestone"]
        or gate_data["target_resolution_digest"] != expected_record_digests["target-resolution"]
        or gate_data["scenario_catalog_digest"] != expected_record_digests["scenario-catalog"]
        or gate_data["release_context_digest"] != expected_record_digests["release-context"]
        or target_data["release_context_digest"] != expected_record_digests["release-context"]
    ):
        raise ReleaseControlError("source gate, target, catalog or context linkage differs")
    if (
        catalog["invocation_id"] != gate["invocation_id"]
        or catalog["sequence"] != gate["sequence"]
        or catalog_data["producer_intent_digest"] != gate_data["producer_intent_digest"]
        or catalog_data["expansion_contract"] != "metriplane.scenario-expansion.v1"
    ):
        raise ReleaseControlError("source catalog is not the original gate producer companion")
    for key in (
        "scenario_registry_digest",
        "environment_registry_digest",
        "obligation_registry_digest",
    ):
        if catalog_data[key] != gate_data[key]:
            raise ReleaseControlError("source catalog changes an original gate registry")
    policy_inputs = _release_closed_mapping(
        context_policy_inputs,
        {
            "readiness_registry_raw",
            "expected_readiness_digest",
            "predecessor_policy_raw",
            "expected_predecessor_policy_digest",
            "expected_context_id",
            "linear_snapshot",
        },
        "source original context policy inputs",
    )
    context_data = _release_context_policy_projection(context, **policy_inputs)
    if (
        context_data["framework_milestone"] != gate_data["milestone"]
        or context_data["linear_snapshot_digest"] != gate_data["linear_snapshot_digest"]
        or context_data["readiness_registry_digest"] != gate_data["readiness_registry_digest"]
        or context_data["predecessor_policy_digest"] != gate_data["predecessor_policy_digest"]
        or policy_inputs["linear_snapshot"]["data"].get("task_state_policy_digest")
        != gate_data["task_state_policy_digest"]
    ):
        raise ReleaseControlError("source gate changes the selected original context policy")
    policy = _release_target_policy_projection(
        context_data["target_policy"], milestone=gate_data["milestone"]
    )
    for prefix in ("initial", "selected"):
        package = target_data[prefix + "_package_version"]
        if not isinstance(package, str) or not package.startswith("v"):
            raise ReleaseControlError("source target lacks its single legacy package v prefix")
        identity = _release_version_pair(package[1:], target_data[prefix + "_release_tag"])
        if f"v{identity[0]}.{identity[1]}" != gate_data["milestone"]:
            raise ReleaseControlError("source target version is outside its milestone")
    if (
        target_data["initial_package_version"] != "v" + policy["initial_normalized_package_version"]
        or target_data["initial_release_tag"] != policy["initial_release_tag"]
        or target_data["resolution_rule"] != policy["resolution_mode"]
        or type(target_data["requires_new_burn"]) is not bool
        or (receipt is not None) is not target_data["requires_new_burn"]
    ):
        raise ReleaseControlError("source target changes selected policy or burn form")
    target_inputs = _release_closed_mapping(
        target_control_inputs,
        {
            "observations",
            "lineage",
            "expected_observations_digest",
            "expected_lineage_digest",
            "target_registry_raw",
            "expected_target_registry_digest",
            "expected_versions",
            "expected_operation_order",
        },
        "source original target control inputs",
    )
    if target_inputs["expected_target_registry_digest"] != gate_data["target_registry_digest"]:
        raise ReleaseControlError("source target changes the original gate target registry")
    replayed_target, usable = _release_target_control_data(
        "release-target-resolution",
        context=context,
        expected_context_digest=expected_record_digests["release-context"],
        producer_intent_digest=target_data["producer_intent_digest"],
        **target_inputs,
    )
    if canonical_json(target_data) != canonical_json(replayed_target):
        raise ReleaseControlError("source target differs from complete original control replay")
    if usable is not True:
        raise ReleaseControlError("source target is occupied or previously burned under its policy")
    return gate_data, target_data


def _install_release_gate_pair(
    context: ReleaseInvocation,
    outputs: list[dict[str, str]],
    *,
    original_stage_capture: _ReleaseCapturedFiles | None = None,
) -> _ReleaseCapturedFiles:
    """Install exact gate bytes as separate single-link originals, before terminal.

    The common supervisor must first finish native pair/input verification and
    worker quiescence. This installation primitive confers no such authority.
    An interrupted exclusive copy remains original failure evidence; it is never
    deleted, overwritten or completed by an installation retry.
    """
    plan = [{"path": name, "schema_id": kind} for name, kind in _RELEASE_GATE_OUTPUT_PLAN]
    if context.intent.get("tool") != "prepare_release_gate_input.py" or (
        canonical_json(context.intent.get("planned_outputs")) != canonical_json(plan)
        or len(outputs) != len(plan)
    ):
        raise ReleaseControlError("gate installation has a different exact two-output owner")
    for row, expected in zip(outputs, plan, strict=True):
        _release_closed_mapping(row, {"path", "schema_id", "sha256"}, "gate installed output")
        _require_digest(row["sha256"], "gate installed output bytes")
        if {k: row[k] for k in expected} != expected:
            raise ReleaseControlError("gate installation changes its fixed output order or type")
    root = _release_capture_absolute(context.root)
    directory = _release_capture_absolute(context.directory)
    if directory != root / "invocations/gate-input" / f"{context.intent['sequence']:03d}":
        raise ReleaseControlError("gate installation has a different original journal root")
    terminal_path = directory / "invocation.json"
    if os.path.lexists(terminal_path) or os.path.lexists(directory / "terminal-commit.json"):
        raise ReleaseControlError("gate installation cannot follow an existing terminal")
    staged_names = [
        (directory / "staged" / row["path"]).relative_to(root).as_posix() for row in outputs
    ]
    if isinstance(context, _ReleaseGateInvocation):
        original_inputs = context.gate_inputs.captured
        original_intent = context.intent_capture
        original_inputs.revalidate()
        original_intent.revalidate()
        intent_name = (directory / "intent.json").relative_to(root).as_posix()
        if (
            original_inputs.root != root
            or original_intent.root != root
            or original_intent.root_directories != original_inputs.root_directories
            or len(original_intent.rows) != 1
            or original_intent.rows[0][:2] != (intent_name, "release-invocation-intent")
        ):
            raise ReleaseControlError("gate installation lost its original input or intent capture")
        # Retain the actual original intent inode. A fresh capture must not read a
        # replacement intent and discover the mismatch only after consuming it.
        original_row = original_intent.rows[0]
        if original_stage_capture is None:
            raise ReleaseControlError("gate producer installation requires its held verified stage")
        carried = _release_gate_pair_capture_handoff(
            context, directory / "staged", original_stage_capture
        )
        held_stage = _ReleaseCapturedFiles(
            carried.root,
            carried.root_directories,
            tuple(
                (name, "prerequisite-original", raw, identity, ancestors)
                for name, _, raw, identity, ancestors in carried.rows
            ),
        )
        captured = _ReleaseCapturedFiles(
            root,
            original_inputs.root_directories,
            ((intent_name, "prerequisite-original", *original_row[2:]), *held_stage.rows),
        )
        captured.revalidate()
    elif original_stage_capture is not None:
        carried = _release_gate_pair_capture_handoff(
            context, directory / "staged", original_stage_capture
        )
        raw, identity, ancestors = _release_held_path(
            directory / "intent.json", expected_prefix=carried.root_directories
        )
        captured = _ReleaseCapturedFiles(
            root,
            carried.root_directories,
            (
                (
                    (directory / "intent.json").relative_to(root).as_posix(),
                    "prerequisite-original",
                    raw,
                    identity,
                    ancestors,
                ),
                *tuple(
                    (name, "prerequisite-original", raw, identity, ancestors)
                    for name, _, raw, identity, ancestors in carried.rows
                ),
            ),
        )
    else:
        # Standalone mechanical readback has no live producer-held authority.
        captured = _ReleaseCapturedFiles.capture(
            root,
            [
                (name, "prerequisite-original")
                for name in [
                    (directory / "intent.json").relative_to(root).as_posix(),
                    *staged_names,
                ]
            ],
            forbidden=(),
            allowed_kinds=frozenset({"prerequisite-original"}),
        )
    _release_captured_command_context(
        context, captured=captured, expected_tool="prepare_release_gate_input.py"
    )
    payloads = []
    for row, name in zip(outputs, staged_names, strict=True):
        raw = captured.read(name, kind="prerequisite-original")
        if sha256_bytes(raw) != row["sha256"]:
            raise ReleaseControlError("gate staged bytes differ from original worker outputs")
        value = _source_json(raw, "gate installation original staged output")
        validate_record(value, row["schema_id"].removeprefix("metriplane.").removesuffix(".v1"))
        if raw != canonical_json(value) or (
            value["status"] != "PASS"
            or value["signatures"] != []
            or value["synthetic"] is not (context.intent["environment"]["fixture_mode"] == "1")
            or value["invocation_id"] != context.intent["invocation_id"]
            or value["sequence"] != context.intent["sequence"]
            or value["data"].get("producer_intent_digest") != sha256_json(context.intent)
            or value["data"].get("invocation_root_locator") != "invocations"
        ):
            raise ReleaseControlError("gate staged record lacks its original producer binding")
        payloads.append(raw)
    root_fd = os.open(root, os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW)
    installed_rows: list[
        tuple[str, str, bytes, tuple[int, ...], tuple[tuple[str, int, int, int], ...]]
    ] = []
    try:
        held_root = os.fstat(root_fd)
        if (held_root.st_dev, held_root.st_ino, held_root.st_mode) != (
            captured.root_directories[-1][1:]
        ):
            raise ReleaseControlError("gate installation root changed before directory open")
        for row in outputs:
            try:
                os.stat(row["path"], dir_fd=root_fd, follow_symlinks=False)
            except FileNotFoundError:
                continue
            raise ReleaseControlError("refusing to overwrite existing canonical gate output")
        for row, name, payload in zip(outputs, staged_names, payloads, strict=True):
            captured.revalidate()
            if os.path.lexists(terminal_path) or os.path.lexists(
                directory / "terminal-commit.json"
            ):
                raise ReleaseControlError("gate installation acquired a premature terminal")
            if captured.read(name, kind="prerequisite-original") != payload:
                raise ReleaseControlError("gate staged bytes changed before exclusive copy")
            for installed_name, _, _, identity, ancestors in installed_rows:
                _release_held_path(
                    root / installed_name,
                    expected_identity=identity,
                    expected_directories=ancestors,
                )
            descriptor = os.open(
                row["path"],
                os.O_WRONLY | os.O_CREAT | os.O_EXCL | os.O_NOFOLLOW,
                0o400,
                dir_fd=root_fd,
            )
            with os.fdopen(descriptor, "wb") as stream:
                stream.write(payload)
                stream.flush()
                os.fsync(stream.fileno())
                st = os.fstat(stream.fileno())
                identity = (
                    st.st_dev,
                    st.st_ino,
                    st.st_mode,
                    st.st_nlink,
                    st.st_size,
                    st.st_mtime_ns,
                    st.st_ctime_ns,
                )
            os.fsync(root_fd)
            raw, actual, ancestors = _release_held_path(
                root / row["path"],
                expected_identity=identity,
                expected_prefix=captured.root_directories,
            )
            if raw != payload or actual != identity:
                raise ReleaseControlError("canonical gate copy failed exact original readback")
            installed_rows.append((row["path"], "prerequisite-original", raw, actual, ancestors))
        captured.revalidate()
        installed = _ReleaseCapturedFiles(root, captured.root_directories, tuple(installed_rows))
        installed.revalidate()
        if os.path.lexists(terminal_path) or os.path.lexists(directory / "terminal-commit.json"):
            raise ReleaseControlError("gate pair installation acquired a premature terminal")
    finally:
        os.close(root_fd)
    return installed


def _release_predecessor_content(
    record: Mapping[str, Any],
    gate_data: Mapping[str, Any],
    *,
    target: Mapping[str, Any],
    original_bytes: Mapping[str, bytes],
    expected_original_paths: Mapping[str, str],
    expected_record_digest: str,
    expected_invocation_id: str,
    expected_sequence: int,
    expected_producer_intent_digest: str,
    context_policy_inputs: Mapping[str, Any],
    synthetic: bool,
) -> dict[str, Any]:
    """Validate the thirty-field original selection content, never its native authority.

    The original capture/journal owner must supply these exact record, input-path,
    raw-byte and producer expectations. This helper does not read paths or infer
    a trust root. Its return cannot authorize a candidate; the connected command
    owner separately replays the retained graph and external authorities.
    """
    if not isinstance(record, Mapping) or not isinstance(gate_data, Mapping):
        raise ReleaseControlError("predecessor record or already validated gate is not an object")
    validate_record(record, "release-predecessor")
    if (
        type(synthetic) is not bool
        or record["synthetic"] is not synthetic
        or record["status"] != "PASS"
        or sha256_json(record) != _require_digest(expected_record_digest, "original predecessor C")
        or record["invocation_id"] != _require_invocation(expected_invocation_id)
        or type(expected_sequence) is not int
        or expected_sequence < 1
        or record["sequence"] != expected_sequence
    ):
        raise ReleaseControlError("predecessor original envelope or mode differs")
    link_types = {
        "qualification_digest": "release-qualification",
        "reconciliation_digest": "release-publication-reconciliation",
        "final_retention_digest": "release-retention-receipts",
        "chain_receipt_digest": "release-evidence-chain",
        "lkg_digest": "release-last-known-good",
        "pointer_transition_retention_digest": "release-retention-receipts",
        "pointer_envelope_digest": "release-evidence-manifest",
        "pointer_retention_digest": "release-retention-receipts",
        "pointer_index_receipt_digest": "release-attempt-index",
        "closed_decision_digest": "release-protected-input",
        "close_ready_observation_digest": "release-task-state-observation",
        "close_root_digest": "release-attempt-index",
    }
    fields = set(link_types) | {
        "lineage_mode",
        "candidate_milestone",
        "predecessor_milestone",
        "version",
        "package_version",
        "release_context_digest",
        "release_context",
        "predecessor_policy_digest",
        "predecessor_policy",
        "predecessor_subject",
        "predecessor_subject_digest",
        "proof_index",
        "producer_intent_digest",
        "invocation_root_locator",
        "genesis_authority_digest",
        "completion_digest",
        "selection_observations",
        "chain_head",
    }
    data = _release_data(record, fields, "complete ordinary predecessor")
    if data["invocation_root_locator"] != "invocations" or data[
        "producer_intent_digest"
    ] != _require_digest(expected_producer_intent_digest, "original predecessor intent"):
        raise ReleaseControlError("predecessor changes its original producer")
    input_fields = {"release_context", "predecessor_policy", "proof_index"}
    if (
        not isinstance(original_bytes, Mapping)
        or not isinstance(expected_original_paths, Mapping)
        or set(original_bytes) != input_fields
        or set(expected_original_paths) != input_fields
    ):
        raise ReleaseControlError("predecessor lacks the closed original input byte set")
    for name in input_fields:
        ref = _release_closed_mapping(
            data[name], {"path", "bytes", "sha256"}, "predecessor " + name
        )
        _release_relative_suffix(ref["path"], "predecessor original input path")
        _release_relative_suffix(expected_original_paths[name], "expected original input path")
        raw = original_bytes[name]
        if (
            not isinstance(raw, bytes)
            or type(ref["bytes"]) is not int
            or ref["bytes"] < 1
            or ref["path"] != expected_original_paths[name]
            or len(raw) != ref["bytes"]
            or sha256_bytes(raw) != _require_digest(ref["sha256"], "predecessor original R")
        ):
            raise ReleaseControlError("predecessor original input path, size or raw digest differs")
    if len(set(expected_original_paths.values())) != len(input_fields):
        raise ReleaseControlError(
            "predecessor aliases distinct context, policy or proof-index inputs"
        )
    context = _source_json(
        original_bytes["release_context"], "original predecessor release context"
    )
    if data["release_context_digest"] != sha256_json(context):
        raise ReleaseControlError(
            "predecessor current context C differs from its original raw bytes"
        )
    policy_raw = original_bytes["predecessor_policy"]
    policy_digest = sha256_bytes(policy_raw)
    if data["predecessor_policy_digest"] != policy_digest:
        raise ReleaseControlError("predecessor raw policy R was replaced by another projection")
    policy_inputs = _release_closed_mapping(
        context_policy_inputs,
        {
            "readiness_registry_raw",
            "expected_readiness_digest",
            "predecessor_policy_raw",
            "expected_predecessor_policy_digest",
            "expected_context_id",
            "linear_snapshot",
        },
        "predecessor original current-context inputs",
    )
    if (
        policy_inputs["predecessor_policy_raw"] != policy_raw
        or policy_inputs["expected_predecessor_policy_digest"] != policy_digest
    ):
        raise ReleaseControlError(
            "predecessor input policy differs from independently bound context"
        )
    current = _release_context_policy_projection(context, **policy_inputs)
    if context["synthetic"] is not synthetic:
        raise ReleaseControlError("predecessor current context changes original authority mode")
    policy = _release_predecessor_policy_projection(
        policy_raw,
        expected_digest=policy_digest,
        readiness_registry_raw=policy_inputs["readiness_registry_raw"],
        expected_readiness_digest=policy_inputs["expected_readiness_digest"],
        expected_context_id=policy_inputs["expected_context_id"],
    )
    subject = policy["expected_predecessor_subject"]
    if (
        data["candidate_milestone"] != current["framework_milestone"]
        or gate_data.get("milestone") != data["candidate_milestone"]
        or gate_data.get("release_context_digest") != data["release_context_digest"]
        or gate_data.get("predecessor_policy_digest") != policy_digest
        or gate_data.get("expected_predecessor_milestone")
        != (subject["framework_milestone"] or subject["release_tag"])
        or data["lineage_mode"] != policy["lineage_mode"]
        or canonical_json(data["predecessor_subject"]) != canonical_json(subject)
        or data["predecessor_subject_digest"] != sha256_json(subject)
        or data["predecessor_milestone"] != subject["framework_milestone"]
        or data["package_version"] != subject["normalized_package_version"]
        or data["version"] != subject["release_tag"]
    ):
        raise ReleaseControlError(
            "predecessor changes selected context, subject, lineage or gate binding"
        )
    previous = _release_version_pair(data["package_version"], data["version"], historical=True)
    target_policy = _release_target_policy_projection(
        current["target_policy"], milestone=data["candidate_milestone"]
    )
    initial = _release_version_pair(
        target_policy["initial_normalized_package_version"],
        target_policy["initial_release_tag"],
    )
    validate_record(target, "release-target-resolution")
    selected = target["data"]
    package = selected.get("selected_package_version")
    if (
        target["status"] != "PASS"
        or target["synthetic"] is not synthetic
        or sha256_json(target) != gate_data.get("target_resolution_digest")
        or selected.get("release_context_digest") != data["release_context_digest"]
        or selected.get("milestone") != data["candidate_milestone"]
        or selected.get("resolution_rule") != target_policy["resolution_mode"]
        or not isinstance(package, str)
        or not package.startswith("v")
    ):
        raise ReleaseControlError(
            "predecessor target differs from the original selected gate target"
        )
    resolved = _release_version_pair(package[1:], selected.get("selected_release_tag"))
    if (
        f"v{resolved[0]}.{resolved[1]}" != data["candidate_milestone"]
        or resolved < initial
        or (
            target_policy["resolution_mode"] == "owner_approved_exact_target"
            and resolved != initial
        )
        or previous >= resolved
    ):
        raise ReleaseControlError("predecessor is not older than the selected current target")
    if (
        data["candidate_milestone"] not in MILESTONES[:-1]
        or data["predecessor_milestone"] in {"v0.9", "v1.0"}
        or policy["proof_requirements"]["indexed_release_completion"] is not False
        or data["completion_digest"] is not None
    ):
        raise ReleaseControlError("MP2_207_COMPLETION_OR_ADOPTION_UNIMPLEMENTED")
    index = _release_closed_mapping(
        _source_json(original_bytes["proof_index"], "original predecessor proof index"),
        {"schema_version", "records", "raw_proofs", "git_objects", "artifacts"},
        "predecessor original proof index",
    )
    if index["schema_version"] != "metriplane.release-predecessor-proof-index.v1":
        raise ReleaseControlError("predecessor original proof index type differs")
    allowed_record_types = frozenset(
        [
            "release-context",
            "linear-release-snapshot",
            "release-candidate-identity",
            "release-artifact-manifest",
            "release-source-freeze",
            "release-gate-input",
            "release-gate-instance",
            "release-role-assignments",
            "release-task-state-policy",
            "release-task-state-observation",
            "release-protected-input",
            "release-qualification-plan",
            "release-qualification",
            "release-attempt",
            "release-cell-result",
            "release-attempt-coordination",
            "release-run-status-snapshot",
            "release-warning-summary",
            "release-approval",
            "release-approval-decision",
            "release-promotion-lock",
            "release-promotion-plan",
            "release-promotion",
            "release-publication-observations",
            "release-publication-reconciliation",
            "release-retention-receipts",
            "release-evidence-manifest",
            "release-evidence-chain",
            "release-last-known-good",
            "release-attempt-index",
            "release-index-recovery",
            "release-postpublication-conflict",
            "release-evidence-store",
            "release-evidence-store-preflight",
            "release-completion",
            "release-predecessor",
        ]
    )
    allowed_raw_kinds = frozenset(
        [
            "original_genesis_authority",
            "original_provider_event",
            "original_provider_state_readback",
            "original_provider_execution_capture",
            "original_backend_entry",
            "original_backend_state_readback",
            "original_backend_operation_response",
            "original_retained_payload",
            "original_stage_intent",
            "original_stage_terminal",
            "original_stage_diagnostic",
            "original_role_key_policy",
        ]
    )
    for group, minimum in (("raw_proofs", 1), ("git_objects", 1), ("artifacts", 2)):
        rows = index[group]
        if (
            not isinstance(rows, list)
            or len(rows) < minimum
            or (group == "artifacts" and len(rows) != 2)
        ):
            raise ReleaseControlError("predecessor proof index lacks its exact typed " + group)
        seen: set[str] = set()
        for value in rows:
            keys = {"kind", "original_file"} | (
                {"purpose"}
                if group == "raw_proofs"
                else {"object_type", "git_object_id"}
                if group == "git_objects"
                else {"artifact_kind", "filename"}
            )
            row = _release_closed_mapping(value, keys, "predecessor typed " + group)
            ref = _release_closed_mapping(
                row["original_file"],
                {"path", "bytes", "sha256"},
                "predecessor typed original",
            )
            _release_relative_suffix(ref["path"], "predecessor typed original path")
            _require_digest(ref["sha256"], "predecessor typed original R")
            diagnostic = group == "raw_proofs" and row["kind"] == "original_stage_diagnostic"
            if type(ref["bytes"]) is not int or ref["bytes"] < (0 if diagnostic else 1):
                raise ReleaseControlError("predecessor typed original byte count is invalid")
            if group == "raw_proofs":
                if not isinstance(row["kind"], str) or row["kind"] not in allowed_raw_kinds:
                    raise ReleaseControlError("predecessor original raw proof kind is unknown")
                _require_nonempty_string(row["purpose"], "predecessor original proof purpose")
                identity = sha256_json(row)
            elif group == "git_objects":
                if row["kind"] != "original_git_object" or row["object_type"] not in (
                    "commit",
                    "tree",
                    "tag",
                    "blob",
                ):
                    raise ReleaseControlError("predecessor Git proof has another object type")
                identity = _release_git_oid(row["git_object_id"], "predecessor original Git object")
            else:
                if row["kind"] != "original_distribution_payload" or row["artifact_kind"] not in (
                    "wheel",
                    "sdist",
                ):
                    raise ReleaseControlError("predecessor distribution proof kind differs")
                _require_nonempty_string(row["filename"], "predecessor original distribution name")
                identity = row["artifact_kind"]
            if identity in seen:
                raise ReleaseControlError("predecessor typed original index repeats an identity")
            seen.add(identity)
    artifact_rows = {row["artifact_kind"]: row for row in index["artifacts"]}
    for artifact in subject["artifacts"]:
        row = artifact_rows[artifact["kind"]]
        if (
            row["filename"] != artifact["filename"]
            or row["original_file"]["sha256"] != artifact["sha256"]
            or row["original_file"]["bytes"] != artifact["bytes"]
        ):
            raise ReleaseControlError(
                "predecessor proof-index artifact differs from selected subject"
            )
    git_roots = {(row["object_type"], row["git_object_id"]) for row in index["git_objects"]}
    if not all(
        (kind, subject[field]) in git_roots
        for kind, field in (
            ("commit", "source_commit"),
            ("tree", "source_tree"),
            ("tag", "tag_object"),
        )
    ):
        raise ReleaseControlError("predecessor proof index omits selected original Git roots")
    # Only the typed root locator layer is checked here. Reachability, actual
    # original node bytes and every native owner remain required before use.
    records = index["records"]
    if not isinstance(records, list):
        raise ReleaseControlError("predecessor original record roots are missing")
    record_keys: set[tuple[str, str]] = set()
    original_paths: set[str] = set()
    for value in records:
        row = _release_closed_mapping(
            value,
            {"kind", "record_type", "record_digest", "original_file"},
            "predecessor original record locator",
        )
        if (
            row["kind"] != "original_release_record"
            or not isinstance(row["record_type"], str)
            or row["record_type"] not in allowed_record_types
        ):
            raise ReleaseControlError("predecessor original record locator type differs")
        key = (
            row["record_type"],
            _require_digest(row["record_digest"], "predecessor original record C"),
        )
        ref = _release_closed_mapping(
            row["original_file"],
            {"path", "bytes", "sha256"},
            "predecessor original record file",
        )
        path = _release_relative_suffix(
            ref["path"], "predecessor proof-index record path"
        ).as_posix()
        if (
            key in record_keys
            or path in original_paths
            or type(ref["bytes"]) is not int
            or ref["bytes"] < 1
        ):
            raise ReleaseControlError("predecessor original record locator aliases or lacks bytes")
        _require_digest(ref["sha256"], "predecessor original record file R")
        record_keys.add(key)
        original_paths.add(path)
    if data["lineage_mode"] == "ORIGINAL_BOOTSTRAP":
        if (
            data["candidate_milestone"] != "v0.4"
            or data["predecessor_milestone"] is not None
            or data["package_version"] != "0.3.0"
            or data["version"] != "v0.3.0"
            or data["selection_observations"] is not None
            or any(data[name] is not None for name in (*link_types, "chain_head"))
        ):
            raise ReleaseControlError("original bootstrap invents inapplicable release history")
        _require_digest(data["genesis_authority_digest"], "original bootstrap authority identity")
    else:
        if (
            data["predecessor_milestone"] not in MILESTONES[:-2]
            or data["genesis_authority_digest"] is not None
        ):
            raise ReleaseControlError("ordinary LKG predecessor selects an invalid profile")
        for field, kind in link_types.items():
            digest = _require_digest(data[field], "predecessor original " + field)
            if (kind, digest) not in record_keys:
                raise ReleaseControlError(
                    "predecessor proof index omits an exact original root: " + field
                )
        _require_digest(data["chain_head"], "original backend chain head")
        selection = _release_closed_mapping(
            data["selection_observations"],
            {
                "observed_at",
                "provider_state",
                "provider_event_history",
                "success_chain_readback",
                "lkg_state_and_history_readback",
                "attempt_index_readback",
            },
            "predecessor current selection observations",
        )
        clock = selection["observed_at"]
        if (
            not isinstance(clock, str)
            or re.fullmatch(
                r"[0-9]{4}-[0-9]{2}-[0-9]{2}[Tt][0-9]{2}:[0-9]{2}:[0-9]{2}(?:\.[0-9]+)?(?:[Zz]|[+-](?:[01][0-9]|2[0-3]):[0-5][0-9])",
                clock,
                re.ASCII,
            )
            is None
        ):
            raise ReleaseControlError("predecessor selection clock is not RFC3339")
        try:
            datetime.fromisoformat(clock.replace("t", "T").replace("z", "Z"))
        except ValueError as exc:
            raise ReleaseControlError("predecessor selection clock is invalid") from exc
        for name in set(selection) - {"observed_at"}:
            ref = _release_closed_mapping(
                selection[name],
                {"path", "bytes", "sha256"},
                "predecessor selection " + name,
            )
            _release_relative_suffix(ref["path"], "predecessor current observation path")
            if type(ref["bytes"]) is not int or ref["bytes"] < 1:
                raise ReleaseControlError("predecessor current observation lacks original bytes")
            _require_digest(ref["sha256"], "predecessor current observation R")
    return data


_RELEASE_GATE_SOURCE_FIELDS: Final[Mapping[str, str]] = {
    "readiness-registry": "readiness_registry_digest",
    "obligations": "obligation_registry_digest",
    "scenarios": "scenario_registry_digest",
    "environments": "environment_registry_digest",
    "targets": "target_registry_digest",
    "evidence-stores": "evidence_store_registry_digest",
    "task-state-policy": "task_state_policy_digest",
}


def _release_gate_bound_inputs(
    context: ReleaseInvocation,
    *,
    outputs: list[dict[str, str]] | None,
    output_root: Path | None,
) -> None:
    if isinstance(context, _ReleaseGateInvocation):
        held = context.gate_inputs
        if (
            held.directory != context.directory
            or held.captured.root != context.root
            or list(held.argv) != context.intent["argv"][1:]
            or str(held.working_directory) != context.intent["environment"]["working_directory"]
        ):
            raise ReleaseControlError("gate invocation differs from its producer-held identity")
        expected = _release_gate_source_revalidate(held)
        original_capture = held.captured
    else:
        # An ordinary worker/historical context only replays its original byte plan.
        # It neither establishes Git authority nor qualifies a native gate output.
        args = _release_original_arguments(context.intent["tool"], context.intent["argv"])
        cwd = _canonical_absolute_path(
            context.intent["environment"]["working_directory"], "original gate cwd"
        )
        expected = {}
        for flag, kind in _RELEASE_GATE_REGISTRY_INPUTS.items():
            path = str(_release_historical_path(args[flag], cwd))
            matches = [row for row in context.intent["inputs"] if row["path"] == path]
            if len(matches) != 1 or matches[0]["schema_id"] not in {
                "metriplane." + kind + ".v1",
                "metriplane.prerequisite-original.v1",
            }:
                raise ReleaseControlError(
                    "original gate registry input is missing or has a different type"
                )
            expected[flag] = _require_digest(matches[0]["sha256"], "original gate registry bytes")
        original_capture = None
    replay = _release_gate_input_plan_replay(
        context, expected_registry_digests=expected, original_capture=original_capture
    )
    if original_capture is not None and replay["captured"] is not original_capture:
        raise ReleaseControlError("gate bound replay discarded its original held capture")
    if outputs is not None:
        current = context.root if output_root is None else _release_capture_absolute(output_root)
        if current not in {context.root, context.directory / "staged"}:
            raise ReleaseControlError("gate output read has a different current output root")
        held_outputs = _release_gate_output_capture(context, current, input_plan=replay)
        required = [
            {
                "path": name,
                "schema_id": kind,
                "sha256": sha256_bytes(
                    held_outputs.read(
                        (current / name).relative_to(context.root).as_posix(), kind=kind
                    )
                ),
            }
            for name, kind in _RELEASE_GATE_OUTPUT_PLAN
        ]
        if outputs != required:
            raise ReleaseControlError("gate outputs differ from its exact original plan or bytes")
        held_outputs.revalidate()
    replay["captured"].revalidate()
    if isinstance(context, _ReleaseGateInvocation):
        _release_gate_source_revalidate(context.gate_inputs)


def _release_gate_capture_argv(argv: Sequence[str], cwd: Path) -> list[str]:
    """Normalize only the separate capture view; the invocation retains original argv."""
    tool = "prepare_release_gate_input.py"
    arguments = _release_original_arguments(tool, [tool, *argv])
    path_flags = {
        *_RELEASE_GATE_REGISTRY_INPUTS,
        *_RELEASE_GATE_DIRECT_RECORDS,
        "release-context",
        "predecessor-policy",
        "prerequisite-proofs",
        "provider-attestation-keyring",
        "invocation-dir",
        "out",
    }
    capture_argv = [tool]
    for flag, value in sorted(arguments.items()):
        capture_argv.append("--" + flag)
        if flag not in TOOL_CONTRACTS[tool].boolean:
            capture_argv.append(
                str(_release_historical_path(value, cwd)) if flag in path_flags else str(value)
            )
    return capture_argv


def _release_gate_output_capture(
    context: ReleaseInvocation,
    output_root: Path,
    *,
    input_plan: Mapping[str, Any],
    original_outputs: _ReleaseCapturedFiles | None = None,
) -> _ReleaseCapturedFiles:
    """Carry exact observed output objects; this is not native or full-namespace proof."""
    captured = input_plan.get("captured")
    if (
        context.intent["tool"] != "prepare_release_gate_input.py"
        or not isinstance(captured, _ReleaseCapturedFiles)
        or captured.root != context.root
        or input_plan.get("intent") != context.intent
    ):
        raise ReleaseControlError("gate output capture has a different original input plan")
    if isinstance(context, _ReleaseGateInvocation) and captured is not context.gate_inputs.captured:
        raise ReleaseControlError("gate output capture discarded its producer-held inputs")
    current = _release_capture_absolute(output_root)
    if current not in {context.root, context.directory / "staged"}:
        raise ReleaseControlError("gate output capture has a different current output root")
    ancestors = input_plan.get("intent_ancestors")
    identity = input_plan.get("intent_identity")
    if not isinstance(ancestors, tuple) or not isinstance(identity, tuple):
        raise ReleaseControlError("gate output capture is missing original intent observations")
    captured.revalidate()
    raw, _, _ = _release_held_path(
        context.directory / "intent.json",
        expected_directories=ancestors,
        expected_prefix=captured.root_directories,
        expected_identity=identity,
    )
    if raw != canonical_json(context.intent):
        raise ReleaseControlError("gate output capture original intent changed")
    if original_outputs is not None:
        return _release_gate_pair_capture_handoff(context, current, original_outputs)
    if isinstance(context, _ReleaseGateInvocation) and current == context.directory / "staged":
        raise ReleaseControlError("gate producer staged replay requires its held worker handoff")
    return _ReleaseCapturedFiles.capture(
        context.root,
        [
            ((current / name).relative_to(context.root).as_posix(), kind)
            for name, kind in _RELEASE_GATE_OUTPUT_PLAN
        ],
        forbidden=[],
        allowed_kinds=frozenset(kind for _, kind in _RELEASE_GATE_OUTPUT_PLAN),
        expected_root_directories=captured.root_directories,
        expected_known_directories=ancestors,
    )


def _release_gate_prepare_inputs(argv: Sequence[str], directory: Path) -> _ReleaseGateInputs:
    cwd = _release_capture_absolute(Path.cwd())
    directory = _release_capture_absolute(directory)
    root = directory.parents[2]
    repository = _source_repository(cwd)
    source_sha = _source_git(repository, "rev-parse", "HEAD").decode().strip()
    source_tree = _source_state(repository, source_sha)
    source_capture = _ReleaseCapturedFiles.capture(
        repository,
        [(name, "source-registry") for name in _SOURCE_REGISTRY_INPUTS.values()],
        forbidden=[],
        allowed_kinds=frozenset({"source-registry"}),
    )
    # The temporary carrier has no gate bytes yet and is never reserved or returned.
    empty_capture = _ReleaseCapturedFiles.capture(
        root, [], forbidden=[], allowed_kinds=frozenset({"gate-pending"})
    )
    provisional = _ReleaseGateInputs(
        empty_capture,
        source_capture,
        repository,
        source_sha,
        source_tree,
        (),
        cwd,
        tuple(argv),
        directory,
    )
    expected = _release_gate_source_revalidate(provisional)
    capture_argv = _release_gate_capture_argv(argv, cwd)
    capture_args = _release_original_arguments("prepare_release_gate_input.py", capture_argv)
    if Path(capture_args["invocation-dir"]) != directory:
        raise ReleaseControlError("gate argv and requested reservation directory differ")
    plan = _release_gate_declared_input_capture(
        root,
        capture_argv,
        expected_registry_digests=expected,
        original_root_directories=empty_capture.root_directories,
    )
    held = _ReleaseGateInputs(
        plan["captured"],
        source_capture,
        repository,
        source_sha,
        source_tree,
        tuple(sorted(expected.items())),
        cwd,
        tuple(argv),
        directory,
    )
    _release_gate_source_revalidate(held)
    held.captured.revalidate()
    return held


def _release_gate_reservation_check(
    held: _ReleaseGateInputs,
    tool: str,
    argv: Sequence[str],
    directory: Path,
    input_paths: Sequence[tuple[Path, str]],
    outputs: Sequence[Mapping[str, str]],
) -> None:
    if (
        tool != "prepare_release_gate_input.py"
        or held.argv != tuple(argv)
        or held.working_directory != Path.cwd()
        or held.directory != directory
        or held.captured.root != directory.parents[2]
    ):
        raise ReleaseControlError("gate reservation differs from the actual original capture")
    expected = _release_gate_source_revalidate(held)
    capture_argv = _release_gate_capture_argv(argv, held.working_directory)
    capture_args = _release_original_arguments(tool, capture_argv)
    if Path(capture_args["invocation-dir"]) != directory:
        raise ReleaseControlError("gate original argv names a different reservation directory")
    plan = _release_gate_declared_input_capture(
        held.captured.root,
        capture_argv,
        expected_registry_digests=expected,
        original_capture=held.captured,
    )
    if plan["captured"] is not held.captured:
        raise ReleaseControlError("gate reservation discarded its original held capture")
    required = sorted(
        (str(held.captured.root / name), "metriplane." + kind + ".v1")
        for name, kind, _, _, _ in held.captured.rows
    )
    actual = sorted((str(path.absolute()), kind) for path, kind in input_paths)
    if actual != required:
        raise ReleaseControlError("gate reservation does not capture its exact typed input closure")
    if list(outputs) != [
        {"path": name, "schema_id": kind} for name, kind in _RELEASE_GATE_OUTPUT_PLAN
    ]:
        raise ReleaseControlError("gate reservation does not plan its exact two outputs")
    _release_gate_source_revalidate(held)
    held.captured.revalidate()


def _release_gate_source_revalidate(held: _ReleaseGateInputs) -> dict[str, str]:
    """Bind this running producer's clean checkout, never a relocated historical checkout."""
    expected_names = set(_SOURCE_REGISTRY_INPUTS.values())
    source_capture = held.source_capture
    if (
        source_capture.root != held.repository
        or {(name, kind) for name, kind, _, _, _ in source_capture.rows}
        != {(name, "source-registry") for name in expected_names}
        or len(source_capture.rows) != len(expected_names)
    ):
        raise ReleaseControlError("gate source capture differs from the seven original owners")
    source_capture.revalidate()
    if _source_state(held.repository, held.source_sha) != held.source_tree:
        raise ReleaseControlError("gate source tree differs from its pre-reservation identity")
    if _source_git(held.repository, "status", "--porcelain=v1", "--untracked-files=all"):
        raise ReleaseControlError("gate source checkout is not clean")
    result = {}
    for flag, field in _RELEASE_GATE_SOURCE_FIELDS.items():
        name = _SOURCE_REGISTRY_INPUTS[field]
        # Same exact regular Git-blob contract as _source_blob; current bytes are
        # read through the already held source file, not a newly opened path.
        entry = _source_git(held.repository, "ls-tree", "-z", held.source_sha, "--", name)
        try:
            identity, actual = entry.rstrip(b"\0").split(b"\t")
            mode, kind, object_id = identity.split(b" ")
        except ValueError as exc:
            raise ReleaseControlError("gate registry is not one original tracked blob") from exc
        if mode not in {b"100644", b"100755"} or kind != b"blob" or actual.decode() != name:
            raise ReleaseControlError("gate registry is not an original regular Git blob")
        original = _source_git(held.repository, "cat-file", "blob", object_id.decode())
        if source_capture.read(name, kind="source-registry") != original:
            raise ReleaseControlError("gate source registry differs from the original Git blob")
        result[flag] = sha256_bytes(original)
    source_capture.revalidate()
    if _source_state(held.repository, held.source_sha) != held.source_tree:
        raise ReleaseControlError("gate source identity changed during original registry read")
    if _source_git(held.repository, "status", "--porcelain=v1", "--untracked-files=all"):
        raise ReleaseControlError("gate source checkout changed during original registry read")
    if held.registry_digests and tuple(sorted(result.items())) != held.registry_digests:
        raise ReleaseControlError("gate source expectations changed after reservation")
    return result


def _release_gate_staged_pair_replay(
    context: ReleaseInvocation,
    *,
    input_plan: Mapping[str, Any],
    original_outputs: _ReleaseCapturedFiles | None = None,
    expected_gate_data: Mapping[str, Any],
    expected_catalog_record: Mapping[str, Any],
) -> dict[str, Any]:
    """Check this pending pair's exact bytes and stage, never native input authority.

    The worker and supervisor independently reconstruct the expected pair from
    the complete original native graph before calling this owner. Public readers
    use the completed original terminal path instead. The returned held output
    capture must survive the supervisor's installation boundary.
    """
    if context.intent["sequence"] != 1:
        raise ReleaseControlError("gate producer retry requires a new captured run")
    terminal = context.directory / "invocation.json"
    if os.path.lexists(terminal) or os.path.lexists(context.directory / "terminal-commit.json"):
        raise ReleaseControlError("pending gate pair already has an original terminal")
    staged = context.directory / "staged"
    captured = _release_gate_output_capture(
        context, staged, input_plan=input_plan, original_outputs=original_outputs
    )
    records = {}
    refs = []
    for name, kind in _RELEASE_GATE_OUTPUT_PLAN:
        raw = captured.read((staged / name).relative_to(context.root).as_posix(), kind=kind)
        record = _source_json(raw, "pending gate pair original output")
        validate_record(record, kind.removeprefix("metriplane.").removesuffix(".v1"))
        if raw != canonical_json(record) or (
            record["status"] != "PASS"
            or record["signatures"] != []
            or record["synthetic"] is not (context.intent["environment"]["fixture_mode"] == "1")
            or record["invocation_id"] != context.intent["invocation_id"]
            or record["sequence"] != context.intent["sequence"]
            or record["data"].get("producer_intent_digest") != sha256_json(context.intent)
            or record["data"].get("invocation_root_locator") != "invocations"
        ):
            raise ReleaseControlError("pending gate pair changes its original producer or mode")
        records[name] = record
        refs.append({"path": name, "schema_id": kind, "sha256": sha256_bytes(raw)})
    gate, catalog = records["gate-input.json"], records["scenario-catalog.json"]
    if (
        canonical_json(gate["data"]) != canonical_json(expected_gate_data)
        or canonical_json(catalog) != canonical_json(expected_catalog_record)
        or gate["data"].get("scenario_catalog_digest") != sha256_json(catalog)
        or gate["data"].get("gate_input_digest")
        != sha256_json({k: v for k, v in gate["data"].items() if k != "gate_input_digest"})
        or gate["data"].get("run_id") != catalog["data"].get("run_id")
    ):
        raise ReleaseControlError("pending gate pair differs from independently replayed content")
    # A gate stage owns exactly these two flat regular files. Enumerate a held
    # directory descriptor; never follow a replacement path during the inventory.
    ancestors = captured.rows[0][4]
    if any(row[4] != ancestors for row in captured.rows) or ancestors[-1][0] != str(staged):
        raise ReleaseControlError("pending gate outputs do not share their exact staged directory")
    descriptor = os.open(staged, os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW)
    try:
        before = os.fstat(descriptor)
        if (str(staged), before.st_dev, before.st_ino, before.st_mode) != ancestors[-1]:
            raise ReleaseControlError("pending gate stage changed before inventory")
        names = {name for name, _ in _RELEASE_GATE_OUTPUT_PLAN}
        if set(os.listdir(descriptor)) != names:
            raise ReleaseControlError("pending gate stage has missing or unplanned members")
        for name, _ in _RELEASE_GATE_OUTPUT_PLAN:
            member = os.stat(name, dir_fd=descriptor, follow_symlinks=False)
            row = next(row for row in captured.rows if Path(row[0]).name == name)
            identity = (
                member.st_dev,
                member.st_ino,
                member.st_mode,
                member.st_nlink,
                member.st_size,
                member.st_mtime_ns,
                member.st_ctime_ns,
            )
            if identity != row[3]:
                raise ReleaseControlError("pending gate output changed during staged inventory")
        captured.revalidate()
        after = os.fstat(descriptor)
        if set(os.listdir(descriptor)) != names or (
            before.st_dev,
            before.st_ino,
            before.st_mode,
            before.st_mtime_ns,
            before.st_ctime_ns,
        ) != (after.st_dev, after.st_ino, after.st_mode, after.st_mtime_ns, after.st_ctime_ns):
            raise ReleaseControlError("pending gate stage changed during inventory")
    finally:
        os.close(descriptor)
    captured.revalidate()
    input_plan["captured"].revalidate()
    if os.path.lexists(terminal) or os.path.lexists(context.directory / "terminal-commit.json"):
        raise ReleaseControlError("pending gate pair acquired a premature terminal")
    return {"captured": captured, "gate_record": gate, "catalog_record": catalog, "outputs": refs}


def _release_gate_open_pinned_directory(
    path: Path, expected_ancestors: tuple[tuple[str, int, int, int], ...]
) -> int:
    """Return one owned directory fd; never replace known ancestor identities."""
    path = _release_capture_absolute(path)
    components = [Path(path.anchor)]
    for part in path.parts[1:]:
        components.append(components[-1] / part)
    if (
        not isinstance(expected_ancestors, tuple)
        or len(expected_ancestors) != len(components)
        or any(
            not isinstance(row, tuple)
            or len(row) != 4
            or row[0] != str(component)
            or any(type(value) is not int for value in row[1:])
            for row, component in zip(expected_ancestors, components, strict=True)
        )
    ):
        raise ReleaseControlError("gate directory needs its exact complete ancestor pins")
    owned: list[int] = []
    links: list[tuple[int, str, int]] = []
    result: int | None = None
    try:
        descriptor = os.open(path.anchor, os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW)
        owned.append(descriptor)
        for index, component in enumerate(components):
            if index:
                parent = descriptor
                descriptor = os.open(
                    component.name, os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW, dir_fd=parent
                )
                owned.append(descriptor)
                links.append((parent, component.name, descriptor))
            current = os.fstat(descriptor)
            if (
                str(component),
                current.st_dev,
                current.st_ino,
                current.st_mode,
            ) != expected_ancestors[index]:
                raise ReleaseControlError("gate directory changed before descriptor access")
        for parent, name, child in reversed(links):
            held = os.fstat(child)
            current = os.stat(name, dir_fd=parent, follow_symlinks=False)
            if (held.st_dev, held.st_ino, held.st_mode) != (
                current.st_dev,
                current.st_ino,
                current.st_mode,
            ):
                raise ReleaseControlError("gate directory link changed during descriptor access")
        result = owned.pop()
    except OSError as exc:
        raise ReleaseControlError("gate pinned directory cannot be opened safely") from exc
    finally:
        failures: list[OSError] = []
        for descriptor in reversed(owned):
            try:
                os.close(descriptor)
            except OSError as exc:
                failures.append(exc)
        if failures:
            if result is not None:
                try:
                    os.close(result)
                except OSError as exc:
                    failures.append(exc)
            raise ReleaseControlError("gate directory descriptor cleanup failed") from failures[0]
    assert result is not None
    return result


def _release_gate_file_identity(info: os.stat_result) -> tuple[int, ...]:
    return (
        info.st_dev,
        info.st_ino,
        info.st_mode,
        info.st_nlink,
        info.st_size,
        info.st_mtime_ns,
        info.st_ctime_ns,
    )


def _release_gate_write_json_at(directory_fd: int, name: str, value: object) -> tuple[int, ...]:
    """Exclusive durable original bytes; return the identity of the actual written fd."""
    if (
        not isinstance(name, str)
        or not name
        or name in {".", ".."}
        or any(ord(character) < 32 for character in name)
        or "/" in name
        or "\\" in name
    ):
        raise ReleaseControlError("gate journal output needs one safe basename")
    if type(directory_fd) is not int or directory_fd < 0:
        raise ReleaseControlError("gate journal output has an invalid directory descriptor")
    raw = canonical_json(value)
    descriptor: int | None = None
    try:
        if not stat.S_ISDIR(os.fstat(directory_fd).st_mode):
            raise ReleaseControlError("gate journal output has no held directory")
        descriptor = os.open(
            name,
            os.O_WRONLY | os.O_CREAT | os.O_EXCL | os.O_NOFOLLOW,
            0o400,
            dir_fd=directory_fd,
        )
        offset = 0
        while offset < len(raw):
            count = os.write(descriptor, raw[offset:])
            if count <= 0:
                raise ReleaseControlError("gate journal write made no progress")
            offset += count
        os.fsync(descriptor)
        written = os.fstat(descriptor)
        identity = _release_gate_file_identity(written)
        if (
            not stat.S_ISREG(written.st_mode)
            or written.st_nlink != 1
            or written.st_size != len(raw)
        ):
            raise ReleaseControlError("gate journal output lost its original file identity")
        os.fsync(directory_fd)
        if (
            _release_gate_file_identity(os.fstat(descriptor)) != identity
            or _release_gate_file_identity(
                os.stat(name, dir_fd=directory_fd, follow_symlinks=False)
            )
            != identity
        ):
            raise ReleaseControlError("gate journal output changed during durable creation")
        return identity
    except OSError as exc:
        raise ReleaseControlError("gate journal output cannot be created durably") from exc
    finally:
        if descriptor is not None:
            try:
                os.close(descriptor)
            except OSError as exc:
                raise ReleaseControlError("gate journal output descriptor cleanup failed") from exc


def _release_gate_stage_inventory(
    stage: Path,
    stage_fd: int,
    ancestors: tuple[tuple[str, int, int, int], ...],
    *,
    expected: Mapping[str, Any] | None = None,
    excluded_sequence: str | None = None,
) -> dict[str, Any]:
    """Observe metadata only through held directories; never follow an unsafe member."""
    directories: dict[str, tuple[str, int, int, int]] = {row[0]: row for row in ancestors}
    entries: dict[str, tuple[int, ...]] = {}
    children: dict[str, tuple[str, ...]] = {}
    descriptors: list[int] = []
    links: list[tuple[int, str, int]] = []

    def visit(path: Path, descriptor: int) -> None:
        info = os.fstat(descriptor)
        identity = (str(path), info.st_dev, info.st_ino, info.st_mode)
        old = directories.get(str(path))
        if old is not None and identity != old:
            raise ReleaseControlError("gate prior directory differs from its held ancestor")
        if expected is not None and expected["directories"].get(str(path)) != identity:
            raise ReleaseControlError("gate prior directory changed before census")
        directories[str(path)] = identity
        names = tuple(sorted(os.listdir(descriptor)))
        visible_names = tuple(name for name in names if path != stage or name != excluded_sequence)
        if expected is not None and expected["children"].get(str(path)) != visible_names:
            raise ReleaseControlError("gate prior namespace changed before member access")
        children[str(path)] = visible_names
        for name in visible_names:
            _release_relative_suffix(name, "gate prior member basename")
            member = path / name
            observed = os.stat(name, dir_fd=descriptor, follow_symlinks=False)
            observed_identity = _release_gate_file_identity(observed)
            if expected is not None and expected["entries"].get(str(member)) != observed_identity:
                # Directory timestamps legitimately change only at the stage itself,
                # whose identity is separately bound without mutable size/timestamps.
                if (
                    not stat.S_ISDIR(observed.st_mode)
                    or expected["entries"].get(str(member), ())[:3] != observed_identity[:3]
                ):
                    raise ReleaseControlError("gate prior member changed before access")
            entries[str(member)] = observed_identity
            if stat.S_ISDIR(observed.st_mode):
                child = os.open(
                    name, os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW, dir_fd=descriptor
                )
                descriptors.append(child)
                links.append((descriptor, name, child))
                held_info = os.fstat(child)
                if (held_info.st_dev, held_info.st_ino, held_info.st_mode) != observed_identity[:3]:
                    raise ReleaseControlError("gate prior directory changed while opening")
                visit(member, child)
        if tuple(sorted(os.listdir(descriptor))) != names:
            raise ReleaseControlError("gate prior namespace changed during census")

    try:
        visit(stage, stage_fd)
        for parent, name, child in reversed(links):
            actual = os.stat(name, dir_fd=parent, follow_symlinks=False)
            held_info = os.fstat(child)
            if (actual.st_dev, actual.st_ino, actual.st_mode) != (
                held_info.st_dev,
                held_info.st_ino,
                held_info.st_mode,
            ):
                raise ReleaseControlError("gate prior directory link changed during census")
        return {"directories": directories, "entries": entries, "children": children}
    except OSError as exc:
        raise ReleaseControlError("gate prior namespace cannot be inspected safely") from exc
    finally:
        failures: list[OSError] = []
        for descriptor in reversed(descriptors):
            try:
                os.close(descriptor)
            except OSError as exc:
                failures.append(exc)
        if failures:
            raise ReleaseControlError("gate prior census descriptor cleanup failed") from failures[
                0
            ]


def _release_gate_prior_partial_projection(
    context: ReleaseInvocation, inventory: Mapping[str, Any], captured: _ReleaseCapturedFiles
) -> dict[str, Any]:
    """The existing partial inventory shape, projected only from held original metadata/bytes."""
    roots = []
    files = []
    unreadable = []
    safe = {str(captured.root / row[0]): row for row in captured.rows}
    for component in ("staged", "workspace"):
        directory = context.directory / component
        root_name = directory.relative_to(context.root).as_posix()
        identity = inventory["entries"].get(str(directory))
        if identity is None:
            roots.append({"path": root_name, "kind": "absent"})
            continue
        if not stat.S_ISDIR(identity[2]):
            roots.append({"path": root_name, "kind": "unsafe"})
            unreadable.append(root_name)
            continue
        roots.append({"path": root_name, "kind": "directory"})
        for filename, observed in sorted(
            inventory["entries"].items(), key=lambda row: Path(row[0])
        ):
            path = Path(filename)
            if path == directory or not path.is_relative_to(directory) or stat.S_ISDIR(observed[2]):
                continue
            suffix = path.relative_to(context.root).as_posix()
            if filename not in safe:
                unreadable.append(suffix)
            else:
                raw = captured.read(suffix, kind="prerequisite-original")
                files.append({"path": suffix, "sha256": sha256_bytes(raw), "size": len(raw)})
    return {
        "schema_version": "metriplane.release-partial-files.v1",
        "roots": roots,
        "files": files,
        "unreadable": unreadable,
    }


def _release_gate_prior_journals(
    held: _ReleaseGateInputs,
    stage: Path,
    inventory: Mapping[str, Any],
) -> tuple[_ReleaseCapturedFiles, dict[str, Any] | None, str | None]:
    """Replay existing gate lineage from held original bytes, without a native authority claim."""
    root = held.captured.root
    names = inventory["children"][str(stage)]
    if any(re.fullmatch(r"[0-9]{3,}", name, flags=re.ASCII) is None for name in names):
        raise ReleaseControlError("gate invocation sequence contains noncanonical entries")
    ordered = sorted(names, key=int)
    if ordered != [f"{index:03d}" for index in range(1, len(ordered) + 1)]:
        raise ReleaseControlError("gate invocation sequence has gaps")
    if any(not stat.S_ISDIR(inventory["entries"][str(stage / name)][2]) for name in ordered):
        raise ReleaseControlError("gate invocation sequence has an unsafe entry")
    identities = {
        Path(name).relative_to(root).as_posix(): identity
        for name, identity in inventory["entries"].items()
        if stat.S_ISREG(identity[2]) and identity[3] == 1
    }
    rows = []
    physical: set[tuple[int, int]] = set()
    for name, identity in sorted(identities.items()):
        path = root / name
        _release_relative_suffix(name, "gate prior captured member")
        try:
            raw, observed, ancestors = _release_held_path(
                path,
                expected_prefix=tuple(inventory["directories"].values()),
                expected_identity=identity,
            )
        except ReleaseControlError as exc:
            relative = path.relative_to(stage).parts
            is_partial = len(relative) >= 3 and relative[1] in {"staged", "workspace"}
            if (
                not is_partial
                or str(exc) != "captured release input cannot be read safely"
                or not isinstance(exc.__cause__, OSError)
            ):
                raise
            # Only a genuine read/open OSError may remain original unreadable
            # partial evidence. Object/capture/cleanup mismatches are never ignored.
            parent_paths = (*reversed(path.parent.parents), path.parent)
            parent_pins = tuple(inventory["directories"][str(parent)] for parent in parent_paths)
            parent_fd = _release_gate_open_pinned_directory(path.parent, parent_pins)
            try:
                if (
                    _release_gate_file_identity(
                        os.stat(path.name, dir_fd=parent_fd, follow_symlinks=False)
                    )
                    != identity
                ):
                    raise ReleaseControlError("gate unreadable prior member changed") from exc
            finally:
                os.close(parent_fd)
            continue
        if ancestors[: len(held.captured.root_directories)] != held.captured.root_directories:
            raise ReleaseControlError("gate prior read lost original root custody")
        if (observed[0], observed[1]) in physical:
            raise ReleaseControlError("gate prior captured members alias one physical file")
        physical.add((observed[0], observed[1]))
        rows.append((name, "prerequisite-original", raw, observed, ancestors))
    captured = _ReleaseCapturedFiles(root, held.captured.root_directories, tuple(rows))
    captured.revalidate()
    if not ordered:
        return captured, None, None
    contexts = {}
    for name in ordered:
        directory = stage / name
        raw = captured.read(
            (directory / "intent.json").relative_to(root).as_posix(), kind="prerequisite-original"
        )
        context = _validate_intent_bytes(directory, raw)
        if context.intent["tool"] != "prepare_release_gate_input.py" or context.intent[
            "planned_outputs"
        ] != [{"path": output, "schema_id": kind} for output, kind in _RELEASE_GATE_OUTPUT_PLAN]:
            raise ReleaseControlError("gate predecessor has a different owner or output plan")
        contexts[name] = context
    terminal_suffixes = {
        (stage / name / "invocation.json").relative_to(root).as_posix()
        for name in ordered
        if str(stage / name / "invocation.json") in inventory["entries"]
    }
    if any(
        _source_json(
            captured.read(name, kind="prerequisite-original"), "gate previous terminal"
        ).get("status")
        == "PASS"
        for name in terminal_suffixes
    ):
        outputs = _ReleaseCapturedFiles.capture(
            root,
            [(name, "prerequisite-original") for name, _ in _RELEASE_GATE_OUTPUT_PLAN],
            forbidden=[],
            allowed_kinds=frozenset({"prerequisite-original"}),
            expected_root_directories=held.captured.root_directories,
        )
        captured = _ReleaseCapturedFiles(
            root, captured.root_directories, tuple(sorted((*captured.rows, *outputs.rows)))
        )
    current = contexts[ordered[-1]]
    latest = current
    terminal_required = (current.directory / "invocation.json").relative_to(
        root
    ).as_posix() in terminal_suffixes
    latest_terminal = None
    while True:
        terminal_name = (current.directory / "invocation.json").relative_to(root).as_posix()
        partial_name = (current.directory / "partial-files.json").relative_to(root).as_posix()
        if not terminal_required and terminal_name in terminal_suffixes:
            raise ReleaseControlError("interrupted gate predecessor acquired a terminal")
        terminal = None
        if not terminal_required:
            _release_gate_terminal_commit_replay(current, None, captured=captured)
        if terminal_required:
            terminal = _release_captured_journal_terminal(
                current, captured=captured, require_pass=False, gate_pair_owner=True
            )
            if current is latest:
                latest_terminal = terminal
        if partial_name in identities:
            raw = captured.read(partial_name, kind="prerequisite-original")
            partial = _source_json(raw, "gate prior partial inventory")
            if raw != canonical_json(partial) or partial != _release_gate_prior_partial_projection(
                current, inventory, captured
            ):
                raise ReleaseControlError(
                    "gate prior partial inventory differs from original bytes"
                )
        if terminal is not None and terminal["status"] == "PASS":
            intent_name = (current.directory / "intent.json").relative_to(root).as_posix()
            row = next(row for row in captured.rows if row[0] == intent_name)
            intent_capture = _ReleaseCapturedFiles(
                root, captured.root_directories, ((row[0], "release-invocation-intent", *row[2:]),)
            )
            plan = _release_gate_input_plan_replay(
                current,
                expected_registry_digests=dict(held.registry_digests),
                original_capture=held.captured,
                original_intent_capture=intent_capture,
            )
            output_capture = _release_gate_output_capture(current, root, input_plan=plan)
            required = [
                {
                    "path": name,
                    "schema_id": kind,
                    "sha256": sha256_bytes(output_capture.read(name, kind=kind)),
                }
                for name, kind in _RELEASE_GATE_OUTPUT_PLAN
            ]
            if terminal["data"]["outputs"] != required:
                raise ReleaseControlError("gate prior PASS outputs differ from its bound plan")
        predecessor = current.intent["predecessor"]
        if predecessor is None:
            break
        previous = contexts[f"{predecessor['sequence']:03d}"]
        previous_raw = captured.read(
            (previous.directory / "intent.json").relative_to(root).as_posix(),
            kind="prerequisite-original",
        )
        if sha256_bytes(previous_raw) != predecessor["intent_digest"]:
            raise ReleaseControlError("gate prior intent differs from original lineage")
        terminal_required = predecessor["terminal_digest"] is not None
        if terminal_required:
            terminal_raw = captured.read(
                (previous.directory / "invocation.json").relative_to(root).as_posix(),
                kind="prerequisite-original",
            )
            if sha256_bytes(terminal_raw) != predecessor["terminal_digest"]:
                raise ReleaseControlError("gate prior terminal differs from original lineage")
        current = previous
    captured.revalidate()
    digest = sha256_json(latest_terminal) if latest_terminal is not None else None
    return (
        captured,
        {
            "sequence": latest.intent["sequence"],
            "intent_digest": sha256_json(latest.intent),
            "terminal_digest": digest,
            "disposition": "TERMINAL" if digest else "INTERRUPTED_MISSING_TERMINAL",
        },
        digest,
    )


def _begin_release_gate_invocation(
    tool: str,
    argv: Sequence[str],
    directory: Path,
    *,
    input_paths: Sequence[tuple[Path, str]],
    planned_outputs: Sequence[tuple[Path, str]],
    held: _ReleaseGateInputs,
) -> ReleaseInvocation:
    """Reserve the ordinary gate journal using its original held directory custody."""
    from metriplane import __version__

    directory = _release_capture_absolute(directory)
    if (
        tool != "prepare_release_gate_input.py"
        or re.fullmatch(r"[0-9]{3,}", directory.name, flags=re.ASCII) is None
        or int(directory.name) < 1
        or directory.name != f"{int(directory.name):03d}"
        or directory.parts[-3:-1] != ("invocations", _invocation_stage(tool))
    ):
        raise ReleaseControlError("gate reservation has an invalid fixed stage/sequence")
    root = directory.parents[2]
    outputs = sorted(
        ({"path": _run_relative(root, path), "schema_id": kind} for path, kind in planned_outputs),
        key=lambda row: row["path"],
    )
    _release_gate_reservation_check(held, tool, argv, directory, input_paths, outputs)
    pins = held.captured.root_directories
    known = {row[0]: row for row in pins}
    for _, _, _, _, ancestors in held.captured.rows:
        for row in ancestors:
            if row[0] in known and known[row[0]] != row:
                raise ReleaseControlError("gate original directory pins conflict")
            known[row[0]] = row
    descriptors: list[int] = []
    try:
        root_fd = _release_gate_open_pinned_directory(root, pins)
        descriptors.append(root_fd)
        parent_fd = root_fd
        visible = root
        for name in ("invocations", _invocation_stage(tool)):
            # An effect through a held parent can only touch that original object.
            check_fd = _release_gate_open_pinned_directory(visible, pins)
            os.close(check_fd)
            created = False
            try:
                os.mkdir(name, mode=0o700, dir_fd=parent_fd)
                created = True
            except FileExistsError:
                pass
            observed = os.stat(name, dir_fd=parent_fd, follow_symlinks=False)
            child = os.open(name, os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW, dir_fd=parent_fd)
            descriptors.append(child)
            actual = os.fstat(child)
            if (actual.st_dev, actual.st_ino, actual.st_mode) != (
                observed.st_dev,
                observed.st_ino,
                observed.st_mode,
            ):
                raise ReleaseControlError("gate journal ancestor changed while opening")
            visible /= name
            row = (str(visible), actual.st_dev, actual.st_ino, actual.st_mode)
            if str(visible) in known and known[str(visible)] != row:
                raise ReleaseControlError("gate journal ancestor differs from original capture")
            pins = (*pins, row)
            if created:
                if os.listdir(child):
                    raise ReleaseControlError("new gate journal ancestor is already occupied")
                os.fsync(child)
                os.fsync(parent_fd)
            parent_fd = child
        stage_fd = parent_fd
        stage = visible
        inventory = _release_gate_stage_inventory(stage, stage_fd, pins)
        prior_capture, previous, previous_digest = _release_gate_prior_journals(
            held, stage, inventory
        )
        if int(directory.name) != len(inventory["children"][str(stage)]) + 1:
            raise ReleaseControlError(
                "gate sequence collides, has gaps or is not the next sequence"
            )
        inputs = []
        for path, kind in input_paths:
            suffix = path.absolute().relative_to(root).as_posix()
            raw = held.captured.read(
                suffix, kind=kind.removeprefix("metriplane.").removesuffix(".v1")
            )
            inputs.append(
                {"path": str(path.absolute()), "schema_id": kind, "sha256": sha256_bytes(raw)}
            )
        inputs.sort(key=lambda row: row["path"])
        intent: dict[str, Any] = {
            "schema_version": "metriplane.release-invocation-intent.v1",
            "sequence": int(directory.name),
            "tool": tool,
            "tool_version": __version__,
            "argv": [tool, *argv],
            "started_at": datetime.now(UTC).isoformat().replace("+00:00", "Z"),
            "inputs": inputs,
            "environment": {
                "working_directory": str(Path.cwd()),
                "python": sys.version.split()[0],
                "fixture_mode": "1"
                if os.environ.get("METRIPLANE_RELEASE_FIXTURE_MODE") == "1"
                else "0",
                "source_date_epoch": os.environ.get("SOURCE_DATE_EPOCH", ""),
                "python_hash_seed": os.environ.get("PYTHONHASHSEED", ""),
            },
            "planned_outputs": outputs,
            "previous_invocation_digest": previous_digest,
            "predecessor": previous,
        }
        intent["invocation_id"] = _intent_identity(intent)
        _release_gate_reservation_check(held, tool, argv, directory, input_paths, outputs)
        check_fd = _release_gate_open_pinned_directory(stage, pins)
        os.close(check_fd)
        _release_gate_stage_inventory(stage, stage_fd, pins, expected=inventory)
        prior_capture.revalidate()
        os.mkdir(directory.name, mode=0o700, dir_fd=stage_fd)
        observed = os.stat(directory.name, dir_fd=stage_fd, follow_symlinks=False)
        invocation_fd = os.open(
            directory.name, os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW, dir_fd=stage_fd
        )
        descriptors.append(invocation_fd)
        actual = os.fstat(invocation_fd)
        if (actual.st_dev, actual.st_ino, actual.st_mode) != (
            observed.st_dev,
            observed.st_ino,
            observed.st_mode,
        ) or os.listdir(invocation_fd):
            raise ReleaseControlError("new gate invocation directory changed or is occupied")
        invocation_pins = (*pins, (str(directory), actual.st_dev, actual.st_ino, actual.st_mode))
        os.fsync(invocation_fd)
        os.fsync(stage_fd)
        check_fd = _release_gate_open_pinned_directory(directory, invocation_pins)
        os.close(check_fd)
        written_identity = _release_gate_write_json_at(invocation_fd, "intent.json", intent)
        intent_name = (directory / "intent.json").relative_to(root).as_posix()
        intent_capture = _ReleaseCapturedFiles.capture(
            root,
            [(intent_name, "release-invocation-intent")],
            forbidden=[],
            allowed_kinds=frozenset({"release-invocation-intent"}),
            expected_root_directories=held.captured.root_directories,
            expected_known_directories=invocation_pins,
            expected_file_identities={intent_name: written_identity},
        )
        _release_gate_stage_inventory(
            stage, stage_fd, pins, expected=inventory, excluded_sequence=directory.name
        )
        prior_capture.revalidate()
        context = _validate_intent_bytes(
            directory, intent_capture.read(intent_name, kind="release-invocation-intent")
        )
        result = _ReleaseGateInvocation(
            context.directory,
            context.root,
            context.intent,
            held,
            intent_capture,
            prior_capture,
            inventory,
        )
        _validate_bound_invocation(result)
        return result
    except OSError as exc:
        raise ReleaseControlError(
            "gate reservation cannot retain original directory custody"
        ) from exc
    finally:
        failures: list[OSError] = []
        for descriptor in reversed(descriptors):
            try:
                os.close(descriptor)
            except OSError as exc:
                failures.append(exc)
        if failures:
            raise ReleaseControlError("gate reservation descriptor cleanup failed") from failures[0]


def _release_gate_partial_projection_at(
    context: ReleaseInvocation,
    directory_fd: int,
    *,
    expected_identities: Mapping[str, tuple[int, ...]] | None = None,
    observed_identities: dict[str, tuple[int, ...]] | None = None,
) -> dict[str, Any]:
    """Inventory quiescent partial bytes through one already pinned original journal."""
    files: list[dict[str, Any]] = []
    unreadable: list[str] = []
    roots: list[dict[str, str]] = []
    observed: dict[str, tuple[int, ...]] = {}

    def observe(path: Path, identity: tuple[int, ...]) -> None:
        name = path.relative_to(context.root).as_posix()
        if expected_identities is not None and (
            name not in expected_identities or expected_identities[name] != identity
        ):
            raise ReleaseControlError("gate partial object changed before original byte access")
        if name in observed and observed[name] != identity:
            raise ReleaseControlError("gate partial original identity changed during census")
        observed[name] = identity

    def same(parent: int, name: str, identity: tuple[int, ...]) -> None:
        if (
            _release_gate_file_identity(os.stat(name, dir_fd=parent, follow_symlinks=False))
            != identity
        ):
            raise ReleaseControlError("gate partial member changed during held inventory")

    def walk(parent: int, name: str, path: Path, before: os.stat_result) -> None:
        relative = path.relative_to(context.root).as_posix()
        _release_relative_suffix(relative, "gate partial member")
        identity = _release_gate_file_identity(before)
        observe(path, identity)
        if stat.S_ISDIR(before.st_mode):
            child = os.open(name, os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW, dir_fd=parent)
            try:
                if _release_gate_file_identity(os.fstat(child)) != identity:
                    raise ReleaseControlError("gate partial directory changed before inventory")
                names = sorted(os.listdir(child))
                for member in names:
                    info = os.stat(member, dir_fd=child, follow_symlinks=False)
                    walk(child, member, path / member, info)
                if (
                    names != sorted(os.listdir(child))
                    or _release_gate_file_identity(os.fstat(child)) != identity
                ):
                    raise ReleaseControlError("gate partial directory changed during inventory")
                same(parent, name, identity)
            finally:
                os.close(child)
        elif not stat.S_ISREG(before.st_mode) or before.st_nlink != 1:
            # Never open symlinks, FIFOs, sockets, devices or aliased files.
            unreadable.append(relative)
            same(parent, name, identity)
        else:
            descriptor: int | None = None
            try:
                try:
                    descriptor = os.open(
                        name, os.O_RDONLY | os.O_NONBLOCK | os.O_NOFOLLOW, dir_fd=parent
                    )
                except OSError:
                    same(parent, name, identity)
                    unreadable.append(relative)
                    return
                if _release_gate_file_identity(os.fstat(descriptor)) != identity:
                    raise ReleaseControlError("gate partial file changed before byte access")
                chunks: list[bytes] = []
                try:
                    while block := os.read(descriptor, 1024 * 1024):
                        chunks.append(block)
                except OSError:
                    if _release_gate_file_identity(os.fstat(descriptor)) != identity:
                        raise ReleaseControlError(
                            "gate partial unreadable object changed"
                        ) from None
                    same(parent, name, identity)
                    unreadable.append(relative)
                    return
                raw = b"".join(chunks)
                if (
                    _release_gate_file_identity(os.fstat(descriptor)) != identity
                    or len(raw) != before.st_size
                ):
                    raise ReleaseControlError("gate partial bytes changed during inventory")
                same(parent, name, identity)
                files.append({"path": relative, "sha256": sha256_bytes(raw), "size": len(raw)})
            finally:
                if descriptor is not None:
                    os.close(descriptor)

    try:
        journal_before = _release_gate_file_identity(os.fstat(directory_fd))
        journal_names = sorted(os.listdir(directory_fd))
        for name in ("staged", "workspace"):
            path = context.directory / name
            relative = path.relative_to(context.root).as_posix()
            try:
                before = os.stat(name, dir_fd=directory_fd, follow_symlinks=False)
            except FileNotFoundError:
                observe(path, ())
                roots.append({"path": relative, "kind": "absent"})
                continue
            if not stat.S_ISDIR(before.st_mode):
                observe(path, _release_gate_file_identity(before))
                roots.append({"path": relative, "kind": "unsafe"})
                unreadable.append(relative)
                same(directory_fd, name, _release_gate_file_identity(before))
            else:
                roots.append({"path": relative, "kind": "directory"})
                walk(directory_fd, name, path, before)
        if journal_before != _release_gate_file_identity(
            os.fstat(directory_fd)
        ) or journal_names != sorted(os.listdir(directory_fd)):
            raise ReleaseControlError("gate partial roots changed during held inventory")
        if expected_identities is not None and observed != expected_identities:
            raise ReleaseControlError("gate partial original identity inventory changed")
        if observed_identities is not None:
            if observed_identities:
                raise ReleaseControlError("gate partial capture destination must be empty")
            observed_identities.update(observed)
        return {
            "schema_version": "metriplane.release-partial-files.v1",
            "roots": roots,
            "files": files,
            "unreadable": unreadable,
        }
    except OSError as exc:
        raise ReleaseControlError("gate partial inventory lost its original directory") from exc


def _release_gate_journal_barrier(context: _ReleaseGateInvocation, directory_fd: int) -> None:
    """Check original journal identity without requiring unchanged failed input bytes."""
    capture = context.intent_capture
    name = (context.directory / "intent.json").relative_to(context.root).as_posix()
    if (
        capture.root != context.root
        or len(capture.rows) != 1
        or capture.rows[0][0] != name
        or canonical_json(context.intent) != capture.rows[0][2]
        or context.prior_capture is None
        or context.prior_inventory is None
        or context.prior_capture.root != context.root
        or context.prior_capture.root_directories != capture.root_directories
    ):
        raise ReleaseControlError("gate supervisor lost its actual reservation captures")
    ancestors = capture.rows[0][4]
    current = os.fstat(directory_fd)
    if not ancestors or ancestors[-1] != (
        str(context.directory),
        current.st_dev,
        current.st_ino,
        current.st_mode,
    ):
        raise ReleaseControlError("gate supervisor directory differs from its original intent")
    capture.revalidate()
    stage_fd = _release_gate_open_pinned_directory(context.directory.parent, ancestors[:-1])
    try:
        _release_gate_stage_inventory(
            context.directory.parent,
            stage_fd,
            ancestors[:-1],
            expected=context.prior_inventory,
            excluded_sequence=context.directory.name,
        )
    finally:
        os.close(stage_fd)
    context.prior_capture.revalidate()
    # Preserve interrupted history: a later terminal cannot silently fill an old gap.
    prior = context.intent["predecessor"]
    if prior is not None and prior["terminal_digest"] is None:
        previous = context.directory.parent / f"{prior['sequence']:03d}"
        key = (previous / "intent.json").relative_to(context.root).as_posix()
        matches = [row for row in context.prior_capture.rows if row[0] == key]
        if len(matches) != 1:
            raise ReleaseControlError("gate supervisor lost its original predecessor")
        previous_fd = _release_gate_open_pinned_directory(previous, matches[0][4])
        try:
            if "invocation.json" in os.listdir(previous_fd):
                raise ReleaseControlError("gate interrupted predecessor acquired a terminal")
        finally:
            os.close(previous_fd)


def _release_gate_journal_capture_at(
    context: _ReleaseGateInvocation,
    directory_fd: int,
    identities: Mapping[str, tuple[int, ...]],
) -> _ReleaseCapturedFiles:
    """Read only exact original/newly created inodes, never first accept a fresh path."""
    _release_gate_journal_barrier(context, directory_fd)
    for name, identity in identities.items():
        if name not in {
            "stdout",
            "stderr",
            "partial-files.json",
            "invocation.json",
            "worker-result.json",
            "terminal-commit.json",
        }:
            raise ReleaseControlError("gate journal capture has an unknown member")
        if (
            _release_gate_file_identity(os.stat(name, dir_fd=directory_fd, follow_symlinks=False))
            != identity
        ):
            raise ReleaseControlError("gate journal member differs from its original writer")
    selected = {
        (context.directory / name).relative_to(context.root).as_posix(): identity
        for name, identity in identities.items()
    }
    captured = _ReleaseCapturedFiles.capture(
        context.root,
        [(name, "prerequisite-original") for name in selected],
        forbidden=(),
        allowed_kinds=frozenset({"prerequisite-original"}),
        expected_root_directories=context.intent_capture.root_directories,
        expected_known_directories=context.intent_capture.rows[0][4],
        expected_file_identities=selected,
    )
    assert context.prior_capture is not None
    rows = tuple(
        (name, "prerequisite-original", raw, identity, ancestors)
        for name, _, raw, identity, ancestors in (
            *context.prior_capture.rows,
            *context.intent_capture.rows,
            *captured.rows,
        )
    )
    if len({row[0] for row in rows}) != len(rows):
        raise ReleaseControlError("gate terminal captures overlap")
    result = _ReleaseCapturedFiles(context.root, captured.root_directories, rows)
    result.revalidate()
    _release_gate_journal_barrier(context, directory_fd)
    return result


def _release_gate_complete_at(
    context: _ReleaseGateInvocation,
    directory_fd: int,
    code: int,
    outputs: list[dict[str, str]],
    diagnostic_identities: Mapping[str, tuple[int, ...]],
    *,
    completion: _ReleaseGateCompletion | None = None,
) -> None:
    """Complete only the original journal after quiescence and exact held readback."""
    if (code == 0) != isinstance(completion, _ReleaseGateCompletion):
        raise ReleaseControlError("gate PASS needs its actual complete held output handoff")
    if "terminal-commit.json" in os.listdir(directory_fd):
        raise ReleaseControlError("gate cannot complete after a premature durability witness")
    if set(diagnostic_identities) != {"stdout", "stderr"}:
        raise ReleaseControlError("gate terminal needs both actual diagnostic writer identities")
    _release_gate_journal_barrier(context, directory_fd)
    identities = dict(diagnostic_identities)
    projection: dict[str, Any] | None = None
    partial_identities: dict[str, tuple[int, ...]] = {}
    if code != 0:
        projection = _release_gate_partial_projection_at(
            context, directory_fd, observed_identities=partial_identities
        )
        _release_gate_journal_barrier(context, directory_fd)
        identities["partial-files.json"] = _release_gate_write_json_at(
            directory_fd, "partial-files.json", projection
        )
    captured = _release_gate_journal_capture_at(context, directory_fd, identities)

    def read(name: str) -> bytes:
        return captured.read(
            (context.directory / name).relative_to(context.root).as_posix(),
            kind="prerequisite-original",
        )

    if projection is not None and (
        read("partial-files.json") != canonical_json(projection)
        or projection
        != _release_gate_partial_projection_at(
            context, directory_fd, expected_identities=partial_identities
        )
    ):
        raise ReleaseControlError("gate retained partial inventory changed")
    inputs = []
    paths = [(context.directory / "intent.json", "metriplane.release-invocation-intent.v1")]
    if projection is not None:
        paths.append(
            (context.directory / "partial-files.json", "metriplane.release-partial-files.v1")
        )
    prior = context.intent["predecessor"]
    if prior is not None:
        previous = context.directory.parent / f"{prior['sequence']:03d}"
        paths.append((previous / "intent.json", "metriplane.release-invocation-intent.v1"))
        if prior["terminal_digest"] is not None:
            paths.append((previous / "invocation.json", "metriplane.release-stage-invocation.v1"))
    for path, kind in paths:
        name = path.relative_to(context.root).as_posix()
        inputs.append(
            {
                "path": name,
                "schema_id": kind,
                "sha256": sha256_bytes(captured.read(name, kind="prerequisite-original")),
            }
        )
    terminal_status = (
        "PASS" if code == 0 else "CANCELLED" if code >= 128 else "BLOCKED" if code == 3 else "FAIL"
    )
    intent = context.intent
    data: dict[str, Any] = {
        "argv": intent["argv"],
        "completed_at": datetime.now(UTC).isoformat().replace("+00:00", "Z"),
        "exit_code": code,
        "inputs": sorted(inputs, key=lambda row: row["path"]),
        "outputs": outputs,
        "previous_invocation_digest": intent["previous_invocation_digest"],
        "started_at": intent["started_at"],
        "stderr_digest": sha256_bytes(read("stderr")),
        "stdout_digest": sha256_bytes(read("stdout")),
        "terminal_status": terminal_status,
        "tool": intent["tool"],
        "tool_version": intent["tool_version"],
    }
    data["invocation_digest"] = sha256_json(data)
    record = make_record(
        "release-stage-invocation",
        data,
        invocation_id=intent["invocation_id"],
        sequence=intent["sequence"],
        synthetic=intent["environment"]["fixture_mode"] == "1",
        status=terminal_status,
    )
    captured.revalidate()
    _release_gate_journal_barrier(context, directory_fd)
    identities["invocation.json"] = _release_gate_write_json_at(
        directory_fd, "invocation.json", record
    )
    terminal_capture = _release_gate_journal_capture_at(context, directory_fd, identities)
    if projection is not None and projection != _release_gate_partial_projection_at(
        context, directory_fd, expected_identities=partial_identities
    ):
        raise ReleaseControlError("gate partial inventory changed during terminal creation")
    if code == 0:
        assert completion is not None
        _release_gate_commit_success(context, directory_fd, terminal_capture, completion)
    else:
        _release_captured_journal_terminal(
            context, captured=terminal_capture, require_pass=False, gate_pair_owner=True
        )
    _release_gate_journal_barrier(context, directory_fd)


def _release_gate_worker_main(
    directory: str, directory_fd: int, receipt_fd: int, pins_json: str
) -> int:
    """Use the parent's original journal descriptor for every gate worker effect."""
    pins = _source_json(pins_json.encode(), "gate worker original pins")
    pins = _release_closed_mapping(pins, {"ancestors", "identity"}, "gate worker original pins")
    ancestors = tuple(tuple(row) for row in pins["ancestors"])
    identity = tuple(pins["identity"])
    path = _release_capture_absolute(Path(directory))
    checked_fd = _release_gate_open_pinned_directory(path, ancestors)
    try:
        held, checked = os.fstat(directory_fd), os.fstat(checked_fd)
        if (held.st_dev, held.st_ino, held.st_mode) != (
            checked.st_dev,
            checked.st_ino,
            checked.st_mode,
        ):
            raise ReleaseControlError("gate worker received a different journal directory")
        raw, observed, _ = _release_held_path(
            path / "intent.json", expected_directories=ancestors, expected_identity=identity
        )
        context = _validate_intent_bytes(path, raw)
        if context.intent["tool"] != "prepare_release_gate_input.py" or observed != identity:
            raise ReleaseControlError("gate worker has no original gate intent")
        _release_gate_write_json_at(directory_fd, "worker.pid", {"pid": os.getpid()})
        os.mkdir("staged", dir_fd=directory_fd)
        os.fsync(directory_fd)
        # The planned native gate operation remains fail-closed until its complete
        # held input/semantic/output graph is connected. Do not enter a pathname
        # writer through the general worker while this private boundary is pending.
        code = 3
        print(
            canonical_json(
                _blocked_result(
                    context.intent["tool"], "gate native held worker operation is not implemented"
                )
            ).decode(),
            file=sys.stderr,
        )
        result_identity = _release_gate_write_json_at(
            directory_fd,
            "worker-result.json",
            {
                "schema_version": "metriplane.release-worker-result.v1",
                "exit_code": code,
                "outputs": [],
                "producer_intent_digest": sha256_json(context.intent),
            },
        )
        receipt = canonical_json({"result_identity": result_identity})
        if os.write(receipt_fd, receipt) != len(receipt):
            raise ReleaseControlError("gate worker result descriptor handoff was incomplete")
        os.close(receipt_fd)
        return code
    finally:
        os.close(checked_fd)


def _release_gate_supervise_invocation(
    context: _ReleaseGateInvocation,
    *,
    artifact_installer: Callable[[Path, Path], list[tuple[Path, Path]]] | None = None,
) -> int:
    """Hold original journal custody from first diagnostic through terminal readback."""
    ancestors = context.intent_capture.rows[0][4] if context.intent_capture.rows else ()
    directory_fd = _release_gate_open_pinned_directory(context.directory, ancestors)
    descriptors: list[int] = []
    outputs: list[dict[str, str]] = []
    code = 3
    group_settled = True
    try:
        _release_gate_journal_barrier(context, directory_fd)
        for name in ("stdout", "stderr"):
            descriptor = os.open(
                name,
                os.O_RDWR | os.O_CREAT | os.O_EXCL | os.O_NOFOLLOW,
                0o400,
                dir_fd=directory_fd,
            )
            descriptors.append(descriptor)
        stdout_fd, stderr_fd = descriptors
        writer_origins = {
            "stdout": _release_gate_file_identity(os.fstat(stdout_fd))[:4],
            "stderr": _release_gate_file_identity(os.fstat(stderr_fd))[:4],
        }
        # Streams do not close the actual writer fds: ownership lasts through replay.
        with (
            os.fdopen(stdout_fd, "wb", closefd=False) as stdout,
            os.fdopen(stderr_fd, "wb", closefd=False) as stderr,
        ):
            try:
                _release_gate_journal_barrier(context, directory_fd)
                _validate_bound_invocation(context)
                root_fd = _release_gate_open_pinned_directory(
                    context.root, context.intent_capture.root_directories
                )
                try:
                    names = os.listdir(root_fd)
                    if any(row["path"] in names for row in context.intent["planned_outputs"]):
                        raise ReleaseControlError(
                            "canonical output already exists; a new staging run is required"
                        )
                finally:
                    os.close(root_fd)
                _release_gate_journal_barrier(context, directory_fd)
                pins = canonical_json(
                    {"ancestors": ancestors, "identity": context.intent_capture.rows[0][3]}
                ).decode()
                receipt_read, receipt_write = os.pipe()
                descriptors.extend((receipt_read, receipt_write))
                os.set_blocking(receipt_read, False)
                command = [
                    sys.executable,
                    "-c",
                    "import sys; from metriplane.release_control import _release_gate_worker_main; raise SystemExit(_release_gate_worker_main(sys.argv[1], int(sys.argv[2]), int(sys.argv[3]), sys.argv[4]))",
                    str(context.directory),
                    str(directory_fd),
                    str(receipt_write),
                    pins,
                ]
                process = subprocess.Popen(
                    command,
                    cwd=Path(__file__).resolve().parents[1],
                    stdout=stdout,
                    stderr=stderr,
                    start_new_session=True,
                    pass_fds=(directory_fd, receipt_write),
                )
                group_settled = False
                try:
                    try:
                        return_code = process.wait()
                    except KeyboardInterrupt:
                        process.kill()
                        process.wait()
                        return_code = -2
                    except BaseException:
                        process.kill()
                        process.wait()
                        raise
                finally:
                    group_settled = _stop_worker_group(process.pid)
                code = 128 - return_code if return_code < 0 else return_code
                if not group_settled:
                    raise ReleaseControlError("worker process group has not quiesced")
                _release_gate_journal_barrier(context, directory_fd)
                _validate_bound_invocation(context)
                if return_code >= 0:
                    try:
                        receipt_raw = os.read(receipt_read, 4096)
                    except BlockingIOError:
                        receipt_raw = b""
                    receipt = _release_closed_mapping(
                        _source_json(receipt_raw, "gate worker actual result handoff"),
                        {"result_identity"},
                        "gate worker actual result handoff",
                    )
                    if receipt_raw != canonical_json(receipt) or len(receipt_raw) >= 4096:
                        raise ReleaseControlError(
                            "gate worker result handoff is not one canonical bounded message"
                        )
                    try:
                        extra = os.read(receipt_read, 1)
                    except BlockingIOError:
                        extra = b""
                    if extra:
                        raise ReleaseControlError("gate worker result handoff has trailing bytes")
                    values = receipt["result_identity"]
                    if (
                        not isinstance(values, list)
                        or len(values) != 7
                        or any(type(value) is not int for value in values)
                    ):
                        raise ReleaseControlError(
                            "gate worker lost its actual result writer identity"
                        )
                    result_identity = tuple(values)
                    result_capture = _release_gate_journal_capture_at(
                        context, directory_fd, {"worker-result.json": result_identity}
                    )
                    result = _source_json(
                        result_capture.read(
                            (context.directory / "worker-result.json")
                            .relative_to(context.root)
                            .as_posix(),
                            kind="prerequisite-original",
                        ),
                        "worker result",
                    )
                    if (
                        set(result)
                        != {"schema_version", "exit_code", "outputs", "producer_intent_digest"}
                        or result["schema_version"] != "metriplane.release-worker-result.v1"
                        or type(result["exit_code"]) is not int
                        or result["exit_code"] != code
                        or result["producer_intent_digest"] != sha256_json(context.intent)
                        or (code != 0 and result["outputs"] != [])
                    ):
                        raise ReleaseControlError(
                            "worker verdict does not match the reserved invocation"
                        )
                    if code == 0:
                        outputs = result["outputs"]
                        _verify_staged_outputs(context, outputs)
                        _validate_bound_invocation(context)
                        _release_gate_journal_barrier(context, directory_fd)
                        _install_release_outputs(
                            context, outputs, artifact_installer=artifact_installer
                        )
                        _validate_bound_invocation(context)
                        _release_gate_journal_barrier(context, directory_fd)
                    result_capture.revalidate()
            except Exception as exc:
                code, outputs = 3, []
                stderr.write((str(exc) + "\n").encode())
            finally:
                stdout.flush()
                os.fsync(stdout.fileno())
                stderr.flush()
                os.fsync(stderr.fileno())
        if not group_settled:
            raise ReleaseControlError(
                "retained invocation is incomplete: worker group still exists"
            )
        _release_gate_journal_barrier(context, directory_fd)
        identities = {}
        for name, descriptor in (("stdout", stdout_fd), ("stderr", stderr_fd)):
            identity = _release_gate_file_identity(os.fstat(descriptor))
            if (
                identity[:4] != writer_origins[name]
                or not stat.S_ISREG(identity[2])
                or identity[3] != 1
                or _release_gate_file_identity(
                    os.stat(name, dir_fd=directory_fd, follow_symlinks=False)
                )
                != identity
            ):
                raise ReleaseControlError("gate diagnostic lost its original writer identity")
            identities[name] = identity
        os.fsync(directory_fd)
        _release_gate_complete_at(context, directory_fd, code, outputs, identities)
        print(
            canonical_json(
                {
                    "tool": context.intent["tool"],
                    "status": "PASS" if code == 0 else "BLOCKED_NOT_READY",
                    "exit_code": code,
                    "invocation": str(context.directory),
                }
            ).decode()
        )
        return code
    except OSError as exc:
        raise ReleaseControlError(
            "retained gate invocation is incomplete: original journal custody failed"
        ) from exc
    finally:
        errors: list[OSError] = []
        for descriptor in reversed([directory_fd, *descriptors]):
            try:
                os.close(descriptor)
            except OSError as exc:
                errors.append(exc)
        if errors:
            raise ReleaseControlError("gate supervisor descriptor cleanup failed") from errors[0]


_RELEASE_FIXTURE_NATIVE_ACTOR = "metriplane-synthetic-native-fixture"
_RELEASE_FIXTURE_NATIVE_WIRE = "metriplane.release-fixture-native-receipt.v1"
_RELEASE_FIXTURE_NATIVE_SCOPE = "SYNTHETIC_RELEASE_QUALIFICATION_ONLY"
_RELEASE_FIXTURE_BACKENDS = (
    "payload-store-a",
    "payload-store-b",
    "attempt-index",
    "success-chain",
    "last-known-good",
    "main-health-state",
    "main-health-summary",
)


@dataclass(frozen=True)
class _ReleaseFixtureNativeFacts:
    """Immutable interpreted fixture bytes, NEVER completed-derived membership."""

    producer_identity: bytes
    subject: bytes
    operations: tuple[bytes, ...]
    raw_inventory: tuple[tuple[str, str, int], ...]
    original_input_inventory: tuple[tuple[str, str, str, int], ...]


def _release_fixture_native_timestamp(value: object) -> datetime:
    if (
        not isinstance(value, str)
        or re.fullmatch(
            r"[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}(?:\.[0-9]+)?Z", value
        )
        is None
    ):
        raise ReleaseControlError("fixture native timestamp is not the fixed UTC wire")
    return _parse_utc_timestamp(value, "fixture native timestamp")


def _release_fixture_native_domain(value: object) -> dict[str, Any]:
    domain = _release_closed_mapping(
        value, {"kind", "subject_digest", "original_policy_digest"}, "fixture subject domain"
    )
    if domain["kind"] not in {
        "readiness_context_policy",
        "release_context",
        "backend_registry",
        "retention_subject",
        "index_scope",
        "index_genesis",
    }:
        raise ReleaseControlError("fixture native subject domain is not closed")
    _require_digest(domain["subject_digest"], "fixture semantic subject C")
    _require_digest(domain["original_policy_digest"], "fixture independent raw policy R")
    return domain


def _release_fixture_native_operation(
    kind: str,
    request: Mapping[str, Any],
    *,
    response_path: str | None = None,
    observation_interval: tuple[str, str] | None = None,
) -> dict[str, Any]:
    # Request content has no producer intent, receipt or future primary-output digest.
    allowed = {
        "linear.read",
        "role.delegation",
        "backend.preflight",
        "target.query",
        "retention.put",
        "retention.hold",
        "retention.read",
        "index.read",
        "index.cas",
    }
    if kind not in allowed:
        raise ReleaseControlError("fixture native operation has no fixed interpreter")
    if response_path is not None:
        _release_relative_suffix(response_path, "fixture original response path")
    return {
        "kind": kind,
        "request": dict(request),
        "response_path": response_path,
        "observation_interval": observation_interval,
    }


def _release_fixture_linear_expectations(
    arguments: Mapping[str, Any],
    *,
    readiness_raw: bytes,
    expected_readiness_digest: str,
    context_id: str,
    expected_context_policy_digest: str,
    replayed_observations: Mapping[str, Mapping[str, Any]],
    response_paths: Mapping[str, str],
) -> tuple[dict[str, Any], list[dict[str, Any]]]:
    """Call ONLY with the complete existing raw/BOM/round replay, before native admission.

    Pagination and dependency discovery are response-driven. Their existing complete
    replay, including both rounds and the root project index, owns this finite read plan.
    This constructor never takes a native receipt or its claimed operations as input.
    """
    if sha256_bytes(readiness_raw) != _require_digest(expected_readiness_digest, "readiness R"):
        raise ReleaseControlError("fixture Linear readiness bytes differ")
    registry = _source_json(readiness_raw, "fixture original readiness")
    rows = _release_id_rows(registry.get("release_contexts"), "context_id", "fixture contexts")
    if context_id not in rows:
        raise ReleaseControlError("fixture Linear selected policy is absent")
    policy = rows[context_id]
    if sha256_json(policy) != _require_digest(expected_context_policy_digest, "context-policy C"):
        raise ReleaseControlError("fixture Linear policy differs from independently selected C")
    if arguments.get("project-id") != policy["decision"]["project_id"]:
        raise ReleaseControlError("fixture Linear original project differs from policy")
    if not replayed_observations or set(replayed_observations) != set(response_paths):
        raise ReleaseControlError("fixture Linear complete replay/response inventory differs")
    operations = []
    rounds = set()
    for identity, member in replayed_observations.items():
        row = member["observation"]
        if row["id"] != identity or type(row["round"]) is not int or row["round"] not in {1, 2}:
            raise ReleaseControlError("fixture Linear replayed observation identity differs")
        rounds.add(row["round"])
        operations.append(
            _release_fixture_native_operation(
                "linear.read",
                {
                    "observation_id": identity,
                    "round": row["round"],
                    "tool": row["tool"],
                    "arguments": row["arguments"],
                },
                response_path=response_paths[identity],
                observation_interval=(row["started_at"], row["completed_at"]),
            )
        )
    if rounds != {1, 2}:
        raise ReleaseControlError("fixture Linear native plan lacks both complete rounds")
    return (
        {
            "kind": "readiness_context_policy",
            "subject_digest": sha256_json(policy),
            "original_policy_digest": expected_readiness_digest,
        },
        operations,
    )


def _release_fixture_role_expectations(
    arguments: Mapping[str, Any],
    *,
    original_role_replay: Mapping[str, Any],
    expected_context_digest: str,
    expected_policy_digest: str,
    independently_expected_operator: str,
    response_paths: Mapping[str, str],
) -> tuple[dict[str, Any], list[dict[str, Any]]]:
    """Original signature/role payload replay is required; test delegation is additional."""
    assignments = original_role_replay["assignments"]
    protected = original_role_replay["record"]["data"]
    policy_raw = original_role_replay["assignment_policy_bytes"]
    if sha256_bytes(policy_raw) != _require_digest(expected_policy_digest, "role policy R"):
        raise ReleaseControlError("fixture role policy differs from independent original R")
    _require_nonempty_string(independently_expected_operator, "independent fixture operator")
    if (
        arguments["milestone"] != assignments["milestone"]
        or arguments["run-id"] != assignments["run_id"]
        or protected["signer_identity"] != independently_expected_operator
    ):
        raise ReleaseControlError("fixture role scope/operator is not independently expected")
    roles = ["operator", "non_author_reviewer", "infrastructure_owner", "publisher"]
    if arguments["milestone"] in {"v0.9", "v1.0"}:
        roles.append("independent_assurance")
    if set(original_role_replay["original_provenance"]) != set(roles) or set(response_paths) != set(
        roles
    ):
        raise ReleaseControlError("fixture role has incomplete original delegation inventory")
    operations = []
    for role in roles:
        binding = original_role_replay["original_provenance"][role]["binding"]
        # The complete original role binding is included; no new actor field formula.
        operations.append(
            _release_fixture_native_operation(
                "role.delegation",
                {
                    "role": role,
                    "binding": binding,
                    "expected_operator": independently_expected_operator,
                    "run_id": arguments["run-id"],
                    "milestone": arguments["milestone"],
                    "context_digest": expected_context_digest,
                    "policy_digest": expected_policy_digest,
                    "subjects": protected["subject_digests"],
                    "issued_at": protected["issued_at"],
                    "expires_at": protected["expires_at"],
                },
                response_path=response_paths[role],
            )
        )
    return (
        {
            "kind": "release_context",
            "subject_digest": expected_context_digest,
            "original_policy_digest": expected_policy_digest,
        },
        operations,
    )


def _release_fixture_backend_rows(raw: bytes, *, expected_digest: str) -> list[dict[str, Any]]:
    if sha256_bytes(raw) != _require_digest(expected_digest, "fixture backend registry R"):
        raise ReleaseControlError("fixture backend registry differs from held original")
    registry = _source_json(raw, "fixture backend registry")
    if (
        registry.get("schema_version") != "metriplane.release-evidence-stores.v1"
        or registry.get("owner") != "MP2-007"
        or registry.get("secrets_embedded") is not False
    ):
        raise ReleaseControlError("fixture backend registry type/owner differs")
    rows = registry.get("backends")
    if (
        not isinstance(rows, list)
        or any(not isinstance(r, dict) for r in rows)
        or [r.get("backend_id") for r in rows] != list(_RELEASE_FIXTURE_BACKENDS)
    ):
        raise ReleaseControlError("fixture backend inventory differs from the seven owned IDs")
    capabilities = [
        ["immutable_put", "read", "sha256_read_back", "hold"],
        ["immutable_put", "read", "sha256_read_back", "hold"],
        ["read", "compare_and_swap", "stale_conflict", "idempotent_operation", "read_back"],
        ["read", "compare_and_swap", "stale_conflict", "idempotent_operation", "read_back"],
        ["read", "compare_and_swap", "stale_conflict", "monotonic_generation", "read_back"],
        ["read", "compare_and_swap", "stale_conflict", "monotonic_generation", "read_back"],
        ["immutable_append", "read", "compare_and_swap", "sha256_read_back", "stale_conflict"],
    ]
    suffixes = (
        "payload-a",
        "payload-b",
        "attempt-index",
        "success-chain",
        "last-known-good",
        "main-health-state",
        "main-health-summary",
    )
    for row, expected, suffix in zip(rows, capabilities, suffixes, strict=True):
        namespaces = _release_closed_mapping(
            row.get("namespaces"),
            {"preflight", "production", "test"},
            "fixture original namespaces",
        )
        if (
            namespaces["preflight"] != "metriplane/release-preflight/{scope}/" + suffix
            or namespaces["test"] != "metriplane/release-tests/{run_id}/" + suffix
        ):
            raise ReleaseControlError(
                "fixture namespace changes its exact governed template/domain"
            )
        if row.get("required_capabilities") != expected:
            raise ReleaseControlError("fixture backend capability contract changed")
        if row.get("binding_status") != "BOUND_CONFIGURED" or not isinstance(
            row.get("live_binding"), dict
        ):
            raise ReleaseControlError(
                "fixture needs an explicitly configured synthetic original binding"
            )
        binding = _release_closed_mapping(
            row["live_binding"],
            {
                "adapter_id",
                "public_configuration",
                "owner_binding_authority",
                "provider_resource_identity",
                "administration_identity",
                "durability_retention_policy",
                "namespace_policy",
            },
            "fixture original backend binding",
        )
        if binding["adapter_id"] != "synthetic-fixture-native-v1":
            raise ReleaseControlError("fixture backend binding selects another or live adapter")
        for field in binding:
            if field == "adapter_id":
                continue
            ref = _release_closed_mapping(
                binding[field], {"path", "bytes", "sha256"}, "fixture original control reference"
            )
            _release_relative_suffix(ref["path"], "fixture original control path")
            _require_digest(ref["sha256"], "fixture original control R")
            if type(ref["bytes"]) is not int or ref["bytes"] < 1:
                raise ReleaseControlError("fixture original control size is invalid")
    declarations = registry.get("stores")
    if not isinstance(declarations, list) or len(declarations) != 2:
        raise ReleaseControlError("fixture registry lacks both payload store declarations")
    groups = []
    for declaration, backend in zip(declarations, rows[:2], strict=True):
        store = _release_closed_mapping(
            declaration,
            {"id", "backend_id", "independence_group", "live_binding"},
            "fixture payload declaration",
        )
        if (
            store["id"] != backend["backend_id"]
            or store["backend_id"] != backend["backend_id"]
            or store["independence_group"] != backend["independence_group"]
            or store["live_binding"]
            != {
                "backend_id": backend["backend_id"],
                "binding_digest": sha256_json(backend["live_binding"]),
            }
        ):
            raise ReleaseControlError(
                "fixture payload declaration changes its original backend binding"
            )
        groups.append(
            _require_nonempty_string(store["independence_group"], "fixture independence label")
        )
    if len(set(groups)) != 2:
        raise ReleaseControlError("fixture payload declarations reuse an independence label")
    return rows


def _release_fixture_preflight_expectations(
    arguments: Mapping[str, Any],
    *,
    registry_raw: bytes,
    expected_registry_digest: str,
    backend_controls: Mapping[str, Mapping[str, Any]],
) -> tuple[dict[str, Any], list[dict[str, Any]]]:
    rows = _release_fixture_backend_rows(registry_raw, expected_digest=expected_registry_digest)
    if arguments.get("mode") != "preflight" or arguments.get("require-backends") != "all":
        raise ReleaseControlError(
            "fixture preflight original command does not require all backends"
        )
    scope = _require_nonempty_string(arguments["scope"], "fixture preflight scope")
    if re.fullmatch(r"[A-Za-z0-9][A-Za-z0-9_.-]{0,159}", scope) is None:
        raise ReleaseControlError("fixture preflight scope is not a safe namespace component")
    operations = []
    for row in rows:
        template = row["namespaces"]["preflight"]
        if template.count("{scope}") != 1 or "{" in template.replace("{scope}", ""):
            raise ReleaseControlError("fixture preflight namespace template differs")
        namespace = template.replace("{scope}", scope)
        _release_relative_suffix(namespace, "fixture preflight namespace")
        if not namespace.startswith("metriplane/release-preflight/"):
            raise ReleaseControlError("fixture preflight cannot address production namespace")
        challenge = {
            "domain": _RELEASE_FIXTURE_NATIVE_SCOPE,
            "scope": scope,
            "backend_id": row["backend_id"],
        }
        operations.append(
            _release_fixture_native_operation(
                "backend.preflight",
                {
                    "backend_id": row["backend_id"],
                    "backend_kind": row["backend_kind"],
                    "binding_digest": sha256_json(row["live_binding"]),
                    "namespace": namespace,
                    "capabilities": row["required_capabilities"],
                    "challenge": challenge,
                    "administration_identity": backend_controls[row["backend_id"]][
                        "administration_identity"
                    ]["administration_id"],
                    "resource_id": backend_controls[row["backend_id"]][
                        "provider_resource_identity"
                    ]["resource_id"],
                },
            )
        )
    return (
        {
            "kind": "backend_registry",
            "subject_digest": sha256_json(_source_json(registry_raw, "registry")),
            "original_policy_digest": expected_registry_digest,
        },
        operations,
    )


def _release_fixture_target_expectations(
    arguments: Mapping[str, Any],
    *,
    context: Mapping[str, Any],
    expected_context_digest: str,
    registry_raw: bytes,
    expected_registry_digest: str,
    requested_versions: Sequence[str],
) -> tuple[dict[str, Any], list[dict[str, Any]]]:
    if sha256_json(context) != _require_digest(expected_context_digest, "fixture target context C"):
        raise ReleaseControlError("fixture target context differs from independent subject")
    validate_record(context, "release-context")
    if context["status"] != "PASS" or context["synthetic"] is not True:
        raise ReleaseControlError("fixture target context is not an original synthetic control")
    if arguments.get("provider-auth-from-approved-environment") is not True:
        raise ReleaseControlError("fixture target capture omits its original command contract")
    data = context["data"]
    policy = _release_target_policy_projection(
        data["target_policy"], milestone=data["framework_milestone"]
    )
    targets = _release_target_registry_projection(
        registry_raw,
        expected_digest=expected_registry_digest,
        milestone=data["framework_milestone"],
    )
    versions = list(requested_versions)
    initial = policy["initial_normalized_package_version"]
    start = _release_version_pair(initial, policy["initial_release_tag"])
    if not versions or versions[0] != initial or len(set(versions)) != len(versions):
        raise ReleaseControlError(
            "fixture target request inventory omits or duplicates the initial target"
        )
    for index, version in enumerate(versions):
        if not isinstance(version, str) or _release_version_pair(version, "v" + version) != (
            *start[:2],
            start[2] + index,
            *start[3:],
        ):
            raise ReleaseControlError(
                "fixture target request search is not finite contiguous same-milestone"
            )
    if policy["resolution_mode"] == "owner_approved_exact_target" and versions != [initial]:
        raise ReleaseControlError(
            "fixture native target request cannot change the owner's exact identity"
        )
    operations = [
        _release_fixture_native_operation(
            "target.query",
            {
                "target_id": target,
                "normalized_package_version": version,
                "release_tag": "v" + version,
                "context_digest": expected_context_digest,
                "registry_digest": expected_registry_digest,
                "resolution_mode": policy["resolution_mode"],
            },
        )
        for version in versions
        for target in targets
    ]
    return (
        {
            "kind": "release_context",
            "subject_digest": expected_context_digest,
            "original_policy_digest": expected_registry_digest,
        },
        operations,
    )


def _release_fixture_retention_expectations(
    arguments: Mapping[str, Any],
    *,
    original_inputs: Sequence[bytes],
    original_manifest: bytes | None,
    registry_raw: bytes,
    expected_registry_digest: str,
    fixture_run_id: str,
    backend_controls: Mapping[str, Mapping[str, Any]],
) -> tuple[dict[str, Any], list[dict[str, Any]]]:
    # Caller must derive fixture_run_id from its original selected run, not a receipt.
    _require_nonempty_string(fixture_run_id, "fixture run identity")
    if re.fullmatch(r"[A-Za-z0-9][A-Za-z0-9_.-]{0,159}", fixture_run_id) is None:
        raise ReleaseControlError("fixture retention run is not a safe namespace component")
    if ("manifest" in arguments) != (original_manifest is not None) or (
        "input" in arguments
    ) != bool(original_inputs):
        raise ReleaseControlError("fixture retention original input form differs")
    if arguments["phase"] not in _RETENTION_PHASES:
        raise ReleaseControlError("fixture retention original phase is not governed")
    if "input" in arguments and len(arguments["input"]) != len(original_inputs):
        raise ReleaseControlError("fixture retention omitted an original repeated input")
    subject = _release_retention_subject_bytes(original_inputs, original_manifest)
    rows = _release_fixture_backend_rows(registry_raw, expected_digest=expected_registry_digest)
    operations = []
    for row in rows[:2]:
        template = row["namespaces"]["test"]
        if template.count("{run_id}") != 1 or "{" in template.replace("{run_id}", ""):
            raise ReleaseControlError("fixture retention namespace template differs")
        namespace = template.replace("{run_id}", fixture_run_id)
        _release_relative_suffix(namespace, "fixture retention namespace")
        if not namespace.startswith("metriplane/release-tests/"):
            raise ReleaseControlError("fixture retention cannot address a production namespace")
        request = {
            "store_id": row["backend_id"],
            "namespace": namespace,
            "binding_digest": sha256_json(row["live_binding"]),
            "object_key": "sha256:" + sha256_bytes(subject),
            "subject_digest": sha256_bytes(subject),
            "subject_bytes": len(subject),
            "phase": arguments["phase"],
            "administration_identity": backend_controls[row["backend_id"]][
                "administration_identity"
            ]["administration_id"],
            "resource_id": backend_controls[row["backend_id"]]["provider_resource_identity"][
                "resource_id"
            ],
        }
        for kind in ("retention.put", "retention.hold", "retention.read"):
            operations.append(_release_fixture_native_operation(kind, request))
    return (
        {
            "kind": "retention_subject",
            "subject_digest": sha256_bytes(subject),
            "original_policy_digest": expected_registry_digest,
        },
        operations,
    )


def _release_fixture_index_genesis(raw: bytes) -> dict[str, Any]:
    genesis = _release_closed_mapping(
        _source_json(raw, "fixture original index genesis"),
        {"schema_version", "backend_id", "fixture_actor", "run_id", "namespace", "binding_digest"},
        "fixture original index genesis",
    )
    run_id = _require_nonempty_string(genesis["run_id"], "fixture genesis run")
    if (
        genesis["schema_version"] != "metriplane.release-fixture-index-genesis.v1"
        or genesis["backend_id"] != "attempt-index"
        or genesis["fixture_actor"] != _RELEASE_FIXTURE_NATIVE_ACTOR
        or re.fullmatch(r"[A-Za-z0-9][A-Za-z0-9_.-]{0,159}", run_id) is None
        or genesis["namespace"] != "metriplane/release-tests/" + run_id + "/attempt-index"
    ):
        raise ReleaseControlError("fixture original genesis has another actor/backend/namespace")
    _require_digest(genesis["binding_digest"], "fixture original index binding C")
    return genesis


def _release_fixture_index_expectations(
    arguments: Mapping[str, Any],
    *,
    tool: str,
    genesis_raw: bytes,
    expected_genesis_digest: str,
    original_entry: Mapping[str, Any] | None = None,
    expected_prior_generation: int | None = None,
) -> tuple[dict[str, Any], list[dict[str, Any]]]:
    if sha256_bytes(genesis_raw) != _require_digest(
        expected_genesis_digest, "fixture original genesis R"
    ):
        raise ReleaseControlError("fixture index genesis differs from independently held original")
    genesis = _release_fixture_index_genesis(genesis_raw)
    backend_flag = (
        "attempt-index-backend" if tool == "export_release_burn_lineage.py" else "index-backend"
    )
    if arguments[backend_flag] != "attempt-index":
        raise ReleaseControlError("fixture index cannot select another backend")
    if tool == "update_release_attempt_index.py":
        if (
            original_entry is None
            or type(expected_prior_generation) is not int
            or expected_prior_generation < 0
        ):
            raise ReleaseControlError(
                "fixture index CAS needs original entry graph and independent prior generation"
            )
        entry = _release_index_entry_content(original_entry)
        scope = entry["scope"]
        for flag, value in {
            "expected-head": entry["previous_head"] or expected_genesis_digest,
            "operation-id": entry["operation_id"],
            "scope-kind": scope["kind"],
            "sequence": str(scope["sequence"]),
            "stage": scope["stage"],
        }.items():
            if str(arguments.get(flag)) != str(value):
                raise ReleaseControlError(
                    "fixture CAS original command differs from entry: " + flag
                )
        if entry["genesis_digest"] != expected_genesis_digest:
            raise ReleaseControlError("fixture CAS selects another original genesis")
        operations = [
            _release_fixture_native_operation(
                "index.cas",
                {
                    "backend_id": "attempt-index",
                    "genesis_digest": expected_genesis_digest,
                    "namespace": genesis["namespace"],
                    "binding_digest": genesis["binding_digest"],
                    "expected_head": entry["previous_head"] or expected_genesis_digest,
                    "operation_id": entry["operation_id"],
                    "prior_generation": expected_prior_generation,
                    "entry_payload": {
                        key: entry[key]
                        for key in (
                            "scope",
                            "milestone",
                            "entry_manifest_digest",
                            "entry_receipts_digest",
                        )
                    },
                },
            )
        ]
        subject = {
            "kind": "index_scope",
            "subject_digest": sha256_json(scope),
            "original_policy_digest": expected_genesis_digest,
        }
    elif tool in {"export_release_attempt_index.py", "export_release_burn_lineage.py"}:
        if (
            arguments.get("read-back-all") is not True
            or original_entry is not None
            or expected_prior_generation is not None
        ):
            raise ReleaseControlError("fixture index read must replay all original history")
        head = _require_digest(arguments["through-head"], "fixture selected index head")
        operations = [
            _release_fixture_native_operation(
                "index.read",
                {
                    "backend_id": "attempt-index",
                    "genesis_digest": expected_genesis_digest,
                    "namespace": genesis["namespace"],
                    "binding_digest": genesis["binding_digest"],
                    "through_head": head,
                },
            )
        ]
        subject = {
            "kind": "index_genesis",
            "subject_digest": expected_genesis_digest,
            "original_policy_digest": expected_genesis_digest,
        }
    else:
        raise ReleaseControlError("fixture native index constructor has no such command owner")
    return subject, operations


def _release_fixture_native_plan(
    *, tool: str, sequence: int, subject: Mapping[str, Any], operations: Sequence[Mapping[str, Any]]
) -> list[dict[str, Any]]:
    """Materialize finite original output names BEFORE reservation: no intent C cycle."""
    if tool not in _RELEASE_GATE_PREREQUISITES or type(sequence) is not int or sequence < 1:
        raise ReleaseControlError("fixture native plan producer identity is invalid")
    domain = _release_fixture_native_domain(subject)
    allowed = {
        "capture_linear_release_snapshot.py": ("readiness_context_policy", {"linear.read"}),
        "record_release_role_assignments.py": ("release_context", {"role.delegation"}),
        "validate_release_evidence_stores.py": ("backend_registry", {"backend.preflight"}),
        "capture_release_target_observations.py": ("release_context", {"target.query"}),
        "retain_release_evidence.py": (
            "retention_subject",
            {"retention.put", "retention.hold", "retention.read"},
        ),
        "update_release_attempt_index.py": ("index_scope", {"index.cas"}),
        "export_release_attempt_index.py": ("index_genesis", {"index.read"}),
        "export_release_burn_lineage.py": ("index_genesis", {"index.read"}),
    }
    if tool not in allowed:
        raise ReleaseControlError(
            "derived-only producer must replay its dependencies, not gain native fixture credit"
        )
    expected_domain, kinds = allowed[tool]
    if domain["kind"] != expected_domain or not operations:
        raise ReleaseControlError("fixture native domain/operation inventory differs from producer")
    result = []
    seen_requests: set[str] = set()
    seen_paths: set[str] = set()
    for ordinal, value in enumerate(operations, 1):
        operation = _release_closed_mapping(
            value,
            {"kind", "request", "response_path", "observation_interval"},
            "fixture expected operation",
        )
        if operation["kind"] not in kinds or not isinstance(operation["request"], dict):
            raise ReleaseControlError("fixture operation belongs to another producer")
        request = {
            "schema_version": "metriplane.release-fixture-native-request.v1",
            "scope": _RELEASE_FIXTURE_NATIVE_SCOPE,
            "subject": domain,
            "kind": operation["kind"],
            "arguments": operation["request"],
        }
        digest = sha256_json(request)
        if digest in seen_requests:
            raise ReleaseControlError("fixture operation inventory repeats one request")
        seen_requests.add(digest)
        prefix = f"native-fixture/{_invocation_stage(tool)}/{sequence:03d}/{ordinal:04d}-{digest}"
        paths = {
            "request": prefix + "/request.json",
            "response": operation["response_path"] or prefix + "/response.bin",
            "receipt": prefix + "/receipt.json",
        }
        for name in paths.values():
            _release_relative_suffix(name, "fixture planned native original")
            if name in seen_paths:
                raise ReleaseControlError(
                    "fixture native requests/responses alias an original path"
                )
            seen_paths.add(name)
        result.append(
            {
                "ordinal": ordinal,
                "request": request,
                "paths": paths,
                "observation_interval": operation["observation_interval"],
            }
        )
    return result


def _release_fixture_preflight_trace(request: Mapping[str, Any]) -> list[dict[str, Any]]:
    challenge = sha256_json(request["challenge"])
    first = {"generation": 1, "value_digest": challenge}
    second = {"generation": 2, "value_digest": sha256_json({"challenge": challenge, "update": 2})}
    state: dict[str, Any] | None = None
    committed_request: dict[str, Any] | None = None
    result = []
    for capability in request["capabilities"]:
        before = state
        expected_head = sha256_json(state) if state is not None else None
        observed = state
        effect = capability
        if capability in {"immutable_put", "immutable_append"}:
            if state is not None:
                raise ReleaseControlError("fixture initial immutable creation is not isolated")
            state = first
            observed = state
        elif capability == "compare_and_swap":
            state = first if state is None else second
            committed_request = {"expected_head": expected_head, "value": state}
            observed = state
        elif capability == "stale_conflict":
            expected_head = "0" * 64
            effect = "conflict_unchanged"
        elif capability == "idempotent_operation":
            if committed_request is None:
                raise ReleaseControlError(
                    "fixture idempotence probe lacks a prior committed operation"
                )
            expected_head = committed_request["expected_head"]
            effect = "idempotent_unchanged"
        elif capability == "monotonic_generation":
            if state is None:
                raise ReleaseControlError("fixture monotonic probe has no committed generation")
            effect = "rejected_older_generation_unchanged"
        elif capability == "hold":
            if state is None:
                raise ReleaseControlError("fixture hold probe has no retained object")
            effect = "governance_hold"
        elif capability not in {"read", "sha256_read_back", "read_back"}:
            raise ReleaseControlError("fixture preflight trace has an unimplemented capability")
        result.append(
            {
                "capability": capability,
                "expected_head": expected_head,
                "before": before,
                "after": state,
                "observed": observed,
                "effect": effect,
            }
        )
    return result


def _release_fixture_native_response(
    kind: str, request: Mapping[str, Any], raw: bytes
) -> dict[str, Any]:
    """Interpret fixed fixture operation facts. This never invokes a provider adapter."""
    if kind == "retention.read":
        if len(raw) != request["subject_bytes"] or sha256_bytes(raw) != request["subject_digest"]:
            raise ReleaseControlError(
                "fixture native retained readback is not the original subject"
            )
        return {"original_bytes": len(raw), "original_digest": sha256_bytes(raw)}
    response = _source_json(raw, "fixture native original response")
    if kind == "linear.read":
        envelope = _release_closed_mapping(
            response, {"content", "isError"}, "fixture Linear envelope"
        )
        if (
            envelope["isError"] is not False
            or not isinstance(envelope["content"], list)
            or len(envelope["content"]) != 1
        ):
            raise ReleaseControlError("fixture Linear original reports error/ambiguous content")
        block = _release_closed_mapping(
            envelope["content"][0], {"type", "text"}, "fixture Linear content"
        )
        if block["type"] != "text" or not isinstance(block["text"], str):
            raise ReleaseControlError("fixture Linear original has the wrong extraction wire")
        try:
            payload = json.loads(block["text"], object_pairs_hook=_closed_json_object)
            canonical_json(payload)
        except (ValueError, UnicodeError, RecursionError) as exc:
            raise ReleaseControlError("fixture Linear nested JSON is malformed") from exc
        if (
            not isinstance(payload, (dict, list))
            or isinstance(payload, dict)
            and any(
                key in payload for key in ("error", "errors", "isError", "truncated", "isTruncated")
            )
        ):
            raise ReleaseControlError("fixture Linear native payload is incomplete/error")
        return {"payload": payload}
    if kind == "role.delegation":
        row = _release_closed_mapping(
            response,
            {
                "granting_actor",
                "role",
                "binding_subject",
                "expected_operator",
                "run_id",
                "milestone",
                "context_digest",
                "policy_digest",
                "issued_at",
                "expires_at",
            },
            "fixture delegation",
        )
        expected_delegation = {
            key: value for key, value in request.items() if key not in {"binding", "subjects"}
        }
        expected_delegation["binding_subject"] = {
            key: value for key, value in request["binding"].items() if key != "provenance_digest"
        }
        if row["granting_actor"] != _RELEASE_FIXTURE_NATIVE_ACTOR or canonical_json(
            {key: value for key, value in row.items() if key != "granting_actor"}
        ) != canonical_json(expected_delegation):
            raise ReleaseControlError(
                "fixture delegation differs from independent subjects/actor/scope"
            )
        if _release_fixture_native_timestamp(row["issued_at"]) >= _release_fixture_native_timestamp(
            row["expires_at"]
        ):
            raise ReleaseControlError("fixture delegation interval is empty")
        return dict(row)
    if kind == "target.query":
        row = _release_closed_mapping(
            response,
            {"target_id", "normalized_package_version", "release_tag", "state", "artifacts"},
            "fixture target response",
        )
        if any(
            row[key] != request[key]
            for key in ("target_id", "normalized_package_version", "release_tag")
        ):
            raise ReleaseControlError("fixture native target response has another identity")
        if row["state"] not in {"unused", "occupied", "partial"} or not isinstance(
            row["artifacts"], list
        ):
            raise ReleaseControlError("fixture native target response is unknown or malformed")
        if row["state"] == "unused" and row["artifacts"]:
            raise ReleaseControlError("fixture native unused target contains artifacts")
        names = set()
        for value in row["artifacts"]:
            artifact = _release_closed_mapping(
                value, {"name", "bytes", "sha256", "original_read_back"}, "fixture target artifact"
            )
            name = _require_nonempty_string(artifact["name"], "fixture target artifact filename")
            if (
                _release_relative_suffix(name, "fixture artifact filename").name != name
                or name in names
                or type(artifact["bytes"]) is not int
                or artifact["bytes"] < 0
            ):
                raise ReleaseControlError(
                    "fixture native target artifact aliases or has invalid size"
                )
            _require_digest(artifact["sha256"], "fixture original artifact R")
            names.add(name)
        return dict(row)
    if kind in {"retention.put", "retention.hold"}:
        row = _release_closed_mapping(
            response,
            set(request) | {"effect", "administration_identity"},
            "fixture retention effect",
        )
        if canonical_json({key: row[key] for key in request}) != canonical_json(request):
            raise ReleaseControlError("fixture retention response changes original request")
        if row["effect"] != ("immutable_put" if kind == "retention.put" else "governance_hold"):
            raise ReleaseControlError("fixture retention response has no requested durable effect")
        _require_nonempty_string(row["administration_identity"], "fixture administrative identity")
        return dict(row)
    if kind == "backend.preflight":
        row = _release_closed_mapping(
            response,
            {
                "backend_id",
                "binding_digest",
                "namespace",
                "administration_identity",
                "resource_id",
                "trace",
            },
            "fixture backend trace",
        )
        if any(
            row[key] != request[key]
            for key in (
                "backend_id",
                "binding_digest",
                "namespace",
                "administration_identity",
                "resource_id",
            )
        ):
            raise ReleaseControlError("fixture backend trace changes binding/namespace")
        _require_nonempty_string(row["administration_identity"], "fixture backend administration")
        expected = _release_fixture_preflight_trace(request)
        if canonical_json(row["trace"]) != canonical_json(expected):
            raise ReleaseControlError(
                "fixture backend native trace omits/changes a required effect"
            )
        return dict(row)
    if kind == "index.cas":
        row = _release_closed_mapping(
            response,
            {
                "backend_id",
                "genesis_digest",
                "operation_id",
                "expected_head",
                "entry",
                "committed_head",
                "read_back_digest",
                "disposition",
            },
            "fixture CAS result",
        )
        if any(
            row[key] != request[key]
            for key in ("backend_id", "genesis_digest", "operation_id", "expected_head")
        ):
            raise ReleaseControlError(
                "fixture CAS original response differs from exact requested scope/head"
            )
        entry = _release_index_entry_content(row["entry"])
        if (
            entry["generation"] != request["prior_generation"] + 1
            or (entry["previous_head"] or entry["genesis_digest"]) != request["expected_head"]
            or entry["genesis_digest"] != request["genesis_digest"]
            or entry["backend_id"] != request["backend_id"]
            or entry["operation_id"] != request["operation_id"]
            or canonical_json({key: entry[key] for key in request["entry_payload"]})
            != canonical_json(request["entry_payload"])
        ):
            raise ReleaseControlError(
                "fixture CAS response changes original payload or backend generation"
            )
        if (
            row["committed_head"] != sha256_json(entry)
            or row["read_back_digest"] != sha256_json(entry)
            or row["disposition"] not in {"committed", "idempotent"}
        ):
            raise ReleaseControlError("fixture CAS did not read back its complete exact entry")
        return dict(row)
    if kind == "index.read":
        row = _release_closed_mapping(
            response,
            {
                "backend_id",
                "genesis_digest",
                "namespace",
                "binding_digest",
                "through_head",
                "entries",
            },
            "fixture index history",
        )
        if any(row[key] != request[key] for key in request) or not isinstance(row["entries"], list):
            raise ReleaseControlError("fixture history changes exact genesis/backend/head")
        previous = None
        operations = set()
        scopes = set()
        for generation, value in enumerate(row["entries"], 1):
            entry = _release_index_entry_content(value)
            if (
                entry["generation"] != generation
                or entry["previous_head"] != previous
                or entry["genesis_digest"] != row["genesis_digest"]
                or entry["backend_id"] != row["backend_id"]
                or entry["operation_id"] in operations
            ):
                raise ReleaseControlError(
                    "fixture original index history is incomplete or replays an operation"
                )
            scope = entry["scope"]
            scope_key = _release_index_scope_key(scope)
            if scope_key in scopes:
                raise ReleaseControlError("fixture index history reuses a logical scope sequence")
            scopes.add(scope_key)
            operations.add(entry["operation_id"])
            previous = sha256_json(entry)
        if (previous or row["genesis_digest"]) != row["through_head"]:
            raise ReleaseControlError(
                "fixture index history does not reach independently selected head"
            )
        return dict(row)
    raise ReleaseControlError("fixture native response has no fixed semantic owner")


def _release_fixture_native_receipt_replay(
    original: ReleaseInvocation,
    *,
    captured: _ReleaseCapturedFiles,
    subject: Mapping[str, Any],
    operations: Sequence[Mapping[str, Any]],
    proof_refs: Sequence[Mapping[str, Any]],
    live: bool,
    use_interval: tuple[str, str],
) -> _ReleaseFixtureNativeFacts:
    """Replay constructor-produced expectations against immutable signed FIXTURE originals.

    This API does not add to a native or verified-derived authority set. The enclosing
    builder must reconstruct expectations using the type-specific constructors, held
    original argv/input graph, full original journals and all exact companions.
    """
    # Must precede context/proof IO. Truthy/falsy aliases are not mode controls.
    if (
        type(live) is not bool
        or live is not False
        or original.intent.get("environment", {}).get("fixture_mode") != "1"
    ):
        raise ReleaseControlError("fixture native interpreter is inaccessible to live admission")
    _release_captured_original_context(original, captured=captured)
    tool = original.intent["tool"]
    _release_original_arguments(tool, original.intent["argv"])
    terminal = _release_captured_journal_terminal(original, captured=captured, require_pass=True)
    if use_interval != (original.intent["started_at"], terminal["data"]["completed_at"]):
        raise ReleaseControlError(
            "fixture native clock window must be its actual original journal interval"
        )
    plan = _release_fixture_native_plan(
        tool=tool, sequence=original.intent["sequence"], subject=subject, operations=operations
    )
    if len(proof_refs) != len(plan):
        raise ReleaseControlError(
            "fixture native proof inventory is incomplete or has extra operations"
        )
    expected_outputs = {row["path"]: row["schema_id"] for row in original.intent["planned_outputs"]}
    producer = {
        "tool": tool,
        "invocation_id": original.intent["invocation_id"],
        "sequence": original.intent["sequence"],
        "intent_digest": sha256_json(original.intent),
    }
    start, end = (_release_fixture_native_timestamp(value) for value in use_interval)
    if start > end:
        raise ReleaseControlError("fixture native use interval is inverted")
    inventory = []
    facts = []
    seen = set()
    consumed_outputs: dict[str, str] = {}
    previous = start
    base = original.root.relative_to(captured.root)

    def read(name: str, ref: object, schema_id: str, *, original_input: bool = False) -> bytes:
        reference = _release_closed_mapping(
            ref, {"path", "bytes", "sha256"}, "fixture original raw reference"
        )
        if (
            reference["path"] != name
            or type(reference["bytes"]) is not int
            or reference["bytes"] < 0
        ):
            raise ReleaseControlError(
                "fixture native raw reference changes its exact original location"
            )
        digest = _require_digest(reference["sha256"], "fixture original R")
        if original_input:
            cwd = _canonical_absolute_path(
                original.intent["environment"]["working_directory"], "fixture original cwd"
            )
            arguments = _release_original_arguments(tool, original.intent["argv"])
            historical_directory = _release_historical_path(arguments["invocation-dir"], cwd)
            historical_root = historical_directory.parents[2]
            rows = [
                row
                for row in original.intent["inputs"]
                if row["path"] == str(historical_root / name)
            ]
            if len(rows) != 1 or rows[0]["schema_id"] != schema_id or rows[0]["sha256"] != digest:
                raise ReleaseControlError(
                    "fixture supplied provenance lacks its exact original input type/R"
                )
        elif expected_outputs.get(name) != schema_id:
            raise ReleaseControlError("fixture native original lacks exact planned output type")
        if name in seen:
            raise ReleaseControlError("fixture native original paths alias")
        seen.add(name)
        if not original_input:
            consumed_outputs[name] = schema_id
        raw = captured.read((base / name).as_posix(), kind="prerequisite-original")
        if len(raw) != reference["bytes"] or sha256_bytes(raw) != digest:
            raise ReleaseControlError("fixture native original R/size differs before parsing")
        inventory.append((name, digest, len(raw)))
        return raw

    for expected, receipt_ref in zip(plan, proof_refs, strict=True):
        paths = expected["paths"]
        raw = read(paths["receipt"], receipt_ref, _RELEASE_FIXTURE_NATIVE_WIRE)
        receipt = _release_closed_mapping(
            _source_json(raw, "fixture original native receipt"),
            {
                "schema_version",
                "scope",
                "producer",
                "subject",
                "ordinal",
                "request",
                "response",
                "started_at",
                "completed_at",
                "signature",
            },
            "fixture native receipt",
        )
        if (
            receipt["schema_version"] != _RELEASE_FIXTURE_NATIVE_WIRE
            or receipt["scope"] != _RELEASE_FIXTURE_NATIVE_SCOPE
            or canonical_json(receipt["producer"]) != canonical_json(producer)
            or canonical_json(receipt["subject"]) != canonical_json(subject)
            or type(receipt["ordinal"]) is not int
            or receipt["ordinal"] != expected["ordinal"]
        ):
            raise ReleaseControlError(
                "fixture receipt producer/subject/ordinal differs from expectation"
            )
        decision = {key: value for key, value in receipt.items() if key != "signature"}
        signer = _validated_signature(
            receipt["signature"], subject_digest=sha256_json(decision), live=False
        )
        if signer != ("test-fixture", _RELEASE_FIXTURE_NATIVE_ACTOR):
            raise ReleaseControlError(
                "fixture native receipt is not from the fixed synthetic interpreter identity"
            )
        begun = _release_fixture_native_timestamp(receipt["started_at"])
        finished = _release_fixture_native_timestamp(receipt["completed_at"])
        if not previous <= begun <= finished <= end:
            raise ReleaseControlError(
                "fixture native operation chronology is out of original order/window"
            )
        interval = expected["observation_interval"]
        if interval is not None and (
            not isinstance(interval, (list, tuple))
            or len(interval) != 2
            or (begun, finished)
            != tuple(_release_fixture_native_timestamp(value) for value in interval)
        ):
            raise ReleaseControlError(
                "fixture receipt clock differs from original observed operation interval"
            )
        previous = finished
        request_raw = read(
            paths["request"], receipt["request"], "metriplane.release-fixture-native-request.v1"
        )
        request = _source_json(request_raw, "fixture original request")
        if canonical_json(request) != canonical_json(expected["request"]):
            raise ReleaseControlError(
                "fixture raw request differs from independently constructed operation"
            )
        response_raw = read(
            paths["response"],
            receipt["response"],
            "application/octet-stream",
            original_input=request["kind"] == "role.delegation",
        )
        response = _release_fixture_native_response(
            request["kind"], request["arguments"], response_raw
        )
        if request["kind"] == "target.query":
            for artifact in response["artifacts"]:
                reference = artifact["original_read_back"]
                original_bytes = read(reference["path"], reference, "application/octet-stream")
                if (
                    len(original_bytes) != artifact["bytes"]
                    or sha256_bytes(original_bytes) != artifact["sha256"]
                ):
                    raise ReleaseControlError("fixture target original artifact readback differs")
        facts.append(
            canonical_json(
                {
                    "kind": request["kind"],
                    "request": request["arguments"],
                    "response": response,
                    "started_at": receipt["started_at"],
                    "completed_at": receipt["completed_at"],
                }
            )
        )
    # The whole plan is finite: one original primary output plus exactly the native
    # originals interpreted above. Original-input provenance is not an output.
    arguments = _release_original_arguments(tool, original.intent["argv"])
    cwd = _canonical_absolute_path(
        original.intent["environment"]["working_directory"], "fixture original output cwd"
    )
    historical_root = _release_historical_path(arguments["invocation-dir"], cwd).parents[2]
    primary = _release_historical_path(arguments["out"], cwd)
    if not primary.is_relative_to(historical_root):
        raise ReleaseControlError("fixture original primary output escapes its run")
    primary_name = primary.relative_to(historical_root).as_posix()
    _release_relative_suffix(primary_name, "fixture original primary output")
    if primary_name in seen:
        raise ReleaseControlError("fixture native original aliases its primary output")
    complete_outputs = {
        primary_name: "metriplane." + _RELEASE_GATE_PREREQUISITES[tool][0] + ".v1",
        **consumed_outputs,
    }
    if expected_outputs != complete_outputs:
        raise ReleaseControlError("fixture original full output plan has extra or missing members")
    interpreted = [_source_json(value, "fixture immutable facts") for value in facts]
    if tool == "retain_release_evidence.py":
        administrators = []
        for offset in (0, 3):
            group = interpreted[offset : offset + 3]
            if len(group) != 3 or [row["kind"] for row in group] != [
                "retention.put",
                "retention.hold",
                "retention.read",
            ]:
                raise ReleaseControlError(
                    "fixture retention lacks the complete two-store operation sequence"
                )
            admin = group[0]["response"]["administration_identity"]
            if group[1]["response"]["administration_identity"] != admin:
                raise ReleaseControlError("fixture hold and put administrative identity differ")
            administrators.append(admin)
        if len(interpreted) != 6 or len(set(administrators)) != 2:
            raise ReleaseControlError(
                "fixture retention does not model two separate administrations"
            )
    if tool == "validate_release_evidence_stores.py":
        if len(interpreted) != 7 or [row["request"]["backend_id"] for row in interpreted] != list(
            _RELEASE_FIXTURE_BACKENDS
        ):
            raise ReleaseControlError(
                "fixture preflight does not cover all original backend identities"
            )
        if len({row["response"]["administration_identity"] for row in interpreted[:2]}) != 2:
            raise ReleaseControlError("fixture payload backends share one administration")
    if tool == "capture_release_target_observations.py":
        groups = [interpreted[index : index + 3] for index in range(0, len(interpreted), 3)]
        for index, group in enumerate(groups):
            if len(group) != 3 or [row["request"]["target_id"] for row in group] != [
                "github-release",
                "pypi",
                "testpypi",
            ]:
                raise ReleaseControlError("fixture target native operation inventory is incomplete")
            unused = all(row["response"]["state"] == "unused" for row in group)
            generic = group[0]["request"]["resolution_mode"] == "next_unused_same_milestone_patch"
            if generic and (unused != (index == len(groups) - 1)):
                raise ReleaseControlError(
                    "fixture generic target capture must stop at its first wholly unused version"
                )
    captured.revalidate()
    arguments = _release_original_arguments(tool, original.intent["argv"])
    cwd = _canonical_absolute_path(
        original.intent["environment"]["working_directory"], "fixture original input cwd"
    )
    historical_root = _release_historical_path(arguments["invocation-dir"], cwd).parents[2]
    original_inputs = []
    for row in original.intent["inputs"]:
        suffix = Path(row["path"]).relative_to(historical_root).as_posix()
        raw = captured.read((base / suffix).as_posix(), kind="prerequisite-original")
        if sha256_bytes(raw) != row["sha256"]:
            raise ReleaseControlError("fixture original transitive input R changed")
        original_inputs.append((suffix, row["schema_id"], row["sha256"], len(raw)))
    captured.revalidate()
    return _ReleaseFixtureNativeFacts(
        canonical_json(producer),
        canonical_json(subject),
        tuple(facts),
        tuple(inventory),
        tuple(original_inputs),
    )


def _release_fixture_native_original_inputs(
    original: ReleaseInvocation,
    *,
    captured: _ReleaseCapturedFiles,
    expected_inputs: Mapping[str, Sequence[Mapping[str, str]]],
) -> tuple[dict[str, Any], dict[str, list[tuple[Path, bytes]]]]:
    """Bind independently selected typed inputs BEFORE bytes; original argv stays intact.

    expected_inputs belongs to the enclosing held typed graph, not the native proof.
    Every row is {path: current run-relative path, schema_id, sha256: original R}.
    Auxiliary original transitive inputs remain governed by the complete journal owner.
    """
    _release_captured_original_context(original, captured=captured)
    tool = original.intent["tool"]
    arguments = _release_original_arguments(tool, original.intent["argv"])
    flags = {
        "capture_linear_release_snapshot.py": {"registry"},
        "record_release_role_assignments.py": {
            "signed-assignments",
            "policy",
            "release-context",
            "provider-attestation-keyring",
        },
        "validate_release_evidence_stores.py": {"stores"},
        "capture_release_target_observations.py": {"targets", "release-context"},
        "retain_release_evidence.py": {"stores", "manifest", "input"},
        "update_release_attempt_index.py": {"entry-manifest", "entry-receipts"},
        "export_release_attempt_index.py": {"genesis", "stores"},
        "export_release_burn_lineage.py": {"genesis", "index-export"},
    }
    if tool not in flags:
        raise ReleaseControlError(
            "fixture producer requires dependency replay, not native evidence"
        )
    if tool == "update_release_attempt_index.py" and arguments["stage"] not in {
        "target-burn",
        "staging-failure",
        "index-recovery",
        "qualification-attempt",
        "pointer-transition",
    }:
        raise ReleaseControlError(
            "fixture task-state commit native policy remains separately unimplemented"
        )
    selected_flags = flags[tool] & set(arguments)
    if set(expected_inputs) != selected_flags:
        raise ReleaseControlError(
            "fixture independent typed-input inventory differs from original command"
        )
    cwd = _canonical_absolute_path(
        original.intent["environment"]["working_directory"], "fixture original cwd"
    )
    directory = _release_historical_path(arguments["invocation-dir"], cwd)
    if directory.parts[-3:] != (
        "invocations",
        _invocation_stage(tool),
        f"{original.intent['sequence']:03d}",
    ):
        raise ReleaseControlError("fixture original invocation root cannot be derived")
    historical_root = directory.parents[2]
    result = {}
    seen = set()
    for flag in sorted(selected_flags):
        values = arguments[flag] if flag in TOOL_CONTRACTS[tool].repeatable else [arguments[flag]]
        expected = expected_inputs[flag]
        if not isinstance(expected, (list, tuple)) or len(expected) != len(values):
            raise ReleaseControlError("fixture original repeated input cardinality differs")
        rows = []
        for value, reference in zip(values, expected, strict=True):
            ref = _release_closed_mapping(
                reference, {"path", "schema_id", "sha256"}, "fixture independently selected input"
            )
            original_path = _release_historical_path(value, cwd)
            if not original_path.is_relative_to(historical_root):
                raise ReleaseControlError("fixture original input escapes the original run")
            suffix = original_path.relative_to(historical_root).as_posix()
            _release_relative_suffix(suffix, "fixture original input suffix")
            if ref["path"] != suffix or suffix in seen:
                raise ReleaseControlError("fixture original selected input differs or aliases")
            seen.add(suffix)
            matching = [
                row for row in original.intent["inputs"] if row["path"] == str(original_path)
            ]
            if (
                len(matching) != 1
                or matching[0]["schema_id"] != ref["schema_id"]
                or matching[0]["sha256"]
                != _require_digest(ref["sha256"], "fixture independent input R")
            ):
                raise ReleaseControlError(
                    "fixture original input is not the independently selected type/R"
                )
            current = original.root / suffix
            raw = captured.read(
                current.relative_to(captured.root).as_posix(), kind="prerequisite-original"
            )
            if sha256_bytes(raw) != ref["sha256"]:
                raise ReleaseControlError("fixture original input R changed before parsing")
            rows.append((current, raw))
        result[flag] = rows
    captured.revalidate()
    return arguments, result


def _release_fixture_native_expectations(
    original: ReleaseInvocation,
    *,
    captured: _ReleaseCapturedFiles,
    record_path: Path,
    expected_inputs: Mapping[str, Sequence[Mapping[str, str]]],
    selection: Mapping[str, Any],
    use_interval: tuple[str, str],
    live: bool,
) -> tuple[dict[str, Any], list[dict[str, Any]]]:
    """Closed constructor dispatch. No caller-supplied expected_operations parameter."""
    if (
        type(live) is not bool
        or live is not False
        or original.intent.get("environment", {}).get("fixture_mode") != "1"
    ):
        raise ReleaseControlError("fixture expectation construction is inaccessible to live mode")
    arguments, inputs = _release_fixture_native_original_inputs(
        original, captured=captured, expected_inputs=expected_inputs
    )
    tool = original.intent["tool"]

    def raw(flag: str) -> bytes:
        return inputs[flag][0][1]

    def path(flag: str) -> Path:
        return inputs[flag][0][0]

    if tool == "capture_linear_release_snapshot.py":
        _release_closed_mapping(
            selection,
            {
                "context_id",
                "context_policy_digest",
                "readiness_digest",
                "original_packet",
                "packet_digest",
                "original_work_orders",
                "work_orders_digest",
                "task_state_policy_raw",
                "task_state_policy_digest",
                "declared_dependencies",
                "observed_at",
                "consumer_stage",
            },
            "fixture Linear graph selectors",
        )
        replay = _release_linear_snapshot_replay(
            record_path,
            captured=captured,
            readiness_registry_raw=raw("registry"),
            expected_readiness_digest=selection["readiness_digest"],
            original_packet=selection["original_packet"],
            expected_packet_digest=selection["packet_digest"],
            original_work_orders=selection["original_work_orders"],
            expected_work_orders_digest=selection["work_orders_digest"],
            task_state_policy_raw=selection["task_state_policy_raw"],
            expected_task_state_policy_digest=selection["task_state_policy_digest"],
            context_id=selection["context_id"],
            declared_dependencies=selection["declared_dependencies"],
            observed_at=selection["observed_at"],
            consumer_stage=selection["consumer_stage"],
        )
        observations = _release_linear_observation_payloads(record_path, captured=captured)
        # Replayed response descriptors are relative to the original snapshot file.
        response_paths = {}
        for row in replay["record"]["data"]["raw_observations"]:
            response = record_path.parent / _release_relative_suffix(
                row["response"]["path"], "fixture Linear original response"
            )
            response_paths[row["id"]] = response.relative_to(original.root).as_posix()
        return _release_fixture_linear_expectations(
            arguments,
            readiness_raw=raw("registry"),
            expected_readiness_digest=selection["readiness_digest"],
            context_id=selection["context_id"],
            expected_context_policy_digest=selection["context_policy_digest"],
            replayed_observations=observations,
            response_paths=response_paths,
        )
    if tool == "record_release_role_assignments.py":
        _release_closed_mapping(
            selection,
            {
                "context_digest",
                "policy_digest",
                "authority_policy_digest",
                "keyring_digest",
                "independently_expected_operator",
            },
            "fixture role selectors",
        )
        replay = _release_original_role_byte_replay(
            path("signed-assignments"),
            context_path=path("release-context"),
            captured=captured,
            expected_context_digest=selection["context_digest"],
            expected_run_id=arguments["run-id"],
            expected_milestone=arguments["milestone"],
            expected_assignment_policy_digest=selection["policy_digest"],
            expected_authority_policy_digest=selection["authority_policy_digest"],
            expected_keyring_digest=selection["keyring_digest"],
            use_interval=use_interval,
            live=False,
        )
        if replay["assignment_policy_bytes"] != raw("policy"):
            raise ReleaseControlError(
                "fixture role protected policy is not its original --policy input"
            )
        return _release_fixture_role_expectations(
            arguments,
            original_role_replay=replay,
            expected_context_digest=selection["context_digest"],
            expected_policy_digest=selection["policy_digest"],
            independently_expected_operator=selection["independently_expected_operator"],
            response_paths={
                role: row["path"].relative_to(original.root).as_posix()
                for role, row in replay["original_provenance"].items()
            },
        )
    if tool == "validate_release_evidence_stores.py":
        _release_closed_mapping(selection, {"registry_digest"}, "fixture preflight selectors")
        return _release_fixture_preflight_expectations(
            arguments,
            registry_raw=raw("stores"),
            expected_registry_digest=selection["registry_digest"],
            backend_controls=_release_fixture_backend_control_capture(
                path("stores"),
                captured=captured,
                expected_registry_digest=selection["registry_digest"],
            ),
        )
    if tool == "capture_release_target_observations.py":
        _release_closed_mapping(
            selection,
            {"context_digest", "registry_digest", "requested_versions"},
            "fixture target selectors",
        )
        return _release_fixture_target_expectations(
            arguments,
            context=_source_json(raw("release-context"), "fixture context"),
            expected_context_digest=selection["context_digest"],
            registry_raw=raw("targets"),
            expected_registry_digest=selection["registry_digest"],
            requested_versions=selection["requested_versions"],
        )
    if tool == "retain_release_evidence.py":
        _release_closed_mapping(
            selection, {"registry_digest", "fixture_run_id"}, "fixture retention selectors"
        )
        return _release_fixture_retention_expectations(
            arguments,
            original_inputs=[value for _, value in inputs.get("input", [])],
            original_manifest=raw("manifest") if "manifest" in inputs else None,
            registry_raw=raw("stores"),
            expected_registry_digest=selection["registry_digest"],
            fixture_run_id=selection["fixture_run_id"],
            backend_controls=_release_fixture_backend_control_capture(
                path("stores"),
                captured=captured,
                expected_registry_digest=selection["registry_digest"],
            ),
        )
    if tool == "update_release_attempt_index.py":
        required = {
            "genesis_raw",
            "genesis_digest",
            "expected_prior_generation",
            "subject_record",
            "subject_path",
            "expected_scope",
            "expected_operation_id",
            "expected_milestone",
            "expected_release_tag",
            "expected_index_backend",
            "expected_prior_head",
            "attempt_directory",
            "expected_attempt_id",
            "coordination_record",
            "coordination_path",
        }
        _release_closed_mapping(selection, required, "fixture original CAS graph selectors")
        original_record = _source_json(
            captured.read(
                record_path.relative_to(captured.root).as_posix(), kind="prerequisite-original"
            ),
            "fixture original CAS receipt",
        )
        binding = _release_index_original_update_binding(
            original_record,
            update=original,
            receipt_path=record_path,
            captured=captured,
            subject_record=selection["subject_record"],
            subject_path=selection["subject_path"],
            expected_scope=selection["expected_scope"],
            expected_operation_id=selection["expected_operation_id"],
            expected_milestone=selection["expected_milestone"],
            expected_release_tag=selection["expected_release_tag"],
            expected_index_backend=selection["expected_index_backend"],
            expected_prior_head=selection["expected_prior_head"],
            expected_synthetic=True,
            attempt_directory=selection["attempt_directory"],
            expected_attempt_id=selection["expected_attempt_id"],
            coordination_record=selection["coordination_record"],
            coordination_path=selection["coordination_path"],
            _fixture_native_genesis_raw=selection["genesis_raw"],
            _fixture_native_prior_generation=selection["expected_prior_generation"],
        )
        return _release_fixture_index_expectations(
            arguments,
            tool=tool,
            genesis_raw=selection["genesis_raw"],
            expected_genesis_digest=selection["genesis_digest"],
            original_entry=binding["entry"],
            expected_prior_generation=selection["expected_prior_generation"],
        )
    if tool in {"export_release_attempt_index.py", "export_release_burn_lineage.py"}:
        _release_closed_mapping(selection, {"genesis_digest"}, "fixture index read selectors")
        return _release_fixture_index_expectations(
            arguments,
            tool=tool,
            genesis_raw=raw("genesis"),
            expected_genesis_digest=selection["genesis_digest"],
        )
    raise ReleaseControlError("fixture native command has no implemented expectation constructor")


def _release_fixture_native_replay(
    original: ReleaseInvocation,
    *,
    captured: _ReleaseCapturedFiles,
    record_path: Path,
    expected_inputs: Mapping[str, Sequence[Mapping[str, str]]],
    selection: Mapping[str, Any],
    proof_refs: Sequence[Mapping[str, Any]],
    use_interval: tuple[str, str],
    live: bool,
) -> _ReleaseFixtureNativeFacts:
    subject, operations = _release_fixture_native_expectations(
        original,
        captured=captured,
        record_path=record_path,
        expected_inputs=expected_inputs,
        selection=selection,
        use_interval=use_interval,
        live=live,
    )
    return _release_fixture_native_receipt_replay(
        original,
        captured=captured,
        subject=subject,
        operations=operations,
        proof_refs=proof_refs,
        live=live,
        use_interval=use_interval,
    )


def _release_fixture_backend_control_capture(
    registry_path: Path, *, captured: _ReleaseCapturedFiles, expected_registry_digest: str
) -> dict[str, dict[str, Any]]:
    """Read six exact original controls per backend under a CLOSED fixture-only wire.

    This wire is explicitly not a production binding or MP2-000 authority policy.
    No executable/module path is loaded from any control.
    """
    raw = captured.read(
        registry_path.relative_to(captured.root).as_posix(), kind="prerequisite-original"
    )
    backends = _release_fixture_backend_rows(raw, expected_digest=expected_registry_digest)
    keys = {
        "public_configuration": {"fixture_only"},
        "owner_binding_authority": {"fixture_actor"},
        "provider_resource_identity": {"resource_id"},
        "administration_identity": {"administration_id"},
        "durability_retention_policy": {"mode", "deletion", "hold"},
        "namespace_policy": {"preflight", "test"},
    }
    result = {}
    paths = set()
    for index, backend in enumerate(backends):
        controls = {}
        for field, fields in keys.items():
            original_path, original_raw = _release_captured_raw_file(
                backend["live_binding"][field],
                containing_path=registry_path,
                containing_kind="prerequisite-original",
                field=("backends", index, "live_binding", field),
                captured=captured,
                expected_kind="prerequisite-original",
                label="fixture original backend " + field,
            )
            if original_path in paths:
                raise ReleaseControlError("fixture backend controls alias one original file")
            paths.add(original_path)
            control = _release_closed_mapping(
                _source_json(original_raw, "fixture backend original control"),
                {"schema_version", "control_kind", "backend_id", "value"},
                "fixture original backend control",
            )
            if (
                control["schema_version"] != "metriplane.release-fixture-backend-control.v1"
                or control["control_kind"] != field
                or control["backend_id"] != backend["backend_id"]
            ):
                raise ReleaseControlError(
                    "fixture original backend control has another type/identity"
                )
            value = _release_closed_mapping(
                control["value"], fields, "fixture backend control value"
            )
            if field == "public_configuration" and value["fixture_only"] is not True:
                raise ReleaseControlError(
                    "fixture public configuration attempts live interpretation"
                )
            if (
                field == "owner_binding_authority"
                and value["fixture_actor"] != _RELEASE_FIXTURE_NATIVE_ACTOR
            ):
                raise ReleaseControlError(
                    "fixture original backend authority is not its fixed test identity"
                )
            if field in {"provider_resource_identity", "administration_identity"}:
                identity = _require_nonempty_string(
                    next(iter(value.values())), "fixture original backend identity"
                )
                if re.fullmatch(r"[A-Za-z0-9][A-Za-z0-9._:-]{0,159}", identity, re.ASCII) is None:
                    raise ReleaseControlError("fixture original resource/admin ID is not canonical")
            if field == "durability_retention_policy" and value != {
                "mode": "retain_indefinitely",
                "deletion": "forbidden",
                "hold": "governance_hold_required",
            }:
                raise ReleaseControlError(
                    "fixture backend retention control changes required policy"
                )
            if field == "namespace_policy" and value != {
                key: backend["namespaces"][key] for key in ("preflight", "test")
            }:
                raise ReleaseControlError("fixture original namespace policy differs from registry")
            controls[field] = value
        result[backend["backend_id"]] = controls
    for field in ("administration_identity", "provider_resource_identity"):
        if result["payload-store-a"][field] == result["payload-store-b"][field]:
            raise ReleaseControlError(
                "fixture original payload controls share a resource or administration"
            )
    captured.revalidate()
    return result


def _release_captured_journal_terminal_content(
    context: ReleaseInvocation,
    *,
    captured: _ReleaseCapturedFiles,
    require_pass: bool,
    gate_pair_owner: bool = False,
) -> dict[str, Any]:
    """Replay original terminal bytes inside a closed captured prerequisite root.

    This proves journal integrity only. Native semantics and original provider
    authority must also pass before a prerequisite can be consumed as authority.
    """

    def read(path: Path) -> bytes:
        try:
            name = path.relative_to(captured.root).as_posix()
        except ValueError as exc:
            raise ReleaseControlError("prerequisite journal escapes captured root") from exc
        return captured.read(name, kind="prerequisite-original")

    def reference(path: Path, kind: str) -> dict[str, str]:
        suffix = path.relative_to(context.root).as_posix()
        _release_relative_suffix(suffix, "original journal reference")
        return {"path": suffix, "schema_id": kind, "sha256": sha256_bytes(read(path))}

    if type(gate_pair_owner) is not bool:
        raise ReleaseControlError("terminal replay has no explicit command owner")
    if gate_pair_owner:
        _release_captured_command_context(
            context, captured=captured, expected_tool="prepare_release_gate_input.py"
        )
    else:
        _release_captured_original_context(context, captured=captured)
    intent = context.intent
    raw = read(context.directory / "invocation.json")
    record = _source_json(raw, "original prerequisite terminal")
    validate_record(record, "release-stage-invocation")
    data = _release_closed_mapping(record["data"], set(_JOURNAL_FIELDS), "original terminal data")
    if raw != canonical_json(record) or (
        record["invocation_id"] != intent["invocation_id"]
        or record["sequence"] != intent["sequence"]
        or record["synthetic"] is not (intent["environment"]["fixture_mode"] == "1")
    ):
        raise ReleaseControlError("original terminal identity differs from its intent")
    for key in ("argv", "tool", "tool_version", "started_at", "previous_invocation_digest"):
        if canonical_json(data[key]) != canonical_json(intent[key]):
            raise ReleaseControlError("original terminal differs from its intent field: " + key)
    if data["invocation_digest"] != sha256_json(
        {key: value for key, value in data.items() if key != "invocation_digest"}
    ):
        raise ReleaseControlError("original terminal semantic digest differs")
    if (
        data["terminal_status"] not in TERMINAL_RESULTS
        or record["status"] != data["terminal_status"]
        or type(data["exit_code"]) is not int
        or data["exit_code"] < 0
        or (data["terminal_status"] == "PASS") != (data["exit_code"] == 0)
        or (require_pass and data["terminal_status"] != "PASS")
    ):
        raise ReleaseControlError("original prerequisite terminal is not a valid required result")
    code = data["exit_code"]
    expected_status = (
        "PASS" if code == 0 else "CANCELLED" if code >= 128 else "BLOCKED" if code == 3 else "FAIL"
    )
    if data["terminal_status"] != expected_status or (code != 0 and data["outputs"] != []):
        raise ReleaseControlError("original terminal differs from its common failure verdict")
    if _parse_utc_timestamp(data["completed_at"], "original completion") < _parse_utc_timestamp(
        intent["started_at"], "original start"
    ):
        raise ReleaseControlError("original prerequisite completion precedes its start")
    for name in ("stdout", "stderr"):
        if sha256_bytes(read(context.directory / name)) != data[name + "_digest"]:
            raise ReleaseControlError("original prerequisite diagnostic bytes differ")
    expected_inputs = [
        reference(context.directory / "intent.json", "metriplane.release-invocation-intent.v1")
    ]
    prior = intent["predecessor"]
    if prior is not None:
        previous_directory = context.directory.parent / f"{prior['sequence']:03d}"
        previous_intent = read(previous_directory / "intent.json")
        if (
            _source_json(previous_intent, "previous prerequisite intent").get("tool")
            != intent["tool"]
        ):
            raise ReleaseControlError("original prerequisite predecessor has a different tool")
        previous = _validate_intent_bytes(previous_directory, previous_intent)
        if (
            previous.intent["tool"] != intent["tool"]
            or sha256_bytes(previous_intent) != prior["intent_digest"]
        ):
            raise ReleaseControlError("original prerequisite predecessor differs")
        expected_inputs.append(
            reference(previous_directory / "intent.json", "metriplane.release-invocation-intent.v1")
        )
        if prior["terminal_digest"] is not None:
            terminal = read(previous_directory / "invocation.json")
            if sha256_bytes(terminal) != prior["terminal_digest"]:
                raise ReleaseControlError("original prerequisite predecessor terminal differs")
            expected_inputs.append(
                reference(
                    previous_directory / "invocation.json", "metriplane.release-stage-invocation.v1"
                )
            )
        elif any(
            row[0] == (previous_directory / "invocation.json").relative_to(captured.root).as_posix()
            for row in captured.rows
        ):
            raise ReleaseControlError("interrupted original prerequisite acquired a terminal")
    # Passing invocations have no failure inventory; failures are replayed by the
    # original failure owner, which must verify the complete partial-files map.
    partial = context.directory / "partial-files.json"
    if any(row[0] == partial.relative_to(captured.root).as_posix() for row in captured.rows):
        if data["terminal_status"] == "PASS":
            raise ReleaseControlError("passing prerequisite has a failure inventory")
        expected_inputs.append(reference(partial, "metriplane.release-partial-files.v1"))
    if canonical_json(data["inputs"]) != canonical_json(
        sorted(expected_inputs, key=lambda row: row["path"])
    ):
        raise ReleaseControlError("original terminal does not bind its complete journal inputs")
    if not isinstance(data["outputs"], list):
        raise ReleaseControlError("original prerequisite output references are missing")
    observed = []
    for output in data["outputs"]:
        row = _release_closed_mapping(output, {"path", "schema_id", "sha256"}, "original output")
        suffix = _release_relative_suffix(row["path"], "original output path")
        _require_nonempty_string(row["schema_id"], "original output type")
        if reference(context.root / suffix, row["schema_id"]) != row:
            raise ReleaseControlError("original terminal output bytes differ")
        observed.append({"path": row["path"], "schema_id": row["schema_id"]})
    if len({row["path"] for row in observed}) != len(observed) or observed != sorted(
        observed, key=lambda row: row["path"]
    ):
        raise ReleaseControlError("original prerequisite output inventory is not canonical")
    if data["terminal_status"] == "PASS" and canonical_json(observed) != canonical_json(
        intent["planned_outputs"]
    ):
        raise ReleaseControlError("original prerequisite outputs do not fill its exact plan")
    worker_name = (context.directory / "worker-result.json").relative_to(captured.root).as_posix()
    if (
        data["terminal_status"] == "PASS"
        and context.intent["tool"] == "validate_release_evidence_stores.py"
        and any(row[0] == worker_name for row in captured.rows)
    ):
        witness_name = (
            (context.directory / "terminal-commit.json").relative_to(captured.root).as_posix()
        )
        if not any(row[0] == witness_name for row in captured.rows):
            raise ReleaseControlError(
                "original evidence-store terminal lacks its durable completion witness"
            )
        witness_raw = read(context.directory / "terminal-commit.json")
        witness = _source_json(witness_raw, "original evidence-store terminal witness")
        expected_witness = {
            "schema_version": "metriplane.gate-terminal-commit.v1",
            "intent_sha256": sha256_json(context.intent),
            "terminal_sha256": sha256_json(record),
        }
        if witness_raw != canonical_json(witness) or witness != expected_witness:
            raise ReleaseControlError(
                "original evidence-store terminal lacks its durable completion witness"
            )
    captured.revalidate()
    return record


def _release_gate_pair_output_content(
    context: ReleaseInvocation,
    *,
    captured: _ReleaseCapturedFiles,
    expected_gate_data: Mapping[str, Any],
    expected_catalog_record: Mapping[str, Any],
) -> dict[str, Any]:
    """Replay both installed gate outputs and their one original common terminal.

    The caller separately reconstructs gate data and catalog from the original
    input plan and native prerequisite graph. This predicate proves only this
    output/worker/terminal boundary; it grants no role/provider authority,
    prerequisite admission, complete retry/namespace proof or public READY.
    Pending worker/supervisor validation cannot enter this completed path.
    """
    _release_captured_command_context(
        context, captured=captured, expected_tool="prepare_release_gate_input.py"
    )
    plan = [{"path": name, "schema_id": kind} for name, kind in _RELEASE_GATE_OUTPUT_PLAN]
    intent = context.intent
    if (
        captured.root != context.root
        or context.directory
        != context.root / "invocations" / "gate-input" / f"{intent['sequence']:03d}"
        or canonical_json(intent["planned_outputs"]) != canonical_json(plan)
    ):
        raise ReleaseControlError("gate pair differs from its fixed root or two-output plan")
    arguments = _release_original_arguments(intent["tool"], intent["argv"])
    cwd = _canonical_absolute_path(
        intent["environment"]["working_directory"], "original gate working directory"
    )
    historical_directory = _release_historical_path(arguments["invocation-dir"], cwd)
    if historical_directory.parts[-3:] != (
        "invocations",
        "gate-input",
        f"{intent['sequence']:03d}",
    ) or _release_historical_path(arguments["out"], cwd) != (
        historical_directory.parents[2] / "gate-input.json"
    ):
        raise ReleaseControlError("gate pair original arguments have different output placement")
    synthetic = intent["environment"]["fixture_mode"] == "1"
    records = {}
    output_refs = []
    for name, kind in _RELEASE_GATE_OUTPUT_PLAN:
        raw = captured.read(name, kind="prerequisite-original")
        value = _source_json(raw, "original gate pair output")
        validate_record(value, kind.removeprefix("metriplane.").removesuffix(".v1"))
        data = value["data"]
        if raw != canonical_json(value) or (
            value["status"] != "PASS"
            or value["signatures"] != []
            or value["synthetic"] is not synthetic
            or value["invocation_id"] != intent["invocation_id"]
            or value["sequence"] != intent["sequence"]
            or data.get("producer_intent_digest") != sha256_json(intent)
            or data.get("invocation_root_locator") != "invocations"
        ):
            raise ReleaseControlError("gate pair output lacks its exact original producer")
        records[name] = value
        output_refs.append({"path": name, "schema_id": kind, "sha256": sha256_bytes(raw)})
    gate = records["gate-input.json"]
    catalog = records["scenario-catalog.json"]
    if (
        canonical_json(gate["data"]) != canonical_json(expected_gate_data)
        or canonical_json(catalog) != canonical_json(expected_catalog_record)
        or gate["data"].get("scenario_catalog_digest") != sha256_json(catalog)
        or gate["data"].get("gate_input_digest")
        != sha256_json({k: v for k, v in gate["data"].items() if k != "gate_input_digest"})
        or gate["data"].get("run_id") != catalog["data"].get("run_id")
    ):
        raise ReleaseControlError("gate pair differs from independently replayed content")
    terminal = _release_captured_journal_terminal_content(
        context, captured=captured, require_pass=True, gate_pair_owner=True
    )
    if canonical_json(terminal["data"]["outputs"]) != canonical_json(output_refs):
        raise ReleaseControlError("gate pair lacks one original terminal for both outputs")
    _release_captured_journal_members(context, captured=captured, terminal=terminal)
    captured.revalidate()
    return {
        "gate_record": gate,
        "catalog_record": catalog,
        "terminal": terminal,
        "producer_intent_digest": sha256_json(intent),
    }


@dataclass(frozen=True)
class _ReleaseGateCompletion:
    """Held byte handoff from gate semantic verification and exclusive installation.

    This private value grants no native input authority. Its producer must first
    replay the full original graph; the live gate remains blocked until wired.
    """

    captured: _ReleaseCapturedFiles
    expected_gate_data: bytes
    expected_catalog_record: bytes


def _release_gate_terminal_commit_record(
    context: ReleaseInvocation, terminal: Mapping[str, Any]
) -> dict[str, str]:
    if context.intent["tool"] != "prepare_release_gate_input.py" or terminal["status"] != "PASS":
        raise ReleaseControlError("gate durability witness has no passing gate owner")
    return {
        "schema_version": "metriplane.gate-terminal-commit.v1",
        "intent_sha256": sha256_json(context.intent),
        "terminal_sha256": sha256_json(terminal),
    }


def _release_gate_terminal_commit_replay(
    context: ReleaseInvocation,
    terminal: Mapping[str, Any] | None,
    *,
    captured: _ReleaseCapturedFiles,
) -> None:
    """Require the original gate PASS prefix witness, never an approval signature."""
    if context.intent["tool"] != "prepare_release_gate_input.py":
        raise ReleaseControlError("gate witness replay has another command owner")
    name = (context.directory / "terminal-commit.json").relative_to(captured.root).as_posix()
    if terminal is None or terminal["status"] != "PASS":
        if any(row[0] == name for row in captured.rows) or os.path.lexists(
            context.directory / "terminal-commit.json"
        ):
            raise ReleaseControlError("negative or interrupted gate acquired a success witness")
    else:
        raw = captured.read(name, kind="prerequisite-original")
        if raw != canonical_json(_release_gate_terminal_commit_record(context, terminal)):
            raise ReleaseControlError(
                "original gate terminal durability witness is missing or differs"
            )
    captured.revalidate()


def _release_gate_commit_success(
    context: _ReleaseGateInvocation,
    directory_fd: int,
    terminal_capture: _ReleaseCapturedFiles,
    completion: _ReleaseGateCompletion,
) -> None:
    """Create the witness only after the complete actual held PASS prefix is durable."""
    _release_gate_journal_barrier(context, directory_fd)
    if "terminal-commit.json" in os.listdir(directory_fd):
        raise ReleaseControlError("gate acquired a premature durability witness")
    carried = completion.captured
    expected_names = {
        "gate-input.json",
        "scenario-catalog.json",
        *(
            str((context.directory / name).relative_to(context.root))
            for name in (
                "worker.pid",
                "worker-result.json",
                "staged/gate-input.json",
                "staged/scenario-catalog.json",
            )
        ),
    }
    if (
        carried.root != context.root
        or carried.root_directories != context.intent_capture.root_directories
        or {row[0] for row in carried.rows} != expected_names
        or any(row[1] != "prerequisite-original" for row in carried.rows)
    ):
        raise ReleaseControlError(
            "gate completion lost its exact held worker/staged/installed capture"
        )
    carried.revalidate()
    terminal_capture.revalidate()
    rows = (*terminal_capture.rows, *carried.rows)
    if len({row[0] for row in rows}) != len(rows):
        raise ReleaseControlError("gate completion captures overlap")
    joined = _ReleaseCapturedFiles(context.root, carried.root_directories, rows)
    joined.revalidate()
    expected_gate = _source_json(completion.expected_gate_data, "gate independently replayed data")
    expected_catalog = _source_json(
        completion.expected_catalog_record, "gate independently replayed catalog"
    )
    result = _release_gate_pair_output_content(
        context,
        captured=joined,
        expected_gate_data=expected_gate,
        expected_catalog_record=expected_catalog,
    )
    # Namespace closure uses the actual held directory, including empty/special extras.
    required = {
        "intent.json",
        "stdout",
        "stderr",
        "worker.pid",
        "worker-result.json",
        "staged",
        "invocation.json",
    }
    if set(os.listdir(directory_fd)) != required:
        raise ReleaseControlError("gate precommit journal has an unowned member")
    staged_rows = [
        row
        for row in carried.rows
        if (carried.root / row[0]).parent == context.directory / "staged"
    ]
    stage_fd = _release_gate_open_pinned_directory(context.directory / "staged", staged_rows[0][4])
    root_fd: int | None = None
    try:
        root_fd = _release_gate_open_pinned_directory(context.root, carried.root_directories)
        if set(os.listdir(stage_fd)) != {"gate-input.json", "scenario-catalog.json"}:
            raise ReleaseControlError("gate precommit staged namespace is not closed")
        # Every named original file is synced through its actual held inode; this
        # includes worker/staged/install bytes and the just-created terminal.
        for name, _, _, identity, ancestors in joined.rows:
            path = joined.root / name
            parent_fd = _release_gate_open_pinned_directory(path.parent, ancestors)
            descriptor: int | None = None
            try:
                descriptor = os.open(
                    path.name, os.O_RDONLY | os.O_NOFOLLOW | os.O_NONBLOCK, dir_fd=parent_fd
                )
                if _release_gate_file_identity(os.fstat(descriptor)) != identity:
                    raise ReleaseControlError("gate precommit file changed before fsync")
                os.fsync(descriptor)
                if (
                    _release_gate_file_identity(os.fstat(descriptor)) != identity
                    or _release_gate_file_identity(
                        os.stat(path.name, dir_fd=parent_fd, follow_symlinks=False)
                    )
                    != identity
                ):
                    raise ReleaseControlError("gate precommit file changed during fsync")
            finally:
                _release_gate_completion_close(
                    [parent_fd, *([descriptor] if descriptor is not None else [])]
                )
        os.fsync(stage_fd)
        os.fsync(root_fd)
        os.fsync(directory_fd)
        if (
            set(os.listdir(stage_fd)) != {"gate-input.json", "scenario-catalog.json"}
            or set(os.listdir(directory_fd)) != required
        ):
            raise ReleaseControlError("gate precommit namespace changed during fsync")
        joined.revalidate()
        _validate_bound_invocation(context)
        _release_gate_journal_barrier(context, directory_fd)
        # The final semantic and journal checks can themselves expose replacement.
        # Recheck the whole held prefix and exact namespaces after those owners,
        # immediately before creating the finite durability witness.
        context.gate_inputs.captured.revalidate()
        if (
            set(os.listdir(stage_fd)) != {"gate-input.json", "scenario-catalog.json"}
            or set(os.listdir(directory_fd)) != required
        ):
            raise ReleaseControlError("gate precommit namespace changed after final validation")
        joined.revalidate()
        identity = _release_gate_write_json_at(
            directory_fd,
            "terminal-commit.json",
            _release_gate_terminal_commit_record(context, result["terminal"]),
        )
        receipt_capture = _release_gate_journal_capture_at(
            context, directory_fd, {"terminal-commit.json": identity}
        )
        receipt_name = (
            (context.directory / "terminal-commit.json").relative_to(context.root).as_posix()
        )
        receipt_rows = tuple(row for row in receipt_capture.rows if row[0] == receipt_name)
        committed = _ReleaseCapturedFiles(
            joined.root, joined.root_directories, (*joined.rows, *receipt_rows)
        )
        _release_gate_terminal_commit_replay(context, result["terminal"], captured=committed)
        if set(os.listdir(stage_fd)) != {"gate-input.json", "scenario-catalog.json"} or set(
            os.listdir(directory_fd)
        ) != required | {"terminal-commit.json"}:
            raise ReleaseControlError("gate committed namespace changed during witness creation")
        context.gate_inputs.captured.revalidate()
        committed.revalidate()
    finally:
        _release_gate_completion_close([stage_fd, *([root_fd] if root_fd is not None else [])])


def _release_gate_completion_close(descriptors: Sequence[int]) -> None:
    """Attempt every owned close even if another descriptor reports a failure."""
    errors: list[OSError] = []
    for descriptor in reversed(descriptors):
        try:
            os.close(descriptor)
        except OSError as exc:
            errors.append(exc)
    if errors:
        raise ReleaseControlError("gate completion descriptor cleanup failed") from errors[0]


def _release_gate_pair_capture_handoff(
    context: ReleaseInvocation,
    output_root: Path,
    captured: _ReleaseCapturedFiles,
) -> _ReleaseCapturedFiles:
    """Preserve the caller's actual two-file capture through semantic replay and copy.

    The caller must hold actual writer or prior replay identities before this
    boundary. This validates byte custody only and grants no native authority.
    """
    if not isinstance(captured, _ReleaseCapturedFiles) or captured.root != context.root:
        raise ReleaseControlError("gate output handoff has another original root")
    if output_root not in {context.root, context.directory / "staged"}:
        raise ReleaseControlError("gate output handoff has another fixed output owner")
    expected = {
        (output_root / name).relative_to(context.root).as_posix(): kind
        for name, kind in _RELEASE_GATE_OUTPUT_PLAN
    }
    if len(captured.rows) != len(expected) or {row[0]: row[1] for row in captured.rows} != expected:
        raise ReleaseControlError("gate output handoff changes its exact member/type census")
    if isinstance(context, _ReleaseGateInvocation):
        if captured.root_directories != context.gate_inputs.captured.root_directories:
            raise ReleaseControlError("gate output handoff discards original root custody")
        original_ancestors = context.intent_capture.rows[0][4]
        if output_root == context.directory / "staged" and any(
            row[4][:-1] != original_ancestors or row[4][-1][0] != str(output_root)
            for row in captured.rows
        ):
            raise ReleaseControlError("gate output handoff discards original journal custody")
        context.gate_inputs.captured.revalidate()
        context.intent_capture.revalidate()
    if any((captured.root / row[0]).parent != output_root for row in captured.rows):
        raise ReleaseControlError("gate output handoff has an unowned nested member")
    captured.revalidate()
    return captured


_RELEASE_FIXTURE_SEED_SCHEMA = "metriplane.release-fixture-native-seed.v1"
_RELEASE_FIXTURE_TRANSCRIPT_MAX_AGE_SECONDS = 300
_RELEASE_FIXTURE_API_VERSION = "metriplane.release-fixture-native-request.v1"


def _release_linear_observation_content(
    data: Mapping[str, Any],
    *,
    read_response: Callable[[int, object], tuple[Path, bytes]],
    revalidate: Callable[[], None],
) -> dict[str, dict[str, Any]]:
    """Shared original response semantics, also usable on held fixture seed facts.

    The caller owns original record/schema/R and the exact declaring-field loader.
    This pure parser never establishes provider or completed-journal authority.
    """
    start = _parse_utc_timestamp(data["capture_started_at"], "Linear capture start")
    end = _parse_utc_timestamp(data["capture_completed_at"], "Linear capture completion")
    if end < start:
        raise ReleaseControlError("Linear capture completion precedes its start")
    observations = _release_id_rows(data["raw_observations"], "id", "original Linear observations")
    if not observations:
        raise ReleaseControlError("original Linear snapshot has no response inventory")
    result = {}
    intervals: dict[int, list[tuple[datetime, datetime]]] = {1: [], 2: []}
    response_paths: set[Path] = set()
    for index, value in enumerate(observations.values()):
        observation = _release_closed_mapping(
            value,
            {
                "id",
                "round",
                "tool",
                "arguments",
                "started_at",
                "completed_at",
                "response",
                "extracted_json_pointer",
                "capture_status",
                "payload_encoding",
            },
            "original Linear observation",
        )
        if type(observation["round"]) is not int or observation["round"] not in {1, 2}:
            raise ReleaseControlError("original Linear observation has an invalid capture round")
        observed_start = _parse_utc_timestamp(observation["started_at"], "Linear observation start")
        observed_end = _parse_utc_timestamp(
            observation["completed_at"], "Linear observation completion"
        )
        if (
            not start <= observed_start <= observed_end <= end
            or observation["capture_status"] != "SUCCESS"
        ):
            raise ReleaseControlError(
                "original Linear observation is incomplete or outside its capture"
            )
        intervals[observation["round"]].append((observed_start, observed_end))
        arguments = observation["arguments"]
        if not isinstance(arguments, dict):
            raise ReleaseControlError("original Linear request is not a closed mapping")
        tool = observation["tool"]
        if not isinstance(tool, str):
            raise ReleaseControlError("Linear observation has no native tool identity")
        if tool == "mcp__codex_apps__linear_list_issues":
            _release_closed_mapping(
                arguments,
                {"project", "includeArchived", "limit", "orderBy", "fields"}
                | ({"cursor"} if "cursor" in arguments else set()),
                "original Linear project request",
            )
            _release_linear_uuid(arguments["project"], "Linear requested project")
            fields = _release_id_list(arguments["fields"], "Linear requested fields", nonempty=True)
            if (
                arguments["includeArchived"] is not True
                or type(arguments["limit"]) is not int
                or arguments["limit"] != 250
                or arguments["orderBy"] != "createdAt"
                or set(fields) != set(_RELEASE_LINEAR_INDEX_FIELDS)
            ):
                raise ReleaseControlError(
                    "Linear project request filters or truncates required fields"
                )
            if "cursor" in arguments:
                _require_nonempty_string(arguments["cursor"], "Linear page cursor")
        elif tool == "mcp__codex_apps__linear_get_issue":
            _release_closed_mapping(
                arguments, {"id", "includeRelations"}, "original Linear detail request"
            )
            if (
                arguments["includeRelations"] is not True
                or not isinstance(arguments["id"], str)
                or re.fullmatch(r"[A-Z][A-Z0-9]*-[1-9][0-9]*", arguments["id"], re.ASCII) is None
            ):
                raise ReleaseControlError("Linear detail request lacks exact identity/relations")
        elif tool in {
            "mcp__codex_apps__linear_list_issue_statuses",
            "mcp__codex_apps__linear_list_milestones",
        }:
            key = "team" if tool == "mcp__codex_apps__linear_list_issue_statuses" else "project"
            _release_closed_mapping(arguments, {key}, "original Linear dictionary request")
            _release_linear_uuid(arguments[key], "Linear dictionary owner")
        else:
            raise ReleaseControlError("Linear observation has an unsupported native response owner")
        response_path, response_raw = read_response(index, observation["response"])
        if response_path in response_paths:
            raise ReleaseControlError("Linear observations reuse an original response namespace")
        response_paths.add(response_path)
        try:
            response = _release_closed_mapping(
                _source_json(response_raw, "original Linear response"),
                {"content", "isError"},
                "original Linear tool envelope",
            )
        except RecursionError as exc:
            raise ReleaseControlError("original Linear response exceeds parser nesting") from exc
        if (
            response["isError"] is not False
            or not isinstance(response["content"], list)
            or len(response["content"]) != 1
        ):
            raise ReleaseControlError("Linear original response is an error or ambiguous content")
        content = _release_closed_mapping(
            response["content"][0], {"type", "text"}, "original Linear text content"
        )
        if (
            content["type"] != "text"
            or not isinstance(content["text"], str)
            or observation["payload_encoding"] != "json_text"
            or observation["extracted_json_pointer"] != "/content/0/text"
        ):
            raise ReleaseControlError(
                "Linear original response extraction is not its fixed native wire"
            )
        try:
            payload = json.loads(content["text"], object_pairs_hook=_closed_json_object)
            canonical_json(payload)
        except (ValueError, UnicodeError, RecursionError) as exc:
            raise ReleaseControlError(
                "Linear original response payload is invalid closed JSON"
            ) from exc
        if not isinstance(payload, (dict, list)):
            raise ReleaseControlError("Linear original response has no native object/array payload")
        if isinstance(payload, dict) and any(
            key in payload for key in ("error", "errors", "isError", "truncated", "isTruncated")
        ):
            raise ReleaseControlError("Linear original payload reports an error or truncation")
        result[observation["id"]] = {"observation": observation, "payload": payload}
    if not all(intervals.values()) or max(end for _, end in intervals[1]) > min(
        start for start, _ in intervals[2]
    ):
        raise ReleaseControlError("Linear capture lacks two distinct ordered complete rounds")
    revalidate()
    return result


def _release_linear_snapshot_projection(
    registry: Mapping[str, Any],
    *,
    payloads: Mapping[str, Mapping[str, Any]],
    original_packet: bytes,
    expected_packet_digest: str,
    original_work_orders: bytes,
    expected_work_orders_digest: str,
    task_state_policy_raw: bytes,
    expected_task_state_policy_digest: str,
    context_id: str,
    declared_dependencies: Mapping[str, Sequence[str]],
) -> dict[str, Any]:
    """Shared complete graph/BOM/lifecycle content; freshness and authority are callers' gates."""
    catalog = _release_readiness_catalog_projection(
        registry, original_packet=original_packet, expected_packet_digest=expected_packet_digest
    )
    contexts = _release_id_rows(
        registry.get("release_contexts"), "context_id", "Linear context policies"
    )
    if context_id not in contexts:
        raise ReleaseControlError("Linear capture context is not governed")
    context = contexts[context_id]
    bindings = _release_id_rows(
        registry.get("provider_issue_bindings"), "issue_identifier", "Linear provider bindings"
    )
    catalogue_ids = set()
    for row in registry["task_catalog"]:
        identifier = row["linear_issue"]
        if identifier not in bindings:
            raise ReleaseControlError("Linear capture lacks a catalogue identity binding")
        catalogue_ids.add(_release_linear_identity(bindings[identifier]["identity"])["issue_id"])
    decision = _release_linear_identity(context["decision"], require_project=True)
    direct = [
        _release_linear_identity(row, require_project=True) for row in context["direct_gate_issues"]
    ]
    direct_ids = {row["issue_id"] for row in direct}
    roots = frozenset(catalogue_ids | direct_ids | {decision["issue_id"]})
    capture_policy = _release_closed_mapping(
        registry.get("linear_capture_policy"),
        {
            "follow_cross_project_blockers",
            "include_all_catalog_tasks",
            "include_all_roadmap_gate_slots",
            "include_archived",
            "nonblocking_relation_disposition",
            "provider_snapshot_atomicity",
            "provider_transport_binding",
            "require_reciprocal_blocking_relations",
            "root_project_ids",
            "stable_complete_rounds",
            "unknown_dependency_disposition",
        },
        "original Linear capture policy",
    )
    if (
        any(
            capture_policy[key] is not True
            for key in (
                "follow_cross_project_blockers",
                "include_all_catalog_tasks",
                "include_all_roadmap_gate_slots",
                "include_archived",
                "require_reciprocal_blocking_relations",
            )
        )
        or canonical_json(capture_policy["stable_complete_rounds"]) != b"2"
        or capture_policy["nonblocking_relation_disposition"]
        != "RETAIN_ENDPOINTS_NOT_AUTOMATIC_BOM"
        or capture_policy["provider_snapshot_atomicity"] != "not_claimed"
        or capture_policy["unknown_dependency_disposition"]
        != "BLOCKED_REQUIRES_EXPLICIT_POLICY_BINDING"
    ):
        raise ReleaseControlError(
            "Linear raw capture policy changes its governed coverage constraints"
        )
    projects = frozenset(
        _release_id_list(
            capture_policy.get("root_project_ids"), "Linear governed root projects", nonempty=True
        )
    )
    rounds = [
        _release_linear_round_projection(
            payloads, round_number=number, root_project_ids=projects, root_issue_ids=roots
        )
        for number in (1, 2)
    ]
    if canonical_json(rounds[0]["semantic"]) != canonical_json(rounds[1]["semantic"]):
        raise ReleaseControlError("Linear complete capture rounds differ")
    latest = rounds[1]
    unbound = sorted(
        row["identity"]["issue_identifier"]
        for row in latest["issues"]
        if row["identity"]["issue_identifier"] not in bindings
    )
    if unbound:
        raise ReleaseControlError(
            "Linear captured issues require explicit policy bindings: " + ", ".join(unbound)
        )
    for row in latest["issues"]:
        binding = bindings[row["identity"]["issue_identifier"]]
        if canonical_json(row["identity"]) != canonical_json(
            binding.get("identity")
        ) or canonical_json(row["project_milestone"]) != canonical_json(
            binding.get("expected_milestone")
        ):
            raise ReleaseControlError(
                "Linear captured issue identity/assignment differs from its policy binding: "
                + row["identity"]["issue_identifier"]
            )
    catalog_dependencies = _release_linear_catalog_dependencies(
        registry,
        issues=latest["issues"],
        original_packet=original_packet,
        expected_packet_digest=expected_packet_digest,
        original_work_orders=original_work_orders,
        expected_work_orders_digest=expected_work_orders_digest,
    )
    # Context/noncatalog amendments still require their independently bound
    # native authority. Caller projections cannot overwrite the original catalog.
    dependencies = dict(declared_dependencies)
    for identifier, original_dependencies in catalog_dependencies.items():
        supplied = dependencies.get(identifier)
        if not isinstance(supplied, (list, tuple)) or set(
            _release_id_list(list(supplied), "catalog dependency projection", nonempty=False)
        ) != set(original_dependencies):
            raise ReleaseControlError("Linear dependency projection changed original work orders")
        dependencies[identifier] = original_dependencies
    projection = _release_linear_bom_projection(
        registry,
        context_id=context_id,
        issues=latest["issues"],
        original_packet=original_packet,
        expected_packet_digest=expected_packet_digest,
        declared_dependencies=dependencies,
    )
    issue_rows = _release_linear_issue_rows(latest["issues"], root_issue_ids=roots)
    _release_linear_lifecycle(
        projection,
        issues=issue_rows,
        team_statuses=latest["team_statuses"],
        task_state_policy_raw=task_state_policy_raw,
        expected_task_state_policy_digest=expected_task_state_policy_digest,
    )
    coverage = {
        "root_project_ids": sorted(projects),
        "root_catalog_issue_ids": sorted(catalogue_ids),
        "root_current_decision_id": decision["issue_id"],
        "root_direct_gate_ids": sorted(direct_ids),
        "blocking_closure_issue_ids": latest["blocking_closure_issue_ids"],
        "relation_endpoint_issue_ids": latest["relation_endpoint_issue_ids"],
        "unresolved_issue_identifiers": [],
        "unresolved_pages": [],
        "excluded_required_issues": [],
    }
    expected = {
        "catalog_projection_digest": sha256_json(catalog),
        "framework_milestone": context["framework_milestone"],
        "task_id": decision["issue_identifier"],
        "decision_issue_id": decision["issue_id"],
        "state": issue_rows[decision["issue_id"]]["state"]["name"],
        "project_scans": rounds[0]["project_scans"] + latest["project_scans"],
        "issues": latest["issues"],
        "team_statuses": latest["team_statuses"],
        "project_milestones": latest["project_milestones"],
        "catalog_issue_ids": sorted(catalogue_ids),
        "direct_gate_issue_ids": sorted(direct_ids),
        "coverage": coverage,
        "stabilization": {
            "rounds": 2,
            "method": "two-complete-equal-projections-no-atomic-snapshot-claim",
            "round_1_projection_digest": rounds[0]["projection_digest"],
            "round_2_projection_digest": latest["projection_digest"],
        },
        **{
            key: projection[key]
            for key in ("required_bom_ids", "required_bom", "required_bom_snapshot_digest")
        },
    }
    return {"expected": expected, "projection": projection}


def _release_linear_provider_clock(
    payloads: Mapping[str, Mapping[str, Any]], policy: Mapping[str, Any]
) -> None:
    """Compare provider fields to original observation times, never a later emulation clock."""
    for member in payloads.values():
        if member["observation"]["tool"] != "mcp__codex_apps__linear_get_issue":
            continue
        completed = _parse_utc_timestamp(
            member["observation"]["completed_at"], "Linear detail completion"
        )
        for key in (
            "createdAt",
            "updatedAt",
            "archivedAt",
            "completedAt",
            "startedAt",
            "canceledAt",
        ):
            value = member["payload"].get(key)
            if (
                value is not None
                and (
                    _parse_utc_timestamp(value, "Linear provider " + key) - completed
                ).total_seconds()
                > policy["server_clock_skew_budget_seconds"]["capture"]
            ):
                raise ReleaseControlError(
                    "Linear provider timestamp exceeds the capture clock budget"
                )


def _release_index_update_subject_content(
    *,
    root: Path,
    receipt_path: Path,
    captured: _ReleaseCapturedFiles,
    manifest_path: Path,
    manifest_raw: bytes,
    manifest: Mapping[str, Any],
    retention: Mapping[str, Any],
    subject_path: Path,
    subject_record: Mapping[str, Any],
    scope: Mapping[str, Any],
    expected_milestone: str,
    expected_release_tag: str,
    expected_synthetic: bool,
    attempt_directory: Path | None = None,
    expected_attempt_id: str | None = None,
    coordination_record: Mapping[str, Any] | None = None,
    coordination_path: Path | None = None,
) -> None:
    """Same original subject/manifest/retention content before or after intent reservation.

    No receipt/token/producer claim is constructed. Caller binds original typed
    inputs and independent command scope; native journal/admission remains separate.
    """
    purpose = (scope["kind"], scope["stage"])
    if purpose not in {
        ("release_staging", "target-burn"),
        ("release_staging", "staging-failure"),
        ("release_candidate", "qualification-attempt"),
    }:
        raise ReleaseControlError("index subject has no existing content owner")

    def original(
        path: Path, supplied: Mapping[str, Any], kind: str
    ) -> tuple[bytes, dict[str, Any]]:
        path = _release_capture_absolute(path)
        if not path.is_relative_to(root):
            raise ReleaseControlError("index original graph member escapes its current root")
        raw = captured.read(
            path.relative_to(captured.root).as_posix(), kind="prerequisite-original"
        )
        actual = _source_json(raw, "index original " + kind)
        validate_record(actual, kind)
        if (
            canonical_json(actual) != canonical_json(supplied)
            or actual["synthetic"] != expected_synthetic
        ):
            raise ReleaseControlError(
                "index original record differs from selected complete subject or mode"
            )
        return raw, actual

    entries = _release_evidence_manifest_content(manifest["data"])
    phase = purpose[1] if purpose[0] == "release_staging" else "attempt"
    if manifest["data"]["phase"] != phase:
        raise ReleaseControlError("original index manifest has a different phase")
    _validate_retention_payload(
        retention["data"],
        expected_input_digest=sha256_bytes(manifest_raw),
        expected_phase=phase,
        label="original index retention",
    )
    entry_root = _release_index_manifest_entry_root(
        root=root, manifest_path=manifest_path, manifest=manifest, scope=scope
    )
    if any(entry_root / row["path"] == receipt_path for row in entries):
        raise ReleaseControlError("index input manifest refers to its future receipt output")

    def manifested(path: Path, record: Mapping[str, Any], kind: str) -> dict[str, Any]:
        raw, actual = original(path, record, kind)
        matches = [row for row in entries if entry_root / row["path"] == path]
        if (
            len(matches) != 1
            or matches[0]["sha256"] != sha256_bytes(raw)
            or matches[0]["size"] != len(raw)
        ):
            raise ReleaseControlError(
                "manifest omits or rebinds the exact original subject path/R/size"
            )
        return actual

    if purpose == ("release_staging", "staging-failure"):
        failure = manifested(subject_path, subject_record, "release-staging-attempt")["data"]
        if (
            failure.get("stage") not in {"attempt-index-update", "attempt-index-validation"}
            or failure.get("result") not in {"FAIL", "BLOCKED", "CANCELLED"}
            or failure.get("disposition") != "TERMINAL"
            or failure.get("milestone") != expected_milestone
            or failure.get("run_id") != scope["run_id"]
            or failure.get("recovery_envelope_digest") is not None
        ):
            raise ReleaseControlError(
                "staging index subject is not its exact original failure family"
            )
        _require_digest(
            failure.get("failed_invocation_digest"), "staging index failed original terminal C"
        )
    elif purpose[0] == "release_staging":
        burn = manifested(subject_path, subject_record, "release-target-burn")["data"]
        if (
            burn.get("disposition") != "new_burn"
            or burn.get("indexing_required") is not True
            or burn.get("milestone") != expected_milestone
            or burn.get("resolved_release_tag") != expected_release_tag
        ):
            raise ReleaseControlError(
                "original target burn does not require this selected index entry"
            )
    else:
        attempt_id = _require_nonempty_string(
            expected_attempt_id, "original logical attempt identity"
        )
        if attempt_directory is None or coordination_path is None or coordination_record is None:
            raise ReleaseControlError("original qualification attempt graph is incomplete")
        directory = _release_capture_absolute(attempt_directory)
        coordination_path = _release_capture_absolute(coordination_path)
        if (
            not directory.is_relative_to(root)
            or directory.name != attempt_id
            or subject_path.parent != directory
            or coordination_path.parent != directory
            or manifest_path.parent != directory
        ):
            raise ReleaseControlError(
                "original attempt inputs differ from their selected attempt directory"
            )
        attempt = manifested(subject_path, subject_record, "release-attempt")["data"]
        coordination = manifested(
            coordination_path, coordination_record, "release-attempt-coordination"
        )["data"]
        if any(
            row.get("attempt_id") != attempt_id
            or row.get("candidate_digest") != scope["candidate_id"]
            or row.get("milestone") != expected_milestone
            for row in (attempt, coordination)
        ):
            raise ReleaseControlError(
                "original attempt/coordination identity differs from selected operation"
            )
        # Complete plan/cell/termination/coordination digest replay is the original
        # S4 attempt owner's prerequisite; do not invent its not-yet-adopted wire.
    captured.revalidate()


def _release_fixture_close_descriptors(descriptors: Sequence[int]) -> None:
    failures: list[OSError] = []
    for descriptor in descriptors:
        try:
            os.close(descriptor)
        except OSError as exc:
            failures.append(exc)
    if failures:
        raise ReleaseControlError(
            "fixture cleanup failed for " + str(len(failures)) + " held descriptors"
        ) from failures[0]


@dataclass(frozen=True)
class _ReleaseFixtureDirectory:
    path: Path
    descriptors: tuple[int, ...]
    links: tuple[tuple[int, str, int], ...]
    identities: tuple[tuple[str, int, int, int], ...]

    @property
    def fd(self) -> int:
        return self.descriptors[-1]

    def revalidate(self) -> None:
        if (
            len(self.descriptors) != len(self.identities)
            or len(self.links) != len(self.descriptors) - 1
            or not self.identities
            or self.identities[-1][0] != str(self.path)
        ):
            raise ReleaseControlError("fixture held directory identity inventory differs")
        for descriptor, expected in zip(self.descriptors, self.identities, strict=True):
            info = os.fstat(descriptor)
            if (info.st_dev, info.st_ino, info.st_mode) != expected[1:]:
                raise ReleaseControlError("fixture held directory object changed before effects")
        for parent, name, child in self.links:
            held = os.fstat(child)
            visible = os.stat(name, dir_fd=parent, follow_symlinks=False)
            if (held.st_dev, held.st_ino, held.st_mode) != (
                visible.st_dev,
                visible.st_ino,
                visible.st_mode,
            ):
                raise ReleaseControlError("fixture held directory namespace was substituted")

    def close(self) -> None:
        _release_fixture_close_descriptors(tuple(reversed(self.descriptors)))


def _release_fixture_directory(
    path: Path, *, expected: Sequence[tuple[str, int, int, int]]
) -> _ReleaseFixtureDirectory:
    """Open each directory without following links, checking old pins before descent."""
    path = _release_capture_absolute(path)
    known: dict[str, tuple[str, int, int, int]] = {}
    for row in expected:
        if row[0] in known and known[row[0]] != row:
            raise ReleaseControlError("fixture supplied directory identities conflict")
        known[row[0]] = row
    descriptors: list[int] = []
    links = []
    identities = []
    try:
        visible = Path(path.anchor)
        descriptor = os.open(path.anchor, os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW)
        descriptors.append(descriptor)
        for index, name in enumerate((None, *path.parts[1:])):
            if index:
                assert name is not None
                child = os.open(
                    name, os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW, dir_fd=descriptor
                )
                descriptors.append(child)
                links.append((descriptor, name, child))
                descriptor = child
                visible /= name
            info = os.fstat(descriptor)
            row = (str(visible), info.st_dev, info.st_ino, info.st_mode)
            if str(visible) in known and known[str(visible)] != row:
                raise ReleaseControlError("fixture directory changed before dependent access")
            identities.append(row)
        result = _ReleaseFixtureDirectory(path, tuple(descriptors), tuple(links), tuple(identities))
        result.revalidate()
        return result
    except BaseException:
        _release_fixture_close_descriptors(tuple(reversed(descriptors)))
        raise


def _release_fixture_seed_namespace(
    captured: _ReleaseCapturedFiles, seed_name: str, member_ids: set[str]
) -> None:
    """Only this stage/sequence slot is owned; unrelated sibling invocations remain untouched."""
    pins = (*captured.root_directories, *(x for row in captured.rows for x in row[4]))
    slot = _release_fixture_directory(captured.root / Path(seed_name).parent, expected=pins)
    raw_fd: int | None = None
    try:
        expected = {"seed.json", "raw"} if member_ids else {"seed.json"}
        if set(os.listdir(slot.fd)) != expected:
            raise ReleaseControlError("fixture seed slot has missing or extra physical members")
        if member_ids:
            raw_fd = os.open("raw", os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW, dir_fd=slot.fd)
            info = os.fstat(raw_fd)
            raw_path = str(slot.path / "raw")
            known = [x for x in pins if x[0] == raw_path]
            if not known or any(
                x != (raw_path, info.st_dev, info.st_ino, info.st_mode) for x in known
            ):
                raise ReleaseControlError("fixture seed raw directory changed before census")
            if set(os.listdir(raw_fd)) != {identity + ".bin" for identity in member_ids}:
                raise ReleaseControlError(
                    "fixture seed raw namespace differs from its full declaration"
                )
            for identity in member_ids:
                info = os.stat(identity + ".bin", dir_fd=raw_fd, follow_symlinks=False)
                if not stat.S_ISREG(info.st_mode) or info.st_nlink != 1:
                    raise ReleaseControlError("fixture raw namespace has an unsafe original member")
        slot.revalidate()
    except OSError as exc:
        raise ReleaseControlError("fixture seed namespace cannot be inspected safely") from exc
    finally:
        _release_fixture_close_descriptors(
            (() if raw_fd is None else (raw_fd,)) + tuple(reversed(slot.descriptors))
        )


@dataclass(frozen=True)
class _ReleaseFixtureSeedPlan:
    captured: _ReleaseCapturedFiles
    seed_path: str
    seed_digest: str
    input_plan: tuple[tuple[str, str, str], ...]
    tool: str
    argv: tuple[str, ...]
    working_directory: Path
    directory: Path
    subject: bytes
    operations: tuple[bytes, ...]
    output_plan: tuple[tuple[str, str], ...]
    response_payloads: tuple[bytes, ...]
    artifact_payloads: tuple[tuple[str, bytes], ...]
    transcript: bytes


def _release_fixture_seed_location(
    tool: str, argv: Sequence[str], cwd: Path, root: Path
) -> tuple[dict[str, Any], Path, str]:
    if tool not in _RELEASE_GATE_PREREQUISITES:
        raise ReleaseControlError("fixture seed has no existing prerequisite owner")
    arguments = _release_original_arguments(tool, list(argv))
    directory = _release_historical_path(arguments["invocation-dir"], cwd)
    if directory.parent != root / "invocations" / _invocation_stage(tool):
        raise ReleaseControlError("fixture seed invocation has another original root/stage")
    if (
        re.fullmatch(r"[0-9]{3,}", directory.name, re.ASCII) is None
        or directory.name != f"{int(directory.name):03d}"
        or int(directory.name) < 1
    ):
        raise ReleaseControlError("fixture seed has a noncanonical original sequence")
    name = f"inputs/fixture-native/{_invocation_stage(tool)}/{directory.name}/seed.json"
    return arguments, directory, name


def _release_fixture_seed_capture(
    tool: str,
    argv: Sequence[str],
    *,
    working_directory: Path,
    held_inputs: _ReleaseCapturedFiles,
    live: bool,
) -> tuple[
    _ReleaseCapturedFiles, dict[str, Any], dict[str, dict[str, Any]], dict[str, bytes], Path, str
]:
    """Extend the existing held input custody before reading any supplied seed member."""
    if (
        type(live) is not bool
        or live is not False
        or os.environ.get("METRIPLANE_RELEASE_FIXTURE_MODE") != "1"
    ):
        raise ReleaseControlError("fixture seed is inaccessible to live execution")
    cwd = _release_capture_absolute(working_directory)
    held_inputs.revalidate()
    _, directory, name = _release_fixture_seed_location(tool, argv, cwd, held_inputs.root)
    existing = {row[0]: row for row in held_inputs.rows}
    known = tuple(dict.fromkeys(row for member in held_inputs.rows for row in member[4]))
    seed_capture = _ReleaseCapturedFiles.capture(
        held_inputs.root,
        [(name, "prerequisite-original")],
        forbidden=(),
        allowed_kinds=frozenset({"prerequisite-original"}),
        expected_root_directories=held_inputs.root_directories,
        expected_known_directories=known,
        expected_file_identities=None if name not in existing else {name: existing[name][3]},
    )
    raw = seed_capture.read(name, kind="prerequisite-original")
    seed = _release_closed_mapping(
        _source_json(raw, "fixture original seed"),
        {"schema_version", "synthetic", "tool", "command_digest", "members", "data"},
        "fixture original seed",
    )
    if (
        seed["schema_version"] != _RELEASE_FIXTURE_SEED_SCHEMA
        or seed["synthetic"] is not True
        or seed["tool"] != tool
    ):
        raise ReleaseControlError("fixture seed mode/type/owner differs")
    command = {"tool": tool, "argv": list(argv), "working_directory": str(cwd)}
    if seed["command_digest"] != sha256_json(command):
        raise ReleaseControlError("fixture seed changes the exact pre-reservation original command")
    rows = _release_id_rows(seed["members"], "member_id", "fixture raw seed members")
    files = []
    for member_id, row in rows.items():
        _release_closed_mapping(
            row, {"member_id", "path", "schema_id", "bytes", "sha256"}, "fixture raw member"
        )
        if (
            re.fullmatch(r"[a-z][a-z0-9-]{0,100}", member_id, re.ASCII) is None
            or row["path"] != "raw/" + member_id + ".bin"
            or row["schema_id"] != "application/octet-stream"
        ):
            raise ReleaseControlError("fixture raw member changes its fixed ID/path/type")
        if type(row["bytes"]) is not int or row["bytes"] < 0:
            raise ReleaseControlError("fixture raw member has an invalid size")
        _require_digest(row["sha256"], "fixture raw member R")
        files.append(((Path(name).parent / row["path"]).as_posix(), "prerequisite-original"))
    raw_capture = _ReleaseCapturedFiles.capture(
        held_inputs.root,
        [(name, kind) for name, kind in files if name not in existing],
        forbidden=(),
        allowed_kinds=frozenset({"prerequisite-original"}),
        expected_root_directories=held_inputs.root_directories,
        expected_known_directories=tuple(dict.fromkeys((*known, *seed_capture.rows[0][4]))),
    )
    selected: dict[
        str, tuple[str, str, bytes, tuple[int, ...], tuple[tuple[str, int, int, int], ...]]
    ] = {}
    for held_row in (*held_inputs.rows, *seed_capture.rows, *raw_capture.rows):
        if held_row[0] in selected and selected[held_row[0]] != held_row:
            raise ReleaseControlError("fixture seed conflicts with an already-held input")
        selected[held_row[0]] = held_row
    if len({row[3][:2] for row in selected.values()}) != len(selected):
        raise ReleaseControlError("fixture seed aliases an original input inode")
    captured = _ReleaseCapturedFiles(
        held_inputs.root, held_inputs.root_directories, tuple(selected[k] for k in sorted(selected))
    )
    _release_fixture_seed_namespace(captured, name, set(rows))
    contents = {}
    for member_id, row in rows.items():
        content = captured.read(
            (Path(name).parent / row["path"]).as_posix(), kind="prerequisite-original"
        )
        if len(content) != row["bytes"] or sha256_bytes(content) != row["sha256"]:
            raise ReleaseControlError("fixture seed member original R/length differs before parse")
        contents[member_id] = content
    _release_fixture_seed_namespace(captured, name, set(rows))
    captured.revalidate()
    return captured, seed, rows, contents, directory, name


def _release_fixture_seed_linear_content(
    seed: Mapping[str, Any],
    *,
    contents: Mapping[str, bytes],
    root: Path,
    seed_path: str,
    readiness_raw: bytes,
    expected_readiness_digest: str,
    selection: Mapping[str, Any],
) -> tuple[dict[str, Any], list[dict[str, Any]], list[bytes], dict[str, Any], set[str]]:
    """Use supplied transcript chronology solely to plan complete immutable fixtures."""
    data = _release_closed_mapping(
        seed["data"],
        {"capture_started_at", "capture_completed_at", "raw_observations"},
        "fixture Linear transcript",
    )
    _release_fixture_native_timestamp(data["capture_started_at"])
    _release_fixture_native_timestamp(data["capture_completed_at"])
    used = set()
    observations = []
    for row in data["raw_observations"]:
        row = _release_closed_mapping(
            row,
            {
                "id",
                "round",
                "tool",
                "arguments",
                "started_at",
                "completed_at",
                "response_member_id",
            },
            "fixture Linear seed observation",
        )
        _release_fixture_native_timestamp(row["started_at"])
        _release_fixture_native_timestamp(row["completed_at"])
        member_id = row["response_member_id"]
        if member_id not in contents or member_id in used:
            raise ReleaseControlError("fixture Linear transcript raw member is missing or aliased")
        used.add(member_id)
        raw = contents[member_id]
        observations.append(
            {
                **{k: v for k, v in row.items() if k != "response_member_id"},
                "response": {
                    "path": "raw/" + member_id + ".bin",
                    "bytes": len(raw),
                    "sha256": sha256_bytes(raw),
                },
                "extracted_json_pointer": "/content/0/text",
                "capture_status": "SUCCESS",
                "payload_encoding": "json_text",
            }
        )
    projected = {**data, "raw_observations": observations}

    def response(index: int, ref: object) -> tuple[Path, bytes]:
        original = data["raw_observations"][index]
        member_id = original["response_member_id"]
        if ref != observations[index]["response"]:
            raise ReleaseControlError(
                "fixture Linear raw reference changes its original transcript field"
            )
        return root / Path(seed_path).parent / observations[index]["response"]["path"], contents[
            member_id
        ]

    payloads = _release_linear_observation_content(
        projected, read_response=response, revalidate=lambda: None
    )
    if sha256_bytes(readiness_raw) != _require_digest(
        expected_readiness_digest, "fixture readiness R"
    ):
        raise ReleaseControlError("fixture seed readiness differs from held policy")
    registry = _source_json(readiness_raw, "fixture readiness")
    content = _release_linear_snapshot_projection(
        registry,
        payloads=payloads,
        original_packet=selection["original_packet"],
        expected_packet_digest=selection["packet_digest"],
        original_work_orders=selection["original_work_orders"],
        expected_work_orders_digest=selection["work_orders_digest"],
        task_state_policy_raw=selection["task_state_policy_raw"],
        expected_task_state_policy_digest=selection["task_state_policy_digest"],
        context_id=selection["context_id"],
        declared_dependencies=selection["declared_dependencies"],
    )
    freshness = _release_task_state_policy_projection(
        selection["task_state_policy_raw"], expected_digest=selection["task_state_policy_digest"]
    )
    _release_linear_provider_clock(payloads, freshness)
    policy = _release_id_rows(registry["release_contexts"], "context_id", "fixture contexts")[
        selection["context_id"]
    ]
    paths = {
        identity: f"fixture-response-{index:04d}.bin" for index, identity in enumerate(payloads, 1)
    }
    subject, ops = _release_fixture_linear_expectations(
        {"project-id": policy["decision"]["project_id"]},
        readiness_raw=readiness_raw,
        expected_readiness_digest=expected_readiness_digest,
        context_id=selection["context_id"],
        expected_context_policy_digest=selection["context_policy_digest"],
        replayed_observations=payloads,
        response_paths=paths,
    )
    # Actual emulation clocks and emitted response paths are fixed later; neither enters request C.
    for op in ops:
        op["response_path"] = None
        op["observation_interval"] = None
    raws = [contents[row["response_member_id"]] for row in data["raw_observations"]]
    return subject, ops, raws, content, used


def _release_fixture_seed_target_content(
    seed: Mapping[str, Any],
    *,
    contents: Mapping[str, bytes],
    arguments: Mapping[str, Any],
    context: Mapping[str, Any],
    expected_context_digest: str,
    registry_raw: bytes,
    expected_registry_digest: str,
    sequence: int,
) -> tuple[dict[str, Any], list[dict[str, Any]], list[bytes], list[tuple[str, bytes]], set[str]]:
    data = _release_closed_mapping(
        seed["data"],
        {"requested_versions", "responses", "capture_started_at", "capture_completed_at"},
        "fixture target seed",
    )
    start = _release_fixture_native_timestamp(data["capture_started_at"])
    end = _release_fixture_native_timestamp(data["capture_completed_at"])
    if start > end:
        raise ReleaseControlError("fixture supplied target observation interval is inverted")
    subject, ops = _release_fixture_target_expectations(
        arguments,
        context=context,
        expected_context_digest=expected_context_digest,
        registry_raw=registry_raw,
        expected_registry_digest=expected_registry_digest,
        requested_versions=data["requested_versions"],
    )
    plan = _release_fixture_native_plan(
        tool="capture_release_target_observations.py",
        sequence=sequence,
        subject=subject,
        operations=ops,
    )
    if not isinstance(data["responses"], list) or len(data["responses"]) != len(plan):
        raise ReleaseControlError(
            "fixture target transcript inventory differs from exact request set"
        )
    used = set()
    raws = []
    artifacts = []
    states = []
    for source, expected in zip(data["responses"], plan, strict=True):
        row = _release_closed_mapping(
            source,
            {"response_member_id", "artifact_member_ids"},
            "fixture target response selector",
        )
        member = row["response_member_id"]
        if member not in contents or member in used:
            raise ReleaseControlError("fixture target response is missing or aliased")
        used.add(member)
        response = _source_json(contents[member], "fixture supplied target response")
        response = _release_closed_mapping(
            response,
            {"target_id", "normalized_package_version", "release_tag", "state", "artifacts"},
            "fixture target transcript",
        )
        if (
            not isinstance(response["artifacts"], list)
            or not isinstance(row["artifact_member_ids"], list)
            or len(row["artifact_member_ids"]) != len(response["artifacts"])
        ):
            raise ReleaseControlError("fixture target artifact inventory differs from held seed")
        converted = []
        for ordinal, (artifact, member_id) in enumerate(
            zip(response["artifacts"], row["artifact_member_ids"], strict=True), 1
        ):
            item = _release_closed_mapping(
                artifact, {"name", "bytes", "sha256"}, "fixture supplied artifact descriptor"
            )
            if member_id not in contents or member_id in used:
                raise ReleaseControlError(
                    "fixture target artifact is missing or aliases original bytes"
                )
            used.add(member_id)
            raw = contents[member_id]
            if (
                type(item["bytes"]) is not int
                or len(raw) != item["bytes"]
                or sha256_bytes(raw) != item["sha256"]
            ):
                raise ReleaseControlError("fixture supplied artifact differs from original R/size")
            path = str(
                Path(expected["paths"]["response"]).parent
                / f"artifact-{ordinal:04d}-{sha256_bytes(raw)}.bin"
            )
            converted.append(
                {
                    **item,
                    "original_read_back": {
                        "path": path,
                        "bytes": len(raw),
                        "sha256": sha256_bytes(raw),
                    },
                }
            )
            artifacts.append((path, raw))
        value = {**response, "artifacts": converted}
        wire = canonical_json(value)
        _release_fixture_native_response("target.query", expected["request"]["arguments"], wire)
        states.append(value["state"])
        raws.append(wire)
    generic = ops[0]["request"]["resolution_mode"] == "next_unused_same_milestone_patch"
    for offset in range(0, len(states), 3):
        if generic and (
            all(v == "unused" for v in states[offset : offset + 3]) != (offset == len(states) - 3)
        ):
            raise ReleaseControlError(
                "fixture generic target plan does not end at the first unused version"
            )
    return subject, ops, raws, artifacts, used


def _release_fixture_seed_prepare(
    tool: str,
    argv: Sequence[str],
    *,
    working_directory: Path,
    held_inputs: _ReleaseCapturedFiles,
    expected_inputs: Mapping[str, Sequence[Mapping[str, str]]],
    input_types: Mapping[str, str],
    selection: Mapping[str, Any],
    live: bool,
    _original: ReleaseInvocation | None = None,
    _intent_capture: _ReleaseCapturedFiles | None = None,
) -> _ReleaseFixtureSeedPlan:
    if set(input_types) != {row[0] for row in held_inputs.rows} or any(
        not isinstance(v, str) or not v for v in input_types.values()
    ):
        raise ReleaseControlError("fixture original typed graph must describe every held input")
    admission_clock = datetime.now(UTC)
    if (_original is None) != (_intent_capture is None):
        raise ReleaseControlError("fixture seed replay needs the actual original intent custody")
    if _original is not None and _intent_capture is not None:
        _release_captured_command_context(_original, captured=_intent_capture, expected_tool=tool)
        if (
            _original.root != held_inputs.root
            or _original.intent["argv"] != list(argv)
            or _original.intent["environment"]["working_directory"] != str(working_directory)
            or _original.intent["environment"]["fixture_mode"] != "1"
        ):
            raise ReleaseControlError("fixture seed replay changed original command/mode/root")
        admission_clock = _release_fixture_native_timestamp(_original.intent["started_at"])
    captured, seed, members, contents, directory, seed_path = _release_fixture_seed_capture(
        tool, argv, working_directory=working_directory, held_inputs=held_inputs, live=live
    )
    arguments, _, _ = _release_fixture_seed_location(tool, argv, working_directory, captured.root)
    allowed = {
        "capture_linear_release_snapshot.py": {"registry"},
        "record_release_role_assignments.py": {
            "signed-assignments",
            "policy",
            "release-context",
            "provider-attestation-keyring",
        },
        "validate_release_evidence_stores.py": {"stores"},
        "capture_release_target_observations.py": {"targets", "release-context"},
        "retain_release_evidence.py": {"stores", "input", "manifest"},
        "update_release_attempt_index.py": {"entry-manifest", "entry-receipts"},
        "export_release_attempt_index.py": {"genesis", "stores"},
        "export_release_burn_lineage.py": {"genesis", "index-export"},
    }
    if tool not in allowed or set(expected_inputs) != allowed[tool] & set(arguments):
        raise ReleaseControlError("fixture seed original typed-input flag set differs")
    inputs = {}
    seen = set()
    for flag in sorted(expected_inputs):
        values = arguments[flag] if flag in TOOL_CONTRACTS[tool].repeatable else [arguments[flag]]
        refs = expected_inputs[flag]
        if not isinstance(refs, (list, tuple)) or len(values) != len(refs):
            raise ReleaseControlError("fixture seed repeated original input set differs")
        selected = []
        for value, reference in zip(values, refs, strict=True):
            row = _release_closed_mapping(
                reference, {"path", "schema_id", "sha256"}, "fixture independently selected input"
            )
            actual = _release_historical_path(value, working_directory)
            if (
                not actual.is_relative_to(captured.root)
                or row["path"] != actual.relative_to(captured.root).as_posix()
                or actual in seen
            ):
                raise ReleaseControlError(
                    "fixture seed selected input escapes, aliases or changes original argument"
                )
            seen.add(actual)
            _require_digest(row["sha256"], "fixture expected original input R")
            if input_types.get(row["path"]) != row["schema_id"]:
                raise ReleaseControlError("fixture original input has no explicit schema")
            original_raw = captured.read(row["path"], kind="prerequisite-original")
            if sha256_bytes(original_raw) != row["sha256"]:
                raise ReleaseControlError("fixture seed selected input R changed")
            selected.append((actual, original_raw, row["schema_id"]))
        inputs[flag] = selected

    def raw(flag: str) -> bytes:
        return inputs[flag][0][1]

    def path(flag: str) -> Path:
        return inputs[flag][0][0]

    data = seed["data"]
    used: set[str] = set()
    artifacts: list[tuple[str, bytes]] = []
    transcript: dict[str, Any] = {}
    if tool == "capture_linear_release_snapshot.py":
        required = {
            "context_id",
            "context_policy_digest",
            "readiness_digest",
            "original_packet",
            "packet_digest",
            "original_work_orders",
            "work_orders_digest",
            "task_state_policy_raw",
            "task_state_policy_digest",
            "declared_dependencies",
            "consumer_stage",
        }
        _release_closed_mapping(selection, required, "fixture Linear seed selectors")
        subject, ops, responses, content, used = _release_fixture_seed_linear_content(
            seed,
            contents=contents,
            root=captured.root,
            seed_path=seed_path,
            readiness_raw=raw("registry"),
            expected_readiness_digest=selection["readiness_digest"],
            selection=selection,
        )
        policy = _release_id_rows(
            _source_json(raw("registry"), "fixture readiness")["release_contexts"],
            "context_id",
            "fixture context",
        )[selection["context_id"]]
        if arguments["project-id"] != policy["decision"]["project_id"]:
            raise ReleaseControlError(
                "fixture original Linear project differs from selected context"
            )
        freshness = _release_task_state_policy_projection(
            selection["task_state_policy_raw"],
            expected_digest=selection["task_state_policy_digest"],
        )
        stage = selection["consumer_stage"]
        if stage not in {"prepromotion", "terminal_commit"}:
            raise ReleaseControlError("fixture seed freshness consumer is not governed")
        now = admission_clock
        end = _parse_utc_timestamp(data["capture_completed_at"], "fixture transcript end")
        if (
            not -freshness["server_clock_skew_budget_seconds"]["capture"]
            <= (now - end).total_seconds()
            <= freshness["freshness_windows_seconds"][stage]
        ):
            raise ReleaseControlError(
                "fixture seed transcript is stale or future; emulation cannot refresh it"
            )
        for observation in data["raw_observations"]:
            end = _parse_utc_timestamp(
                observation["completed_at"], "fixture supplied observation time"
            )
            if (
                observation["round"] == 2
                and (now - end).total_seconds() > freshness["freshness_windows_seconds"][stage]
            ):
                raise ReleaseControlError("fixture seed original second-round observation is stale")
        transcript = {
            "kind": "supplied-linear-fixture-transcript",
            "data": data,
            "projection": content,
            "freshness_checked_at": now.isoformat().replace("+00:00", "Z"),
        }
    elif tool == "capture_release_target_observations.py":
        _release_closed_mapping(
            selection, {"context_digest", "registry_digest"}, "fixture target seed selectors"
        )
        subject, ops, responses, artifacts, used = _release_fixture_seed_target_content(
            seed,
            contents=contents,
            arguments=arguments,
            context=_source_json(raw("release-context"), "fixture target context"),
            expected_context_digest=selection["context_digest"],
            registry_raw=raw("targets"),
            expected_registry_digest=selection["registry_digest"],
            sequence=int(directory.name),
        )
        ended = _release_fixture_native_timestamp(data["capture_completed_at"])
        if (
            not 0
            <= (admission_clock - ended).total_seconds()
            <= _RELEASE_FIXTURE_TRANSCRIPT_MAX_AGE_SECONDS
        ):
            raise ReleaseControlError(
                "fixture original target transcript is stale/future at admission"
            )
        transcript = {
            "kind": "supplied-target-fixture-transcript",
            "data": data,
            "admission_clock": admission_clock.isoformat().replace("+00:00", "Z"),
            "clock_domain": "fixture-protocol-original-admission-not-provider-freshness",
        }
    elif tool == "record_release_role_assignments.py":
        _release_closed_mapping(data, set(), "fixture role seed")
        _release_closed_mapping(
            selection,
            {
                "context_digest",
                "policy_digest",
                "authority_policy_digest",
                "keyring_digest",
                "independently_expected_operator",
                "use_interval",
            },
            "fixture role selectors",
        )
        replay = _release_original_role_byte_replay(
            path("signed-assignments"),
            context_path=path("release-context"),
            captured=captured,
            expected_context_digest=selection["context_digest"],
            expected_run_id=arguments["run-id"],
            expected_milestone=arguments["milestone"],
            expected_assignment_policy_digest=selection["policy_digest"],
            expected_authority_policy_digest=selection["authority_policy_digest"],
            expected_keyring_digest=selection["keyring_digest"],
            use_interval=selection["use_interval"],
            live=False,
        )
        if replay["assignment_policy_bytes"] != raw("policy"):
            raise ReleaseControlError("fixture original assignment policy does not match --policy")
        subject, ops = _release_fixture_role_expectations(
            arguments,
            original_role_replay=replay,
            expected_context_digest=selection["context_digest"],
            expected_policy_digest=selection["policy_digest"],
            independently_expected_operator=selection["independently_expected_operator"],
            response_paths={
                role: row["path"].relative_to(captured.root).as_posix()
                for role, row in replay["original_provenance"].items()
            },
        )
        responses = [captured.read(op["response_path"], kind="prerequisite-original") for op in ops]
    else:
        _release_closed_mapping(data, {"response_member_ids"}, "fixture finite response seed")
        if tool == "validate_release_evidence_stores.py":
            _release_closed_mapping(
                selection, {"registry_digest"}, "fixture preflight seed selectors"
            )
            subject, ops = _release_fixture_preflight_expectations(
                arguments,
                registry_raw=raw("stores"),
                expected_registry_digest=selection["registry_digest"],
                backend_controls=_release_fixture_backend_control_capture(
                    path("stores"),
                    captured=captured,
                    expected_registry_digest=selection["registry_digest"],
                ),
            )
        elif tool == "retain_release_evidence.py":
            _release_closed_mapping(
                selection, {"registry_digest", "fixture_run_id"}, "fixture retention seed selectors"
            )
            subject, ops = _release_fixture_retention_expectations(
                arguments,
                original_inputs=[r for _, r, _ in inputs.get("input", [])],
                original_manifest=raw("manifest") if "manifest" in inputs else None,
                registry_raw=raw("stores"),
                expected_registry_digest=selection["registry_digest"],
                fixture_run_id=selection["fixture_run_id"],
                backend_controls=_release_fixture_backend_control_capture(
                    path("stores"),
                    captured=captured,
                    expected_registry_digest=selection["registry_digest"],
                ),
            )
        elif tool in {"export_release_attempt_index.py", "export_release_burn_lineage.py"}:
            _release_closed_mapping(
                selection, {"genesis_digest"}, "fixture index read seed selectors"
            )
            subject, ops = _release_fixture_index_expectations(
                arguments,
                tool=tool,
                genesis_raw=raw("genesis"),
                expected_genesis_digest=selection["genesis_digest"],
            )
        else:
            required = {
                "genesis_path",
                "genesis_digest",
                "expected_prior_generation",
                "subject_path",
                "subject_record",
                "expected_scope",
                "expected_operation_id",
                "expected_milestone",
                "expected_release_tag",
                "expected_index_backend",
                "expected_prior_head",
                "attempt_directory",
                "expected_attempt_id",
                "coordination_record",
                "coordination_path",
            }
            _release_closed_mapping(
                selection, required, "fixture original CAS pre-reservation graph"
            )
            genesis_path = _release_capture_absolute(selection["genesis_path"])
            if not genesis_path.is_relative_to(captured.root):
                raise ReleaseControlError("fixture original genesis escapes held input root")
            genesis_name = genesis_path.relative_to(captured.root).as_posix()
            if input_types.get(genesis_name) != "metriplane.release-fixture-index-genesis.v1":
                raise ReleaseControlError(
                    "fixture original genesis is absent from held typed inputs"
                )
            genesis_raw = captured.read(genesis_name, kind="prerequisite-original")
            if sha256_bytes(genesis_raw) != selection["genesis_digest"]:
                raise ReleaseControlError("fixture original genesis R differs")
            genesis = _release_fixture_index_genesis(genesis_raw)
            scope = _release_index_scope_content(
                selection["expected_scope"], milestone=selection["expected_milestone"]
            )
            if arguments.get("scope-id") not in {None, scope["scope_id"]}:
                raise ReleaseControlError(
                    "fixture original CAS command changes independent scope identity"
                )
            for flag, value in {
                "scope-kind": scope["kind"],
                "stage": scope["stage"],
                "sequence": scope["sequence"],
                "operation-id": selection["expected_operation_id"],
                "index-backend": selection["expected_index_backend"],
                "expected-head": selection["expected_prior_head"],
                "release-tag": selection["expected_release_tag"],
            }.items():
                if arguments.get(flag) != value:
                    raise ReleaseControlError(
                        "fixture original CAS command changes independent scope/head: " + flag
                    )
            if (
                scope.get("release_tag") != selection["expected_release_tag"]
                or selection["expected_index_backend"] != "attempt-index"
            ):
                raise ReleaseControlError("fixture CAS selected tag/backend differs")
            if scope["kind"] == "release_staging":
                if (
                    arguments["milestone"] != selection["expected_milestone"]
                    or arguments["run-id"] != scope["run_id"]
                    or arguments.get("candidate-id-not-resolved") is not True
                    or scope["candidate_id"] is not None
                    or any(
                        selection[k] is not None
                        for k in (
                            "attempt_directory",
                            "expected_attempt_id",
                            "coordination_record",
                            "coordination_path",
                        )
                    )
                ):
                    raise ReleaseControlError(
                        "fixture original burn CAS scope is resolved or contradictory"
                    )
            elif arguments["candidate-id"] != scope["candidate_id"]:
                raise ReleaseControlError("fixture original attempt candidate differs")
            manifest = _source_json(raw("entry-manifest"), "fixture original manifest")
            retention = _source_json(raw("entry-receipts"), "fixture original retention")
            for record, kind in (
                (manifest, "release-evidence-manifest"),
                (retention, "release-retention-receipts"),
            ):
                validate_record(record, kind)
                if record["status"] != "PASS" or record["synthetic"] is not True:
                    raise ReleaseControlError("fixture CAS input mode/result differs")
            _release_index_update_subject_content(
                root=captured.root,
                receipt_path=_release_historical_path(arguments["out"], working_directory),
                captured=captured,
                manifest_path=path("entry-manifest"),
                manifest_raw=raw("entry-manifest"),
                manifest=manifest,
                retention=retention,
                subject_path=selection["subject_path"],
                subject_record=selection["subject_record"],
                scope=scope,
                expected_milestone=selection["expected_milestone"],
                expected_release_tag=selection["expected_release_tag"],
                expected_synthetic=True,
                attempt_directory=selection["attempt_directory"],
                expected_attempt_id=selection["expected_attempt_id"],
                coordination_record=selection["coordination_record"],
                coordination_path=selection["coordination_path"],
            )
            generation = selection["expected_prior_generation"]
            if type(generation) is not int or generation < 0:
                raise ReleaseControlError("fixture original prior generation is invalid")
            subject = {
                "kind": "index_scope",
                "subject_digest": sha256_json(scope),
                "original_policy_digest": selection["genesis_digest"],
            }
            ops = [
                _release_fixture_native_operation(
                    "index.cas",
                    {
                        "backend_id": "attempt-index",
                        "genesis_digest": selection["genesis_digest"],
                        "namespace": genesis["namespace"],
                        "binding_digest": genesis["binding_digest"],
                        "expected_head": selection["expected_prior_head"],
                        "operation_id": selection["expected_operation_id"],
                        "prior_generation": generation,
                        "entry_payload": {
                            "scope": scope,
                            "milestone": selection["expected_milestone"],
                            "entry_manifest_digest": sha256_json(manifest),
                            "entry_receipts_digest": sha256_json(retention),
                        },
                    },
                )
            ]
        ids = data["response_member_ids"]
        if (
            not isinstance(ids, list)
            or len(ids) != len(ops)
            or any(not isinstance(x, str) for x in ids)
            or len(set(ids)) != len(ids)
            or not set(ids) <= set(contents)
        ):
            raise ReleaseControlError(
                "fixture supplied response inventory differs from exact constructor plan"
            )
        used = set(ids)
        responses = [contents[key] for key in ids]
    if used != set(contents):
        raise ReleaseControlError("fixture seed has extra unconsumed original raw members")
    plan = _release_fixture_native_plan(
        tool=tool, sequence=int(directory.name), subject=subject, operations=ops
    )
    outputs = []
    for row, response in zip(plan, responses, strict=True):
        _release_fixture_native_response(
            row["request"]["kind"], row["request"]["arguments"], response
        )
        outputs.extend(
            [
                (row["paths"]["request"], "metriplane.release-fixture-native-request.v1"),
                (row["paths"]["receipt"], _RELEASE_FIXTURE_NATIVE_WIRE),
            ]
        )
        if row["request"]["kind"] != "role.delegation":
            outputs.append((row["paths"]["response"], "application/octet-stream"))
    outputs.extend((name, "application/octet-stream") for name, _ in artifacts)
    primary = _release_historical_path(arguments["out"], working_directory)
    if primary.parent != captured.root:
        raise ReleaseControlError("fixture primary output is not its canonical original run root")
    outputs.append((primary.name, "metriplane." + _RELEASE_GATE_PREREQUISITES[tool][0] + ".v1"))
    if len({name for name, _ in outputs}) != len(outputs):
        raise ReleaseControlError("fixture output plan contains aliases")
    for name, _ in outputs:
        suffix = _release_relative_suffix(name, "fixture output plan")
        if suffix.parts[0] in {"inputs", "invocations"} or any(
            suffix == Path(row[0])
            or suffix.is_relative_to(Path(row[0]))
            or Path(row[0]).is_relative_to(suffix)
            for row in captured.rows
        ):
            raise ReleaseControlError("fixture output plan overlaps held original inputs/journal")
    captured.revalidate()
    types = {**input_types, seed_path: _RELEASE_FIXTURE_SEED_SCHEMA}
    types.update(
        {
            (Path(seed_path).parent / row["path"]).as_posix(): row["schema_id"]
            for row in members.values()
        }
    )
    input_plan = tuple(
        (name, types[name], sha256_bytes(content)) for name, _, content, _, _ in captured.rows
    )
    return _ReleaseFixtureSeedPlan(
        captured,
        seed_path,
        sha256_bytes(captured.read(seed_path, kind="prerequisite-original")),
        input_plan,
        tool,
        tuple(argv),
        working_directory,
        directory,
        canonical_json(subject),
        tuple(canonical_json(op) for op in ops),
        tuple(sorted(outputs)),
        tuple(responses),
        tuple(artifacts),
        canonical_json(transcript),
    )


@dataclass(frozen=True)
class _ReleaseFixtureSeedInvocation:
    original: ReleaseInvocation
    plan: _ReleaseFixtureSeedPlan
    intent_capture: _ReleaseCapturedFiles

    def revalidate(self) -> None:
        plan, original = self.plan, self.original
        if (
            original.root != plan.captured.root
            or original.directory != plan.directory
            or self.intent_capture.root != original.root
            or self.intent_capture.root_directories != plan.captured.root_directories
        ):
            raise ReleaseControlError("fixture original seed/intent custody has another root")
        plan.captured.revalidate()
        _release_captured_command_context(
            original, captured=self.intent_capture, expected_tool=plan.tool
        )
        intent = original.intent
        if (
            intent["argv"] != list(plan.argv)
            or intent["environment"]["working_directory"] != str(plan.working_directory)
            or intent["environment"]["fixture_mode"] != "1"
        ):
            raise ReleaseControlError("fixture intent changes the original command or fixture mode")
        expected_inputs = [
            {"path": str(original.root / name), "schema_id": schema, "sha256": digest}
            for name, schema, digest in plan.input_plan
        ]
        if canonical_json(intent["inputs"]) != canonical_json(expected_inputs):
            raise ReleaseControlError(
                "fixture original intent lacks its exact full seed/input inventory"
            )
        expected_outputs = [
            {"path": name, "schema_id": schema} for name, schema in plan.output_plan
        ]
        if canonical_json(intent["planned_outputs"]) != canonical_json(expected_outputs):
            raise ReleaseControlError(
                "fixture original output inventory was not fixed before reservation"
            )
        seed = _source_json(
            plan.captured.read(plan.seed_path, kind="prerequisite-original"), "held fixture seed"
        )
        if (
            sha256_bytes(plan.captured.read(plan.seed_path, kind="prerequisite-original"))
            != plan.seed_digest
        ):
            raise ReleaseControlError("fixture original seed bytes drifted")
        _release_fixture_seed_namespace(
            plan.captured, plan.seed_path, {row["member_id"] for row in seed["members"]}
        )
        if plan.tool == "capture_release_target_observations.py":
            ended = _release_fixture_native_timestamp(seed["data"]["capture_completed_at"])
            admitted = _release_fixture_native_timestamp(intent["started_at"])
            if (
                not 0
                <= (admitted - ended).total_seconds()
                <= _RELEASE_FIXTURE_TRANSCRIPT_MAX_AGE_SECONDS
            ):
                raise ReleaseControlError(
                    "fixture target transcript was stale/future at original reservation"
                )


def _release_fixture_seed_bind(
    original: ReleaseInvocation,
    *,
    plan: _ReleaseFixtureSeedPlan,
    original_intent_capture: _ReleaseCapturedFiles,
) -> _ReleaseFixtureSeedInvocation:
    """Parent supplies actual created-intent inode custody; never recapture it here.

    Only a private producer factory may carry this object across the worker boundary.
    It does not confer completed-journal, semantic graph, native, or release authority.
    """
    value = _ReleaseFixtureSeedInvocation(original, plan, original_intent_capture)
    value.revalidate()
    return value


@dataclass(frozen=True)
class _ReleaseFixtureEmulation:
    bound: _ReleaseFixtureSeedInvocation
    sidecars: tuple[tuple[str, str, bytes], ...]
    proof_refs: tuple[bytes, ...]
    operation_times: tuple[tuple[str, str], ...]


def _release_fixture_seed_emulate(bound: _ReleaseFixtureSeedInvocation) -> _ReleaseFixtureEmulation:
    """Interpret supplied bytes in memory; no provider, worker, terminal, or output effects."""
    bound.revalidate()
    original, plan = bound.original, bound.plan
    inventory = _release_fixture_native_plan(
        tool=plan.tool,
        sequence=original.intent["sequence"],
        subject=_source_json(plan.subject, "fixture subject"),
        operations=[_source_json(value, "fixture operation") for value in plan.operations],
    )
    producer = {
        "tool": plan.tool,
        "invocation_id": original.intent["invocation_id"],
        "sequence": original.intent["sequence"],
        "intent_digest": sha256_json(original.intent),
    }
    values = []
    refs = []
    times = []
    previous = _release_fixture_native_timestamp(original.intent["started_at"])
    for item, raw in zip(inventory, plan.response_payloads, strict=True):
        started = datetime.now(UTC)
        if started < previous:
            raise ReleaseControlError("fixture actual emulation clock regressed")
        request = item["request"]
        _release_fixture_native_response(request["kind"], request["arguments"], raw)
        if request["kind"] == "index.cas":
            _release_fixture_index_cas_effect(bound, request["arguments"], raw)
        finished = datetime.now(UTC)
        if finished < started:
            raise ReleaseControlError("fixture actual operation clock regressed")
        start, end = (clock.isoformat().replace("+00:00", "Z") for clock in (started, finished))
        request_raw = canonical_json(request)

        def ref(name: str, content: bytes) -> dict[str, Any]:
            return {"path": name, "bytes": len(content), "sha256": sha256_bytes(content)}

        receipt = {
            "schema_version": _RELEASE_FIXTURE_NATIVE_WIRE,
            "scope": _RELEASE_FIXTURE_NATIVE_SCOPE,
            "producer": producer,
            "subject": _source_json(plan.subject, "fixture subject"),
            "ordinal": item["ordinal"],
            "request": ref(item["paths"]["request"], request_raw),
            "response": ref(item["paths"]["response"], raw),
            "started_at": start,
            "completed_at": end,
        }
        digest = sha256_json(receipt)
        receipt["signature"] = {
            "provider": "test-fixture",
            "algorithm": "test-sha256-v1",
            "actor_id": _RELEASE_FIXTURE_NATIVE_ACTOR,
            "synthetic": True,
            "subject_digest": digest,
            "signature": sha256_json(
                {"actor_id": _RELEASE_FIXTURE_NATIVE_ACTOR, "subject_digest": digest}
            ),
        }
        _validated_signature(receipt["signature"], subject_digest=digest, live=False)
        receipt_raw = canonical_json(receipt)
        values.extend(
            [
                (item["paths"]["request"], _RELEASE_FIXTURE_API_VERSION, request_raw),
                (item["paths"]["receipt"], _RELEASE_FIXTURE_NATIVE_WIRE, receipt_raw),
            ]
        )
        if request["kind"] != "role.delegation":
            values.append((item["paths"]["response"], "application/octet-stream", raw))
        else:
            # Existing provenance remains the original input, never a response copy.
            if plan.captured.read(item["paths"]["response"], kind="prerequisite-original") != raw:
                raise ReleaseControlError("fixture delegation changed original input bytes")
        refs.append(canonical_json(ref(item["paths"]["receipt"], receipt_raw)))
        times.append((start, end))
        previous = finished
    values.extend((name, "application/octet-stream", raw) for name, raw in plan.artifact_payloads)
    primary = _release_historical_path(
        _release_original_arguments(plan.tool, list(plan.argv))["out"], plan.working_directory
    ).name
    if {(name, kind) for name, kind, _ in values} != set(plan.output_plan) - {
        (primary, "metriplane." + _RELEASE_GATE_PREREQUISITES[plan.tool][0] + ".v1")
    }:
        raise ReleaseControlError("fixture emulation changed its original complete sidecar plan")
    bound.revalidate()
    return _ReleaseFixtureEmulation(bound, tuple(sorted(values)), tuple(refs), tuple(times))


def _release_fixture_index_cas_effect(
    bound: _ReleaseFixtureSeedInvocation,
    request: Mapping[str, Any],
    response_raw: bytes,
) -> None:
    """Serialize the synthetic CAS with pinned state/lock custody and durable readback."""
    bound.revalidate()
    original = bound.original
    response = _release_fixture_native_response("index.cas", request, response_raw)
    state_path = original.root / ".fixture-native-state"
    root = _release_fixture_directory(original.root, expected=bound.plan.captured.root_directories)
    try:
        try:
            os.mkdir(state_path.name, mode=0o700, dir_fd=root.fd)
            os.fsync(root.fd)
        except FileExistsError:
            info = os.stat(state_path.name, dir_fd=root.fd, follow_symlinks=False)
            if not stat.S_ISDIR(info.st_mode):
                raise ReleaseControlError("fixture CAS backend state directory is unsafe")
        state_directory = _release_fixture_directory(state_path, expected=root.identities)
        try:
            lock_descriptor = os.open(
                "attempt-index.lock",
                os.O_RDWR | os.O_CREAT | os.O_NOFOLLOW,
                0o600,
                dir_fd=state_directory.fd,
            )
            with os.fdopen(lock_descriptor, "a+b") as lock:
                lock_info = os.fstat(lock.fileno())
                if not stat.S_ISREG(lock_info.st_mode) or lock_info.st_nlink != 1:
                    raise ReleaseControlError(
                        "fixture CAS backend lock is not one private regular file"
                    )
                if os.name == "nt":
                    import msvcrt

                    if os.fstat(lock.fileno()).st_size == 0:
                        lock.write(b"\0")
                        lock.flush()
                        os.fsync(lock.fileno())
                    lock.seek(0)
                    msvcrt.locking(  # type: ignore[attr-defined]
                        lock.fileno(),
                        msvcrt.LK_LOCK,  # type: ignore[attr-defined]
                        1,
                    )
                else:
                    import fcntl

                    fcntl.flock(lock.fileno(), fcntl.LOCK_EX)
                lock_identity = _release_gate_file_identity(os.fstat(lock.fileno()))

                def revalidate_lock() -> None:
                    state_directory.revalidate()
                    visible = os.stat(
                        "attempt-index.lock",
                        dir_fd=state_directory.fd,
                        follow_symlinks=False,
                    )
                    if _release_gate_file_identity(visible) != lock_identity:
                        raise ReleaseControlError("fixture CAS backend lock was substituted")

                def read_state() -> bytes | None:
                    revalidate_lock()
                    try:
                        descriptor = os.open(
                            "attempt-index.json",
                            os.O_RDONLY | os.O_NOFOLLOW | os.O_NONBLOCK,
                            dir_fd=state_directory.fd,
                        )
                    except FileNotFoundError:
                        return None
                    with os.fdopen(descriptor, "rb") as stream:
                        info = os.fstat(stream.fileno())
                        if not stat.S_ISREG(info.st_mode) or info.st_nlink != 1:
                            raise ReleaseControlError(
                                "fixture CAS backend state is not one private regular file"
                            )
                        before = _release_gate_file_identity(info)
                        raw = stream.read()
                        after = _release_gate_file_identity(os.fstat(stream.fileno()))
                    visible = _release_gate_file_identity(
                        os.stat(
                            "attempt-index.json",
                            dir_fd=state_directory.fd,
                            follow_symlinks=False,
                        )
                    )
                    if before != after or after != visible:
                        raise ReleaseControlError("fixture CAS backend state was substituted")
                    return raw

                state_raw = read_state()
                state = (
                    _release_closed_mapping(
                        _source_json(state_raw, "fixture CAS backend state"),
                        {
                            "schema_version",
                            "genesis_digest",
                            "head",
                            "generation",
                            "operations",
                            "scopes",
                        },
                        "fixture CAS backend state",
                    )
                    if state_raw is not None
                    else {
                        "schema_version": "metriplane.release-fixture-index-state.v1",
                        "genesis_digest": request["genesis_digest"],
                        "head": request["genesis_digest"],
                        "generation": 0,
                        "operations": {},
                        "scopes": {},
                    }
                )
                if (
                    state["schema_version"] != "metriplane.release-fixture-index-state.v1"
                    or _require_digest(state["genesis_digest"], "fixture CAS state genesis")
                    != request["genesis_digest"]
                    or _require_digest(state["head"], "fixture CAS state head") != state["head"]
                    or type(state["generation"]) is not int
                    or state["generation"] < 0
                    or not isinstance(state["operations"], dict)
                    or not isinstance(state["scopes"], dict)
                    or state["generation"] != len(state["operations"])
                    or state["generation"] != len(state["scopes"])
                    or any(
                        not isinstance(key, str)
                        or not key
                        or _require_digest(value, "fixture CAS state operation") != value
                        for key, value in state["operations"].items()
                    )
                    or any(
                        _require_digest(key, "fixture CAS state scope") != key
                        or _require_digest(value, "fixture CAS state scope entry") != value
                        for key, value in state["scopes"].items()
                    )
                ):
                    raise ReleaseControlError("fixture CAS backend state is invalid")
                operation = request["operation_id"]
                entry_digest = sha256_json(response["entry"])
                scope_digest = sha256_json(_release_index_scope_key(response["entry"]["scope"]))
                previous = state["operations"].get(operation)
                if previous is not None:
                    if previous != entry_digest or response["disposition"] != "idempotent":
                        raise ReleaseControlError(
                            "fixture CAS replay is not the exact idempotent original operation"
                        )
                    descriptor = os.open(
                        "attempt-index.json",
                        os.O_RDONLY | os.O_NOFOLLOW | os.O_NONBLOCK,
                        dir_fd=state_directory.fd,
                    )
                    try:
                        info = os.fstat(descriptor)
                        if not stat.S_ISREG(info.st_mode) or info.st_nlink != 1:
                            raise ReleaseControlError(
                                "fixture CAS backend state is not one private regular file"
                            )
                        os.fsync(descriptor)
                    finally:
                        os.close(descriptor)
                    os.fsync(state_directory.fd)
                    if read_state() != state_raw:
                        raise ReleaseControlError("fixture CAS idempotent state readback differs")
                    bound.revalidate()
                    return
                if scope_digest in state["scopes"]:
                    raise ReleaseControlError("fixture CAS rejected a reused logical scope")
                if (
                    request["expected_head"] != state["head"]
                    or request["prior_generation"] != state["generation"]
                    or response["disposition"] != "committed"
                ):
                    raise ReleaseControlError("fixture CAS rejected a stale or competing writer")
                updated = {
                    **state,
                    "head": entry_digest,
                    "generation": state["generation"] + 1,
                    "operations": {**state["operations"], operation: entry_digest},
                    "scopes": {**state["scopes"], scope_digest: entry_digest},
                }
                temporary = "attempt-index." + original.intent["invocation_id"] + ".tmp"
                _release_gate_write_json_at(state_directory.fd, temporary, updated)
                revalidate_lock()
                os.replace(
                    temporary,
                    "attempt-index.json",
                    src_dir_fd=state_directory.fd,
                    dst_dir_fd=state_directory.fd,
                )
                os.fsync(state_directory.fd)
                if read_state() != canonical_json(updated):
                    raise ReleaseControlError("fixture CAS committed state readback differs")
                bound.revalidate()
        finally:
            state_directory.close()
    finally:
        root.close()


def _release_fixture_write_set(
    destination: _ReleaseFixtureDirectory,
    values: Sequence[tuple[str, str, bytes]],
    *,
    before_effect: Callable[[], None],
    original_parent_directories: Sequence[_ReleaseFixtureDirectory],
) -> _ReleaseCapturedFiles:
    """Exclusive FD-relative mechanical copies. Partial objects remain on every failure.

    Caller owns the finite planned destination set and prior semantic verification.
    No completion witness or release authority is created by this byte installer.
    """
    names = [name for name, _, _ in values]
    if not names or len(set(names)) != len(names):
        raise ReleaseControlError("fixture exclusive copy inventory is empty or repeated")
    paths = [_release_relative_suffix(name, "fixture exclusive output") for name in names]
    if any(
        a.is_relative_to(b) or b.is_relative_to(a)
        for i, a in enumerate(paths)
        for b in paths[i + 1 :]
    ):
        raise ReleaseControlError("fixture exclusive output files overlap")
    directories: dict[str, int] = {".": destination.fd}
    held_directories = {".": destination}
    required = {part.as_posix() for path in paths for part in path.parents if part != Path(".")}
    pins = {row[0]: row for row in destination.identities}
    for directory in original_parent_directories:
        if not directory.path.is_relative_to(destination.path):
            raise ReleaseControlError("fixture parent custody escapes original destination")
        name = directory.path.relative_to(destination.path).as_posix()
        if name in held_directories:
            raise ReleaseControlError("fixture parent custody has duplicate or root aliases")
        for row in directory.identities:
            if row[0] in pins and pins[row[0]] != row:
                raise ReleaseControlError("fixture original output ancestor custody conflicts")
            pins[row[0]] = row
        held_directories[name] = directory
        directories[name] = directory.fd
    if set(held_directories) != {".", *required}:
        raise ReleaseControlError("fixture exact output parent FD inventory is missing or extra")
    file_rows: list[
        tuple[str, str, bytes, tuple[int, ...], tuple[tuple[str, int, int, int], ...]]
    ] = []

    def validate_links() -> None:
        for directory in held_directories.values():
            directory.revalidate()

    def identity(info: os.stat_result) -> tuple[int, ...]:
        return (
            info.st_dev,
            info.st_ino,
            info.st_mode,
            info.st_nlink,
            info.st_size,
            info.st_mtime_ns,
            info.st_ctime_ns,
        )

    try:
        before_effect()
        validate_links()
        # Every parent is held by the original creation lifecycle before this byte copier.
        # No mkdir or fresh directory open can substitute a new ancestor here.
        for path in paths:
            try:
                os.stat(
                    path.name, dir_fd=directories[path.parent.as_posix()], follow_symlinks=False
                )
            except FileNotFoundError:
                continue
            raise ReleaseControlError("fixture exclusive copy refuses an existing destination")
        for (name, kind, raw), path in zip(values, paths, strict=True):
            before_effect()
            validate_links()
            for oldname, _, _, oldidentity, ancestors in file_rows:
                _release_held_path(
                    destination.path / oldname,
                    expected_directories=ancestors,
                    expected_identity=oldidentity,
                )
            parent = directories[path.parent.as_posix()]
            fd = os.open(
                path.name,
                os.O_WRONLY | os.O_CREAT | os.O_EXCL | os.O_NOFOLLOW,
                0o600,
                dir_fd=parent,
            )
            try:
                created = os.fstat(fd)
                if not stat.S_ISREG(created.st_mode) or created.st_nlink != 1:
                    raise ReleaseControlError(
                        "fixture created output is not an exclusive regular file"
                    )
                offset = 0
                while offset < len(raw):
                    count = os.write(fd, raw[offset:])
                    if count <= 0:
                        raise ReleaseControlError("fixture exclusive output write made no progress")
                    offset += count
                os.fchmod(fd, 0o444)
                os.fsync(fd)
                held = identity(os.fstat(fd))
                visible = identity(os.stat(path.name, dir_fd=parent, follow_symlinks=False))
                if held != visible:
                    raise ReleaseControlError("fixture created output was replaced before capture")
            finally:
                os.close(fd)
            os.fsync(parent)
            validate_links()
            ancestry = tuple(
                pins[str(part)] for part in reversed((destination.path / path).parents)
            )
            actual, current, dirs = _release_held_path(
                destination.path / path, expected_directories=ancestry, expected_identity=held
            )
            if actual != raw or current != held:
                raise ReleaseControlError("fixture exclusive installed bytes differ")
            file_rows.append((name, kind, raw, held, dirs))
        before_effect()
        validate_links()
        os.fsync(destination.fd)
        result = _ReleaseCapturedFiles(destination.path, destination.identities, tuple(file_rows))
        result.revalidate()
        return result
    except OSError as exc:
        raise ReleaseControlError(
            "fixture exclusive copy failed; all partial bytes are retained"
        ) from exc


def _release_fixture_stage_sidecars(
    emulation: _ReleaseFixtureEmulation,
    *,
    original_staged_directory: _ReleaseFixtureDirectory,
    original_parent_directories: Sequence[_ReleaseFixtureDirectory],
) -> _ReleaseCapturedFiles:
    """Called only with the actual supervisor-created stage directory custody."""
    bound = emulation.bound
    bound.revalidate()
    staged = original_staged_directory
    if staged.path != bound.original.directory / "staged":
        raise ReleaseControlError("fixture supplied stage directory is not the original invocation")
    known = {
        row[0]: row
        for row in (
            *bound.plan.captured.root_directories,
            *(x for member in bound.intent_capture.rows for x in member[4]),
        )
    }
    if any(known.get(row[0], row) != row for row in staged.identities):
        raise ReleaseControlError("fixture staging lost original root/intent ancestor custody")
    staged.revalidate()
    primary = _release_historical_path(
        _release_original_arguments(bound.plan.tool, list(bound.plan.argv))["out"],
        bound.plan.working_directory,
    ).name
    _release_fixture_exact_tree(
        staged,
        {name for name, _, _ in emulation.sidecars},
        empty_files=True,
        additional_files={primary} if primary in os.listdir(staged.fd) else set(),
    )
    return _release_fixture_write_set(
        staged,
        emulation.sidecars,
        before_effect=bound.revalidate,
        original_parent_directories=original_parent_directories,
    )


def _release_fixture_exact_tree(
    directory: _ReleaseFixtureDirectory,
    names: set[str],
    *,
    empty_files: bool = False,
    additional_files: set[str] | frozenset[str] = frozenset(),
) -> None:
    """NUL-safe exact namespace census through held descriptors, never pathlib traversal."""
    expected: dict[str, set[str]] = {".": set()}
    for name in names:
        path = _release_relative_suffix(name, "fixture planned staged member")
        for index, part in enumerate(path.parts):
            parent = Path(*path.parts[:index]).as_posix()
            expected.setdefault(parent, set())
            if index < len(path.parts) - 1 or not empty_files:
                expected[parent].add(part)
            if index < len(path.parts) - 1:
                expected.setdefault(Path(*path.parts[: index + 1]).as_posix(), set())
    expected["."].update(additional_files)
    opened = []
    try:
        fds = {".": directory.fd}
        for parent in sorted(expected, key=lambda p: (len(Path(p).parts), p)):
            fd = fds[parent]
            if set(os.listdir(fd)) != expected[parent]:
                raise ReleaseControlError(
                    "fixture staged namespace differs from complete original output plan"
                )
            for name in expected[parent]:
                relative = (Path(parent) / name).as_posix()
                info = os.stat(name, dir_fd=fd, follow_symlinks=False)
                if relative in expected:
                    child = os.open(name, os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW, dir_fd=fd)
                    opened.append(child)
                    fds[relative] = child
                    held = os.fstat(child)
                    if (held.st_dev, held.st_ino, held.st_mode) != (
                        info.st_dev,
                        info.st_ino,
                        info.st_mode,
                    ):
                        raise ReleaseControlError("fixture stage changed during namespace census")
                elif not stat.S_ISREG(info.st_mode) or info.st_nlink != 1:
                    raise ReleaseControlError(
                        "fixture staged output is unsafe or aliases another file"
                    )
        directory.revalidate()
    except OSError as exc:
        raise ReleaseControlError("fixture staged namespace cannot be inspected safely") from exc
    finally:
        _release_fixture_close_descriptors(tuple(reversed(opened)))


@dataclass(frozen=True)
class _ReleaseFixtureCollected:
    emulation: _ReleaseFixtureEmulation
    staged: _ReleaseCapturedFiles
    outputs: tuple[bytes, ...]


def _release_fixture_collect_staged(
    emulation: _ReleaseFixtureEmulation,
    *,
    original_staged_directory: _ReleaseFixtureDirectory,
    original_stage_files: _ReleaseCapturedFiles,
) -> _ReleaseFixtureCollected:
    """Exact byte/envelope inventory only; parent must apply all type-specific semantic owners."""
    bound = emulation.bound
    bound.revalidate()
    staged = original_staged_directory
    if (
        staged.path != bound.original.directory / "staged"
        or original_stage_files.root != staged.path
        or original_stage_files.root_directories != staged.identities
    ):
        raise ReleaseControlError("fixture collection lost the original created stage custody")
    original_stage_files.revalidate()
    expected = dict(bound.plan.output_plan)
    if {row[0] for row in original_stage_files.rows} != set(expected):
        raise ReleaseControlError(
            "fixture collector lacks original identity for every planned file"
        )
    _release_fixture_exact_tree(staged, set(expected))
    sidecars = {name: (schema, raw) for name, schema, raw in emulation.sidecars}
    outputs = []
    for name, schema in bound.plan.output_plan:
        row = next(row for row in original_stage_files.rows if row[0] == name)
        if row[1] != schema:
            raise ReleaseControlError("fixture staged type differs from original plan")
        raw = original_stage_files.read(name, kind=schema)
        if name in sidecars:
            if sidecars[name] != (schema, raw):
                raise ReleaseControlError("fixture staged native original differs")
        else:
            record = _source_json(raw, "fixture staged primary")
            validate_record(record, _RELEASE_GATE_PREREQUISITES[bound.plan.tool][0])
            if (
                record["status"] != "PASS"
                or record["synthetic"] is not True
                or record["signatures"] != []
                or record["invocation_id"] != bound.original.intent["invocation_id"]
                or record["sequence"] != bound.original.intent["sequence"]
                or record["data"].get("producer_intent_digest")
                != sha256_json(bound.original.intent)
                or record["data"].get("invocation_root_locator") != "invocations"
            ):
                raise ReleaseControlError(
                    "fixture staged primary has another original producer/mode"
                )
        outputs.append(
            canonical_json({"path": name, "schema_id": schema, "sha256": sha256_bytes(raw)})
        )
    original_stage_files.revalidate()
    _release_fixture_exact_tree(staged, set(expected))
    bound.revalidate()
    return _ReleaseFixtureCollected(emulation, original_stage_files, tuple(outputs))


def _release_fixture_install_sidecar_set(
    collected: _ReleaseFixtureCollected,
    *,
    original_run_directory: _ReleaseFixtureDirectory,
    original_parent_directories: Sequence[_ReleaseFixtureDirectory],
) -> _ReleaseCapturedFiles:
    """Mechanical complete output copy, called after parent graph/worker/quiescence checks.

    Returned bytes are never consumable authority absent the original successful full
    journal, semantic graph and durable completion witness. Failure retains partials.
    """
    bound = collected.emulation.bound
    root = original_run_directory
    if root.path != bound.original.root or root.identities != bound.plan.captured.root_directories:
        raise ReleaseControlError("fixture install lost the originally held run directory")

    def revalidate() -> None:
        bound.revalidate()
        collected.staged.revalidate()
        root.revalidate()

    revalidate()
    if {row[0] for row in collected.staged.rows} != set(dict(bound.plan.output_plan)):
        raise ReleaseControlError("fixture install inventory differs from original complete plan")
    # Each invocation owns one native stage/sequence directory; partial retries are forbidden.
    stage_prefix = (
        Path("native-fixture")
        / _invocation_stage(bound.plan.tool)
        / f"{bound.original.intent['sequence']:03d}"
    )
    prefix_custody = [
        directory
        for directory in original_parent_directories
        if directory.path == root.path / stage_prefix
    ]
    if len(prefix_custody) != 1:
        raise ReleaseControlError("fixture installer lacks original native stage directory custody")
    native_names = {
        Path(name).relative_to(stage_prefix).as_posix()
        for name, _ in bound.plan.output_plan
        if Path(name).is_relative_to(stage_prefix)
    }
    _release_fixture_exact_tree(prefix_custody[0], native_names, empty_files=True)
    values = []
    for name, schema in bound.plan.output_plan:
        raw = collected.staged.read(name, kind=schema)
        descriptor = canonical_json(
            {"path": name, "schema_id": schema, "sha256": sha256_bytes(raw)}
        )
        if descriptor not in collected.outputs:
            raise ReleaseControlError("fixture copy lost original collected descriptor")
        values.append((name, schema, raw))
    return _release_fixture_write_set(
        root,
        values,
        before_effect=revalidate,
        original_parent_directories=original_parent_directories,
    )


def _release_fixture_reserve_invocation(
    plan: _ReleaseFixtureSeedPlan,
) -> tuple[ReleaseInvocation, _ReleaseCapturedFiles]:
    """Reserve one fixture prerequisite journal through the retained original root."""
    from metriplane import __version__

    tool, directory, root = plan.tool, plan.directory, plan.captured.root
    if (
        directory.parents[2] != root
        or directory.parent != root / "invocations" / _invocation_stage(tool)
        or re.fullmatch(r"[0-9]{3,}", directory.name, flags=re.ASCII) is None
        or directory.name != f"{int(directory.name):03d}"
        or int(directory.name) < 1
    ):
        raise ReleaseControlError("fixture reservation has another fixed root/stage/sequence")
    plan.captured.revalidate()
    pins = plan.captured.root_directories
    known = {row[0]: row for row in pins}
    for _, _, _, _, ancestors in plan.captured.rows:
        for row in ancestors:
            if row[0] in known and known[row[0]] != row:
                raise ReleaseControlError("fixture reservation input directory pins conflict")
            known[row[0]] = row
    descriptors: list[int] = []
    try:
        root_fd = _release_gate_open_pinned_directory(root, pins)
        descriptors.append(root_fd)
        parent_fd = root_fd
        visible = root
        for name in ("invocations", _invocation_stage(tool)):
            plan.captured.revalidate()
            created = False
            try:
                os.mkdir(name, mode=0o700, dir_fd=parent_fd)
                created = True
            except FileExistsError:
                pass
            child = os.open(name, os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW, dir_fd=parent_fd)
            descriptors.append(child)
            current = os.fstat(child)
            visible /= name
            row = (str(visible), current.st_dev, current.st_ino, current.st_mode)
            if str(visible) in known and known[str(visible)] != row:
                raise ReleaseControlError("fixture journal ancestor differs from original capture")
            pins = (*pins, row)
            if created:
                if os.listdir(child):
                    raise ReleaseControlError("new fixture journal ancestor is occupied")
                os.fsync(child)
                os.fsync(parent_fd)
            parent_fd = child
        stage_fd, stage = parent_fd, visible
        inventory = _release_gate_stage_inventory(stage, stage_fd, pins)
        names = inventory["children"][str(stage)]
        if list(names) != [f"{number:03d}" for number in range(1, len(names) + 1)]:
            raise ReleaseControlError("fixture journal sequence inventory is noncanonical")
        if int(directory.name) != len(names) + 1:
            raise ReleaseControlError("fixture sequence is not the next original reservation")
        predecessor = None
        previous_digest = None
        if names:
            previous_directory = stage / names[-1]
            intent_path = previous_directory / "intent.json"
            identity = inventory["entries"].get(str(intent_path))
            if identity is None:
                raise ReleaseControlError("fixture predecessor lacks an original intent")
            prior_raw, _, _ = _release_held_path(
                intent_path,
                expected_prefix=tuple(inventory["directories"].values()),
                expected_identity=identity,
            )
            prior = _validate_intent_bytes(previous_directory, prior_raw)
            if prior.intent["tool"] != tool:
                raise ReleaseControlError("fixture predecessor has another command owner")
            terminal_path = previous_directory / "invocation.json"
            terminal_identity = inventory["entries"].get(str(terminal_path))
            if terminal_identity is not None:
                terminal_raw, _, _ = _release_held_path(
                    terminal_path,
                    expected_prefix=tuple(inventory["directories"].values()),
                    expected_identity=terminal_identity,
                )
                terminal = _source_json(terminal_raw, "fixture predecessor terminal")
                validate_record(terminal, "release-stage-invocation")
                if terminal_raw != canonical_json(terminal):
                    raise ReleaseControlError("fixture predecessor terminal is noncanonical")
                previous_digest = sha256_json(terminal)
            predecessor = {
                "sequence": prior.intent["sequence"],
                "intent_digest": sha256_json(prior.intent),
                "terminal_digest": previous_digest,
                "disposition": ("TERMINAL" if previous_digest else "INTERRUPTED_MISSING_TERMINAL"),
            }
        inputs = [
            {"path": str(root / name), "schema_id": schema, "sha256": digest}
            for name, schema, digest in plan.input_plan
        ]
        outputs = [{"path": name, "schema_id": schema} for name, schema in plan.output_plan]
        intent: dict[str, Any] = {
            "schema_version": "metriplane.release-invocation-intent.v1",
            "sequence": int(directory.name),
            "tool": tool,
            "tool_version": __version__,
            "argv": list(plan.argv),
            "started_at": datetime.now(UTC).isoformat().replace("+00:00", "Z"),
            "inputs": inputs,
            "environment": {
                "working_directory": str(plan.working_directory),
                "python": sys.version.split()[0],
                "fixture_mode": "1",
                "source_date_epoch": os.environ.get("SOURCE_DATE_EPOCH", ""),
                "python_hash_seed": os.environ.get("PYTHONHASHSEED", ""),
            },
            "planned_outputs": outputs,
            "previous_invocation_digest": previous_digest,
            "predecessor": predecessor,
        }
        intent["invocation_id"] = _intent_identity(intent)
        plan.captured.revalidate()
        _release_gate_stage_inventory(stage, stage_fd, pins, expected=inventory)
        os.mkdir(directory.name, mode=0o700, dir_fd=stage_fd)
        invocation_fd = os.open(
            directory.name, os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW, dir_fd=stage_fd
        )
        descriptors.append(invocation_fd)
        current = os.fstat(invocation_fd)
        if os.listdir(invocation_fd):
            raise ReleaseControlError("new fixture invocation directory is occupied")
        invocation_pins = (*pins, (str(directory), current.st_dev, current.st_ino, current.st_mode))
        os.fsync(invocation_fd)
        os.fsync(stage_fd)
        written = _release_gate_write_json_at(invocation_fd, "intent.json", intent)
        intent_name = (directory / "intent.json").relative_to(root).as_posix()
        captured = _ReleaseCapturedFiles.capture(
            root,
            [(intent_name, "release-invocation-intent")],
            forbidden=(),
            allowed_kinds=frozenset({"release-invocation-intent"}),
            expected_root_directories=plan.captured.root_directories,
            expected_known_directories=invocation_pins,
            expected_file_identities={intent_name: written},
        )
        _release_gate_stage_inventory(
            stage, stage_fd, pins, expected=inventory, excluded_sequence=directory.name
        )
        plan.captured.revalidate()
        context = _validate_intent_bytes(
            directory, captured.read(intent_name, kind="release-invocation-intent")
        )
        return context, captured
    except OSError as exc:
        raise ReleaseControlError(
            "fixture invocation cannot be reserved with original custody"
        ) from exc
    finally:
        errors: list[OSError] = []
        for descriptor in reversed(descriptors):
            try:
                os.close(descriptor)
            except OSError as exc:
                errors.append(exc)
        if errors:
            raise ReleaseControlError("fixture reservation descriptor cleanup failed") from errors[
                0
            ]


def _release_fixture_command_prepare(
    tool: str, argv: list[str], directory: Path
) -> _ReleaseFixtureSeedInvocation:
    """Bind a public native-fixture command to its complete supplied seed.

    The live path never enters this function.  The fixture seed remains test evidence;
    it supplies no release approval, durable-store binding or production authority.
    """
    if tool not in {
        "validate_release_evidence_stores.py",
        "capture_release_target_observations.py",
        "record_release_role_assignments.py",
        "retain_release_evidence.py",
        "export_release_attempt_index.py",
        "export_release_burn_lineage.py",
        "update_release_attempt_index.py",
    } or argv[:1] != [tool]:
        raise ReleaseControlError("fixture native command has another owner")
    root = directory.parents[2]
    arguments = _release_original_arguments(tool, argv)
    cwd = Path.cwd()
    if tool == "record_release_role_assignments.py":
        held, expected_inputs, input_types, selection = _release_fixture_role_command_inputs(
            root, arguments, cwd
        )
    elif tool == "capture_release_target_observations.py":
        paths = {
            "release-context": (
                "inputs/context.json",
                "metriplane.release-context.v1",
            ),
            "targets": ("inputs/targets.json", "metriplane.release-targets.v1"),
        }
        for flag, (name, _) in paths.items():
            if _release_historical_path(arguments[flag], cwd) != root / name:
                raise ReleaseControlError(
                    "fixture target command input has another fixed path: " + flag
                )
        held = _ReleaseCapturedFiles.capture(
            root,
            [(name, "prerequisite-original") for name, _ in paths.values()],
            forbidden=(),
            allowed_kinds=frozenset({"prerequisite-original"}),
        )
        expected_inputs = {
            flag: [
                {
                    "path": name,
                    "schema_id": schema,
                    "sha256": sha256_bytes(held.read(name, kind="prerequisite-original")),
                }
            ]
            for flag, (name, schema) in paths.items()
        }
        input_types = {name: schema for name, schema in paths.values()}
        selection = {
            "context_digest": sha256_json(
                _source_json(
                    held.read("inputs/context.json", kind="prerequisite-original"),
                    "fixture target context",
                )
            ),
            "registry_digest": expected_inputs["targets"][0]["sha256"],
        }
    elif tool == "retain_release_evidence.py":
        held, expected_inputs, input_types, selection = _release_fixture_retention_command_inputs(
            root, arguments, cwd
        )
    elif tool == "export_release_attempt_index.py":
        held, expected_inputs, input_types, selection = (
            _release_fixture_index_export_command_inputs(root, arguments, cwd)
        )
    elif tool == "export_release_burn_lineage.py":
        held, expected_inputs, input_types, selection = (
            _release_fixture_burn_lineage_command_inputs(root, arguments, cwd)
        )
    elif tool == "update_release_attempt_index.py":
        held, expected_inputs, input_types, selection = (
            _release_fixture_index_update_command_inputs(root, arguments, cwd)
        )
    else:
        held, expected_inputs, input_types, selection = _release_fixture_preflight_command_inputs(
            root, arguments, cwd
        )
    held.revalidate()
    plan = _release_fixture_seed_prepare(
        tool,
        argv,
        working_directory=cwd,
        held_inputs=held,
        expected_inputs=expected_inputs,
        input_types=input_types,
        selection=selection,
        live=False,
    )
    original, written_intent = _release_fixture_reserve_invocation(plan)
    intent_row = written_intent.rows[0]
    intent_capture = _ReleaseCapturedFiles(
        written_intent.root,
        written_intent.root_directories,
        ((intent_row[0], "prerequisite-original", *intent_row[2:]),),
    )
    return _release_fixture_seed_bind(original, plan=plan, original_intent_capture=intent_capture)


def _release_fixture_role_command_inputs(
    root: Path, arguments: Mapping[str, Any], cwd: Path
) -> tuple[
    _ReleaseCapturedFiles,
    dict[str, list[dict[str, str]]],
    dict[str, str],
    dict[str, Any],
]:
    """Capture the signed fixture role envelope and every referenced original byte."""
    flags = {
        "signed-assignments": "metriplane.release-protected-input.v1",
        "policy": "application/octet-stream",
        "release-context": "metriplane.release-context.v1",
    }
    if "provider-attestation-keyring" in arguments:
        flags["provider-attestation-keyring"] = "metriplane.provider-attestation-keyring.v1"
    paths = {flag: _release_historical_path(arguments[flag], cwd) for flag in flags}
    if any(not path.is_relative_to(root) or path == root for path in paths.values()):
        raise ReleaseControlError("fixture role command input escapes its fixed run root")
    protected_name = paths["signed-assignments"].relative_to(root).as_posix()
    first = _ReleaseCapturedFiles.capture(
        root,
        [(protected_name, "prerequisite-original")],
        forbidden=(),
        allowed_kinds=frozenset({"prerequisite-original"}),
    )
    protected_raw = first.read(protected_name, kind="prerequisite-original")
    protected = _source_json(protected_raw, "fixture protected role command input")
    validate_record(protected, "release-protected-input")
    data = _release_closed_mapping(
        protected["data"],
        {
            "input_kind",
            "assignment_kind",
            "decision",
            "authorized_role",
            "conflicts",
            "signer_identity",
            "signing_method",
            "issued_at",
            "expires_at",
            "authority_policy_digest",
            "provider_attestation_keyring_digest",
            "assignments",
            "assignment_payload_digest",
            "release_context",
            "assignment_policy_registry",
            "role_provenance_files",
            "subject_digests",
        },
        "fixture protected role command data",
    )
    names = set()
    for value in [
        data["release_context"],
        data["assignment_policy_registry"],
        *(value for value in data["role_provenance_files"].values() if value is not None),
    ]:
        row = _release_closed_mapping(
            value, {"path", "bytes", "sha256"}, "fixture role original reference"
        )
        suffix = _release_relative_suffix(row["path"], "fixture role original reference")
        path = paths["signed-assignments"].parent / suffix
        if not path.is_relative_to(root) or path == paths["signed-assignments"]:
            raise ReleaseControlError("fixture role original reference escapes or aliases")
        names.add(path.relative_to(root).as_posix())
    for flag in ("policy", "release-context"):
        if paths[flag].relative_to(root).as_posix() not in names:
            raise ReleaseControlError("fixture role command flag differs from signed reference")
    capture_names = sorted(
        {
            protected_name,
            *names,
            *(
                path.relative_to(root).as_posix()
                for flag, path in paths.items()
                if flag == "provider-attestation-keyring"
            ),
        }
    )
    held = _ReleaseCapturedFiles.capture(
        root,
        [(name, "prerequisite-original") for name in capture_names],
        forbidden=(),
        allowed_kinds=frozenset({"prerequisite-original"}),
        expected_root_directories=first.root_directories,
        expected_known_directories=first.rows[0][4],
    )
    if held.read(protected_name, kind="prerequisite-original") != protected_raw:
        raise ReleaseControlError("fixture protected role input changed during capture")
    expected_inputs = {
        flag: [
            {
                "path": path.relative_to(root).as_posix(),
                "schema_id": schema,
                "sha256": sha256_bytes(
                    held.read(path.relative_to(root).as_posix(), kind="prerequisite-original")
                ),
            }
        ]
        for flag, (path, schema) in {
            flag: (paths[flag], schema) for flag, schema in flags.items()
        }.items()
    }
    input_types = {name: "application/octet-stream" for name in capture_names}
    input_types[protected_name] = flags["signed-assignments"]
    input_types[paths["release-context"].relative_to(root).as_posix()] = flags["release-context"]
    if "provider-attestation-keyring" in paths:
        input_types[paths["provider-attestation-keyring"].relative_to(root).as_posix()] = flags[
            "provider-attestation-keyring"
        ]
    now = datetime.now(UTC).isoformat().replace("+00:00", "Z")
    assignments = data["assignments"]
    selection = {
        "context_digest": sha256_json(
            _source_json(
                held.read(
                    paths["release-context"].relative_to(root).as_posix(),
                    kind="prerequisite-original",
                ),
                "fixture role context",
            )
        ),
        "policy_digest": expected_inputs["policy"][0]["sha256"],
        "authority_policy_digest": data["authority_policy_digest"],
        "keyring_digest": data["provider_attestation_keyring_digest"],
        "independently_expected_operator": assignments["authorized_executor_id"],
        "use_interval": (now, now),
    }
    return held, expected_inputs, input_types, selection


def _release_fixture_preflight_command_inputs(
    root: Path, arguments: Mapping[str, Any], cwd: Path
) -> tuple[
    _ReleaseCapturedFiles,
    dict[str, list[dict[str, str]]],
    dict[str, str],
    dict[str, str],
]:
    """Capture the preflight registry and every referenced fixture control."""
    stores = _release_historical_path(arguments["stores"], cwd)
    if stores != root / "inputs/stores.json":
        raise ReleaseControlError("fixture preflight registry has another fixed input path")
    first = _ReleaseCapturedFiles.capture(
        root,
        [("inputs/stores.json", "prerequisite-original")],
        forbidden=(),
        allowed_kinds=frozenset({"prerequisite-original"}),
    )
    registry_raw = first.read("inputs/stores.json", kind="prerequisite-original")
    digest = sha256_bytes(registry_raw)
    backends = _release_fixture_backend_rows(registry_raw, expected_digest=digest)
    control_names: set[str] = set()
    for backend in backends:
        live_binding = _release_closed_mapping(
            backend["live_binding"],
            {
                "adapter_id",
                "public_configuration",
                "owner_binding_authority",
                "provider_resource_identity",
                "administration_identity",
                "durability_retention_policy",
                "namespace_policy",
            },
            "fixture preflight backend binding",
        )
        if live_binding["adapter_id"] != "synthetic-fixture-native-v1":
            raise ReleaseControlError("fixture preflight backend has another adapter")
        for field, reference in live_binding.items():
            if field == "adapter_id":
                continue
            row = _release_closed_mapping(
                reference, {"path", "bytes", "sha256"}, "fixture preflight control reference"
            )
            suffix = _release_relative_suffix(row["path"], "fixture preflight control")
            path = stores.parent / suffix
            if not path.is_relative_to(root) or path == stores:
                raise ReleaseControlError("fixture preflight control escapes or aliases registry")
            control_names.add(path.relative_to(root).as_posix())
    controls = _ReleaseCapturedFiles.capture(
        root,
        [(name, "prerequisite-original") for name in sorted(control_names)],
        forbidden=(),
        allowed_kinds=frozenset({"prerequisite-original"}),
        expected_root_directories=first.root_directories,
        expected_known_directories=first.rows[0][4],
    )
    held = _ReleaseCapturedFiles(
        root, first.root_directories, tuple(sorted((*first.rows, *controls.rows)))
    )
    expected_inputs = {
        "stores": [
            {
                "path": "inputs/stores.json",
                "schema_id": "metriplane.release-evidence-stores.v1",
                "sha256": digest,
            }
        ]
    }
    input_types = {
        name: (
            "metriplane.release-evidence-stores.v1"
            if name == "inputs/stores.json"
            else "application/octet-stream"
        )
        for name, _, _, _, _ in held.rows
    }
    return held, expected_inputs, input_types, {"registry_digest": digest}


def _release_fixture_retention_command_inputs(
    root: Path, arguments: Mapping[str, Any], cwd: Path
) -> tuple[
    _ReleaseCapturedFiles,
    dict[str, list[dict[str, str]]],
    dict[str, str],
    dict[str, Any],
]:
    """Capture one fixture retention subject plus both stores' governed controls."""
    if "through-stage" in arguments:
        raise ReleaseControlError(
            "RETENTION_THROUGH_STAGE_CUSTODY_REQUIRED: public fixture retention needs the complete original journal graph"
        )
    held, expected_inputs, input_types, selection = _release_fixture_preflight_command_inputs(
        root, arguments, cwd
    )
    values: dict[str, list[str]] = {}
    if "manifest" in arguments:
        values["manifest"] = [arguments["manifest"]]
    if "input" in arguments:
        values["input"] = list(arguments["input"])
    names: list[tuple[str, str]] = []
    for flag, paths in values.items():
        for value in paths:
            path = _release_historical_path(value, cwd)
            if not path.is_relative_to(root) or path == root:
                raise ReleaseControlError("fixture retention subject escapes its fixed run root")
            name = path.relative_to(root).as_posix()
            if name in input_types or any(name == existing for existing, _ in names):
                raise ReleaseControlError("fixture retention subject aliases another input")
            names.append((name, flag))
    subjects = _ReleaseCapturedFiles.capture(
        root,
        [(name, "prerequisite-original") for name, _ in names],
        forbidden=(),
        allowed_kinds=frozenset({"prerequisite-original"}),
        expected_root_directories=held.root_directories,
        expected_known_directories=held.rows[0][4],
    )
    combined = _ReleaseCapturedFiles(
        root, held.root_directories, tuple(sorted((*held.rows, *subjects.rows)))
    )
    for flag in values:
        expected_inputs[flag] = [
            {
                "path": name,
                "schema_id": "application/octet-stream",
                "sha256": sha256_bytes(combined.read(name, kind="prerequisite-original")),
            }
            for name, role in names
            if role == flag
        ]
    input_types.update({name: "application/octet-stream" for name, _ in names})
    selection["fixture_run_id"] = root.name
    combined.revalidate()
    return combined, expected_inputs, input_types, selection


def _release_fixture_index_export_command_inputs(
    root: Path, arguments: Mapping[str, Any], cwd: Path
) -> tuple[
    _ReleaseCapturedFiles,
    dict[str, list[dict[str, str]]],
    dict[str, str],
    dict[str, str],
]:
    """Capture the independently selected fixture index genesis and store registry."""
    paths = {
        "genesis": ("inputs/genesis.json", "metriplane.release-fixture-index-genesis.v1"),
        "stores": ("inputs/stores.json", "metriplane.release-evidence-stores.v1"),
    }
    for flag, (name, _) in paths.items():
        if _release_historical_path(arguments[flag], cwd) != root / name:
            raise ReleaseControlError("fixture index export input has another fixed path: " + flag)
    held = _ReleaseCapturedFiles.capture(
        root,
        [(name, "prerequisite-original") for name, _ in paths.values()],
        forbidden=(),
        allowed_kinds=frozenset({"prerequisite-original"}),
    )
    genesis_raw = held.read("inputs/genesis.json", kind="prerequisite-original")
    genesis_digest = sha256_bytes(genesis_raw)
    _release_fixture_index_genesis(genesis_raw)
    _release_fixture_backend_rows(
        held.read("inputs/stores.json", kind="prerequisite-original"),
        expected_digest=sha256_bytes(held.read("inputs/stores.json", kind="prerequisite-original")),
    )
    expected_inputs = {
        flag: [
            {
                "path": name,
                "schema_id": schema,
                "sha256": sha256_bytes(held.read(name, kind="prerequisite-original")),
            }
        ]
        for flag, (name, schema) in paths.items()
    }
    input_types = {name: schema for name, schema in paths.values()}
    if arguments["through-head"] != genesis_digest:
        held, history_types, _ = _release_fixture_index_export_history_capture(
            root,
            held=held,
            genesis_raw=genesis_raw,
            genesis_digest=genesis_digest,
            through_head=arguments["through-head"],
        )
        input_types.update(history_types)
    held.revalidate()
    return held, expected_inputs, input_types, {"genesis_digest": genesis_digest}


def _release_fixture_index_export_history_capture(
    root: Path,
    *,
    held: _ReleaseCapturedFiles,
    genesis_raw: bytes,
    genesis_digest: str,
    through_head: str,
) -> tuple[_ReleaseCapturedFiles, dict[str, str], int]:
    """Capture every passing first-party journal and record needed to explain one head."""
    stage = root / "invocations/update-release-attempt-index"
    journal_names: dict[str, str] = {}
    if stage.exists():
        for directory in _journal_sequences(stage):
            for path in sorted(directory.rglob("*")):
                relative_member = path.relative_to(directory)
                partial_namespace = relative_member.parts[0] in {"staged", "workspace"}
                info = path.lstat()
                unsafe = (
                    path.is_symlink()
                    or not stat.S_ISREG(info.st_mode)
                    or info.st_nlink != 1
                    or not info.st_mode & stat.S_IRUSR
                )
                if unsafe and partial_namespace:
                    continue
                if unsafe:
                    raise ReleaseControlError("fixture index ordinary journal member is unsafe")
                if stat.S_ISREG(info.st_mode):
                    journal_names[path.relative_to(root).as_posix()] = (
                        "metriplane.release-journal-artifact.v1"
                    )
    if journal_names:
        already = {row[0] for row in held.rows}
        journal_capture = _ReleaseCapturedFiles.capture(
            root,
            [
                (name, "prerequisite-original")
                for name in sorted(journal_names)
                if name not in already
            ],
            forbidden=(),
            allowed_kinds=frozenset({"prerequisite-original"}),
            expected_root_directories=held.root_directories,
            expected_known_directories=held.rows[0][4],
        )
        held = _ReleaseCapturedFiles(
            root, held.root_directories, tuple(sorted((*held.rows, *journal_capture.rows)))
        )

    contexts: dict[tuple[str, int], list[tuple[ReleaseInvocation, dict[str, Any] | None]]] = {}
    if stage.is_dir() and not stage.is_symlink():
        for directory in _journal_sequences(stage):
            intent_name = (directory / "intent.json").relative_to(root).as_posix()
            context = _validate_intent_bytes(
                directory, held.read(intent_name, kind="prerequisite-original")
            )
            terminal_name = (directory / "invocation.json").relative_to(root).as_posix()
            terminal = (
                _source_json(
                    held.read(terminal_name, kind="prerequisite-original"),
                    "captured fixture index terminal",
                )
                if any(row[0] == terminal_name for row in held.rows)
                else None
            )
            if terminal is not None:
                validate_record(terminal, "release-stage-invocation")
            key = (context.intent["invocation_id"], context.intent["sequence"])
            contexts.setdefault(key, []).append((context, terminal))

    terminal_outputs: set[str] = set()
    for matches in contexts.values():
        for _, terminal in matches:
            if terminal is None:
                continue
            outputs = terminal.get("data", {}).get("outputs")
            if not isinstance(outputs, list):
                raise ReleaseControlError("fixture index terminal outputs are malformed")
            for value in outputs:
                output_row = _release_closed_mapping(
                    value,
                    {"path", "schema_id", "sha256"},
                    "fixture index terminal output",
                )
                terminal_outputs.add(
                    _release_relative_suffix(
                        output_row["path"], "fixture index terminal output path"
                    ).as_posix()
                )
    if terminal_outputs:
        already = {row[0] for row in held.rows}
        output_capture = _ReleaseCapturedFiles.capture(
            root,
            [
                (name, "prerequisite-original")
                for name in sorted(terminal_outputs)
                if name not in already
            ],
            forbidden=(),
            allowed_kinds=frozenset({"prerequisite-original"}),
            expected_root_directories=held.root_directories,
            expected_known_directories=held.rows[0][4],
        )
        held = _ReleaseCapturedFiles(
            root, held.root_directories, tuple(sorted((*held.rows, *output_capture.rows)))
        )
    for matches in contexts.values():
        for context, summary in matches:
            if summary is None:
                continue
            replayed = _release_captured_journal_terminal(
                context, captured=held, require_pass=False
            )
            if replayed["status"] != "PASS":
                _release_captured_partial_inventory(context, captured=held)
    held.revalidate()

    candidates: dict[str, list[tuple[Path, dict[str, Any], dict[str, Any]]]] = {}
    for path in sorted(root.rglob("*.json")):
        relative = path.relative_to(root)
        if relative.parts[0] in {
            "inputs",
            "invocations",
            "native-fixture",
            ".fixture-native-state",
        }:
            continue
        try:
            record = _source_json(_safe_release_bytes(path), "fixture candidate index receipt")
            if (
                record.get("record_type") != "release-attempt-index"
                or record.get("data", {}).get("kind") != "update_receipt"
            ):
                continue
            validate_record(record, "release-attempt-index")
            entry = _release_index_receipt_content(record["data"])
        except (OSError, ReleaseControlError):
            continue
        candidates.setdefault(sha256_json(entry), []).append((path, record, entry))

    receipt_names = {
        path.relative_to(root).as_posix() for rows in candidates.values() for path, _, _ in rows
    }
    if receipt_names:
        already = {row[0] for row in held.rows}
        receipt_capture = _ReleaseCapturedFiles.capture(
            root,
            [
                (name, "prerequisite-original")
                for name in sorted(receipt_names)
                if name not in already
            ],
            forbidden=(),
            allowed_kinds=frozenset({"prerequisite-original"}),
            expected_root_directories=held.root_directories,
            expected_known_directories=held.rows[0][4],
        )
        held = _ReleaseCapturedFiles(
            root, held.root_directories, tuple(sorted((*held.rows, *receipt_capture.rows)))
        )
        held.revalidate()

    chain: list[tuple[Path, dict[str, Any], dict[str, Any], ReleaseInvocation]] = []
    cursor = _require_digest(through_head, "fixture selected index head")
    while cursor != genesis_digest:
        if any(sha256_json(row[2]) == cursor for row in chain):
            raise ReleaseControlError("fixture index head lacks a complete acyclic receipt chain")
        owners = candidates.get(cursor, [])
        if not owners:
            raise ReleaseControlError("fixture index head lacks a complete acyclic receipt chain")
        passing = []
        for path, receipt, entry in owners:
            matches = contexts.get((receipt["invocation_id"], receipt["sequence"]), [])
            if len(matches) != 1 or matches[0][1] is None or matches[0][1]["status"] != "PASS":
                # An installed receipt from an interrupted producer is retained evidence,
                # but cannot own a successful index generation.
                continue
            terminal = _release_captured_journal_terminal(
                matches[0][0], captured=held, require_pass=True
            )
            witness_name = (
                (matches[0][0].directory / "terminal-commit.json").relative_to(root).as_posix()
            )
            expected_witness = {
                "schema_version": "metriplane.gate-terminal-commit.v1",
                "intent_sha256": sha256_json(matches[0][0].intent),
                "terminal_sha256": sha256_json(terminal),
            }
            if not any(row[0] == witness_name for row in held.rows) or held.read(
                witness_name, kind="prerequisite-original"
            ) != canonical_json(expected_witness):
                raise ReleaseControlError(
                    "fixture index passing journal lacks its durable terminal-commit witness"
                )
            receipt_name = path.relative_to(root).as_posix()
            output_ref = {
                "path": receipt_name,
                "schema_id": "metriplane.release-attempt-index.v1",
                "sha256": sha256_bytes(held.read(receipt_name, kind="prerequisite-original")),
            }
            if (
                receipt["data"].get("invocation_root_locator") != "invocations"
                or receipt["data"].get("producer_intent_digest")
                != sha256_json(matches[0][0].intent)
                or output_ref not in terminal["data"]["outputs"]
            ):
                raise ReleaseControlError(
                    "fixture index receipt differs from its captured producer journal"
                )
            passing.append((path, receipt, entry, matches[0][0]))
        committed = [row for row in passing if row[1]["data"]["disposition"] == "committed"]
        if len(committed) > 1 or not passing:
            raise ReleaseControlError(
                "fixture index head lacks one original operation receipt lineage"
            )
        row = (
            committed[0]
            if committed
            else min(passing, key=lambda value: (value[1]["sequence"], str(value[0])))
        )
        chain.append(row)
        cursor = row[2]["previous_head"] or row[2]["genesis_digest"]
    chain.reverse()
    if [row[2]["generation"] for row in chain] != list(range(1, len(chain) + 1)):
        raise ReleaseControlError("fixture index receipt generations are incomplete")

    names: dict[str, str] = {
        **journal_names,
        **{
            name: "metriplane.release-journal-artifact.v1"
            for name in terminal_outputs | receipt_names
        },
    }
    for receipt_path, receipt, entry, context in chain:
        arguments = _release_original_arguments(context.intent["tool"], context.intent["argv"])
        historical_cwd = Path(context.intent["environment"]["working_directory"])
        historical_invocation = _release_historical_path(
            arguments["invocation-dir"], historical_cwd
        )
        try:
            historical_root = historical_invocation.parents[2]
        except IndexError as exc:
            raise ReleaseControlError(
                "fixture index historical invocation root is incomplete"
            ) from exc

        def current_original(flag: str) -> Path:
            historical = _release_historical_path(arguments[flag], historical_cwd)
            try:
                suffix = historical.relative_to(historical_root)
            except ValueError as exc:
                raise ReleaseControlError(
                    "fixture index history input escapes its historical run root"
                ) from exc
            current = root / suffix
            if not current.is_relative_to(root):
                raise ReleaseControlError("fixture index history input escapes its run root")
            return current

        names[receipt_path.relative_to(root).as_posix()] = "metriplane.release-attempt-index.v1"
        for path in sorted(context.directory.rglob("*")):
            if path.is_file() and not path.is_symlink():
                names.setdefault(
                    path.relative_to(root).as_posix(),
                    "application/vnd.metriplane.release-journal-evidence",
                )
        for flag, kind in (
            ("entry-manifest", "release-evidence-manifest"),
            ("entry-receipts", "release-retention-receipts"),
        ):
            path = current_original(flag)
            names[path.relative_to(root).as_posix()] = "metriplane." + kind + ".v1"
            if flag == "entry-manifest":
                manifest = _source_json(
                    _safe_release_bytes(path), "fixture index history original manifest"
                )
                validate_record(manifest, "release-evidence-manifest")
                entry_root = _release_index_manifest_entry_root(
                    root=root,
                    manifest_path=path,
                    manifest=manifest,
                    scope=entry["scope"],
                )
                for member in _release_evidence_manifest_content(manifest["data"]):
                    member_path = entry_root / _release_relative_suffix(
                        member["path"], "fixture index history manifest member"
                    )
                    if not member_path.is_relative_to(root):
                        raise ReleaseControlError(
                            "fixture index history manifest member escapes its run root"
                        )
                    raw = _safe_release_bytes(member_path)
                    if len(raw) != member["size"] or sha256_bytes(raw) != member["sha256"]:
                        raise ReleaseControlError(
                            "fixture index history manifest member bytes differ"
                        )
                    schema = "application/octet-stream"
                    try:
                        candidate = _source_json(raw, "fixture index history manifest record")
                        record_type = candidate.get("record_type")
                        if isinstance(record_type, str):
                            validate_record(candidate, record_type)
                            schema = "metriplane." + record_type + ".v1"
                    except ReleaseControlError:
                        pass
                    names[member_path.relative_to(root).as_posix()] = schema
        _, operations = _release_fixture_index_expectations(
            arguments,
            tool="update_release_attempt_index.py",
            genesis_raw=genesis_raw,
            expected_genesis_digest=genesis_digest,
            original_entry=entry,
            expected_prior_generation=entry["generation"] - 1,
        )
        plan = _release_fixture_native_plan(
            tool="update_release_attempt_index.py",
            sequence=context.intent["sequence"],
            subject={
                "kind": "index_scope",
                "subject_digest": sha256_json(entry["scope"]),
                "original_policy_digest": genesis_digest,
            },
            operations=operations,
        )
        names[plan[0]["paths"]["response"]] = "application/octet-stream"
    already_held = {row[0] for row in held.rows}
    extra = _ReleaseCapturedFiles.capture(
        root,
        [(name, "prerequisite-original") for name in sorted(names) if name not in already_held],
        forbidden=(),
        allowed_kinds=frozenset({"prerequisite-original"}),
        expected_root_directories=held.root_directories,
        expected_known_directories=held.rows[0][4],
    )
    combined = _ReleaseCapturedFiles(
        root, held.root_directories, tuple(sorted((*held.rows, *extra.rows)))
    )
    combined.revalidate()
    return combined, names, len(chain)


def _release_fixture_burn_lineage_command_inputs(
    root: Path, arguments: Mapping[str, Any], cwd: Path
) -> tuple[
    _ReleaseCapturedFiles,
    dict[str, list[dict[str, str]]],
    dict[str, str],
    dict[str, str],
]:
    """Capture one complete export and every retained original needed for burn replay."""
    genesis_path = _release_historical_path(arguments["genesis"], cwd)
    export_path = _release_historical_path(arguments["index-export"], cwd)
    if genesis_path != root / "inputs/genesis.json" or not export_path.is_relative_to(root):
        raise ReleaseControlError("fixture burn lineage input has another run or genesis")
    names = {
        "inputs/genesis.json": "metriplane.release-fixture-index-genesis.v1",
        export_path.relative_to(root).as_posix(): "metriplane.release-attempt-index.v1",
    }
    held = _ReleaseCapturedFiles.capture(
        root,
        [(name, "prerequisite-original") for name in sorted(names)],
        forbidden=(),
        allowed_kinds=frozenset({"prerequisite-original"}),
    )
    genesis_raw = held.read("inputs/genesis.json", kind="prerequisite-original")
    genesis_digest = sha256_bytes(genesis_raw)
    _release_fixture_index_genesis(genesis_raw)
    export_raw = held.read(export_path.relative_to(root).as_posix(), kind="prerequisite-original")
    export = _source_json(export_raw, "fixture burn lineage original index export")
    validate_record(export, "release-attempt-index")
    data = export["data"]
    if (
        export["status"] != "PASS"
        or export["synthetic"] is not True
        or data.get("kind") != "complete_export"
        or data.get("genesis_digest") != genesis_digest
        or data.get("through_head") != arguments["through-head"]
    ):
        raise ReleaseControlError("fixture burn lineage selects another complete export")
    held, history_types, generation = _release_fixture_index_export_history_capture(
        root,
        held=held,
        genesis_raw=genesis_raw,
        genesis_digest=genesis_digest,
        through_head=arguments["through-head"],
    )
    names.update(history_types)
    if data.get("generation") != generation or len(data.get("entries", [])) != generation:
        raise ReleaseControlError("fixture burn lineage export generation differs from history")

    extra_names: dict[str, str] = {}
    for row in data["entries"]:
        entry = _release_index_entry_content(row["entry"])
        if entry["milestone"] != arguments["milestone"] or entry["scope"]["stage"] != "target-burn":
            continue
        manifest_ref = _release_closed_mapping(
            row["original_manifest"],
            {"record_type", "record_digest", "original_file"},
            "fixture burn lineage manifest link",
        )["original_file"]
        manifest_file = _release_closed_mapping(
            manifest_ref, {"path", "bytes", "sha256"}, "fixture burn manifest file"
        )
        manifest_name = _release_relative_suffix(
            manifest_file["path"], "fixture burn manifest path"
        ).as_posix()
        manifest = _source_json(
            held.read(manifest_name, kind="prerequisite-original"),
            "fixture burn original manifest",
        )
        candidates = []
        for member in _release_evidence_manifest_content(manifest["data"]):
            subject_name = _release_relative_suffix(
                member["path"], "fixture burn manifest subject"
            ).as_posix()
            subject_path = root / subject_name
            if not subject_path.is_file() or subject_path.is_symlink():
                continue
            raw = _safe_release_bytes(subject_path)
            if len(raw) != member["size"] or sha256_bytes(raw) != member["sha256"]:
                raise ReleaseControlError("fixture burn manifest subject bytes differ")
            try:
                subject = _source_json(raw, "fixture burn subject")
                validate_record(subject, "release-target-burn")
            except ReleaseControlError:
                continue
            candidates.append(subject_name)
        if len(candidates) != 1:
            raise ReleaseControlError("fixture burn manifest lacks one exact retained burn")
        extra_names[candidates[0]] = "metriplane.release-target-burn.v1"

    export_stage = root / "invocations/export-release-attempt-index"
    matches = []
    if export_stage.is_dir() and not export_stage.is_symlink():
        for directory in _journal_sequences(export_stage):
            context = _validate_intent(directory)
            if (
                context.intent["invocation_id"] == export["invocation_id"]
                and context.intent["sequence"] == export["sequence"]
            ):
                matches.append(context)
    if len(matches) != 1 or _validate_terminal(matches[0])["status"] != "PASS":
        raise ReleaseControlError("fixture burn lineage lacks its passing original export journal")
    validate_release_producer_journal(
        export,
        export_path,
        producer="export_release_attempt_index.py",
    )
    for path in sorted(matches[0].directory.rglob("*")):
        if path.is_file() and not path.is_symlink():
            extra_names.setdefault(path.relative_to(root).as_posix(), "application/octet-stream")
    already = {row[0] for row in held.rows}
    extra = _ReleaseCapturedFiles.capture(
        root,
        [(name, "prerequisite-original") for name in sorted(extra_names) if name not in already],
        forbidden=(),
        allowed_kinds=frozenset({"prerequisite-original"}),
        expected_root_directories=held.root_directories,
        expected_known_directories=held.rows[0][4],
    )
    held = _ReleaseCapturedFiles(
        root, held.root_directories, tuple(sorted((*held.rows, *extra.rows)))
    )
    names.update(extra_names)
    expected_inputs = {
        flag: [
            {
                "path": path.relative_to(root).as_posix(),
                "schema_id": schema,
                "sha256": sha256_bytes(
                    held.read(path.relative_to(root).as_posix(), kind="prerequisite-original")
                ),
            }
        ]
        for flag, path, schema in (
            ("genesis", genesis_path, "metriplane.release-fixture-index-genesis.v1"),
            ("index-export", export_path, "metriplane.release-attempt-index.v1"),
        )
    }
    held.revalidate()
    return held, expected_inputs, names, {"genesis_digest": genesis_digest}


def _release_fixture_index_update_command_inputs(
    root: Path, arguments: Mapping[str, Any], cwd: Path
) -> tuple[
    _ReleaseCapturedFiles,
    dict[str, list[dict[str, str]]],
    dict[str, str],
    dict[str, Any],
]:
    """Capture one first-generation fixture CAS and its retained staging subject."""
    if arguments["scope-kind"] != "release_staging" or arguments["stage"] not in {
        "target-burn",
        "staging-failure",
    }:
        raise ReleaseControlError(
            "INDEX_UPDATE_SCOPE_GRAPH_REQUIRED: fixture CAS needs a release-staging subject"
        )
    paths = {
        "entry-manifest": (
            _release_historical_path(arguments["entry-manifest"], cwd),
            "metriplane.release-evidence-manifest.v1",
        ),
        "entry-receipts": (
            _release_historical_path(arguments["entry-receipts"], cwd),
            "metriplane.release-retention-receipts.v1",
        ),
    }
    if any(not path.is_relative_to(root) or path == root for path, _ in paths.values()):
        raise ReleaseControlError("fixture CAS manifest or retention escapes its run root")
    first = _ReleaseCapturedFiles.capture(
        root,
        [
            *(
                (path.relative_to(root).as_posix(), "prerequisite-original")
                for path, _ in paths.values()
            ),
            ("inputs/genesis.json", "prerequisite-original"),
        ],
        forbidden=(),
        allowed_kinds=frozenset({"prerequisite-original"}),
    )
    manifest_path = paths["entry-manifest"][0]
    manifest_raw = first.read(
        manifest_path.relative_to(root).as_posix(), kind="prerequisite-original"
    )
    manifest = _source_json(manifest_raw, "fixture CAS original manifest")
    validate_record(manifest, "release-evidence-manifest")
    if manifest["status"] != "PASS" or manifest["synthetic"] is not True:
        raise ReleaseControlError("fixture CAS manifest is not passing synthetic evidence")
    scope_id = _require_nonempty_string(
        arguments.get("scope-id"), "fixture CAS independently selected scope"
    )
    scope = _release_index_scope_content(
        {
            "kind": "release_staging",
            "scope_id": scope_id,
            "stage": arguments["stage"],
            "sequence": arguments["sequence"],
            "milestone": arguments["milestone"],
            "run_id": arguments["run-id"],
            "release_tag": arguments["release-tag"],
            "candidate_id": None,
        },
        milestone=arguments["milestone"],
    )
    role = (
        "release-target-burn" if arguments["stage"] == "target-burn" else "release-staging-attempt"
    )
    entries = _release_evidence_manifest_content(manifest["data"])
    matches = list(entries)
    if len(matches) != 1:
        raise ReleaseControlError("fixture CAS manifest does not select exactly one subject")
    entry_root = _release_index_manifest_entry_root(
        root=root, manifest_path=manifest_path, manifest=manifest, scope=scope
    )
    subject_path = entry_root / _release_relative_suffix(
        matches[0]["path"], "fixture CAS manifest subject"
    )
    if not subject_path.is_relative_to(root):
        raise ReleaseControlError("fixture CAS subject escapes its run root")
    subject_name = subject_path.relative_to(root).as_posix()
    subject_capture = _ReleaseCapturedFiles.capture(
        root,
        [(subject_name, "prerequisite-original")],
        forbidden=(),
        allowed_kinds=frozenset({"prerequisite-original"}),
        expected_root_directories=first.root_directories,
        expected_known_directories=first.rows[0][4],
    )
    held = _ReleaseCapturedFiles(
        root, first.root_directories, tuple(sorted((*first.rows, *subject_capture.rows)))
    )
    subject_raw = held.read(subject_name, kind="prerequisite-original")
    if len(subject_raw) != matches[0]["size"] or sha256_bytes(subject_raw) != matches[0]["sha256"]:
        raise ReleaseControlError("fixture CAS subject differs from its manifest")
    subject_record = _source_json(subject_raw, "fixture CAS subject")
    subject_kind = (
        "release-target-burn" if role == "release-target-burn" else "release-staging-attempt"
    )
    validate_record(subject_record, subject_kind)
    genesis_path = root / "inputs/genesis.json"
    genesis_raw = held.read("inputs/genesis.json", kind="prerequisite-original")
    genesis_digest = sha256_bytes(genesis_raw)
    _release_fixture_index_genesis(genesis_raw)
    expected_inputs = {
        flag: [
            {
                "path": path.relative_to(root).as_posix(),
                "schema_id": schema,
                "sha256": sha256_bytes(
                    held.read(path.relative_to(root).as_posix(), kind="prerequisite-original")
                ),
            }
        ]
        for flag, (path, schema) in paths.items()
    }
    input_types = {
        **{path.relative_to(root).as_posix(): schema for path, schema in paths.values()},
        "inputs/genesis.json": "metriplane.release-fixture-index-genesis.v1",
        subject_name: "metriplane." + subject_kind + ".v1",
    }
    prior_generation = 0
    if arguments["expected-head"] != genesis_digest:
        held, history_types, prior_generation = _release_fixture_index_export_history_capture(
            root,
            held=held,
            genesis_raw=genesis_raw,
            genesis_digest=genesis_digest,
            through_head=arguments["expected-head"],
        )
        input_types.update(history_types)
    held.revalidate()
    return (
        held,
        expected_inputs,
        input_types,
        {
            "genesis_path": genesis_path,
            "genesis_digest": genesis_digest,
            "expected_prior_generation": prior_generation,
            "subject_path": subject_path,
            "subject_record": subject_record,
            "expected_scope": scope,
            "expected_operation_id": arguments["operation-id"],
            "expected_milestone": arguments["milestone"],
            "expected_release_tag": arguments["release-tag"],
            "expected_index_backend": arguments["index-backend"],
            "expected_prior_head": arguments["expected-head"],
            "attempt_directory": None,
            "expected_attempt_id": None,
            "coordination_record": None,
            "coordination_path": None,
        },
    )


def _release_fixture_primary(
    emulation: _ReleaseFixtureEmulation,
) -> bytes:
    bound = emulation.bound
    original, plan = bound.original, bound.plan
    operations = _release_fixture_native_plan(
        tool=plan.tool,
        sequence=original.intent["sequence"],
        subject=_source_json(plan.subject, "fixture native subject"),
        operations=[_source_json(raw, "fixture native operation") for raw in plan.operations],
    )
    if plan.tool == "capture_release_target_observations.py":
        sidecars = {name: raw for name, _, raw in emulation.sidecars}

        def ref(name: str) -> dict[str, Any]:
            raw = sidecars[name]
            return {"path": name, "bytes": len(raw), "sha256": sha256_bytes(raw)}

        def original_ref(name: str) -> dict[str, Any]:
            raw = plan.captured.read(name, kind="prerequisite-original")
            return {"path": name, "bytes": len(raw), "sha256": sha256_bytes(raw)}

        rows = []
        for item, response_raw in zip(operations, plan.response_payloads, strict=True):
            response = _source_json(response_raw, "fixture target response")
            artifacts = []
            for artifact in response["artifacts"]:
                source = artifact["original_read_back"]["path"]
                artifact_ref = ref(source)
                if (
                    artifact_ref["bytes"] != artifact["bytes"]
                    or artifact_ref["sha256"] != artifact["sha256"]
                ):
                    raise ReleaseControlError(
                        "fixture target artifact differs from its supplied original bytes"
                    )
                artifacts.append(
                    {
                        "name": artifact["name"],
                        "expected_digest": None,
                        "observed_digest": artifact["sha256"],
                        "size": artifact["bytes"],
                        "original_read_back": artifact_ref,
                    }
                )
            rows.append(
                {
                    "target_id": response["target_id"],
                    "version": response["normalized_package_version"],
                    "state": response["state"],
                    "raw_result_digest": ref(item["paths"]["response"])["sha256"],
                    "artifacts": artifacts,
                }
            )
        data = {
            "producer_intent_digest": sha256_json(original.intent),
            "invocation_root_locator": "invocations",
            "api_version": _RELEASE_FIXTURE_API_VERSION,
            "capture_phase": "prebuild",
            "captured_at": emulation.operation_times[-1][1],
            "provider": "test-fixture",
            "tool": plan.tool,
            "registry_digest": original_ref("inputs/targets.json")["sha256"],
            "original_registry": original_ref("inputs/targets.json"),
            "original_release_context": {
                "record_type": "release-context",
                "record_digest": original_ref("inputs/context.json")["sha256"],
                "original_file": original_ref("inputs/context.json"),
            },
            "observations": [ref(item["paths"]["response"]) for item in operations],
            "targets": rows,
        }
        data["observation_digest"] = sha256_json(data)
        return canonical_json(
            make_record(
                "release-target-observations",
                data,
                invocation_id=original.intent["invocation_id"],
                sequence=original.intent["sequence"],
                synthetic=True,
            )
        )
    if plan.tool == "record_release_role_assignments.py":
        arguments = _release_original_arguments(plan.tool, list(plan.argv))
        protected_path = _release_historical_path(
            arguments["signed-assignments"], plan.working_directory
        )
        protected_name = protected_path.relative_to(plan.captured.root).as_posix()
        protected_raw = plan.captured.read(protected_name, kind="prerequisite-original")
        protected = _source_json(protected_raw, "fixture original protected roles")
        assignments = protected["data"]["assignments"]
        data = {
            **assignments,
            "kind": "recorded_assignments",
            "original_protected_input": {
                "path": protected_name,
                "bytes": len(protected_raw),
                "sha256": sha256_bytes(protected_raw),
            },
            "original_protected_input_digest": sha256_json(protected),
            "producer_intent_digest": sha256_json(original.intent),
            "invocation_root_locator": "invocations",
        }
        return canonical_json(
            make_record(
                "release-role-assignments",
                data,
                invocation_id=original.intent["invocation_id"],
                sequence=original.intent["sequence"],
                synthetic=True,
            )
        )
    if plan.tool == "retain_release_evidence.py":
        sidecars = {name: raw for name, _, raw in emulation.sidecars}

        def native_ref(name: str) -> dict[str, Any]:
            raw = sidecars[name]
            return {"path": name, "bytes": len(raw), "sha256": sha256_bytes(raw)}

        stores = []
        for start in (0, 3):
            request = operations[start]["request"]["arguments"]
            stores.append(
                {
                    "store_id": request["store_id"],
                    "content_digest": request["subject_digest"],
                    "read_back_digest": request["subject_digest"],
                    "put_receipt_digest": native_ref(operations[start]["paths"]["response"])[
                        "sha256"
                    ],
                    "hold_receipt_digest": native_ref(operations[start + 1]["paths"]["response"])[
                        "sha256"
                    ],
                    "namespace": request["namespace"],
                    "object_key": request["object_key"],
                    "independence_group": request["administration_identity"],
                    "backend_binding_digest": request["binding_digest"],
                    "native_proofs": {
                        "put": native_ref(operations[start]["paths"]["response"]),
                        "hold": native_ref(operations[start + 1]["paths"]["response"]),
                        "read_back": native_ref(operations[start + 2]["paths"]["response"]),
                    },
                }
            )
        registry_raw = plan.captured.read("inputs/stores.json", kind="prerequisite-original")
        data = {
            "producer_intent_digest": sha256_json(original.intent),
            "invocation_root_locator": "invocations",
            "all_content_equal": True,
            "input_digest": _source_json(plan.subject, "fixture retention subject")[
                "subject_digest"
            ],
            "original_registry": {
                "path": "inputs/stores.json",
                "bytes": len(registry_raw),
                "sha256": sha256_bytes(registry_raw),
            },
            "phase": _release_original_arguments(plan.tool, list(plan.argv))["phase"],
            "retained_at": emulation.operation_times[-1][1],
            "stores": stores,
            "receipt_set_digest": sha256_json(stores),
        }
        _release_retention_content(data)
        return canonical_json(
            make_record(
                "release-retention-receipts",
                data,
                invocation_id=original.intent["invocation_id"],
                sequence=original.intent["sequence"],
                synthetic=True,
            )
        )
    if plan.tool in {"export_release_attempt_index.py", "export_release_burn_lineage.py"}:
        response = _source_json(plan.response_payloads[0], "fixture index read response")
        response_path = operations[0]["paths"]["response"]
        response_raw = {name: raw for name, _, raw in emulation.sidecars}[response_path]
        index_native_ref = {
            "path": response_path,
            "bytes": len(response_raw),
            "sha256": sha256_bytes(response_raw),
        }
        genesis_raw = plan.captured.read("inputs/genesis.json", kind="prerequisite-original")
        typed = {name: schema for name, schema, _ in plan.input_plan}

        def captured_ref(name: str) -> dict[str, Any]:
            raw = plan.captured.read(name, kind="prerequisite-original")
            return {"path": name, "bytes": len(raw), "sha256": sha256_bytes(raw)}

        def records(kind: str) -> list[tuple[str, dict[str, Any]]]:
            result = []
            schema = "metriplane." + kind + ".v1"
            for name, value in typed.items():
                if value != schema:
                    continue
                record = _source_json(
                    plan.captured.read(name, kind="prerequisite-original"),
                    "fixture export original " + kind,
                )
                validate_record(record, kind)
                result.append((name, record))
            return result

        if plan.tool == "export_release_burn_lineage.py":
            export_records = [
                (name, value)
                for name, value in records("release-attempt-index")
                if value["data"].get("kind") == "complete_export"
            ]
            if len(export_records) != 1:
                raise ReleaseControlError("fixture burn lineage lacks one complete index export")
            export_name, export = export_records[0]
            if (
                export["data"].get("kind") != "complete_export"
                or export["data"].get("through_head") != response["through_head"]
                or [row["entry"] for row in export["data"].get("entries", [])]
                != response["entries"]
            ):
                raise ReleaseControlError("fixture burn lineage changes its complete index export")

            def linked_record(value: object, kind: str) -> tuple[str, dict[str, Any]]:
                link = _release_closed_mapping(
                    value,
                    {"record_type", "record_digest", "original_file"},
                    "fixture burn indexed link",
                )
                raw_ref = _release_closed_mapping(
                    link["original_file"],
                    {"path", "bytes", "sha256"},
                    "fixture burn indexed original",
                )
                name = _release_relative_suffix(
                    raw_ref["path"], "fixture burn indexed path"
                ).as_posix()
                raw = plan.captured.read(name, kind="prerequisite-original")
                record = _source_json(raw, "fixture burn indexed record")
                validate_record(record, kind)
                if (
                    link["record_type"] != kind
                    or link["record_digest"] != sha256_json(record)
                    or raw_ref != {"path": name, "bytes": len(raw), "sha256": sha256_bytes(raw)}
                ):
                    raise ReleaseControlError("fixture burn indexed link differs")
                return name, record

            burns = []
            seen: set[tuple[str, str]] = set()
            arguments = _release_original_arguments(plan.tool, list(plan.argv))
            for row in export["data"]["entries"]:
                entry = _release_index_entry_content(row["entry"])
                if (
                    entry["milestone"] != arguments["milestone"]
                    or entry["scope"]["stage"] != "target-burn"
                ):
                    continue
                manifest_name, manifest = linked_record(
                    row["original_manifest"], "release-evidence-manifest"
                )
                _, receipt = linked_record(row["original_receipt"], "release-attempt-index")
                candidates = []
                for name, burn in records("release-target-burn"):
                    matches = [
                        member
                        for member in _release_evidence_manifest_content(manifest["data"])
                        if (Path(manifest_name).parent / member["path"]).as_posix() == name
                        or member["path"] == name
                    ]
                    if len(matches) != 1:
                        continue
                    raw = plan.captured.read(name, kind="prerequisite-original")
                    if matches[0]["size"] != len(raw) or matches[0]["sha256"] != sha256_bytes(raw):
                        raise ReleaseControlError("fixture burn manifest member differs")
                    candidates.append(burn)
                if len(candidates) != 1 or candidates[0]["data"].get("disposition") != "new_burn":
                    raise ReleaseControlError("fixture burn entry lacks one retained new burn")
                burn = candidates[0]["data"]
                for target in sorted(
                    burn["affected_targets"], key=lambda item: (item["target_id"], item["version"])
                ):
                    key = (target["target_id"], target["version"])
                    if key in seen:
                        continue
                    seen.add(key)
                    burns.append(
                        {
                            "burn_manifest_digest": sha256_json(manifest),
                            "index_receipt_digest": sha256_json(receipt),
                            "observation_digest": burn["observation_digest"],
                            "package_version": target["version"],
                            "release_tag": "v" + target["version"],
                            "sequence": entry["scope"]["sequence"],
                            "target_id": target["target_id"],
                        }
                    )
            data = {
                "burns": burns,
                "index_backend_id": "attempt-index",
                "index_genesis_digest": response["genesis_digest"],
                "milestone": arguments["milestone"],
                "original_genesis": captured_ref("inputs/genesis.json"),
                "original_index_export": {
                    "record_type": "release-attempt-index",
                    "record_digest": sha256_json(export),
                    "original_file": captured_ref(export_name),
                },
                "read_back_complete": True,
                "through_head": response["through_head"],
                "producer_intent_digest": sha256_json(original.intent),
                "invocation_root_locator": "invocations",
            }
            data["lineage_digest"] = sha256_json(data)
            return canonical_json(
                make_record(
                    "release-burn-lineage",
                    data,
                    invocation_id=original.intent["invocation_id"],
                    sequence=original.intent["sequence"],
                    synthetic=True,
                )
            )

        receipt_records = records("release-attempt-index")
        manifest_records = records("release-evidence-manifest")
        retention_records = records("release-retention-receipts")
        exported = []
        for entry in response["entries"]:
            entry = _release_index_entry_content(entry)
            receipt_matches = [
                (name, record)
                for name, record in receipt_records
                if record["data"].get("kind") == "update_receipt"
                and canonical_json(_release_index_receipt_content(record["data"]))
                == canonical_json(entry)
            ]
            manifest_matches = [
                (name, record)
                for name, record in manifest_records
                if sha256_json(record) == entry["entry_manifest_digest"]
            ]
            retention_matches = [
                (name, record)
                for name, record in retention_records
                if sha256_json(record) == entry["entry_receipts_digest"]
            ]
            native_matches = []
            for name, schema in typed.items():
                if schema != "application/octet-stream":
                    continue
                raw = plan.captured.read(name, kind="prerequisite-original")
                try:
                    value = _source_json(raw, "fixture export CAS candidate")
                except ReleaseControlError:
                    continue
                if (
                    canonical_json(value.get("entry")) == canonical_json(entry)
                    and value.get("committed_head") == sha256_json(entry)
                    and value.get("read_back_digest") == sha256_json(entry)
                    and value.get("disposition") in {"committed", "idempotent"}
                ):
                    native_matches.append(name)
            if any(
                len(matches) != 1
                for matches in (
                    receipt_matches,
                    manifest_matches,
                    retention_matches,
                    native_matches,
                )
            ):
                raise ReleaseControlError(
                    "fixture populated export lacks one exact receipt/manifest/retention/native link"
                )

            def record_link(match: tuple[str, dict[str, Any]], kind: str) -> dict[str, Any]:
                name, record = match
                return {
                    "record_type": kind,
                    "record_digest": sha256_json(record),
                    "original_file": captured_ref(name),
                }

            exported.append(
                {
                    "entry": entry,
                    "entry_digest": sha256_json(entry),
                    "original_native_response": captured_ref(native_matches[0]),
                    "original_receipt": record_link(receipt_matches[0], "release-attempt-index"),
                    "original_manifest": record_link(
                        manifest_matches[0], "release-evidence-manifest"
                    ),
                    "original_retention": record_link(
                        retention_matches[0], "release-retention-receipts"
                    ),
                }
            )
        data = {
            "kind": "complete_export",
            "backend_id": "attempt-index",
            "backend_binding_digest": response["binding_digest"],
            "genesis": {
                "path": "inputs/genesis.json",
                "bytes": len(genesis_raw),
                "sha256": sha256_bytes(genesis_raw),
            },
            "genesis_digest": response["genesis_digest"],
            "through_head": response["through_head"],
            "generation": len(exported),
            "capture_started_at": emulation.operation_times[0][0],
            "capture_completed_at": emulation.operation_times[0][1],
            "entries": exported,
            "head_observation": {
                "head": response["through_head"],
                "generation": len(exported),
                "observed_at": emulation.operation_times[0][1],
                "original_native_response": index_native_ref,
            },
            "producer_intent_digest": sha256_json(original.intent),
            "invocation_root_locator": "invocations",
        }
        return canonical_json(
            make_record(
                "release-attempt-index",
                data,
                invocation_id=original.intent["invocation_id"],
                sequence=original.intent["sequence"],
                synthetic=True,
            )
        )
    if plan.tool == "update_release_attempt_index.py":
        response = _source_json(plan.response_payloads[0], "fixture CAS response")
        entry = _release_index_entry_content(response["entry"])
        scope = entry["scope"]
        data = {
            **{
                field: entry[field]
                for field in (
                    "backend_id",
                    "genesis_digest",
                    "generation",
                    "previous_head",
                    "operation_id",
                    "token",
                    "milestone",
                    "entry_manifest_digest",
                    "entry_receipts_digest",
                )
            },
            "committed_head": response["committed_head"],
            "disposition": response["disposition"],
            "read_back_digest": response["read_back_digest"],
            "scope_id": scope["scope_id"],
            "scope_kind": scope["kind"],
            "sequence": scope["sequence"],
            "stage": scope["stage"],
            "kind": "update_receipt",
            "entry_scope": scope,
            "producer_intent_digest": sha256_json(original.intent),
            "invocation_root_locator": "invocations",
        }
        _release_index_receipt_content(data)
        return canonical_json(
            make_record(
                "release-attempt-index",
                data,
                invocation_id=original.intent["invocation_id"],
                sequence=original.intent["sequence"],
                synthetic=True,
            )
        )
    if plan.tool != "validate_release_evidence_stores.py":
        raise ReleaseControlError("fixture native primary has another owner")
    rows = []
    for item, proof_raw in zip(operations, emulation.proof_refs, strict=True):
        request = item["request"]["arguments"]
        rows.append(
            {
                "backend_id": request["backend_id"],
                "capabilities_tested": request["capabilities"],
                "create_digest": sha256_json(request["challenge"]),
                "namespace": request["namespace"],
                "operation_id": sha256_json(item["request"]),
                "read_back_digest": sha256_json(request["challenge"]),
                "result": "PASS",
                "backend_binding_digest": request["binding_digest"],
                "native_proof_files": [_source_json(proof_raw, "fixture preflight proof")],
            }
        )
    registry_raw = plan.captured.read("inputs/stores.json", kind="prerequisite-original")
    return canonical_json(
        make_record(
            "release-evidence-store-preflight",
            {
                "backends": rows,
                "independence_verified": True,
                "invocation_root_locator": "invocations",
                "mode": "isolated_preflight",
                "original_registry": {
                    "path": "inputs/stores.json",
                    "bytes": len(registry_raw),
                    "sha256": sha256_bytes(registry_raw),
                },
                "producer_intent_digest": sha256_json(original.intent),
                "production_heads_mutated": False,
                "registry_digest": sha256_bytes(registry_raw),
                "scope": _release_original_arguments(plan.tool, list(plan.argv))["scope"],
            },
            invocation_id=original.intent["invocation_id"],
            sequence=original.intent["sequence"],
            synthetic=True,
        )
    )


def _release_fixture_output_parents(
    root: _ReleaseFixtureDirectory, names: Sequence[str]
) -> list[_ReleaseFixtureDirectory]:
    paths = sorted(
        {parent for name in names for parent in Path(name).parents if parent != Path(".")},
        key=lambda value: (len(value.parts), value.as_posix()),
    )
    held: list[_ReleaseFixtureDirectory] = []
    try:
        for suffix in paths:
            root.revalidate()
            path = root.path / suffix
            parent_suffix = suffix.parent.as_posix()
            parent = (
                root
                if parent_suffix == "."
                else next((item for item in held if item.path == root.path / suffix.parent), None)
            )
            if parent is None:
                raise ReleaseControlError("fixture output parent custody is incomplete")
            parent.revalidate()
            try:
                os.mkdir(suffix.name, mode=0o700, dir_fd=parent.fd)
                os.fsync(parent.fd)
            except FileExistsError:
                pass
            expected = tuple(
                dict.fromkeys(
                    (*root.identities, *(row for item in held for row in item.identities))
                )
            )
            held.append(_release_fixture_directory(path, expected=expected))
        root.revalidate()
        return held
    except BaseException:
        errors: list[BaseException] = []
        for directory in reversed(held):
            try:
                directory.close()
            except BaseException as exc:
                errors.append(exc)
        if errors:
            raise ReleaseControlError(
                "fixture output-parent cleanup failed for " + str(len(errors)) + " directories"
            ) from errors[0]
        raise


def _release_fixture_close_directories(
    groups: Sequence[Sequence[_ReleaseFixtureDirectory]],
) -> None:
    """Attempt every held-directory close before reporting any cleanup failure."""
    errors: list[BaseException] = []
    for group in groups:
        for directory in reversed(group):
            try:
                directory.close()
            except BaseException as exc:
                errors.append(exc)
    if errors:
        raise ReleaseControlError(
            "fixture held-directory cleanup failed for " + str(len(errors)) + " groups"
        ) from errors[0]


def _release_fixture_worker(
    bound: _ReleaseFixtureSeedInvocation,
    directory_fd: int,
    stdout_fd: int,
    stderr_fd: int,
    receipt_fd: int,
) -> int:
    """Run the supplied native fixture under the parent's original directory custody."""
    staged: _ReleaseFixtureDirectory | None = None
    run: _ReleaseFixtureDirectory | None = None
    staged_parents: list[_ReleaseFixtureDirectory] = []
    output_parents: list[_ReleaseFixtureDirectory] = []
    context = bound.original
    try:
        bound.revalidate()
        _release_gate_write_json_at(directory_fd, "worker.pid", {"pid": os.getpid()})
        emulation = _release_fixture_seed_emulate(bound)
        os.mkdir("staged", mode=0o700, dir_fd=directory_fd)
        os.fsync(directory_fd)
        pins = tuple(
            dict.fromkeys(
                (
                    *bound.plan.captured.root_directories,
                    *(row for member in bound.intent_capture.rows for row in member[4]),
                )
            )
        )
        staged = _release_fixture_directory(context.directory / "staged", expected=pins)
        staged_parents = _release_fixture_output_parents(
            staged, [name for name, _, _ in emulation.sidecars]
        )
        sidecars = _release_fixture_stage_sidecars(
            emulation,
            original_staged_directory=staged,
            original_parent_directories=staged_parents,
        )
        primary_name = _release_historical_path(
            _release_original_arguments(bound.plan.tool, list(bound.plan.argv))["out"],
            bound.plan.working_directory,
        ).name
        primary_schema = "metriplane." + _RELEASE_GATE_PREREQUISITES[bound.plan.tool][0] + ".v1"
        primary_raw = _release_fixture_primary(emulation)
        primary = _release_fixture_write_set(
            staged,
            [
                (
                    primary_name,
                    primary_schema,
                    primary_raw,
                )
            ],
            before_effect=bound.revalidate,
            original_parent_directories=(),
        )
        staged_files = _ReleaseCapturedFiles(
            staged.path,
            staged.identities,
            tuple(sorted((*sidecars.rows, *primary.rows))),
        )
        collected = _release_fixture_collect_staged(
            emulation,
            original_staged_directory=staged,
            original_stage_files=staged_files,
        )
        if collected.staged.read(primary_name, kind=primary_schema) != primary_raw:
            raise ReleaseControlError("fixture native primary changed after semantic replay")
        run = _release_fixture_directory(
            context.root, expected=bound.plan.captured.root_directories
        )
        output_parents = _release_fixture_output_parents(
            run, [name for name, _ in bound.plan.output_plan]
        )
        installed = _release_fixture_install_sidecar_set(
            collected,
            original_run_directory=run,
            original_parent_directories=output_parents,
        )
        installed.revalidate()
        outputs = [
            {
                "path": name,
                "schema_id": schema,
                "sha256": sha256_bytes(installed.read(name, kind=schema)),
            }
            for name, schema in bound.plan.output_plan
        ]
        staged_identities = {
            name: list(identity) for name, _, _, identity, _ in collected.staged.rows
        }
        installed_identities = {name: list(identity) for name, _, _, identity, _ in installed.rows}
        _release_fixture_close_directories(
            (
                output_parents,
                (() if run is None else (run,)),
                staged_parents,
                (() if staged is None else (staged,)),
            )
        )
        output_parents, staged_parents, run, staged = [], [], None, None
        result_identity = _release_gate_write_json_at(
            directory_fd,
            "worker-result.json",
            {
                "schema_version": "metriplane.release-worker-result.v1",
                "exit_code": 0,
                "outputs": outputs,
                "producer_intent_digest": sha256_json(context.intent),
            },
        )
        receipt = canonical_json(
            {
                "result_identity": list(result_identity),
                "staged_identities": staged_identities,
                "installed_identities": installed_identities,
            }
        )
        offset = 0
        while offset < len(receipt):
            count = os.write(receipt_fd, receipt[offset:])
            if count <= 0:
                raise ReleaseControlError("fixture worker receipt write made no progress")
            offset += count
        os.write(stdout_fd, canonical_json({"status": "PASS", "tool": bound.plan.tool}))
        return 0
    except KeyboardInterrupt:
        return 130
    except Exception as exc:
        try:
            os.write(stderr_fd, (str(exc) + "\n").encode())
        except OSError:
            pass
        return 3
    finally:
        try:
            _release_fixture_close_directories(
                (
                    output_parents,
                    (() if run is None else (run,)),
                    staged_parents,
                    (() if staged is None else (staged,)),
                )
            )
        except Exception:
            pass


def _release_fixture_complete_at(
    bound: _ReleaseFixtureSeedInvocation,
    directory_fd: int,
    code: int,
    outputs: list[dict[str, str]],
    diagnostic_identities: Mapping[str, tuple[int, ...]],
    completion_captures: Sequence[_ReleaseCapturedFiles],
    *,
    completed_at: str,
) -> None:
    """Commit a terminal and PASS witness through the original held journal."""
    context = bound.original
    bound.revalidate()
    for capture in completion_captures:
        capture.revalidate()
    identities = dict(diagnostic_identities)
    partial = None
    if code != 0:
        partial = _release_gate_partial_projection_at(context, directory_fd)
        identities["partial-files.json"] = _release_gate_write_json_at(
            directory_fd, "partial-files.json", partial
        )
    selected = {
        (context.directory / name).relative_to(context.root).as_posix(): identity
        for name, identity in identities.items()
    }
    captured = _ReleaseCapturedFiles.capture(
        context.root,
        [(name, "prerequisite-original") for name in selected],
        forbidden=(),
        allowed_kinds=frozenset({"prerequisite-original"}),
        expected_root_directories=bound.intent_capture.root_directories,
        expected_known_directories=bound.intent_capture.rows[0][4],
        expected_file_identities=selected,
    )
    if partial is not None:
        name = (context.directory / "partial-files.json").relative_to(context.root).as_posix()
        if captured.read(name, kind="prerequisite-original") != canonical_json(partial):
            raise ReleaseControlError("fixture partial inventory changed after durable creation")
    bound.revalidate()
    for capture in completion_captures:
        capture.revalidate()
    inputs = _terminal_inputs(context)
    terminal_status = (
        "PASS" if code == 0 else "CANCELLED" if code >= 128 else "BLOCKED" if code == 3 else "FAIL"
    )
    data: dict[str, Any] = {
        "argv": context.intent["argv"],
        "completed_at": completed_at,
        "exit_code": code,
        "inputs": inputs,
        "outputs": outputs,
        "previous_invocation_digest": context.intent["previous_invocation_digest"],
        "started_at": context.intent["started_at"],
        "stderr_digest": sha256_bytes(
            captured.read(
                (context.directory / "stderr").relative_to(context.root).as_posix(),
                kind="prerequisite-original",
            )
        ),
        "stdout_digest": sha256_bytes(
            captured.read(
                (context.directory / "stdout").relative_to(context.root).as_posix(),
                kind="prerequisite-original",
            )
        ),
        "terminal_status": terminal_status,
        "tool": context.intent["tool"],
        "tool_version": context.intent["tool_version"],
    }
    data["invocation_digest"] = sha256_json(data)
    record = make_record(
        "release-stage-invocation",
        data,
        invocation_id=context.intent["invocation_id"],
        sequence=context.intent["sequence"],
        synthetic=True,
        status=terminal_status,
    )
    bound.revalidate()
    terminal_identity = _release_gate_write_json_at(directory_fd, "invocation.json", record)
    if code == 0:
        terminal_name = (context.directory / "invocation.json").relative_to(context.root).as_posix()
        terminal_capture = _ReleaseCapturedFiles.capture(
            context.root,
            [(terminal_name, "prerequisite-original")],
            forbidden=(),
            allowed_kinds=frozenset({"prerequisite-original"}),
            expected_root_directories=bound.intent_capture.root_directories,
            expected_known_directories=bound.intent_capture.rows[0][4],
            expected_file_identities={terminal_name: terminal_identity},
        )
        raw = terminal_capture.read(terminal_name, kind="prerequisite-original")
        if raw != canonical_json(record):
            raise ReleaseControlError("fixture terminal differs from its original durable writer")
        bound.revalidate()
        for capture in completion_captures:
            capture.revalidate()
        terminal_capture.revalidate()
        witness_identity = _release_gate_write_json_at(
            directory_fd,
            "terminal-commit.json",
            {
                "schema_version": "metriplane.gate-terminal-commit.v1",
                "intent_sha256": sha256_json(context.intent),
                "terminal_sha256": sha256_json(record),
            },
        )
        witness_name = (
            (context.directory / "terminal-commit.json").relative_to(context.root).as_posix()
        )
        witness_capture = _ReleaseCapturedFiles.capture(
            context.root,
            [(witness_name, "prerequisite-original")],
            forbidden=(),
            allowed_kinds=frozenset({"prerequisite-original"}),
            expected_root_directories=bound.intent_capture.root_directories,
            expected_known_directories=bound.intent_capture.rows[0][4],
            expected_file_identities={witness_name: witness_identity},
        )
        terminal_capture.revalidate()
        witness_capture.revalidate()
    bound.revalidate()
    for capture in completion_captures:
        capture.revalidate()
    _validate_terminal(context)
    if code == 0:
        terminal_capture.revalidate()
        witness_capture.revalidate()
    for capture in completion_captures:
        capture.revalidate()


def _release_fixture_role_interval(bound: _ReleaseFixtureSeedInvocation, completed_at: str) -> None:
    """Recheck the signed role authority across the actual supervised action interval."""
    if bound.plan.tool != "record_release_role_assignments.py":
        raise ReleaseControlError("fixture role interval has another command owner")
    arguments = _release_original_arguments(bound.plan.tool, list(bound.plan.argv))
    protected_path = _release_historical_path(
        arguments["signed-assignments"], bound.plan.working_directory
    )
    context_path = _release_historical_path(
        arguments["release-context"], bound.plan.working_directory
    )
    policy_path = _release_historical_path(arguments["policy"], bound.plan.working_directory)
    protected = _source_json(
        bound.plan.captured.read(
            protected_path.relative_to(bound.plan.captured.root).as_posix(),
            kind="prerequisite-original",
        ),
        "fixture protected role interval",
    )
    data = protected["data"]
    context = _source_json(
        bound.plan.captured.read(
            context_path.relative_to(bound.plan.captured.root).as_posix(),
            kind="prerequisite-original",
        ),
        "fixture role interval context",
    )
    policy_raw = bound.plan.captured.read(
        policy_path.relative_to(bound.plan.captured.root).as_posix(),
        kind="prerequisite-original",
    )
    _release_original_role_byte_replay(
        protected_path,
        context_path=context_path,
        captured=bound.plan.captured,
        expected_context_digest=sha256_json(context),
        expected_run_id=arguments["run-id"],
        expected_milestone=arguments["milestone"],
        expected_assignment_policy_digest=sha256_bytes(policy_raw),
        expected_authority_policy_digest=data["authority_policy_digest"],
        expected_keyring_digest=data["provider_attestation_keyring_digest"],
        use_interval=(bound.original.intent["started_at"], completed_at),
        live=False,
    )
    bound.revalidate()


def _release_fixture_uninstall(
    bound: _ReleaseFixtureSeedInvocation, installed: _ReleaseCapturedFiles
) -> None:
    """Remove only the exact installed identities after a late fail-closed check."""
    installed.revalidate()
    for name, _, _, identity, ancestors in reversed(installed.rows):
        path = installed.root / name
        descriptor = _release_gate_open_pinned_directory(path.parent, ancestors)
        try:
            current = _release_gate_file_identity(
                os.stat(path.name, dir_fd=descriptor, follow_symlinks=False)
            )
            if current != identity:
                raise ReleaseControlError("fixture late rollback output identity changed")
            os.unlink(path.name, dir_fd=descriptor)
            os.fsync(descriptor)
        finally:
            os.close(descriptor)
    bound.revalidate()


def _release_fixture_command_supervise(bound: _ReleaseFixtureSeedInvocation) -> int:
    """Supervise one real child worker while retaining the original journal descriptor."""
    context = bound.original
    ancestors = bound.intent_capture.rows[0][4]
    directory_fd = _release_gate_open_pinned_directory(context.directory, ancestors)
    descriptors: list[int] = []
    outputs: list[dict[str, str]] = []
    completion_captures: list[_ReleaseCapturedFiles] = []
    code = 3
    completed_at: str | None = None
    try:
        bound.revalidate()
        for name in ("stdout", "stderr"):
            descriptors.append(
                os.open(
                    name,
                    os.O_RDWR | os.O_CREAT | os.O_EXCL | os.O_NOFOLLOW,
                    0o400,
                    dir_fd=directory_fd,
                )
            )
        stdout_fd, stderr_fd = descriptors
        read_fd, write_fd = os.pipe()
        descriptors.extend((read_fd, write_fd))
        pid = os.fork()
        if pid == 0:
            try:
                os.close(read_fd)
                os.setsid()
                worker_code = _release_fixture_worker(
                    bound, directory_fd, stdout_fd, stderr_fd, write_fd
                )
            except BaseException:
                worker_code = 3
            os._exit(worker_code)
        os.close(write_fd)
        descriptors.remove(write_fd)
        try:
            while True:
                try:
                    _, status = os.waitpid(pid, 0)
                    break
                except InterruptedError:
                    continue
        except KeyboardInterrupt:
            os.kill(pid, signal.SIGKILL)
            _, status = os.waitpid(pid, 0)
        group_settled = _stop_worker_group(pid)
        if not group_settled:
            raise ReleaseControlError("fixture worker process group has not quiesced")
        if os.WIFSIGNALED(status):
            code = 128 + os.WTERMSIG(status)
        elif os.WIFEXITED(status):
            code = os.WEXITSTATUS(status)
        else:
            code = 3
        receipt_chunks = []
        while chunk := os.read(read_fd, 65536):
            receipt_chunks.append(chunk)
        receipt_raw = b"".join(receipt_chunks)
        if code == 0:
            receipt = _release_closed_mapping(
                _source_json(receipt_raw, "fixture worker result handoff"),
                {"result_identity", "staged_identities", "installed_identities"},
                "fixture worker result handoff",
            )
            result_identity = tuple(receipt["result_identity"])
            if len(result_identity) != 7 or any(
                type(value) is not int for value in result_identity
            ):
                raise ReleaseControlError("fixture worker result identity is malformed")
            result_name = (
                (context.directory / "worker-result.json").relative_to(context.root).as_posix()
            )
            result_capture = _ReleaseCapturedFiles.capture(
                context.root,
                [(result_name, "prerequisite-original")],
                forbidden=(),
                allowed_kinds=frozenset({"prerequisite-original"}),
                expected_root_directories=bound.intent_capture.root_directories,
                expected_known_directories=ancestors,
                expected_file_identities={result_name: result_identity},
            )
            result = _source_json(
                result_capture.read(result_name, kind="prerequisite-original"),
                "fixture worker result",
            )
            outputs = result["outputs"]
            if (
                result.get("schema_version") != "metriplane.release-worker-result.v1"
                or result.get("exit_code") != 0
                or result.get("producer_intent_digest") != sha256_json(context.intent)
                or [{"path": row["path"], "schema_id": row["schema_id"]} for row in outputs]
                != context.intent["planned_outputs"]
            ):
                raise ReleaseControlError("fixture worker result differs from its reserved plan")
            installed_identities = {
                name: tuple(identity) for name, identity in receipt["installed_identities"].items()
            }
            expected = {name for name, _ in bound.plan.output_plan}
            if set(installed_identities) != expected:
                raise ReleaseControlError("fixture worker installed identity inventory differs")
            installed = _ReleaseCapturedFiles.capture(
                context.root,
                [(name, "prerequisite-original") for name, _ in bound.plan.output_plan],
                forbidden=(),
                allowed_kinds=frozenset({"prerequisite-original"}),
                expected_root_directories=bound.plan.captured.root_directories,
                expected_file_identities=installed_identities,
            )
            for row in outputs:
                if (
                    sha256_bytes(installed.read(row["path"], kind="prerequisite-original"))
                    != row["sha256"]
                ):
                    raise ReleaseControlError(
                        "fixture worker installed bytes differ from its result"
                    )
            installed.revalidate()
            staged_identities = {
                (context.directory / "staged" / name).relative_to(context.root).as_posix(): tuple(
                    identity
                )
                for name, identity in receipt["staged_identities"].items()
            }
            if set(staged_identities) != {
                (context.directory / "staged" / name).relative_to(context.root).as_posix()
                for name, _ in bound.plan.output_plan
            }:
                raise ReleaseControlError("fixture worker staged identity inventory differs")
            staged_capture = _ReleaseCapturedFiles.capture(
                context.root,
                [(name, "prerequisite-original") for name in staged_identities],
                forbidden=(),
                allowed_kinds=frozenset({"prerequisite-original"}),
                expected_root_directories=bound.intent_capture.root_directories,
                expected_file_identities=staged_identities,
            )
            completion_captures.extend((installed, staged_capture, result_capture))
            completed_at = datetime.now(UTC).isoformat().replace("+00:00", "Z")
            if bound.plan.tool == "record_release_role_assignments.py":
                try:
                    _release_fixture_role_interval(bound, completed_at)
                except ReleaseControlError as exc:
                    _release_fixture_uninstall(bound, installed)
                    completion_captures = [staged_capture, result_capture]
                    outputs = []
                    code = 3
                    os.write(stderr_fd, (str(exc) + "\n").encode())
        bound.revalidate()
        for descriptor in (stdout_fd, stderr_fd):
            os.fsync(descriptor)
        identities = {
            name: _release_gate_file_identity(os.fstat(descriptor))
            for name, descriptor in (("stdout", stdout_fd), ("stderr", stderr_fd))
        }
        os.fsync(directory_fd)
        if code != 0 or completed_at is None:
            completed_at = datetime.now(UTC).isoformat().replace("+00:00", "Z")
        _release_fixture_complete_at(
            bound,
            directory_fd,
            code,
            outputs,
            identities,
            completion_captures,
            completed_at=completed_at,
        )
    finally:
        errors: list[OSError] = []
        for descriptor in reversed([directory_fd, *descriptors]):
            try:
                os.close(descriptor)
            except OSError as exc:
                errors.append(exc)
        if errors:
            raise ReleaseControlError("fixture supervisor descriptor cleanup failed") from errors[0]
    print(
        canonical_json(
            {
                "tool": context.intent["tool"],
                "status": "PASS" if code == 0 else "BLOCKED_NOT_READY",
                "exit_code": code,
                "invocation": str(context.directory),
            }
        ).decode()
    )
    return code


def _release_fixture_original_seed(
    original: ReleaseInvocation,
    *,
    captured: _ReleaseCapturedFiles,
    expected_tool: str,
) -> tuple[dict[str, Any], dict[str, bytes], str]:
    """Replay the exact fixed typed seed/input slot without reading the historical root.

    Full original producer/companion journals remain a separate prerequisite. The seed
    proves only fixture transcript identity, not provider or release authority.
    """
    if original.intent.get("environment", {}).get("fixture_mode") != "1":
        raise ReleaseControlError("fixture original seed is unavailable in live mode")
    _release_captured_command_context(original, captured=captured, expected_tool=expected_tool)
    argv = original.intent["argv"]
    cwd = _canonical_absolute_path(
        original.intent["environment"]["working_directory"], "fixture original cwd"
    )
    args = _release_original_arguments(expected_tool, argv)
    historical_directory = _release_historical_path(args["invocation-dir"], cwd)
    historical_root = historical_directory.parents[2]
    sequence = original.intent["sequence"]
    if (
        historical_directory.parent
        != historical_root / "invocations" / _invocation_stage(expected_tool)
        or historical_directory.name != f"{sequence:03d}"
        or original.directory
        != original.root / "invocations" / _invocation_stage(expected_tool) / f"{sequence:03d}"
    ):
        raise ReleaseControlError("fixture original seed stage/sequence identity differs")
    name = f"inputs/fixture-native/{_invocation_stage(expected_tool)}/{sequence:03d}/seed.json"
    base = original.root.relative_to(captured.root)

    def read(name: str, schema: str, expected_digest: str | None = None) -> bytes:
        _release_relative_suffix(name, "fixture original input")
        rows = [
            row for row in original.intent["inputs"] if row["path"] == str(historical_root / name)
        ]
        if len(rows) != 1 or rows[0]["schema_id"] != schema:
            raise ReleaseControlError(
                "fixture seed original input type/membership differs before read"
            )
        digest = _require_digest(rows[0]["sha256"], "fixture original input R")
        if expected_digest is not None and digest != expected_digest:
            raise ReleaseControlError("fixture seed member descriptor changes original input R")
        raw = captured.read((base / name).as_posix(), kind="prerequisite-original")
        if sha256_bytes(raw) != digest:
            raise ReleaseControlError("fixture seed original input R differs before parse")
        return raw

    raw = read(name, _RELEASE_FIXTURE_SEED_SCHEMA)
    seed = _release_closed_mapping(
        _source_json(raw, "fixture original seed"),
        {"schema_version", "synthetic", "tool", "command_digest", "members", "data"},
        "fixture original seed",
    )
    if (
        seed["schema_version"] != _RELEASE_FIXTURE_SEED_SCHEMA
        or seed["synthetic"] is not True
        or seed["tool"] != expected_tool
        or seed["command_digest"]
        != sha256_json({"tool": expected_tool, "argv": argv, "working_directory": str(cwd)})
    ):
        raise ReleaseControlError("fixture seed original command/mode/type changed")
    rows = _release_id_rows(seed["members"], "member_id", "fixture original seed members")
    contents = {}
    names = {name}
    for identity, row in rows.items():
        _release_closed_mapping(
            row,
            {"member_id", "path", "schema_id", "bytes", "sha256"},
            "fixture original seed member",
        )
        if (
            re.fullmatch(r"[a-z][a-z0-9-]{0,100}", identity, re.ASCII) is None
            or row["path"] != "raw/" + identity + ".bin"
            or row["schema_id"] != "application/octet-stream"
            or type(row["bytes"]) is not int
            or row["bytes"] < 0
        ):
            raise ReleaseControlError("fixture original member path/type/size differs")
        member = (Path(name).parent / row["path"]).as_posix()
        names.add(member)
        content = read(member, row["schema_id"], _require_digest(row["sha256"], "fixture member R"))
        if len(content) != row["bytes"]:
            raise ReleaseControlError("fixture original seed member size differs")
        contents[identity] = content
    prefix = historical_root / Path(name).parent
    actual = {
        Path(row["path"]).relative_to(historical_root).as_posix()
        for row in original.intent["inputs"]
        if Path(row["path"]).is_relative_to(prefix)
    }
    if actual != names:
        raise ReleaseControlError(
            "fixture original intent has an incomplete or extra seed slot input"
        )
    # Only explicit original files are read. Namespace checks use current held paths.
    selected = _ReleaseCapturedFiles(
        original.root,
        tuple(
            x
            for x in captured.root_directories
            if Path(x[0]) in {original.root, *original.root.parents}
        ),
        tuple(
            (
                n,
                "prerequisite-original",
                *next(row[2:] for row in captured.rows if row[0] == (base / n).as_posix()),
            )
            for n in sorted(names)
        ),
    )
    # Original root may be a captured subroot; its full existing ancestor pins come from a member.
    member_ancestors = selected.rows[0][4]
    root_pins = tuple(
        x for x in member_ancestors if Path(x[0]) in {original.root, *original.root.parents}
    )
    selected = _ReleaseCapturedFiles(original.root, root_pins, selected.rows)
    _release_fixture_seed_namespace(selected, name, set(rows))
    captured.revalidate()
    return seed, contents, sha256_bytes(raw)


def _release_fixture_target_transcript_replay(
    original: ReleaseInvocation,
    *,
    captured: _ReleaseCapturedFiles,
    original_context: Mapping[str, Any],
    expected_context_digest: str,
    registry_raw: bytes,
    expected_registry_digest: str,
    native_facts: _ReleaseFixtureNativeFacts,
) -> dict[str, Any]:
    """Connect supplied target chronology/content to the separately replayed native facts.

    No wall-clock age is imposed on later historical replay. This private 300-second
    fixture ceiling is measured against the original reservation, not provider time.
    """
    seed, contents, digest = _release_fixture_original_seed(
        original, captured=captured, expected_tool="capture_release_target_observations.py"
    )
    args = _release_original_arguments(original.intent["tool"], original.intent["argv"])
    subject, operations, responses, artifacts, used = _release_fixture_seed_target_content(
        seed,
        contents=contents,
        arguments=args,
        context=original_context,
        expected_context_digest=expected_context_digest,
        registry_raw=registry_raw,
        expected_registry_digest=expected_registry_digest,
        sequence=original.intent["sequence"],
    )
    if used != set(contents):
        raise ReleaseControlError("fixture target transcript has unconsumed members")
    producer = {
        "tool": original.intent["tool"],
        "invocation_id": original.intent["invocation_id"],
        "sequence": original.intent["sequence"],
        "intent_digest": sha256_json(original.intent),
    }
    if native_facts.producer_identity != canonical_json(
        producer
    ) or native_facts.subject != canonical_json(subject):
        raise ReleaseControlError(
            "fixture target native facts have another original producer/subject"
        )
    if len(native_facts.operations) != len(operations):
        raise ReleaseControlError("fixture target operation inventory differs from original seed")
    for op, raw, fact_raw in zip(operations, responses, native_facts.operations, strict=True):
        fact = _source_json(fact_raw, "fixture target native fact")
        if (
            fact["kind"] != op["kind"]
            or canonical_json(fact["request"]) != canonical_json(op["request"])
            or canonical_json(fact["response"])
            != canonical_json(_source_json(raw, "fixture planned target response"))
        ):
            raise ReleaseControlError(
                "fixture native target observations changed supplied transcript"
            )
    admitted = _release_fixture_native_timestamp(original.intent["started_at"])
    start = _release_fixture_native_timestamp(seed["data"]["capture_started_at"])
    end = _release_fixture_native_timestamp(seed["data"]["capture_completed_at"])
    if (
        not start <= end <= admitted
        or (admitted - end).total_seconds() > _RELEASE_FIXTURE_TRANSCRIPT_MAX_AGE_SECONDS
    ):
        raise ReleaseControlError("fixture target transcript failed its original admission clock")
    captured.revalidate()
    return {
        "seed_raw_digest": digest,
        "supplied_interval": (
            seed["data"]["capture_started_at"],
            seed["data"]["capture_completed_at"],
        ),
        "original_admission_clock": original.intent["started_at"],
        "clock_domain": "fixture-protocol-only",
        "fixture_provider": "test-fixture",
        "fixture_api_version": _RELEASE_FIXTURE_API_VERSION,
        "artifact_inventory": tuple((name, sha256_bytes(raw), len(raw)) for name, raw in artifacts),
    }


@dataclass(frozen=True)
class _ReleaseGateJournalReadback:
    """Original journal byte custody only; never native gate authority."""

    context: ReleaseInvocation
    captured: _ReleaseCapturedFiles
    inventory: Mapping[str, Any]
    inventory_digest: str
    intents: tuple[_ReleaseCapturedFiles, ...]
    plans: tuple[tuple[int, Mapping[str, Any]], ...]

    def read(self, path: Path) -> bytes:
        return self.captured.read(
            path.relative_to(self.context.root).as_posix(), kind="prerequisite-original"
        )

    def revalidate(self) -> None:
        if sha256_json(self.inventory) != self.inventory_digest:
            raise ReleaseControlError("gate reader metadata carrier changed")
        self.captured.revalidate()
        for held in self.intents:
            held.revalidate()
        for _, plan in self.plans:
            plan["captured"].revalidate()
        stage = self.context.directory.parent
        pins = self.intents[0].rows[0][4][:-1]
        descriptor = _release_gate_open_pinned_directory(stage, pins)
        try:
            _release_gate_stage_inventory(stage, descriptor, pins, expected=self.inventory)
        finally:
            os.close(descriptor)
        self.captured.revalidate()


def _release_gate_reader_input_plan(
    context: ReleaseInvocation, held_intent: _ReleaseCapturedFiles
) -> Mapping[str, Any]:
    """The existing original input-plan owner, with the reader's original intent."""
    original_inputs = None
    if isinstance(context, _ReleaseGateInvocation):
        if held_intent is not context.intent_capture:
            raise ReleaseControlError("gate reader replaced its producer-held original intent")
        expected = _release_gate_source_revalidate(context.gate_inputs)
        original_inputs = context.gate_inputs.captured
    else:
        arguments = _release_original_arguments(context.intent["tool"], context.intent["argv"])
        cwd = _canonical_absolute_path(
            context.intent["environment"]["working_directory"], "original gate reader cwd"
        )
        expected = {}
        for flag, kind in _RELEASE_GATE_REGISTRY_INPUTS.items():
            original = str(_release_historical_path(arguments[flag], cwd))
            rows = [row for row in context.intent["inputs"] if row["path"] == original]
            if len(rows) != 1 or rows[0]["schema_id"] not in {
                "metriplane." + kind + ".v1",
                "metriplane.prerequisite-original.v1",
            }:
                raise ReleaseControlError(
                    "gate reader original registry type or membership differs"
                )
            expected[flag] = _require_digest(rows[0]["sha256"], "original gate reader registry")
    plan = _release_gate_input_plan_replay(
        context,
        expected_registry_digests=expected,
        original_capture=original_inputs,
        original_intent_capture=held_intent,
    )
    return {**plan, "reader_registry_digests": expected}


def _release_gate_journal_readback_capture(
    context: ReleaseInvocation,
    *,
    original_root: _ReleaseCapturedFiles | None = None,
    original_intent: _ReleaseCapturedFiles | None = None,
) -> _ReleaseGateJournalReadback:
    """Observe the complete gate byte namespace before any terminal-entry validation."""
    if context.intent["tool"] != "prepare_release_gate_input.py":
        raise ReleaseControlError("gate journal reader has another command owner")
    if (
        context.directory
        != context.root / "invocations/gate-input" / f"{context.intent['sequence']:03d}"
    ):
        raise ReleaseControlError("gate reader has another fixed journal owner")
    if original_root is not None and original_root.root != context.root:
        raise ReleaseControlError("gate reader has another original root carrier")
    if original_root is not None:
        original_root.revalidate()
    if isinstance(context, _ReleaseGateInvocation):
        held_current = context.intent_capture
        if (
            held_current.root != context.root
            or context.gate_inputs.captured.root != context.root
            or held_current.root_directories != context.gate_inputs.captured.root_directories
            or len(held_current.rows) != 1
            or held_current.rows[0][:2]
            != (
                (context.directory / "intent.json").relative_to(context.root).as_posix(),
                "release-invocation-intent",
            )
            or (
                original_root is not None
                and original_root.root_directories != held_current.root_directories
            )
            or (original_intent is not None and original_intent is not held_current)
        ):
            raise ReleaseControlError("gate reader discarded original producer root custody")
        held_current.revalidate()
    elif original_intent is not None:
        held_current = original_intent
        if (
            held_current.root != context.root
            or len(held_current.rows) != 1
            or held_current.rows[0][:2]
            != (
                (context.directory / "intent.json").relative_to(context.root).as_posix(),
                "release-invocation-intent",
            )
            or (
                original_root is not None
                and held_current.root_directories != original_root.root_directories
            )
        ):
            raise ReleaseControlError("gate reader has another original intent carrier")
        held_current.revalidate()
    else:
        held_current = _ReleaseCapturedFiles.capture(
            context.root,
            [
                (
                    (context.directory / "intent.json").relative_to(context.root).as_posix(),
                    "release-invocation-intent",
                )
            ],
            forbidden=(),
            allowed_kinds=frozenset({"release-invocation-intent"}),
            expected_root_directories=None
            if original_root is None
            else original_root.root_directories,
        )
    if len(held_current.rows) != 1 or held_current.rows[0][2] != canonical_json(context.intent):
        raise ReleaseControlError("gate reader context differs from its original intent")
    root_pins = held_current.root_directories
    stage = context.directory.parent
    stage_pins = held_current.rows[0][4][:-1]
    descriptor = _release_gate_open_pinned_directory(stage, stage_pins)
    try:
        inventory = _release_gate_stage_inventory(stage, descriptor, stage_pins)
    finally:
        os.close(descriptor)
    names = inventory["children"][str(stage)]
    if any(re.fullmatch(r"[0-9]{3,}", name, flags=re.ASCII) is None for name in names):
        raise ReleaseControlError("gate reader sequences are noncanonical")
    ordered = sorted(names, key=int)
    if ordered != [f"{number:03d}" for number in range(1, len(ordered) + 1)]:
        raise ReleaseControlError("gate reader sequences are not contiguous")
    if any(not stat.S_ISDIR(inventory["entries"][str(stage / name)][2]) for name in ordered):
        raise ReleaseControlError("gate reader sequence is not an original directory")
    allowed_common = {
        "intent.json",
        "invocation.json",
        "stdout",
        "stderr",
        "partial-files.json",
        "worker.pid",
        "worker-result.json",
        "terminal-commit.json",
        "staged",
        "workspace",
    }
    for filename in inventory["entries"]:
        suffix = Path(filename).relative_to(stage).parts
        if len(suffix) >= 2 and (
            suffix[1] not in allowed_common
            or (len(suffix) > 2 and suffix[1] not in {"staged", "workspace"})
        ):
            raise ReleaseControlError("gate reader journal has an unowned member")
    for name in ordered:
        directory = stage / name
        terminal_path = directory / "invocation.json"
        identity = inventory["entries"].get(str(terminal_path))
        if identity is None:
            continue
        # Observe only the fixed terminal before selecting success/failure scratch
        # ownership. Unknown output bytes cannot turn into a captured success plan.
        raw, _, _ = _release_held_path(
            terminal_path,
            expected_prefix=tuple(inventory["directories"].values()),
            expected_identity=identity,
        )
        terminal = _source_json(raw, "gate reader original terminal phase")
        if terminal.get("status") == "PASS":
            expected = {
                "intent.json",
                "invocation.json",
                "stdout",
                "stderr",
                "worker.pid",
                "worker-result.json",
                "staged",
                "terminal-commit.json",
            }
            if set(inventory["children"][str(directory)]) != expected or set(
                inventory["children"].get(str(directory / "staged"), ())
            ) != {name for name, _ in _RELEASE_GATE_OUTPUT_PLAN}:
                raise ReleaseControlError(
                    "gate reader completed namespace differs from its exact pair"
                )
    rows = []
    physical = set()
    for filename, identity in sorted(inventory["entries"].items()):
        path = Path(filename)
        if not stat.S_ISREG(identity[2]) or identity[3] != 1:
            continue
        try:
            raw, observed, ancestors = _release_held_path(
                path,
                expected_prefix=tuple(inventory["directories"].values()),
                expected_identity=identity,
            )
        except ReleaseControlError as exc:
            suffix = path.relative_to(stage).parts
            # Preserve actual unreadable failure bytes as the existing partial
            # owner does; never suppress an identity/ancestor/cleanup mismatch.
            if not (
                len(suffix) >= 3
                and suffix[1] in {"staged", "workspace"}
                and str(exc) == "captured release input cannot be read safely"
                and isinstance(exc.__cause__, OSError)
            ):
                raise
            continue
        if observed[:2] in physical:
            raise ReleaseControlError("gate reader original files alias")
        physical.add(observed[:2])
        rows.append(
            (
                path.relative_to(context.root).as_posix(),
                "prerequisite-original",
                raw,
                observed,
                ancestors,
            )
        )
    captured = _ReleaseCapturedFiles(context.root, root_pins, tuple(rows))
    captured.revalidate()
    intents = []
    plans = []
    needs_outputs = False
    for name in ordered:
        directory = stage / name
        selected = [row for row in rows if context.root / row[0] == directory / "intent.json"]
        if len(selected) != 1:
            raise ReleaseControlError("gate reader lacks an original sequence intent")
        row = selected[0]
        actual = _validate_intent_bytes(directory, row[2])
        if actual.intent["tool"] != context.intent["tool"]:
            raise ReleaseControlError("gate reader sequence has another command owner")
        held = _ReleaseCapturedFiles(
            context.root, root_pins, ((row[0], "release-invocation-intent", *row[2:]),)
        )
        if directory == context.directory:
            if actual.intent != context.intent or held.rows != held_current.rows:
                raise ReleaseControlError("gate reader lost its original selected intent")
            held = held_current
            actual = context
        intents.append(held)
        terminal_name = (directory / "invocation.json").relative_to(context.root).as_posix()
        terminal_rows = [row for row in rows if row[0] == terminal_name]
        if (
            terminal_rows
            and _source_json(terminal_rows[0][2], "gate reader terminal").get("status") == "PASS"
        ):
            needs_outputs = True
            plans.append((actual.intent["sequence"], _release_gate_reader_input_plan(actual, held)))
    if needs_outputs:
        if original_root is not None and original_root.rows:
            if {(row[0], row[1]) for row in original_root.rows} != {
                (name, "prerequisite-original") for name, _ in _RELEASE_GATE_OUTPUT_PLAN
            }:
                raise ReleaseControlError("gate reader original output inventory differs")
            original_root.revalidate()
            outputs = original_root
        else:
            outputs = _ReleaseCapturedFiles.capture(
                context.root,
                [(name, "prerequisite-original") for name, _ in _RELEASE_GATE_OUTPUT_PLAN],
                forbidden=(),
                allowed_kinds=frozenset({"prerequisite-original"}),
                expected_root_directories=root_pins,
            )
        captured = _ReleaseCapturedFiles(context.root, root_pins, (*captured.rows, *outputs.rows))
    result = _ReleaseGateJournalReadback(
        context, captured, inventory, sha256_json(inventory), tuple(intents), tuple(plans)
    )
    result.revalidate()
    return result


def _release_gate_reader_partial(
    context: ReleaseInvocation, readback: _ReleaseGateJournalReadback
) -> None:
    path = context.directory / "partial-files.json"
    if str(path) in readback.inventory["entries"]:
        raw = readback.read(path)
        value = _source_json(raw, "gate reader partial inventory")
        if raw != canonical_json(value) or value != _release_gate_prior_partial_projection(
            context, readback.inventory, readback.captured
        ):
            raise ReleaseControlError("gate reader partial inventory differs from original bytes")


def _release_gate_reader_terminal_entry(
    context: ReleaseInvocation, readback: _ReleaseGateJournalReadback
) -> dict[str, Any]:
    if (
        not isinstance(readback, _ReleaseGateJournalReadback)
        or context.root != readback.context.root
        or context.intent["tool"] != "prepare_release_gate_input.py"
    ):
        raise ReleaseControlError("gate reader carrier has another original owner")
    readback.revalidate()
    record = _release_captured_journal_terminal_content(
        context, captured=readback.captured, require_pass=False, gate_pair_owner=True
    )
    _release_gate_reader_partial(context, readback)
    if record["status"] == "PASS":
        plans = [
            plan for sequence, plan in readback.plans if sequence == context.intent["sequence"]
        ]
        if len(plans) != 1:
            raise ReleaseControlError("gate reader lacks its original passing input plan")
        plan = plans[0]
        held = next(
            value
            for value in readback.intents
            if value.rows[0][0]
            == (context.directory / "intent.json").relative_to(context.root).as_posix()
        )
        replay = _release_gate_input_plan_replay(
            context,
            expected_registry_digests=plan["reader_registry_digests"],
            original_capture=plan["captured"],
            original_intent_capture=held,
        )
        if replay["captured"] is not plan["captured"]:
            raise ReleaseControlError("gate reader discarded its passing original inputs")
        if isinstance(context, _ReleaseGateInvocation):
            _release_gate_source_revalidate(context.gate_inputs)
        expected = [
            {
                "path": name,
                "schema_id": kind,
                "sha256": sha256_bytes(readback.read(context.root / name)),
            }
            for name, kind in _RELEASE_GATE_OUTPUT_PLAN
        ]
        if record["data"]["outputs"] != expected:
            raise ReleaseControlError("gate reader terminal changes its exact output pair")
        _release_captured_journal_members(context, captured=readback.captured, terminal=record)
    readback.revalidate()
    return record


def _release_gate_terminal_readback(
    context: ReleaseInvocation, readback: _ReleaseGateJournalReadback
) -> dict[str, Any]:
    """Strict common gate lineage over one original capture; no native admission."""
    if (
        not isinstance(readback, _ReleaseGateJournalReadback)
        or context.intent != readback.context.intent
        or context.root != readback.context.root
    ):
        raise ReleaseControlError("gate terminal readback changes the original selected context")
    current = context
    required = True
    result = None
    while True:
        raw = readback.read(current.directory / "intent.json")
        actual = _validate_intent_bytes(current.directory, raw)
        if actual.intent != current.intent:
            raise ReleaseControlError("gate reader intent changed during original lineage replay")
        if required:
            terminal = _validate_terminal_entry(current, _gate_readback=readback)
            _release_gate_terminal_commit_replay(current, terminal, captured=readback.captured)
            if result is None:
                result = terminal
        else:
            if str(current.directory / "invocation.json") in readback.inventory["entries"]:
                raise ReleaseControlError("interrupted gate predecessor acquired a terminal")
            _release_gate_terminal_commit_replay(current, None, captured=readback.captured)
            _release_gate_reader_partial(current, readback)
        prior = current.intent["predecessor"]
        if prior is None:
            break
        previous = current.directory.parent / f"{prior['sequence']:03d}"
        previous_raw = readback.read(previous / "intent.json")
        if sha256_bytes(previous_raw) != prior["intent_digest"]:
            raise ReleaseControlError("gate reader predecessor original intent differs")
        required = prior["terminal_digest"] is not None
        if (
            required
            and sha256_bytes(readback.read(previous / "invocation.json"))
            != prior["terminal_digest"]
        ):
            raise ReleaseControlError("gate reader predecessor original terminal differs")
        current = _validate_intent_bytes(previous, previous_raw)
    readback.revalidate()
    assert result is not None
    return result


@dataclass(frozen=True)
class _ReleasePrerequisiteGraphNode:
    path: str
    producer: str
    original_record: bytes
    original_root: str
    native_facts: _ReleaseFixtureNativeFacts | None
    dependencies: tuple[str, ...]


@dataclass(frozen=True)
class _ReleasePrerequisiteGraph:
    context_digest: str
    before: str
    root: Path
    captured: _ReleaseCapturedFiles
    nodes: tuple[_ReleasePrerequisiteGraphNode, ...]


def _release_graph_original_ref(
    path: Path, *, record_path: Path, captured: _ReleaseCapturedFiles
) -> dict[str, Any]:
    """Construct a reference only from held original bytes, never a detached digest."""
    if not path.is_relative_to(record_path.parent):
        raise ReleaseControlError(
            "graph original cannot be represented by a safe containing-relative reference"
        )
    suffix = path.relative_to(record_path.parent).as_posix()
    _release_relative_suffix(suffix, "graph original reference")
    raw = captured.read(path.relative_to(captured.root).as_posix(), kind="prerequisite-original")
    return {"path": suffix, "bytes": len(raw), "sha256": sha256_bytes(raw)}


def _release_graph_bound_inputs(
    original: ReleaseInvocation,
    *,
    captured: _ReleaseCapturedFiles,
    selected: Mapping[str, Sequence[Mapping[str, str]]],
) -> dict[str, list[tuple[Path, bytes]]]:
    """Bind all selected original argv inputs before their bytes, including pure owners."""
    arguments = _release_original_arguments(original.intent["tool"], original.intent["argv"])
    cwd = _canonical_absolute_path(
        original.intent["environment"]["working_directory"], "graph original cwd"
    )
    historical = _release_historical_path(arguments["invocation-dir"], cwd).parents[2]
    result: dict[str, list[tuple[Path, bytes]]] = {}
    seen: set[Path] = set()
    if not isinstance(selected, dict):
        raise ReleaseControlError("graph typed inputs are not a closed flag mapping")
    for flag, references in selected.items():
        if flag not in arguments or flag in TOOL_CONTRACTS[original.intent["tool"]].boolean:
            raise ReleaseControlError("graph selected input is not an original input flag")
        values = (
            arguments[flag]
            if flag in TOOL_CONTRACTS[original.intent["tool"]].repeatable
            else [arguments[flag]]
        )
        if not isinstance(references, (list, tuple)) or len(references) != len(values):
            raise ReleaseControlError("graph repeated input cardinality differs")
        rows = []
        for value, reference in zip(values, references, strict=True):
            ref = _release_closed_mapping(
                reference, {"path", "schema_id", "sha256"}, "graph selected original"
            )
            suffix = _release_relative_suffix(ref["path"], "graph original suffix")
            old = _release_historical_path(value, cwd)
            if old != historical / suffix:
                raise ReleaseControlError("graph original argv and selected suffix differ")
            matching = [row for row in original.intent["inputs"] if row["path"] == str(old)]
            if (
                len(matching) != 1
                or matching[0]["schema_id"] != ref["schema_id"]
                or matching[0]["sha256"] != _require_digest(ref["sha256"], "graph original R")
            ):
                raise ReleaseControlError("graph selected input type/R differs before reading")
            path = original.root / suffix
            if path in seen:
                raise ReleaseControlError("graph selected inputs alias")
            seen.add(path)
            raw = captured.read(
                path.relative_to(captured.root).as_posix(), kind="prerequisite-original"
            )
            if sha256_bytes(raw) != ref["sha256"]:
                raise ReleaseControlError("graph original input R changed before parsing")
            rows.append((path, raw))
        result[flag] = rows
    captured.revalidate()
    return result


def _release_graph_primary_equal(record: Mapping[str, Any], expected: Mapping[str, Any]) -> None:
    if canonical_json(record["data"]) != canonical_json(expected):
        raise ReleaseControlError(
            "graph primary differs from its complete original semantic projection"
        )


def _release_graph_native_projection(
    original: ReleaseInvocation,
    *,
    record_path: Path,
    record: Mapping[str, Any],
    captured: _ReleaseCapturedFiles,
    facts: _ReleaseFixtureNativeFacts,
    inputs: Mapping[str, list[tuple[Path, bytes]]],
    selection: Mapping[str, Any],
    plan: Sequence[Mapping[str, Any]],
    dependencies: Mapping[str, _ReleasePrerequisiteGraphNode],
) -> None:
    """Compare native facts to the WHOLE primary; this grants no public/live membership."""
    tool = original.intent["tool"]
    args = _release_original_arguments(tool, original.intent["argv"])
    validate_record(record, _RELEASE_GATE_PREREQUISITES[tool][0])
    if (
        record["status"] != "PASS"
        or record["synthetic"] is not True
        or record["sequence"] != original.intent["sequence"]
        or record["invocation_id"] != original.intent["invocation_id"]
    ):
        raise ReleaseControlError(
            "graph complete primary envelope differs from original passing producer"
        )
    pair = {
        "producer_intent_digest": sha256_json(original.intent),
        "invocation_root_locator": "invocations",
    }
    if any(record["data"].get(key) != value for key, value in pair.items()):
        raise ReleaseControlError("graph primary producer pair differs")
    producer = {
        "tool": tool,
        "invocation_id": original.intent["invocation_id"],
        "sequence": original.intent["sequence"],
        "intent_digest": pair["producer_intent_digest"],
    }
    if facts.producer_identity != canonical_json(producer) or len(facts.operations) != len(plan):
        raise ReleaseControlError("graph native fact producer or complete operation count differs")
    operations = [_source_json(raw, "graph actual native operation") for raw in facts.operations]
    interval = (
        original.intent["started_at"],
        _release_captured_journal_terminal(original, captured=captured, require_pass=True)["data"][
            "completed_at"
        ],
    )

    def ref(index: int, field: str) -> dict[str, Any]:
        return _release_graph_original_ref(
            original.root / plan[index]["paths"][field],
            record_path=record_path,
            captured=captured,
        )

    def input_ref(flag: str) -> dict[str, Any]:
        return _release_graph_original_ref(
            inputs[flag][0][0], record_path=record_path, captured=captured
        )

    if tool == "capture_linear_release_snapshot.py":
        # The expectation constructor already reruns the entire raw/two-round/BOM/lifecycle
        # owner, including the complete primary's self-digest and transport pair.
        _release_linear_snapshot_replay(
            record_path,
            captured=captured,
            readiness_registry_raw=inputs["registry"][0][1],
            expected_readiness_digest=selection["readiness_digest"],
            original_packet=selection["original_packet"],
            expected_packet_digest=selection["packet_digest"],
            original_work_orders=selection["original_work_orders"],
            expected_work_orders_digest=selection["work_orders_digest"],
            task_state_policy_raw=selection["task_state_policy_raw"],
            expected_task_state_policy_digest=selection["task_state_policy_digest"],
            context_id=selection["context_id"],
            declared_dependencies=selection["declared_dependencies"],
            observed_at=selection["observed_at"],
            consumer_stage=selection["consumer_stage"],
        )
    elif tool == "record_release_role_assignments.py":
        _release_recorded_role_byte_replay(
            record_path,
            protected_path=inputs["signed-assignments"][0][0],
            context_path=inputs["release-context"][0][0],
            captured=captured,
            expected_context_digest=selection["context_digest"],
            expected_run_id=args["run-id"],
            expected_milestone=args["milestone"],
            expected_assignment_policy_digest=selection["policy_digest"],
            expected_authority_policy_digest=selection["authority_policy_digest"],
            expected_keyring_digest=selection["keyring_digest"],
            expected_producer_intent_digest=pair["producer_intent_digest"],
            expected_invocation_id=original.intent["invocation_id"],
            expected_sequence=original.intent["sequence"],
            use_interval=interval,
            live=False,
        )
    elif tool == "validate_release_evidence_stores.py":
        rows = []
        for index, operation in enumerate(operations):
            request = operation["request"]
            # The native interpreter independently proves the closed trace, both isolated
            # namespaces and distinct administration. These are fixture-only identities.
            challenge = sha256_json(request["challenge"])
            rows.append(
                {
                    "backend_id": request["backend_id"],
                    "backend_binding_digest": request["binding_digest"],
                    "capabilities_tested": request["capabilities"],
                    "create_digest": challenge,
                    "read_back_digest": challenge,
                    "namespace": request["namespace"],
                    "operation_id": sha256_json(plan[index]["request"]),
                    "result": "PASS",
                    "native_proof_files": [ref(index, field) for field in ("receipt",)],
                }
            )
        _release_graph_primary_equal(
            record,
            {
                **pair,
                "backends": rows,
                "independence_verified": True,
                "mode": "isolated_preflight",
                "production_heads_mutated": False,
                "original_registry": input_ref("stores"),
                "registry_digest": selection["registry_digest"],
                "scope": args["scope"],
            },
        )
    elif tool == "capture_release_target_observations.py":
        rows = []
        for index, operation in enumerate(operations):
            response = operation["response"]
            artifacts = []
            for artifact in response["artifacts"]:
                path = original.root / _release_relative_suffix(
                    artifact["original_read_back"]["path"],
                    "graph target original readback",
                )
                raw_ref = _release_graph_original_ref(
                    path, record_path=record_path, captured=captured
                )
                if raw_ref["bytes"] != artifact["bytes"] or raw_ref["sha256"] != artifact["sha256"]:
                    raise ReleaseControlError("graph target artifact differs from native original")
                artifacts.append(
                    {
                        "name": artifact["name"],
                        "expected_digest": None,
                        "observed_digest": artifact["sha256"],
                        "size": artifact["bytes"],
                        "original_read_back": raw_ref,
                    }
                )
            rows.append(
                {
                    "target_id": response["target_id"],
                    "version": response["normalized_package_version"],
                    "state": response["state"],
                    "raw_result_digest": ref(index, "response")["sha256"],
                    "artifacts": artifacts,
                }
            )
        expected = {
            **pair,
            "api_version": "metriplane.release-fixture-native-request.v1",
            "capture_phase": "prebuild",
            "captured_at": operations[-1]["completed_at"],
            "provider": "test-fixture",
            "tool": tool,
            "registry_digest": selection["registry_digest"],
            "original_registry": input_ref("targets"),
            "original_release_context": {
                "record_type": "release-context",
                "record_digest": selection["context_digest"],
                "original_file": input_ref("release-context"),
            },
            "observations": [ref(index, "response") for index in range(len(plan))],
            "targets": rows,
        }
        expected["observation_digest"] = sha256_json(expected)
        _release_graph_primary_equal(record, expected)
        _release_fixture_target_transcript_replay(
            original,
            captured=captured,
            original_context=_source_json(
                inputs["release-context"][0][1], "graph original target context"
            ),
            expected_context_digest=selection["context_digest"],
            registry_raw=inputs["targets"][0][1],
            expected_registry_digest=selection["registry_digest"],
            native_facts=facts,
        )
    elif tool == "retain_release_evidence.py":
        if "through-stage" in args:
            raise ReleaseControlError(
                "RETENTION_THROUGH_STAGE_CUSTODY_REQUIRED: original consumed-journal closure is not supplied by put/read facts"
            )
        subject = _release_retention_subject_bytes(
            [raw for _, raw in inputs.get("input", [])],
            inputs["manifest"][0][1] if "manifest" in inputs else None,
        )
        stores = []
        for start in (0, 3):
            request = operations[start]["request"]
            stores.append(
                {
                    "store_id": request["store_id"],
                    "content_digest": sha256_bytes(subject),
                    "read_back_digest": sha256_bytes(subject),
                    "put_receipt_digest": ref(start, "response")["sha256"],
                    "hold_receipt_digest": ref(start + 1, "response")["sha256"],
                    "namespace": request["namespace"],
                    "object_key": request["object_key"],
                    "independence_group": request["administration_identity"],
                    "backend_binding_digest": request["binding_digest"],
                    "native_proofs": {
                        "put": ref(start, "response"),
                        "hold": ref(start + 1, "response"),
                        "read_back": ref(start + 2, "response"),
                    },
                }
            )
        expected = {
            **pair,
            "all_content_equal": True,
            "input_digest": sha256_bytes(subject),
            "original_registry": input_ref("stores"),
            "phase": args["phase"],
            "retained_at": operations[-1]["completed_at"],
            "stores": stores,
            "receipt_set_digest": sha256_json(stores),
        }
        _release_retention_content(expected)
        _release_graph_primary_equal(record, expected)
        for flag in ("manifest", "input"):
            for path, _ in inputs.get(flag, []):
                if path.relative_to(captured.root).as_posix() not in {
                    node.path for node in dependencies.values()
                }:
                    raise ReleaseControlError(
                        "retention subject lacks its original semantic producer dependency"
                    )
    elif tool == "update_release_attempt_index.py":
        entry = _release_index_receipt_content(record["data"])
        response = operations[0]["response"]
        if canonical_json(entry) != canonical_json(response["entry"]) or any(
            record["data"][field] != response[field]
            for field in ("committed_head", "read_back_digest", "disposition")
        ):
            raise ReleaseControlError(
                "index primary is not the complete original CAS response entry/token"
            )
        for flag in ("entry-manifest", "entry-receipts"):
            input_name = inputs[flag][0][0].relative_to(captured.root).as_posix()
            if input_name not in {node.path for node in dependencies.values()}:
                raise ReleaseControlError(
                    "index original manifest/retention has not passed dependency replay"
                )
    elif tool in {"export_release_attempt_index.py", "export_release_burn_lineage.py"}:
        _release_graph_index_read_projection(
            original,
            record_path=record_path,
            record=record,
            captured=captured,
            operations=operations,
            plan=plan,
            inputs=inputs,
            dependencies=dependencies,
        )
    else:
        raise ReleaseControlError(
            "graph native owner is not one of the eight implemented interpreters"
        )
    captured.revalidate()


def _release_graph_index_read_projection(
    original: ReleaseInvocation,
    *,
    record_path: Path,
    record: Mapping[str, Any],
    captured: _ReleaseCapturedFiles,
    operations: Sequence[Mapping[str, Any]],
    plan: Sequence[Mapping[str, Any]],
    inputs: Mapping[str, list[tuple[Path, bytes]]],
    dependencies: Mapping[str, _ReleasePrerequisiteGraphNode],
) -> None:
    response = operations[0]["response"]
    args = _release_original_arguments(original.intent["tool"], original.intent["argv"])
    pair = {
        "producer_intent_digest": sha256_json(original.intent),
        "invocation_root_locator": "invocations",
    }
    nodes = {node.path: node for node in dependencies.values()}

    def linked(value: object, kind: str) -> Mapping[str, Any]:
        link = _release_closed_mapping(
            value,
            {"record_type", "record_digest", "original_file"},
            "graph indexed original",
        )
        raw_ref = _release_closed_mapping(
            link["original_file"],
            {"path", "bytes", "sha256"},
            "graph indexed raw original",
        )
        path = record_path.parent / _release_relative_suffix(
            raw_ref["path"], "graph indexed original suffix"
        )
        name = path.relative_to(captured.root).as_posix()
        if name not in nodes:
            raise ReleaseControlError("index read lacks separately replayed original record graph")
        _release_graph_original_input_identity(
            original, path=path, schema_id="metriplane." + kind + ".v1", expected_raw=raw_ref
        )
        actual_ref = _release_graph_original_ref(path, record_path=record_path, captured=captured)
        value_record = _source_json(nodes[name].original_record, "graph original dependency")
        if (
            canonical_json(raw_ref) != canonical_json(actual_ref)
            or link["record_type"] != kind
            or value_record["record_type"] != kind
            or link["record_digest"] != sha256_json(value_record)
        ):
            raise ReleaseControlError("index read dependency original path/R/C/type differs")
        return value_record

    if original.intent["tool"] == "export_release_burn_lineage.py":
        data = _release_closed_mapping(
            record["data"],
            {
                "burns",
                "index_backend_id",
                "index_genesis_digest",
                "lineage_digest",
                "milestone",
                "original_genesis",
                "original_index_export",
                "read_back_complete",
                "through_head",
                *pair,
            },
            "graph full burn lineage",
        )
        export = linked(data["original_index_export"], "release-attempt-index")
        if (
            export["data"]["kind"] != "complete_export"
            or [row["entry"] for row in export["data"]["entries"]] != response["entries"]
            or export["data"]["through_head"] != response["through_head"]
        ):
            raise ReleaseControlError("burn lineage selects a different complete original export")
        burns = []
        seen_pairs: set[tuple[str, str]] = set()
        for row in export["data"]["entries"]:
            entry = row["entry"]
            if entry["milestone"] != args["milestone"] or entry["scope"]["stage"] != "target-burn":
                continue
            manifest = linked(row["original_manifest"], "release-evidence-manifest")
            receipt = linked(row["original_receipt"], "release-attempt-index")
            manifest_nodes = [
                node for node in nodes.values() if node.original_record == canonical_json(manifest)
            ]
            if len(manifest_nodes) != 1 or manifest["data"]["phase"] != "target-burn":
                raise ReleaseControlError("burn entry lacks its exact original burn manifest owner")
            manifest_root = captured.root / manifest_nodes[0].original_root
            candidates = []
            for node in nodes.values():
                candidate = _source_json(node.original_record, "graph burn subject")
                if candidate["record_type"] != "release-target-burn":
                    continue
                matches = [
                    member
                    for member in manifest["data"]["entries"]
                    if manifest_root
                    / _release_relative_suffix(member["path"], "burn manifest member")
                    == captured.root / node.path
                ]
                if len(matches) != 1:
                    continue
                raw = captured.read(node.path, kind="prerequisite-original")
                if matches[0]["sha256"] != sha256_bytes(raw) or matches[0]["size"] != len(raw):
                    raise ReleaseControlError("burn manifest original subject path/R/size differs")
                candidates.append(candidate)
            if len(candidates) != 1:
                raise ReleaseControlError(
                    "burn index manifest does not select one original validated burn"
                )
            burn = candidates[0]["data"]
            if burn["disposition"] != "new_burn":
                raise ReleaseControlError("burn history contains a non-burn disposition")
            for target in sorted(
                burn["affected_targets"],
                key=lambda item: (item["target_id"], item["version"]),
            ):
                pair_id = (target["target_id"], target["version"])
                if pair_id in seen_pairs:
                    continue
                seen_pairs.add(pair_id)
                burns.append(
                    {
                        "burn_manifest_digest": sha256_json(manifest),
                        "index_receipt_digest": sha256_json(receipt),
                        "observation_digest": burn["observation_digest"],
                        "package_version": target["version"],
                        "release_tag": "v" + target["version"],
                        "sequence": entry["scope"]["sequence"],
                        "target_id": target["target_id"],
                    }
                )
        expected = {
            **pair,
            "burns": burns,
            "index_backend_id": "attempt-index",
            "index_genesis_digest": response["genesis_digest"],
            "milestone": args["milestone"],
            "original_genesis": _release_graph_original_ref(
                inputs["genesis"][0][0], record_path=record_path, captured=captured
            ),
            "original_index_export": data["original_index_export"],
            "read_back_complete": True,
            "through_head": response["through_head"],
        }
        expected["lineage_digest"] = sha256_json(expected)
        _release_graph_primary_equal(record, expected)
        return
    data = _release_closed_mapping(
        record["data"],
        {
            "kind",
            "backend_id",
            "backend_binding_digest",
            "genesis",
            "genesis_digest",
            "through_head",
            "generation",
            "capture_started_at",
            "capture_completed_at",
            "entries",
            "head_observation",
            *pair,
        },
        "graph complete export",
    )
    native_ref = _release_graph_original_ref(
        original.root / plan[0]["paths"]["response"],
        record_path=record_path,
        captured=captured,
    )
    expected_head = {
        "head": response["through_head"],
        "generation": len(response["entries"]),
        "observed_at": operations[0]["completed_at"],
        "original_native_response": native_ref,
    }
    if canonical_json(data["head_observation"]) != canonical_json(expected_head):
        raise ReleaseControlError("export head does not bind actual native original response/time")
    if len(data["entries"]) != len(response["entries"]):
        raise ReleaseControlError("export omits or adds native original generations")
    for row, entry in zip(data["entries"], response["entries"], strict=True):
        _release_closed_mapping(
            row,
            {
                "entry",
                "entry_digest",
                "original_native_response",
                "original_receipt",
                "original_manifest",
                "original_retention",
            },
            "graph exported entry",
        )
        if canonical_json(row["entry"]) != canonical_json(entry) or row[
            "entry_digest"
        ] != sha256_json(entry):
            raise ReleaseControlError("export rewrites original native index entry")
        receipt = linked(row["original_receipt"], "release-attempt-index")
        manifest = linked(row["original_manifest"], "release-evidence-manifest")
        retention = linked(row["original_retention"], "release-retention-receipts")
        if (
            canonical_json(_release_index_receipt_content(receipt["data"])) != canonical_json(entry)
            or sha256_json(manifest) != entry["entry_manifest_digest"]
            or sha256_json(retention) != entry["entry_receipts_digest"]
        ):
            raise ReleaseControlError(
                "export native entry differs from complete original retained graph"
            )
        receipt_node = next(
            node for node in nodes.values() if node.original_record == canonical_json(receipt)
        )
        if receipt_node.native_facts is None:
            raise ReleaseControlError("export CAS receipt lacks original native replay")
        cas = _source_json(receipt_node.native_facts.operations[0], "graph original CAS operation")
        ref = _release_closed_mapping(
            row["original_native_response"],
            {"path", "bytes", "sha256"},
            "graph original CAS response reference",
        )
        response_path = record_path.parent / _release_relative_suffix(
            ref["path"], "graph original CAS response"
        )
        receipt_root = captured.root / receipt_node.original_root
        if not response_path.is_relative_to(receipt_root):
            raise ReleaseControlError("export CAS response escapes its original producer root")
        if (
            type(ref["bytes"]) is not int
            or ref["bytes"] < 1
            or (
                response_path.relative_to(receipt_root).as_posix(),
                _require_digest(ref["sha256"], "export original CAS R"),
                ref["bytes"],
            )
            not in receipt_node.native_facts.raw_inventory
        ):
            raise ReleaseControlError(
                "export cannot substitute a response outside original CAS custody"
            )
        _release_graph_original_input_identity(
            original, path=response_path, schema_id="application/octet-stream", expected_raw=ref
        )
        raw = captured.read(
            response_path.relative_to(captured.root).as_posix(),
            kind="prerequisite-original",
        )
        if (
            sha256_bytes(raw) != ref["sha256"]
            or len(raw) != ref["bytes"]
            or _release_fixture_native_response("index.cas", cas["request"], raw) != cas["response"]
        ):
            raise ReleaseControlError("export original CAS response differs before semantic replay")
    expected = {
        **pair,
        "kind": "complete_export",
        "backend_id": "attempt-index",
        "backend_binding_digest": response["binding_digest"],
        "genesis": _release_graph_original_ref(
            inputs["genesis"][0][0], record_path=record_path, captured=captured
        ),
        "genesis_digest": response["genesis_digest"],
        "through_head": response["through_head"],
        "generation": len(response["entries"]),
        "capture_started_at": operations[0]["started_at"],
        "capture_completed_at": operations[0]["completed_at"],
        "entries": data["entries"],
        "head_observation": expected_head,
    }
    _release_graph_primary_equal(record, expected)


def _release_graph_auxiliary(
    original: ReleaseInvocation,
    *,
    captured: _ReleaseCapturedFiles,
    references: Mapping[str, Mapping[str, str]],
) -> dict[str, tuple[Path, bytes]]:
    """Auxiliary transitive inputs still need exact original intent type/R custody."""
    if not isinstance(references, dict):
        raise ReleaseControlError("graph auxiliary references must be a closed mapping")
    args = _release_original_arguments(original.intent["tool"], original.intent["argv"])
    cwd = _canonical_absolute_path(
        original.intent["environment"]["working_directory"], "graph auxiliary cwd"
    )
    historical = _release_historical_path(args["invocation-dir"], cwd).parents[2]
    result = {}
    seen = set()
    for name, reference in references.items():
        _require_nonempty_string(name, "graph auxiliary name")
        row = _release_closed_mapping(
            reference, {"path", "schema_id", "sha256"}, "graph typed auxiliary"
        )
        suffix = _release_relative_suffix(row["path"], "graph auxiliary suffix")
        matching = [
            item for item in original.intent["inputs"] if item["path"] == str(historical / suffix)
        ]
        if (
            len(matching) != 1
            or matching[0]["schema_id"] != row["schema_id"]
            or matching[0]["sha256"] != _require_digest(row["sha256"], "graph auxiliary R")
        ):
            raise ReleaseControlError("graph auxiliary lacks original intent type/R before reading")
        path = original.root / suffix
        if path in seen:
            raise ReleaseControlError("graph auxiliary paths alias")
        seen.add(path)
        raw = captured.read(
            path.relative_to(captured.root).as_posix(), kind="prerequisite-original"
        )
        if sha256_bytes(raw) != row["sha256"]:
            raise ReleaseControlError("graph auxiliary changed before parse")
        result[name] = path, raw
    return result


def _release_graph_pure_projection(
    original: ReleaseInvocation,
    *,
    record: Mapping[str, Any],
    record_path: Path,
    captured: _ReleaseCapturedFiles,
    inputs: Mapping[str, list[tuple[Path, bytes]]],
    auxiliary: Mapping[str, tuple[Path, bytes]],
    selection: Mapping[str, Any],
    dependencies: Mapping[str, _ReleasePrerequisiteGraphNode],
    origins: Mapping[str, Mapping[str, Any]],
) -> None:
    tool = original.intent["tool"]
    args = _release_original_arguments(tool, original.intent["argv"])

    def dependency(flag: str, kind: str) -> Mapping[str, Any]:
        if flag not in dependencies or flag not in inputs or len(inputs[flag]) != 1:
            raise ReleaseControlError(
                "pure graph owner lacks its exact original dependency flag: " + flag
            )
        node = dependencies[flag]
        path, raw = inputs[flag][0]
        value = _source_json(raw, "pure graph original dependency")
        if (
            node.path != path.relative_to(captured.root).as_posix()
            or node.original_record != canonical_json(value)
            or value["record_type"] != kind
        ):
            raise ReleaseControlError("pure graph original dependency path/type/C differs")
        return value

    if tool in {"resolve_release_target.py", "record_release_target_burn.py"}:
        _release_closed_mapping(
            selection,
            {
                "expected_versions",
                "expected_operation_order",
                "expected_context_digest",
                "expected_target_registry_digest",
            },
            "graph pure target selectors",
        )
        if set(auxiliary) != {"context", "target_registry"}:
            raise ReleaseControlError("pure target requires exact original context/registry inputs")
        observations_flag = (
            "live-target-observations"
            if tool == "resolve_release_target.py"
            else "target-observations"
        )
        lineage_flag = (
            "retained-burn-lineage" if tool == "resolve_release_target.py" else "burn-lineage"
        )
        observations = dependency(observations_flag, "release-target-observations")
        lineage = dependency(lineage_flag, "release-burn-lineage")
        context = _source_json(auxiliary["context"][1], "graph original target context")
        expected, _ = _release_target_control_data(
            record["record_type"],
            context=context,
            observations=observations,
            lineage=lineage,
            expected_context_digest=selection["expected_context_digest"],
            expected_observations_digest=sha256_json(observations),
            expected_lineage_digest=sha256_json(lineage),
            target_registry_raw=auxiliary["target_registry"][1],
            expected_target_registry_digest=selection["expected_target_registry_digest"],
            expected_versions=selection["expected_versions"],
            expected_operation_order=selection["expected_operation_order"],
            producer_intent_digest=sha256_json(original.intent),
        )
        if tool == "resolve_release_target.py":
            if (
                set(inputs) != {"live-target-observations", "retained-burn-lineage", "targets"}
                or inputs["targets"][0] != auxiliary["target_registry"]
            ):
                raise ReleaseControlError("target resolution original registry input differs")
            if any(
                args[flag] != expected[field]
                for flag, field in (
                    ("milestone", "milestone"),
                    ("initial-package-version", "initial_package_version"),
                    ("initial-release-tag", "initial_release_tag"),
                )
            ):
                raise ReleaseControlError("target resolution original selection flags differ")
        else:
            target = dependency("target-resolution", "release-target-resolution")
            resolved, _ = _release_target_control_data(
                "release-target-resolution",
                context=context,
                observations=observations,
                lineage=lineage,
                expected_context_digest=selection["expected_context_digest"],
                expected_observations_digest=sha256_json(observations),
                expected_lineage_digest=sha256_json(lineage),
                target_registry_raw=auxiliary["target_registry"][1],
                expected_target_registry_digest=selection["expected_target_registry_digest"],
                expected_versions=selection["expected_versions"],
                expected_operation_order=selection["expected_operation_order"],
                producer_intent_digest=target["data"]["producer_intent_digest"],
            )
            _release_graph_primary_equal(target, resolved)
        _release_graph_primary_equal(record, expected)
    elif tool == "build_release_evidence_manifest.py":
        if selection or auxiliary:
            raise ReleaseControlError("manifest has no detached scope/phase authority selectors")
        _release_graph_manifest_projection(
            original,
            record=record,
            captured=captured,
            inputs=inputs,
            dependencies=dependencies,
            origins=origins,
        )
    elif tool == "record_release_staging_attempt.py":
        _release_graph_staging_projection(
            original,
            record=record,
            captured=captured,
            auxiliary=auxiliary,
            selection=selection,
        )
    elif tool == "record_release_index_recovery.py":
        _release_graph_recovery_projection(
            original,
            record=record,
            captured=captured,
            dependencies=dependencies,
            inputs=inputs,
            selection=selection,
            origins=origins,
        )
    else:
        raise ReleaseControlError(
            "graph pure owner is not one of the five existing prerequisite types"
        )
    captured.revalidate()


def _release_graph_staging_projection(
    original: ReleaseInvocation,
    *,
    record: Mapping[str, Any],
    captured: _ReleaseCapturedFiles,
    auxiliary: Mapping[str, tuple[Path, bytes]],
    selection: Mapping[str, Any],
) -> None:
    """Project complete retained ordinary negative prerequisite custody, never continuation."""
    _release_closed_mapping(selection, {"expected_context_digest"}, "graph staging selectors")
    if set(auxiliary) != {"context", "failed_intent", "failed_terminal"}:
        raise ReleaseControlError(
            "staging requires the exact held context and original failed journal"
        )
    args = _release_original_arguments(original.intent["tool"], original.intent["argv"])
    context = _source_json(auxiliary["context"][1], "staging original context")
    validate_record(context, "release-context")
    if (
        sha256_json(context) != selection["expected_context_digest"]
        or context["synthetic"] is not True
        or context["status"] != "PASS"
    ):
        raise ReleaseControlError("staging original context identity or mode differs")
    failed = _validate_intent_bytes(
        auxiliary["failed_intent"][0].parent, auxiliary["failed_intent"][1]
    )
    terminal = _release_captured_journal_terminal(failed, captured=captured, require_pass=False)
    if (
        canonical_json(terminal)
        != canonical_json(_source_json(auxiliary["failed_terminal"][1], "staging failed terminal"))
        or auxiliary["failed_terminal"][0] != failed.directory / "invocation.json"
    ):
        raise ReleaseControlError("staging substitutes its original failed terminal")
    if terminal["status"] not in {"FAIL", "BLOCKED", "CANCELLED"}:
        raise ReleaseControlError("staging cannot turn a passing original into failure evidence")
    stages = {
        "record_release_role_assignments.py": "role-resource-resolution",
        "validate_release_evidence_stores.py": "evidence-store-preflight",
        "capture_linear_release_snapshot.py": "snapshot",
        "capture_release_target_observations.py": "target-observation",
        "export_release_burn_lineage.py": "burn-lineage",
        "resolve_release_target.py": "target-resolution",
        "record_release_target_burn.py": "target-burn",
        "update_release_attempt_index.py": "attempt-index-update",
        "validate_release_attempt_index.py": "attempt-index-validation",
    }
    if stages.get(failed.intent["tool"]) != args["stage"]:
        raise ReleaseControlError(
            "STAGING_ADDITIONAL_STAGE_OWNER_REQUIRED: only seven ordinary prerequisites and the two exact index failure stages are projected here"
        )
    if "stage-record" in args:
        raise ReleaseControlError(
            "STAGING_NEGATIVE_STAGE_RECORD_OWNER_REQUIRED: an optional complete stage result needs its exact original failed-worker binding"
        )
    cwd = _canonical_absolute_path(
        original.intent["environment"]["working_directory"], "staging original cwd"
    )
    historical = _release_historical_path(args["invocation-dir"], cwd).parents[2]
    if _release_historical_path(args["work-dir"], cwd) != historical:
        raise ReleaseControlError("staging work-dir differs from its original run root")
    failed_old = _release_historical_path(args["failed-invocation-dir"], cwd)
    if (
        not failed_old.is_relative_to(historical)
        or original.root / failed_old.relative_to(historical) != failed.directory
        or failed.root != original.root
    ):
        raise ReleaseControlError("staging failed journal differs from its original run/command")
    if _parse_utc_timestamp(
        terminal["data"]["completed_at"], "staging failure completion"
    ) > _parse_utc_timestamp(original.intent["started_at"], "staging recorder start"):
        raise ReleaseControlError("staging failure completes after its recorder starts")
    failed_args = _release_original_arguments(failed.intent["tool"], failed.intent["argv"])
    failed_cwd = _canonical_absolute_path(
        failed.intent["environment"]["working_directory"], "staging original failed cwd"
    )
    if _release_historical_path(failed_args["invocation-dir"], failed_cwd).parents[2] != historical:
        raise ReleaseControlError("staging cannot relabel another historical run")
    lineage = _release_replay_original_lineage(failed, captured=captured, require_pass=False)
    required = {auxiliary["context"][0]}
    for prior in lineage:
        intent = prior["intent"]
        directory = (
            failed.root
            / "invocations"
            / _invocation_stage(intent["tool"])
            / f"{intent['sequence']:03d}"
        )
        required.update(
            captured.root / row[0]
            for row in captured.rows
            if (captured.root / row[0]).is_relative_to(directory)
        )
        prior_args = _release_original_arguments(intent["tool"], intent["argv"])
        prior_cwd = _canonical_absolute_path(
            intent["environment"]["working_directory"], "staging failed original cwd"
        )
        prior_root = _release_historical_path(prior_args["invocation-dir"], prior_cwd).parents[2]
        for row in intent["inputs"]:
            old = _canonical_absolute_path(row["path"], "staging available original input")
            if not old.is_relative_to(prior_root):
                raise ReleaseControlError("staging failed original input escapes its run")
            required.add(failed.root / old.relative_to(prior_root))
    available = []
    actual = set()
    for row in original.intent["inputs"]:
        old = _canonical_absolute_path(row["path"], "staging recorder original input")
        if not old.is_relative_to(historical):
            raise ReleaseControlError("staging recorder imports an external available input")
        current = original.root / old.relative_to(historical)
        raw = captured.read(
            current.relative_to(captured.root).as_posix(), kind="prerequisite-original"
        )
        if sha256_bytes(raw) != row["sha256"] or current in actual:
            raise ReleaseControlError("staging available input R differs or aliases")
        actual.add(current)
        available.append(dict(row))
    if actual != required:
        raise ReleaseControlError(
            "staging omits/adds original failed lineage, diagnostics, payload or available typed inputs"
        )
    milestone = context["data"].get("framework_milestone")
    if milestone not in MILESTONES:
        raise ReleaseControlError("staging cannot invent an unknown milestone scope")
    expected = {
        "available_inputs": sorted(available, key=lambda row: row["path"]),
        "blockers": [
            f"{args['stage']}: original {terminal['status']} (exit {terminal['data']['exit_code']}); corrected staging requires a new run"
        ],
        "disposition": "TERMINAL",
        "failed_invocation_digest": sha256_json(terminal),
        "invocation_root_locator": "invocations",
        "milestone": milestone,
        "producer_intent_digest": sha256_json(original.intent),
        "recovery_envelope_digest": None,
        "result": terminal["status"],
        "run_id": historical.name,
        "sequence": original.intent["sequence"],
        "stage": args["stage"],
        "stage_record_digest": None,
    }
    _release_graph_primary_equal(record, expected)
    captured.revalidate()


def _release_graph_failed_operation_from_manifest(
    *,
    captured: _ReleaseCapturedFiles,
    origins: Mapping[str, Mapping[str, Any]],
    dependencies: Mapping[str, _ReleasePrerequisiteGraphNode],
    failure_manifest_path: Path,
    failure_manifest: Mapping[str, Any],
    failure_entry: Mapping[str, Any],
    original_receipt: Mapping[str, Any],
) -> dict[str, Any]:
    """Follow the manifest-selected staging envelope to its one original failed CAS."""
    manifest_node = dependencies["failure-envelope-manifest"]
    failure_node = dependencies["failure-entry-receipt"]
    original_node = dependencies["original-entry-receipt"]
    if (
        manifest_node.producer != "build_release_evidence_manifest.py"
        or failure_node.producer != "update_release_attempt_index.py"
        or original_node.producer != "update_release_attempt_index.py"
        or original_node.native_facts is None
        or failure_node.native_facts is None
    ):
        raise ReleaseControlError("recovery lacks its original native CAS and manifest owners")
    manifest_origin = origins.get(manifest_node.path)
    if manifest_origin is None:
        raise ReleaseControlError("recovery manifest lacks its captured original origin")
    manifest_directory = (
        captured.root
        / manifest_origin["run_root"]
        / "invocations"
        / _invocation_stage(manifest_node.producer)
        / f"{manifest_origin['record']['sequence']:03d}"
    )
    manifest_original = _validate_intent_bytes(
        manifest_directory,
        captured.read(
            (manifest_directory / "intent.json").relative_to(captured.root).as_posix(),
            kind="prerequisite-original",
        ),
    )
    envelope_path, envelope_raw = _release_original_consumed_file(
        manifest_original.intent,
        current_root=manifest_original.root,
        captured=captured,
        expected_tool=manifest_node.producer,
        flag="input",
        expected_schema_id="metriplane.release-staging-attempt.v1",
    )
    envelope_name = envelope_path.relative_to(captured.root).as_posix()
    envelope_origin = origins.get(envelope_name)
    if (
        envelope_origin is None
        or envelope_origin["producer"] != "record_release_staging_attempt.py"
        or envelope_name not in manifest_node.dependencies
        or envelope_name not in failure_node.dependencies
        or envelope_raw != canonical_json(envelope_origin["record"])
    ):
        raise ReleaseControlError("recovery failure payload lacks its exact replayed staging owner")
    envelope = envelope_origin["record"]
    entry_root = _release_index_manifest_entry_root(
        root=manifest_original.root,
        manifest_path=failure_manifest_path,
        manifest=failure_manifest,
        scope=failure_entry["scope"],
    )
    entries = _release_evidence_manifest_content(failure_manifest["data"])
    manifested = [row for row in entries if entry_root / row["path"] == envelope_path]
    if (
        failure_entry["scope"]["stage"] != "staging-failure"
        or len(manifested) != 1
        or manifested[0]["sha256"] != sha256_bytes(envelope_raw)
        or manifested[0]["size"] != len(envelope_raw)
    ):
        raise ReleaseControlError(
            "recovery manifest does not retain its exact failed-operation envelope"
        )
    staging_directory = (
        captured.root
        / envelope_origin["run_root"]
        / "invocations"
        / _invocation_stage(envelope_origin["producer"])
        / f"{envelope['sequence']:03d}"
    )
    staging = _validate_intent_bytes(
        staging_directory,
        captured.read(
            (staging_directory / "intent.json").relative_to(captured.root).as_posix(),
            kind="prerequisite-original",
        ),
    )
    _release_captured_original_context(staging, captured=captured)
    staging_args = _release_original_arguments(staging.intent["tool"], staging.intent["argv"])
    staging_cwd = _canonical_absolute_path(
        staging.intent["environment"]["working_directory"], "recovery staging original cwd"
    )
    staging_historical = _release_historical_path(
        staging_args["invocation-dir"], staging_cwd
    ).parents[2]
    failed_historical = _release_historical_path(staging_args["failed-invocation-dir"], staging_cwd)
    if not failed_historical.is_relative_to(staging_historical):
        raise ReleaseControlError("recovery failed journal escapes its original staging run")
    failed_directory = staging.root / failed_historical.relative_to(staging_historical)
    failed_intent_path = failed_directory / "intent.json"
    selected = [
        row
        for row in staging.intent["inputs"]
        if row["path"] == str(failed_historical / "intent.json")
    ]
    if len(selected) != 1 or selected[0]["schema_id"] != "metriplane.release-invocation-intent.v1":
        raise ReleaseControlError("recovery staging lacks original failed intent membership/type")
    failed_raw = captured.read(
        failed_intent_path.relative_to(captured.root).as_posix(), kind="prerequisite-original"
    )
    if sha256_bytes(failed_raw) != selected[0]["sha256"]:
        raise ReleaseControlError("recovery staging changes original failed intent bytes")
    failed = _validate_intent_bytes(failed_directory, failed_raw)
    return _release_graph_failed_index_operation(
        failed,
        captured=captured,
        envelope=envelope,
        original_receipt=original_receipt,
        native_facts=original_node.native_facts,
    )


def _release_graph_recovery_projection(
    original: ReleaseInvocation,
    *,
    record: Mapping[str, Any],
    captured: _ReleaseCapturedFiles,
    dependencies: Mapping[str, _ReleasePrerequisiteGraphNode],
    inputs: Mapping[str, list[tuple[Path, bytes]]],
    selection: Mapping[str, Any],
    origins: Mapping[str, Mapping[str, Any]],
) -> None:
    """Replay the actual pre-effect recovery command, original authorization and graph."""
    args = _release_original_arguments(original.intent["tool"], original.intent["argv"])
    _release_closed_mapping(
        selection,
        {
            "expected_context_digest",
            "expected_authority_policy_digest",
            "expected_keyring_digest",
        },
        "graph independently expected recovery trust/context",
    )
    if args.get("abandon-original-never-committed") is True:
        raise ReleaseControlError(
            "RECOVERY_ORIGINAL_ABSENCE_TASK_STATE_AND_AUTHORIZATION_REQUIRED: index.read is not a live absence/owner decision"
        )
    types = {
        "original-entry-receipt": "release-attempt-index",
        "failure-envelope-manifest": "release-evidence-manifest",
        "failure-envelope-receipts": "release-retention-receipts",
        "failure-entry-receipt": "release-attempt-index",
        "role-assignments": "release-role-assignments",
        "release-context": "release-context",
        "signed-recovery-authorization": "release-protected-input",
        "provider-attestation-keyring": "provider-attestation-keyring",
    }
    dependency_flags = set(types) - {
        "release-context",
        "signed-recovery-authorization",
        "provider-attestation-keyring",
    }
    if set(inputs) != set(types) or set(dependencies) != dependency_flags:
        raise ReleaseControlError(
            "committed recovery lacks its exact typed original/dependency closure"
        )
    parsed = {}
    cwd = _canonical_absolute_path(
        original.intent["environment"]["working_directory"], "recovery original cwd"
    )
    historical = _release_historical_path(args["invocation-dir"], cwd).parents[2]
    for flag, kind in types.items():
        if len(inputs[flag]) != 1:
            raise ReleaseControlError("recovery original input cardinality differs")
        path, raw = inputs[flag][0]
        suffix = path.relative_to(original.root)
        row = {
            "path": str(historical / suffix),
            "schema_id": "metriplane." + kind + ".v1",
            "sha256": sha256_bytes(raw),
        }
        if row not in original.intent["inputs"]:
            raise ReleaseControlError("recovery original schema/R differs from fixed input owner")
        value = _source_json(raw, "recovery original " + flag)
        parsed[flag] = value
        if flag in dependencies:
            node = dependencies[flag]
            if node.path != path.relative_to(
                captured.root
            ).as_posix() or node.original_record != canonical_json(value):
                raise ReleaseControlError("recovery original dependency path/C differs")
    context = parsed["release-context"]
    validate_record(context, "release-context")
    if (
        context["status"] != "PASS"
        or context["synthetic"] is not True
        or sha256_json(context) != selection["expected_context_digest"]
    ):
        raise ReleaseControlError("recovery changes independently selected original context")
    verifier = ProviderAttestationVerifier._from_keyring_value(
        parsed["provider-attestation-keyring"],
        expected_digest=selection["expected_keyring_digest"],
    )
    if (
        args["provider-attestation-keyring-digest"] != verifier.keyring_digest
        or args["authority-policy-digest"] != selection["expected_authority_policy_digest"]
        or selection["expected_authority_policy_digest"]
        != release_authority_policy_digest(selection["expected_keyring_digest"])
    ):
        raise ReleaseControlError(
            "recovery original trust flags differ from independent captured policy/keyring"
        )
    prior = _release_index_receipt_content(parsed["original-entry-receipt"]["data"])
    scope = prior["scope"]
    if args["scope-kind"] != scope["kind"]:
        raise ReleaseControlError("recovery original scope discriminant differs")
    for flag, field in (
        ("milestone", "milestone"),
        ("run-id", "run_id"),
        ("release-tag", "release_tag"),
        ("candidate-id", "candidate_id"),
        ("assurance-round", "assurance_round"),
    ):
        if flag in args and str(args[flag]) != str(
            prior["milestone"] if flag == "milestone" else scope.get(field)
        ):
            raise ReleaseControlError("recovery original scope selector differs: " + flag)
    if context["data"]["framework_milestone"] != prior["milestone"]:
        raise ReleaseControlError("recovery original context changes milestone")
    _release_graph_failed_operation_from_manifest(
        captured=captured,
        origins=origins,
        dependencies=dependencies,
        failure_manifest_path=inputs["failure-envelope-manifest"][0][0],
        failure_manifest=parsed["failure-envelope-manifest"],
        failure_entry=_release_index_receipt_content(parsed["failure-entry-receipt"]["data"]),
        original_receipt=parsed["original-entry-receipt"],
    )
    terminal = _release_captured_journal_terminal(original, captured=captured, require_pass=True)
    expected = _release_recovery_committed_data(
        original_receipt=parsed["original-entry-receipt"],
        failure_manifest=parsed["failure-envelope-manifest"],
        failure_retention=parsed["failure-envelope-receipts"],
        failure_receipt=parsed["failure-entry-receipt"],
        authorization=parsed["signed-recovery-authorization"],
        roles=parsed["role-assignments"],
        expected_context_digest=selection["expected_context_digest"],
        expected_authority_policy_digest=selection["expected_authority_policy_digest"],
        planned_operation_id=args["recovery-operation-id"],
        planned_sequence=_release_graph_positive_integer(
            args["recovery-sequence"], "planned recovery sequence"
        ),
        producer_intent_digest=sha256_json(original.intent),
        use_interval=(original.intent["started_at"], terminal["data"]["completed_at"]),
    )
    _release_graph_primary_equal(record, expected)
    captured.revalidate()


def _release_prerequisite_graph_replay(
    bundle_path: Path,
    *,
    captured: _ReleaseCapturedFiles,
    expected_context_digest: str,
    before: str,
    selections: Mapping[str, Mapping[str, Any]],
    live: bool,
) -> _ReleasePrerequisiteGraph:
    """Private, per-call fixture composition. Never a public verified-derived constructor.

    Each selection is a trusted enclosing caller's independently chosen typed input
    closure, selectors and ORIGINAL dependency locators. No expected primary payload,
    native facts, approved boolean, verifier callback or global cache is accepted.
    Any incomplete branch raises; no partial graph or membership result escapes.
    """
    if type(live) is not bool or live is not False:
        raise ReleaseControlError("fixture prerequisite graph is inaccessible to live admission")
    path = _release_capture_absolute(bundle_path)
    if not path.is_relative_to(captured.root):
        raise ReleaseControlError("graph bundle escapes captured original root")
    raw = captured.read(path.relative_to(captured.root).as_posix(), kind="prerequisite-proofs")
    bundle = _source_json(raw, "graph original prerequisite bundle")
    origins = _release_prerequisite_origin_rows(
        bundle,
        bundle_path=path,
        captured=captured,
        expected_context_digest=expected_context_digest,
        before=before,
    )
    rows = {row["record_path"]: row for row in origins}
    if not isinstance(selections, dict) or set(selections) != set(rows):
        raise ReleaseControlError("graph selections omit or add an original primary")
    complete: dict[str, _ReleasePrerequisiteGraphNode] = {}
    visiting: set[str] = set()

    def visit(name: str) -> _ReleasePrerequisiteGraphNode:
        if name in complete:
            return complete[name]
        if name in visiting:
            raise ReleaseControlError("original prerequisite dependency graph cycles")
        visiting.add(name)
        row = rows[name]
        chosen = _release_closed_mapping(
            selections[name],
            {"inputs", "auxiliary", "selectors", "proof_refs", "dependencies"},
            "graph original selection",
        )
        dependencies = chosen["dependencies"]
        if not isinstance(dependencies, dict) or any(
            not isinstance(key, str) or not isinstance(value, str) or value not in rows
            for key, value in dependencies.items()
        ):
            raise ReleaseControlError("graph dependencies are not exact captured primary locators")
        if len(set(dependencies.values())) != len(dependencies):
            raise ReleaseControlError("graph dependency roles alias one primary")
        bound = {key: visit(value) for key, value in dependencies.items()}
        directory = (
            captured.root
            / row["run_root"]
            / "invocations"
            / _invocation_stage(row["producer"])
            / f"{row['record']['sequence']:03d}"
        )
        original = _validate_intent_bytes(directory, canonical_json(row["intent"]))
        _release_captured_original_context(original, captured=captured)
        if (
            original.intent["environment"]["fixture_mode"] != "1"
            or row["record"]["synthetic"] is not True
        ):
            raise ReleaseControlError("graph original is not fixture-only")
        start = _parse_utc_timestamp(original.intent["started_at"], "graph original consumer start")
        for value in dependencies.values():
            predecessor = rows[value]
            terminal = predecessor["terminal"]
            if (
                _parse_utc_timestamp(terminal["data"]["completed_at"], "graph dependency completed")
                > start
            ):
                raise ReleaseControlError(
                    "graph dependency completes after original consumer starts"
                )
            for companion in predecessor["companions"]:
                if (
                    _parse_utc_timestamp(
                        companion["terminal"]["data"]["completed_at"],
                        "graph companion completed",
                    )
                    > start
                ):
                    raise ReleaseControlError(
                        "graph dependency companion finishes after original consumer starts"
                    )
        inputs = _release_graph_bound_inputs(original, captured=captured, selected=chosen["inputs"])
        auxiliary = _release_graph_auxiliary(
            original, captured=captured, references=chosen["auxiliary"]
        )
        if not isinstance(chosen["selectors"], dict):
            raise ReleaseControlError("graph selectors must be a closed mapping")
        selectors = dict(chosen["selectors"])
        for context_key in ("context_digest", "expected_context_digest"):
            if context_key in selectors and selectors[context_key] != expected_context_digest:
                raise ReleaseControlError("graph branch changes independently selected context C")
        for field in (
            "original_packet",
            "original_work_orders",
            "task_state_policy_raw",
            "genesis_raw",
        ):
            if field in selectors:
                if selectors[field] != field or field not in auxiliary:
                    raise ReleaseControlError(
                        "graph raw selector must name its held original auxiliary"
                    )
                selectors[field] = auxiliary[field][1]
        if row["producer"] == "retain_release_evidence.py":
            if selectors.get("fixture_run_id") != Path(row["historical_root"]).name:
                raise ReleaseControlError(
                    "retention namespace run must derive from its original selected run"
                )
        if row["producer"] == "update_release_attempt_index.py":
            for field in ("subject", "coordination"):
                if field + "_record" in selectors or field + "_path" in selectors:
                    raise ReleaseControlError(
                        "graph CAS cannot accept caller-serialized subject/coordination authority"
                    )
                node = bound.get(field)
                selectors[field + "_record"] = (
                    _source_json(node.original_record, "graph original CAS dependency")
                    if node
                    else None
                )
                selectors[field + "_path"] = captured.root / node.path if node else None
        record_path = captured.root / name
        facts = None
        if row["producer"] in _RELEASE_GRAPH_NATIVE_TOOLS:
            interval = (
                original.intent["started_at"],
                row["terminal"]["data"]["completed_at"],
            )
            subject, operations = _release_fixture_native_expectations(
                original,
                captured=captured,
                record_path=record_path,
                expected_inputs=chosen["inputs"],
                selection=selectors,
                use_interval=interval,
                live=False,
            )
            plan = _release_fixture_native_plan(
                tool=row["producer"],
                sequence=original.intent["sequence"],
                subject=subject,
                operations=operations,
            )
            facts = _release_fixture_native_receipt_replay(
                original,
                captured=captured,
                subject=subject,
                operations=operations,
                proof_refs=chosen["proof_refs"],
                use_interval=interval,
                live=False,
            )
            _release_graph_native_projection(
                original,
                record_path=record_path,
                record=row["record"],
                captured=captured,
                facts=facts,
                inputs=inputs,
                selection=selectors,
                plan=plan,
                dependencies=bound,
            )
        else:
            _release_original_invocation_binding(
                original,
                expected_tool=row["producer"],
                captured=captured,
                output_plan=[
                    {
                        "path": record_path.relative_to(original.root).as_posix(),
                        "schema_id": "metriplane." + row["record"]["record_type"] + ".v1",
                    }
                ],
            )
            if chosen["proof_refs"] != []:
                raise ReleaseControlError("pure prerequisite cannot import native proof receipts")
            _release_graph_pure_projection(
                original,
                record=row["record"],
                record_path=record_path,
                captured=captured,
                inputs=inputs,
                auxiliary=auxiliary,
                selection=selectors,
                dependencies=bound,
                origins=rows,
            )
        captured.revalidate()
        node = _ReleasePrerequisiteGraphNode(
            name,
            row["producer"],
            canonical_json(row["record"]),
            row["run_root"],
            facts,
            tuple(sorted(dependencies.values())),
        )
        complete[name] = node
        visiting.remove(name)
        return node

    for name in sorted(rows):
        visit(name)
    captured.revalidate()
    return _ReleasePrerequisiteGraph(
        expected_context_digest,
        before,
        captured.root,
        captured,
        tuple(complete[name] for name in sorted(complete)),
    )


def _release_recovery_committed_data(
    *,
    original_receipt: Mapping[str, Any],
    failure_manifest: Mapping[str, Any],
    failure_retention: Mapping[str, Any],
    failure_receipt: Mapping[str, Any],
    authorization: Mapping[str, Any],
    roles: Mapping[str, Any],
    expected_context_digest: str,
    expected_authority_policy_digest: str,
    planned_operation_id: str,
    planned_sequence: int,
    producer_intent_digest: str,
    use_interval: tuple[str, str],
) -> dict[str, Any]:
    """Prospective acyclic committed recovery content, after each original graph replay.

    The two plan values are explicit original pre-effect CLI inputs. The protected
    authorization is a distinct original signed input; it binds the plan and earlier
    records, never this output or the later append receipt. Fixture signatures only.
    Native committed receipts, retention and role delegation must already be replayed
    by the enclosing graph. This function never records or signs a decision.
    """
    for record, kind in (
        (original_receipt, "release-attempt-index"),
        (failure_manifest, "release-evidence-manifest"),
        (failure_retention, "release-retention-receipts"),
        (failure_receipt, "release-attempt-index"),
        (authorization, "release-protected-input"),
        (roles, "release-role-assignments"),
    ):
        validate_record(record, kind)
        if record["status"] != "PASS" or record["synthetic"] is not True:
            raise ReleaseControlError(
                "committed recovery is restricted to exact passing original fixtures"
            )
    original_entry = _release_index_receipt_content(original_receipt["data"])
    failure_entry = _release_index_receipt_content(failure_receipt["data"])
    _release_evidence_manifest_content(failure_manifest["data"])
    _release_retention_content(failure_retention["data"])
    if (
        original_entry["scope"]["kind"] != failure_entry["scope"]["kind"]
        or original_entry["scope"]["scope_id"] != failure_entry["scope"]["scope_id"]
        or original_entry["milestone"] != failure_entry["milestone"]
        or original_entry["genesis_digest"] != failure_entry["genesis_digest"]
        or original_entry["generation"] >= failure_entry["generation"]
        or original_entry["operation_id"] == failure_entry["operation_id"]
        or failure_entry["entry_manifest_digest"] != sha256_json(failure_manifest)
        or failure_entry["entry_receipts_digest"] != sha256_json(failure_retention)
    ):
        raise ReleaseControlError(
            "committed recovery original/failure graph scopes or chronology differ"
        )
    operation = _require_nonempty_string(planned_operation_id, "pre-effect recovery operation")
    if re.fullmatch(
        r"[A-Za-z0-9][A-Za-z0-9._:/-]{0,159}", operation, re.ASCII
    ) is None or operation in {
        original_entry["operation_id"],
        failure_entry["operation_id"],
    }:
        raise ReleaseControlError("recovery operation is malformed or reuses an earlier operation")
    if type(planned_sequence) is not int or planned_sequence < 1:
        raise ReleaseControlError(
            "pre-effect recovery sequence is not a positive logical append counter"
        )
    _require_digest(expected_context_digest, "recovery expected context C")
    _require_digest(expected_authority_policy_digest, "recovery expected policy C")
    plan = {
        "schema_version": "metriplane.release-index-recovery-plan.v1",
        "release_context_digest": expected_context_digest,
        "scope_kind": original_entry["scope"]["kind"],
        "scope_id": original_entry["scope"]["scope_id"],
        "index_backend_id": "attempt-index",
        "genesis_digest": original_entry["genesis_digest"],
        "original_receipt_digest": sha256_json(original_receipt),
        "failure_envelope_manifest_digest": sha256_json(failure_manifest),
        "failure_envelope_receipts_digest": sha256_json(failure_retention),
        "failure_entry_receipt_digest": sha256_json(failure_receipt),
        "recovery_operation_id": operation,
        "recovery_sequence": planned_sequence,
    }
    data = _release_closed_mapping(
        authorization["data"],
        {
            "authority_policy_digest",
            "authorized_role",
            "conflicts",
            "decision",
            "expires_at",
            "input_kind",
            "issued_at",
            "provider_event",
            "signer_identity",
            "signing_method",
            "subject_digests",
        },
        "original committed recovery authorization",
    )
    if (
        data["authority_policy_digest"] != expected_authority_policy_digest
        or data["authorized_role"] != "infrastructure_owner"
        or data["conflicts"] != []
        or data["decision"] != "AUTHORIZE_COMMITTED_INDEX_RECOVERY"
        or data["input_kind"] != "index_recovery"
        or data["signing_method"] != "provider-attestation-v1"
        or data["provider_event"] is not None
    ):
        raise ReleaseControlError(
            "original fixture recovery authorization changes kind, role, policy or decision"
        )
    expected_subjects = [
        {"subject": "recovery_plan", "sha256": sha256_json(plan)},
        {"subject": "role_assignments", "sha256": sha256_json(roles)},
    ]
    if canonical_json(data["subject_digests"]) != canonical_json(expected_subjects):
        raise ReleaseControlError(
            "original recovery authorization does not bind the exact acyclic plan and roles"
        )
    started, completed = (
        _parse_utc_timestamp(value, "recovery original interval") for value in use_interval
    )
    issued = _parse_utc_timestamp(data["issued_at"], "original recovery authorization issued")
    expires = _parse_utc_timestamp(data["expires_at"], "original recovery authorization expires")
    if not issued <= started <= completed < expires:
        raise ReleaseControlError(
            "original recovery authorization is outside its original use interval"
        )
    assignment_data = {
        key: value
        for key, value in roles["data"].items()
        if key
        not in {
            "kind",
            "original_protected_input",
            "original_protected_input_digest",
            "producer_intent_digest",
            "invocation_root_locator",
        }
    }
    _release_role_assignment_payload(
        assignment_data,
        live=False,
        expected_milestone=original_entry["milestone"],
        expected_authority_policy_digest=expected_authority_policy_digest,
        check_conflicts=True,
        expected_context_digest=expected_context_digest,
        use_interval=use_interval,
    )
    actor = assignment_data["infrastructure_owner"]["actor_id"]
    if data["signer_identity"] != actor or _validated_record_signers(authorization, live=False) != {
        ("test-fixture", actor)
    }:
        raise ReleaseControlError(
            "recovery authorization lacks the originally assigned infrastructure signer"
        )
    return {
        "authorization_digest": sha256_json(authorization),
        "failed_task_state_observation_digest": None,
        "failure_entry_receipt_digest": sha256_json(failure_receipt),
        "failure_envelope_manifest_digest": sha256_json(failure_manifest),
        "failure_envelope_receipts_digest": sha256_json(failure_retention),
        "index_backend_id": "attempt-index",
        "invocation_root_locator": "invocations",
        "live_absence_proof_digest": None,
        "original_entry_digest": sha256_json(original_entry),
        "original_entry_disposition": "committed",
        "original_operation_id": original_entry["operation_id"],
        "producer_intent_digest": _require_digest(
            producer_intent_digest, "recovery original producer intent"
        ),
        "provider_termination_digest": None,
        "recovery_operation_id": operation,
        "recovery_sequence": planned_sequence,
        "scope_id": original_entry["scope"]["scope_id"],
        "scope_kind": original_entry["scope"]["kind"],
        "task_state_invalidation_reason": None,
    }


def _release_graph_positive_integer(value: object, label: str) -> int:
    if type(value) is not int or value < 1:
        raise ReleaseControlError(label + " is not an original positive parsed integer argument")
    return value


def _release_graph_manifest_projection(
    original: ReleaseInvocation,
    *,
    record: Mapping[str, Any],
    captured: _ReleaseCapturedFiles,
    inputs: Mapping[str, list[tuple[Path, bytes]]],
    dependencies: Mapping[str, _ReleasePrerequisiteGraphNode],
    origins: Mapping[str, Mapping[str, Any]],
) -> None:
    """Complete ordinary pre-candidate manifest from original typed inputs and journal custody.

    The encompassing graph alone supplies origin rows after the real origin/namespace
    owner. No caller inventory/phase expectation is accepted here. Later release phases
    and external finalizer roots require their own existing stage owners.
    """
    args = _release_original_arguments(original.intent["tool"], original.intent["argv"])
    phase = args["phase"]
    kinds = {"target-burn": "release-target-burn", "staging-failure": "release-staging-attempt"}
    if phase not in kinds or "additional-invocation-root" in args:
        raise ReleaseControlError(
            "MANIFEST_ADDITIONAL_PHASE_CUSTODY_REQUIRED: only ordinary same-run pre-candidate phases are implemented"
        )
    if (
        set(inputs) != {"input"}
        or len(inputs["input"]) != 1
        or args["exclude-current-invocation"] is not True
    ):
        raise ReleaseControlError(
            "ordinary manifest requires its one actual original subject and exclusion flag"
        )
    cwd = _canonical_absolute_path(
        original.intent["environment"]["working_directory"], "manifest original cwd"
    )
    historical = _release_historical_path(args["invocation-dir"], cwd).parents[2]
    if _release_historical_path(args["invocation-root"], cwd) != historical / "invocations":
        raise ReleaseControlError("manifest cannot select a different original invocation root")
    nodes = {node.path: node for node in dependencies.values()}
    subject_path, subject_raw = inputs["input"][0]
    subject_name = subject_path.relative_to(captured.root).as_posix()
    subject = _source_json(subject_raw, "manifest original subject")
    if (
        subject_name not in nodes
        or nodes[subject_name].original_record != canonical_json(subject)
        or subject["record_type"] != kinds[phase]
    ):
        raise ReleaseControlError(
            "manifest subject lacks its independently replayed original semantic dependency"
        )
    if phase == "target-burn" and subject["data"]["disposition"] != "new_burn":
        raise ReleaseControlError("no-new-burn does not create a burn manifest")
    if phase == "staging-failure" and subject["data"]["run_id"] != historical.name:
        raise ReleaseControlError("staging manifest changes its original failure run")
    start = _parse_utc_timestamp(original.intent["started_at"], "manifest start")
    # Row values are privately reconstructed originals; they are never a selected
    # caller approval result. Every prior primary in this root must have semantic replay.
    known_journals: dict[Path, Mapping[str, Any]] = {}
    prior = {}
    for name, row in origins.items():
        if captured.root / row["run_root"] != original.root:
            continue
        for lineage in [row["lineage"], *(c["lineage"] for c in row["companions"])]:
            for item in lineage:
                intent = item["intent"]
                directory = (
                    original.root
                    / "invocations"
                    / _invocation_stage(intent["tool"])
                    / f"{intent['sequence']:03d}"
                )
                if directory in known_journals and canonical_json(
                    known_journals[directory]
                ) != canonical_json(item):
                    raise ReleaseControlError("manifest original journal role identities conflict")
                known_journals[directory] = item
        if (
            _parse_utc_timestamp(row["terminal"]["data"]["completed_at"], "manifest prior primary")
            <= start
        ):
            if name not in nodes or nodes[name].original_record != canonical_json(row["record"]):
                raise ReleaseControlError("manifest omits an available original semantic producer")
            prior[name] = row
    actual_dirs = {
        (captured.root / row[0]).parent
        for row in captured.rows
        if (captured.root / row[0]).is_relative_to(original.root / "invocations")
        and len((captured.root / row[0]).relative_to(original.root).parts) == 4
        and Path(row[0]).name == "intent.json"
    }
    for directory in sorted(
        actual_dirs - set(known_journals),
        key=lambda value: (str(value.parent), int(value.name)),
        reverse=True,
    ):
        if directory in known_journals:
            continue
        path = directory / "intent.json"
        old_path = historical / path.relative_to(original.root)
        matches = [x for x in original.intent["inputs"] if x["path"] == str(old_path)]
        if (
            len(matches) != 1
            or matches[0]["schema_id"] != "metriplane.release-invocation-intent.v1"
        ):
            raise ReleaseControlError(
                "manifest unassigned journal lacks original input membership/type before read"
            )
        raw = captured.read(
            path.relative_to(captured.root).as_posix(), kind="prerequisite-original"
        )
        if sha256_bytes(raw) != matches[0]["sha256"]:
            raise ReleaseControlError("manifest original negative intent R differs before parse")
        negative = _validate_intent_bytes(directory, raw)
        if _parse_utc_timestamp(negative.intent["started_at"], "manifest negative start") >= start:
            raise ReleaseControlError("manifest cannot adopt future unassigned journal")
        lineage = _release_replay_original_lineage(negative, captured=captured, require_pass=False)
        if lineage[0]["terminal"]["status"] == "PASS":
            raise ReleaseControlError(
                "manifest cannot replace a passing semantic primary with journal-only custody"
            )
        for item in lineage:
            intent = item["intent"]
            prior_dir = (
                original.root
                / "invocations"
                / _invocation_stage(intent["tool"])
                / f"{intent['sequence']:03d}"
            )
            if prior_dir in known_journals and canonical_json(
                known_journals[prior_dir]
            ) != canonical_json(item):
                raise ReleaseControlError(
                    "manifest negative lineage overlaps with different original bytes"
                )
            known_journals[prior_dir] = item
    if actual_dirs != set(known_journals):
        raise ReleaseControlError(
            "manifest original namespace census differs from complete assigned journals"
        )
    consumed: set[str] = set()
    for name, row in prior.items():
        if row["producer"] != "update_release_attempt_index.py":
            continue
        entry = _release_index_receipt_content(row["record"]["data"])
        candidates = [
            node
            for node in nodes.values()
            if sha256_json(_source_json(node.original_record, "manifest indexed original"))
            == entry["entry_manifest_digest"]
        ]
        if len(candidates) != 1:
            raise ReleaseControlError(
                "manifest prior index lacks its full original consumed manifest"
            )
        value = _source_json(candidates[0].original_record, "manifest indexed original")
        validate_record(value, "release-evidence-manifest")
        _release_evidence_manifest_content(value["data"])
        overlap = consumed & set(value["data"]["invocation_journal_digests"])
        if overlap:
            raise ReleaseControlError(
                "manifest prior index entries rebound an already consumed journal"
            )
        consumed.update(value["data"]["invocation_journal_digests"])
    required: dict[Path, tuple[str, str]] = {}
    journals: set[str] = set()

    def include(path: Path, kind: str, role: str) -> None:
        if not path.is_relative_to(original.root):
            raise ReleaseControlError("manifest original member escapes its run")
        if path in required and required[path] != (kind, role):
            # A typed original subject can also be an original journal's input.
            old_kind, old_role = required[path]
            if old_kind != kind:
                raise ReleaseControlError("manifest original member has incompatible typed roles")
            required[path] = (kind, min(old_role, role))
        else:
            required[path] = (kind, role)

    # Keep earlier payload/receipt/index records transitively even where their journals
    # have already been consumed. Primary output types come from the actual owner table.
    for name, row in prior.items():
        include(
            captured.root / name,
            "metriplane." + row["record"]["record_type"] + ".v1",
            row["record"]["record_type"],
        )
    for directory, item in known_journals.items():
        intent, terminal = item["intent"], item["terminal"]
        if (
            directory == original.directory
            or _parse_utc_timestamp(intent["started_at"], "manifest journal start") >= start
        ):
            continue
        if terminal is not None:
            if (
                _parse_utc_timestamp(
                    terminal["data"]["completed_at"], "manifest journal completion"
                )
                > start
            ):
                raise ReleaseControlError(
                    "manifest captures a journal still active at its original boundary"
                )
            digest = sha256_json(terminal)
            if digest in consumed:
                continue
            journals.add(digest)
        # Interrupted predecessors contribute original intent/available diagnostics,
        # never a synthesized terminal or journal digest. The retry owner proved absence.
        for name, kind, _, _, _ in captured.rows:
            path = captured.root / name
            if path.is_relative_to(directory):
                typed = {
                    "intent.json": "metriplane.release-invocation-intent.v1",
                    "invocation.json": "metriplane.release-stage-invocation.v1",
                    "partial-files.json": "metriplane.release-partial-files.v1",
                    "worker-result.json": "metriplane.release-worker-result.v1",
                }.get(path.name, "application/octet-stream")
                include(path, typed, "invocation-journal")
        old_args = _release_original_arguments(intent["tool"], intent["argv"])
        old_cwd = _canonical_absolute_path(
            intent["environment"]["working_directory"], "manifest prior cwd"
        )
        old_root = _release_historical_path(old_args["invocation-dir"], old_cwd).parents[2]
        if old_root != historical:
            raise ReleaseControlError("manifest cannot relabel a foreign historical producer")
        for member in intent["inputs"]:
            path = _canonical_absolute_path(member["path"], "manifest available input")
            if not path.is_relative_to(old_root):
                raise ReleaseControlError("manifest original typed input escapes its root")
            include(
                original.root / path.relative_to(old_root), member["schema_id"], "original-input"
            )
        for member in [] if terminal is None else terminal["data"]["outputs"]:
            include(original.root / member["path"], member["schema_id"], "original-output")
    declared = {}
    for member in original.intent["inputs"]:
        path = _canonical_absolute_path(member["path"], "manifest original input")
        if not path.is_relative_to(historical):
            raise ReleaseControlError("manifest cannot late-read an external original")
        current = original.root / path.relative_to(historical)
        if current in declared:
            raise ReleaseControlError("manifest original input aliases")
        declared[current] = member
    if set(declared) != set(required):
        raise ReleaseControlError(
            "manifest original input plan omits/adds full stage-available custody"
        )
    entries = []
    for path, (kind, role) in sorted(required.items(), key=lambda item: item[0].as_posix()):
        member = declared[path]
        if member["schema_id"] != kind:
            raise ReleaseControlError("manifest original input type differs before read")
        raw = captured.read(
            path.relative_to(captured.root).as_posix(), kind="prerequisite-original"
        )
        if sha256_bytes(raw) != member["sha256"]:
            raise ReleaseControlError("manifest original input R differs before projection")
        entries.append(
            {
                "path": path.relative_to(original.root).as_posix(),
                "media_type": "application/json"
                if kind.startswith("metriplane.")
                else "application/octet-stream",
                "role": role,
                "sha256": sha256_bytes(raw),
                "size": len(raw),
            }
        )
    expected = {
        "candidate_digest": None,
        "entries": entries,
        "invocation_journal_digests": sorted(journals),
        "phase": phase,
        "scope_kind": "release-staging",
        "scope_id": historical.name,
        "producer_intent_digest": sha256_json(original.intent),
        "invocation_root_locator": "invocations",
    }
    expected["manifest_digest"] = sha256_json(
        {key: expected[key] for key in ("entries", "invocation_journal_digests")}
    )
    _release_evidence_manifest_content(expected)
    _release_graph_primary_equal(record, expected)
    captured.revalidate()


def _release_graph_original_input_identity(
    original: ReleaseInvocation, *, path: Path, schema_id: str, expected_raw: Mapping[str, Any]
) -> None:
    """Check a transitive linked original's known input identity before any byte read."""
    args = _release_original_arguments(original.intent["tool"], original.intent["argv"])
    cwd = _canonical_absolute_path(
        original.intent["environment"]["working_directory"], "graph linked input cwd"
    )
    historical = _release_historical_path(args["invocation-dir"], cwd).parents[2]
    if not path.is_relative_to(original.root):
        raise ReleaseControlError("graph linked original is outside the actual consumer input root")
    selected = [
        row
        for row in original.intent["inputs"]
        if row["path"] == str(historical / path.relative_to(original.root))
    ]
    if (
        len(selected) != 1
        or selected[0]["schema_id"] != schema_id
        or selected[0]["sha256"]
        != _require_digest(expected_raw["sha256"], "graph linked original R")
    ):
        raise ReleaseControlError(
            "graph linked original lacks consumer intent membership/type/R before reading"
        )


def _release_graph_failed_index_operation(
    failed: ReleaseInvocation,
    *,
    captured: _ReleaseCapturedFiles,
    envelope: Mapping[str, Any],
    original_receipt: Mapping[str, Any],
    native_facts: _ReleaseFixtureNativeFacts,
) -> dict[str, Any]:
    """Bind a negative original command to the exact reconstructed native entry.

    This is a private content/custody owner. The enclosing graph must replay the
    original staging producer and original CAS native facts independently. This
    helper never treats a constructed dataclass or a signed recovery plan as that
    admission, and it does not implement another failure-recorder family.
    """
    validate_record(envelope, "release-staging-attempt")
    validate_record(original_receipt, "release-attempt-index")
    if any(
        value["synthetic"] is not True or value["status"] != "PASS"
        for value in (envelope, original_receipt)
    ):
        raise ReleaseControlError("failed-index binding requires passing fixture originals")
    data = envelope["data"]
    stage_tools = {
        "attempt-index-update": "update_release_attempt_index.py",
        "attempt-index-validation": "validate_release_attempt_index.py",
    }
    if data.get("stage") not in stage_tools or failed.intent["tool"] != stage_tools[data["stage"]]:
        raise ReleaseControlError("failure envelope has no matching original index operation")
    _release_captured_original_context(failed, captured=captured)
    terminal = _release_captured_journal_terminal(failed, captured=captured, require_pass=False)
    if (
        terminal["status"] not in {"FAIL", "BLOCKED", "CANCELLED"}
        or data.get("result") != terminal["status"]
        or data.get("failed_invocation_digest") != sha256_json(terminal)
        or data.get("disposition") != "TERMINAL"
        or data.get("recovery_envelope_digest") is not None
    ):
        raise ReleaseControlError("failure envelope substitutes its actual negative original")
    _release_replay_original_lineage(failed, captured=captured, require_pass=False)
    entry = _release_index_receipt_content(original_receipt["data"])
    if _source_json(native_facts.producer_identity, "reconstructed CAS producer") != {
        "tool": "update_release_attempt_index.py",
        "invocation_id": original_receipt["invocation_id"],
        "sequence": original_receipt["sequence"],
        "intent_digest": original_receipt["data"].get("producer_intent_digest"),
    }:
        raise ReleaseControlError("reconstructed native fact belongs to another original producer")
    if entry["scope"]["kind"] != "release_staging":
        raise ReleaseControlError(
            "RECOVERY_OTHER_FAILURE_FAMILY_REQUIRED: this original staging owner does not admit blocker/evaluation/conflict history"
        )
    args = _release_original_arguments(failed.intent["tool"], failed.intent["argv"])
    cwd = _canonical_absolute_path(
        failed.intent["environment"]["working_directory"], "failed index cwd"
    )
    historical = _release_historical_path(args["invocation-dir"], cwd).parents[2]
    if (
        data.get("run_id") != historical.name
        or data.get("milestone") != entry["milestone"]
        or entry["scope"]["run_id"] != historical.name
    ):
        raise ReleaseControlError("failed index envelope changes its original run/milestone")
    if len(native_facts.operations) != 1:
        raise ReleaseControlError("reconstructed original requires exactly one native CAS fact")
    fact = _source_json(native_facts.operations[0], "reconstructed original CAS fact")
    if fact.get("kind") != "index.cas":
        raise ReleaseControlError("original reconstruction is not a CAS entry")
    # Replay the existing response owner again, including the original token. The
    # facts themselves are supplied only by actual native replay in the enclosing graph.
    response = _release_fixture_native_response(
        "index.cas", fact["request"], canonical_json(fact["response"])
    )
    if canonical_json(response["entry"]) != canonical_json(entry):
        raise ReleaseControlError("reconstructed receipt changes its exact native original entry")
    if data["stage"] == "attempt-index-update":
        scope = entry["scope"]
        expected = {
            "scope-kind": "release_staging",
            "milestone": entry["milestone"],
            "run-id": scope["run_id"],
            "stage": scope["stage"],
            "sequence": scope["sequence"],
            "operation-id": entry["operation_id"],
            "expected-head": entry["previous_head"] or entry["genesis_digest"],
            "index-backend": "attempt-index",
        }
        if any(args.get(key) != value for key, value in expected.items()):
            raise ReleaseControlError("failed original update command changes scope/operation/head")
        for flag, field in (("release-tag", "release_tag"), ("candidate-id", "candidate_id")):
            if scope[field] is None:
                if args.get(flag + "-not-resolved") is not True or flag in args:
                    raise ReleaseControlError("failed update changes unresolved original identity")
            elif args.get(flag) != scope[field] or flag + "-not-resolved" in args:
                raise ReleaseControlError("failed update changes resolved original identity")
        for flag, kind, field in (
            ("entry-manifest", "release-evidence-manifest", "entry_manifest_digest"),
            ("entry-receipts", "release-retention-receipts", "entry_receipts_digest"),
        ):
            _, raw = _release_original_consumed_file(
                failed.intent,
                current_root=failed.root,
                captured=captured,
                expected_tool=failed.intent["tool"],
                flag=flag,
                expected_schema_id="metriplane." + kind + ".v1",
            )
            value = _source_json(raw, "failed original " + flag)
            validate_record(value, kind)
            if (
                value["status"] != "PASS"
                or value["synthetic"] is not True
                or sha256_json(value) != entry[field]
            ):
                raise ReleaseControlError("failed update replaces original retained payload C")
    else:
        if args.get("index-backend") != "attempt-index" or args.get("read-back") is not True:
            raise ReleaseControlError("failed validator did not select actual original read-back")
        _, raw = _release_original_consumed_file(
            failed.intent,
            current_root=failed.root,
            captured=captured,
            expected_tool=failed.intent["tool"],
            flag="through-receipt",
            expected_schema_id="metriplane.release-attempt-index.v1",
        )
        if canonical_json(_source_json(raw, "failed original through-receipt")) != canonical_json(
            original_receipt
        ):
            raise ReleaseControlError("failed read-back names another original receipt")
        _, genesis_raw = _release_original_consumed_file(
            failed.intent,
            current_root=failed.root,
            captured=captured,
            expected_tool=failed.intent["tool"],
            flag="genesis",
            expected_schema_id="metriplane.release-fixture-index-genesis.v1",
        )
        if sha256_bytes(genesis_raw) != entry["genesis_digest"]:
            raise ReleaseControlError("failed read-back changes the original index genesis")
        _release_fixture_index_genesis(genesis_raw)
    captured.revalidate()
    return {
        "failed_intent_digest": sha256_json(failed.intent),
        "failed_terminal_digest": sha256_json(terminal),
        "failure_envelope_digest": sha256_json(envelope),
        "original_entry_digest": sha256_json(entry),
        "original_operation_id": entry["operation_id"],
        "original_prior_head": entry["previous_head"] or entry["genesis_digest"],
        "stage": data["stage"],
    }


def _release_index_manifest_entry_root(
    *,
    root: Path,
    manifest_path: Path,
    manifest: Mapping[str, Any],
    scope: Mapping[str, Any],
) -> Path:
    """Return the one phase-owned namespace, never a caller-selected fallback.

    root belongs to the independently captured original invocation/input carrier.
    Manifest entry paths are a different wire domain from containing-relative raw
    sidecars. Ordinary staging entries retain the exact original run namespace even
    when their manifest output is nested in failures/<sequence>/.
    """
    root = _release_capture_absolute(root)
    manifest_path = _release_capture_absolute(manifest_path)
    if not manifest_path.is_relative_to(root):
        raise ReleaseControlError("manifest output is outside its original input carrier")
    data = manifest["data"]
    if scope["kind"] == "release_staging" and scope["stage"] in {"target-burn", "staging-failure"}:
        if (
            data["phase"] != scope["stage"]
            or data["scope_kind"] != "release-staging"
            or data["scope_id"] != scope["run_id"]
            or data["candidate_digest"] is not None
        ):
            raise ReleaseControlError("staging manifest changes its original run namespace")
        return root
    if scope["kind"] == "release_candidate" and scope["stage"] == "qualification-attempt":
        if data["phase"] != "attempt" or data["scope_kind"] != "release-attempt":
            raise ReleaseControlError("attempt manifest changes its owner namespace")
        return manifest_path.parent
    raise ReleaseControlError("manifest phase has no implemented original namespace owner")


_RELEASE_GRAPH_NATIVE_TOOLS = frozenset(
    {
        "capture_linear_release_snapshot.py",
        "record_release_role_assignments.py",
        "validate_release_evidence_stores.py",
        "capture_release_target_observations.py",
        "export_release_burn_lineage.py",
        "retain_release_evidence.py",
        "update_release_attempt_index.py",
        "export_release_attempt_index.py",
    }
)
